-- Step 73, part 3 of 3: breeding guides (run part 1 first; it creates the table).

insert into public.breeding_guides
  (slug, award_species_id, species_slug, glossary_slug, seo_title, summary, intro, facts, sections, faq, society_tip)
select v.slug, a.id, v.species_slug, v.glossary_slug, v.seo_title, v.summary, v.intro, v.facts, v.sections, v.faq, v.society_tip
from (values
  ($g$regani-julie$g$, $g$42036fc7-136e-45fd-859b-e41709839088$g$::uuid, $g$regani-julie$g$, null, $g$How to Breed Regan's Julies: Pairs, Caves and Raising Fry$g$, $g$Breeding Julidochromis regani means forming a true pair, giving them rockwork caves and hard alkaline water, then letting the family raise the fry.$g$, $g$Regan's Julie is a Lake Tanganyika cave spawner that forms lasting pairs and raises its fry inside the rockwork. Once you have a bonded pair, spawning is fairly routine, and watching several generations of fry share a cave with their parents is a real treat. The hard part is getting a compatible pair in the first place, which is why this is a Class C species.$g$, $g${"method": "Cave spawner (eggs hidden on the roof or wall of a cave)", "sexing": "Hard to sex by looks; females are usually larger. Venting or watching which fish pair up works best", "group": "One bonded pair, ideally formed from a group of 6 juveniles", "breeding_tank": "30 gallons or more, sand bottom, stacked rock with many narrow caves", "conditioning": "Varied diet of quality pellets, frozen mysis and brine shrimp for 2 to 3 weeks", "trigger": "A settled pair with a private cave and stable hard water around 78 to 80°F", "spawn": "Commonly reported 20 to 100 eggs, sometimes more from large females", "eggs": "Hatch in about 3 days at 78 to 80°F; parents guard them inside the cave", "fry": "Free swimming roughly a week after hatching, about 10 days after the spawn; they stay close to the rocks", "first_foods": "Baby brine shrimp, crushed flake and fine powdered foods", "grow_out": "Slow growers; about 1 inch at 2 to 3 months", "parents": "Good parents; older fry are often tolerated until the next spawn"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank is a sensible minimum for one pair, and larger is better if you want fry to stay with the parents. Use a sand bottom and build tall stacks of rock with plenty of narrow gaps and caves, so the pair can claim one and the fry have places to hide.\n\nKeep water hard and alkaline, in line with the care numbers for this fish: pH 7.8 to 9, GH 10 to 20, and 75 to 81°F. Around 78 to 80°F suits spawning. A sponge filter or a gently flowing canister with a sponge pre-filter keeps fry safe from the intake."}, {"heading": "Getting a compatible pair", "text": "Julies are hard to sex by looks. Females are usually the larger fish, but size alone is not reliable, and venting (checking the genital papilla) takes practice. The easiest route is to raise 6 juveniles together and let a pair form on its own.\n\nOnce two fish start sharing one cave and chasing others away, move the rest out. Pairs can turn on each other, so watch for one fish being driven into a corner. If that happens, separate them with a divider for a while before trying again.\n\nCondition with good pellets plus frozen mysis and brine shrimp for 2 to 3 weeks."}, {"heading": "Spawning: what you'll see", "text": "You often won't see the spawn itself. The pair spend more time in one cave, dig sand out of it, and become more defensive. The female lays her eggs on the roof or wall of the cave, and the male fertilizes them.\n\nBreeders commonly report 20 to 100 eggs, with large, mature females sometimes laying more. The pair take turns guarding the entrance. Avoid moving rocks or shining a flashlight into the cave, which can stress them into eating the spawn.\n\nIf the pair spawn again while older fry are still in the tank, you may see two or three sizes of fry around the same rock pile. That is normal for Julies and a good sign the pair is settled."}, {"heading": "Eggs and early fry", "text": "At 78 to 80°F the eggs commonly hatch in about 3 days. The wrigglers stay stuck to the cave or on the floor of it while they use up their yolk.\n\nRoughly a week after hatching, about 10 days after the spawn, the fry start swimming. They do not roam the tank like many fish; they hover close to the rockwork near their cave. Parents handle egg care and fungus control themselves, so leave them alone."}, {"heading": "Raising the fry", "text": "- Week 1 of swimming: baby brine shrimp once or twice a day, plus finely powdered flake.\n- Weeks 2 to 4: keep up baby brine shrimp and add crushed flake and small pellets.\n- Water changes: 15 to 20% weekly with matched temperature and hardness.\n- Temperature: hold steady at 78 to 80°F.\n\nFry can stay with the parents, which is the natural way for this species. If you want to raise every fry, move some to a grow-out tank once they reach about half an inch."}, {"heading": "Growing out", "text": "Julies grow slowly. Expect fry to reach roughly an inch at 2 to 3 months and close to adult size in about a year. Feed small meals several times a day and keep the water clean, since stunting is common in crowded grow-out tanks. Rockwork in the grow-out tank cuts down on squabbles.\n\nOnce fry are around an inch, they can be moved to a separate tank or sold on as juveniles. Leaving a large group of older fry with the pair works for a while, but parents may start to chase them once a new spawn arrives."}, {"heading": "Common mistakes", "text": "- Buying two adults and assuming they will pair. Raise a group instead.\n- Too few caves, which leads to fighting.\n- Soft or acidic water; keep it hard and alkaline.\n- Shifting rocks to peek at the eggs.\n- Tankmates that steal fry. A species tank gives the best results."}]$g$::jsonb, $g$[{"q": "How can you tell a male from a female Julidochromis regani?", "a": "It's difficult. Females are usually larger, but the reliable methods are venting or simply watching which fish pair up."}, {"q": "Do Julies eat their fry?", "a": "Bonded pairs normally protect their fry, and older fry are often tolerated alongside new spawns. Stress or disturbance can lead to egg eating."}, {"q": "How long do Julie eggs take to hatch?", "a": "Commonly about 3 days at 78 to 80°F, with fry swimming roughly a week after that."}, {"q": "How many fry do Regan's Julies have?", "a": "Breeders commonly report 20 to 100 eggs per spawn, sometimes more from large females."}]$g$::jsonb, $g$Julie fry hide in the rocks, so for stage 3 a short video or a photo near the cave mouth works better than a still of open water. For stage 5, move a few 60-day fry to a small tub or net breeder for a clear shot with your challenge code card.$g$),
  ($g$sunshine-peacock$g$, $g$e14e3b7f-3338-4e48-a592-5ba9c7358a8c$g$::uuid, $g$sunshine-peacock$g$, null, $g$How to Breed Stuartgranti Peacocks: Harems and Holding$g$, $g$Aulonocara stuartgranti is a maternal mouthbrooder: keep one male with several females, condition well, and the females hold eggs for about 3 to 4 weeks.$g$, $g$The Stuartgranti Peacock is a Lake Malawi cichlid where the female carries eggs and fry in her mouth. Spawning comes easily in a well run harem tank, and stripping or watching a holding female release her first fry is a big milestone. The Class C challenge is keeping water and stress right so females hold to term, and keeping the line pure.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Males show bright blue and yellow color; females stay brown or grey with dark bars", "group": "1 male to 3 or 4 females", "breeding_tank": "55 gallons or more, sand bottom, open rocks or flat stones", "conditioning": "Quality pellets plus frozen mysis and brine shrimp for 2 to 3 weeks", "trigger": "Mature, well fed females and a colored, settled dominant male", "spawn": "Commonly 15 to 40 fry per brood; young females hold fewer", "eggs": "Female holds for about 3 to 4 weeks at 78 to 80°F", "fry": "Released fully formed, about 1/3 inch, and ready to eat", "first_foods": "Baby brine shrimp and crushed pellets or flake", "grow_out": "About 1 inch at 2 months; males color from about 6 months", "parents": "No care after release; adults will eat fry, so isolate holding females"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 55 gallons, in line with the care numbers for this fish. Peacocks spawn over sand or on flat stones, so give them an open sandy area plus some rockwork for females to hide in. Hard, alkaline water suits them: pH 7.8 to 8.6, GH 6 to 15, and 76 to 82°F, with about 78 to 80°F ideal for breeding.\n\nStrong filtration and weekly water changes of 25 to 30% keep nitrate low, which helps females hold full term. Have a separate 10 to 20 gallon tank ready for holding females.\n\nAvoid housing them with aggressive mbuna, which stress holding females. Peaceful peacocks or haps of a similar size are fine in a display tank, but a species tank gives you the clearest results and no risk of crosses."}, {"heading": "Choosing a harem", "text": "Keep one male with 3 or 4 females so his attention is spread out. Males are easy to spot: they turn bright blue with yellow or orange depending on the strain. Females stay brown or grey with darker bars.\n\nKeep only one Aulonocara species in the tank. Female peacocks look very similar across species and cross easily, and hybrids should never be sold or passed on. Condition with good pellets and frozen mysis or brine shrimp for 2 to 3 weeks."}, {"heading": "Spawning: what you'll see", "text": "The male darkens, digs a shallow pit or picks a flat stone, and shimmies to lead a female over. She lays a few eggs, picks them up in her mouth, and the male fertilizes them as she mouths at his anal fin. This repeats until she has her clutch.\n\nAfterwards she has a swollen throat and a square chin, eats little or nothing, and hides. That's a holding female.\n\nYoung females often hold poorly on their first few spawns and may eat or spit the eggs early. That usually improves with age and size, so don't give up on a female after one failed hold."}, {"heading": "Holding time", "text": "Females commonly hold for about 3 to 4 weeks at 78 to 80°F. Broods of 15 to 40 are commonly reported, and young females often hold fewer.\n\nMove a holding female after 3 to 7 days, gently, in a net or container with water, so she is less likely to spit. Let her release in the holding tank, then return her to the group once she has eaten for a few days. Some breeders strip fry at about 2 weeks and finish them in a tumbler, but letting her hold to term is simpler and easier on her.\n\nFeed the holding tank lightly while the female is in it, since she usually won't eat until she releases. Keep the water clean and the tank quiet, with a few rocks or a flowerpot she can hide behind."}, {"heading": "Raising the fry", "text": "- First week: baby brine shrimp and crushed flake two or three times a day.\n- Weeks 2 to 4: add crushed small pellets and frozen cyclops.\n- Water changes: 20 to 30% twice a week in small tanks.\n- Temperature: 78 to 80°F.\n\nFry are released fully formed, so there is no wriggler stage to manage."}, {"heading": "Growing out", "text": "Expect about an inch at 2 months. Males usually start showing color from around 6 months, though it varies by strain. Grow them in a tank with plenty of room and frequent feeding. Crowded, underfed fry grow slowly and fight more.\n\nFry from different broods grow at different speeds, so sort them by size every few weeks. Feeding three or four small meals a day gives better growth than one big feed, and frequent water changes keep growth steady."}, {"heading": "Common mistakes", "text": "- Mixing peacock species, which leads to hybrids.\n- Too few females, so one gets harassed.\n- Moving a female too early, causing her to spit.\n- Leaving fry in the main tank, where adults will eat them.\n- High nitrate, which can cause females to swallow or spit early."}]$g$::jsonb, $g$[{"q": "How long do peacock cichlids hold their eggs?", "a": "Commonly about 3 to 4 weeks at 78 to 80°F, depending on temperature and the female."}, {"q": "How do you tell male and female Stuartgranti peacocks apart?", "a": "Adult males show bright blue and yellow color. Females stay brownish with darker vertical bars."}, {"q": "How many fry does a peacock cichlid have?", "a": "Broods of 15 to 40 are commonly reported, with young females holding fewer."}, {"q": "Should I strip a holding peacock?", "a": "It isn't required. Letting her hold to term in her own tank is simplest; stripping is an option for experienced breeders."}]$g$::jsonb, $g$For stage 2, a clear photo of the holding female's swollen throat is the usual way to show a spawn, since the eggs are in her mouth. For stage 1, make sure the male and his females are all in the shot with your challenge code card.$g$),
  ($g$venustus-cichlid$g$, $g$30041874-9cfb-4676-8c77-40d2205af622$g$::uuid, $g$venustus-cichlid$g$, null, $g$How to Breed Venustus Cichlids: Big Tanks and Mouthbrooding$g$, $g$Nimbochromis venustus is a large maternal mouthbrooder: keep a male with several females in 100 gallons or more and move holding females to raise the fry.$g$, $g$Venustus is a big Lake Malawi predator, and the female carries the brood in her mouth. Given a large tank and a group of females, they spawn readily and broods can be big. The Class C challenge is space: males are aggressive, females need room to escape, and you need spare tanks for holding females and fry.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Mature males get a blue head and yellow body; females keep a brown blotched pattern", "group": "1 male to 3 or more females", "breeding_tank": "100 gallons or more, sand bottom, rockwork and open swimming space", "conditioning": "Quality carnivore pellets, frozen krill and mysis for 2 to 3 weeks", "trigger": "A mature, colored male with several conditioned females", "spawn": "Commonly 30 to 100 fry, more from large females", "eggs": "Female holds for about 3 weeks at 78 to 80°F", "fry": "Released fully formed and ready to eat", "first_foods": "Baby brine shrimp and crushed pellets", "grow_out": "About 1 to 1.5 inches by 2 months", "parents": "No care after release; adults eat fry, so move the holding female"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Venustus reach about 10 inches, so start with at least 100 gallons, in line with the care numbers for this fish. Use sand, some rockwork, and plenty of open swimming room. Keep water hard and alkaline: pH 7.8 to 8.6, GH 10 to 25, and 76 to 82°F, with 78 to 80°F good for spawning.\n\nThese are heavy eaters, so use strong filtration and change 30% or more weekly. Set up a separate 20 to 40 gallon tank for holding females and fry."}, {"heading": "Choosing a group", "text": "Keep one male with at least 3 females. A single female will get pestered hard. Mature males develop a bright blue head and a yellowish body, while females keep the giraffe-like brown blotches. Young fish all look like females, so buy a group of juveniles if you can.\n\nKeep one Nimbochromis species per tank to avoid hybrids. Feed a carnivore diet: quality pellets plus frozen krill and mysis for 2 to 3 weeks before you expect spawning.\n\nFemales usually start breeding at around 4 to 5 inches. Males take longer to show full color and may not spawn well until they are the dominant fish in the tank. Remove any second male that starts coloring up and harassing the group."}, {"heading": "Spawning: what you'll see", "text": "The male colors up, clears a spot in the sand or on a flat rock, and displays to females. When one is ready, the pair circle, she lays eggs, picks them up in her mouth, and the male fertilizes them.\n\nAfterwards the female has a stretched, bulging throat, stops eating, and hides. Large females can hold big broods; 30 to 100 is commonly reported, and big females may carry more."}, {"heading": "Holding time", "text": "Holding females commonly carry the brood for about 3 weeks at 78 to 80°F. Move her after a few days, gently and with a container rather than a long chase, to reduce the chance she spits.\n\nOnce she releases, give her a week or two to eat and recover before returning her to the group. Some breeders strip fry at about 2 weeks and finish them in a tumbler. That works, but holding to term is easier on beginners.\n\nKeep the holding tank quiet and covered, with a few rocks or a flowerpot she can hide behind. She won't eat much while holding, so feed lightly and keep the water clean until she releases."}, {"heading": "Raising the fry", "text": "- First week: baby brine shrimp and crushed pellets two or three times a day.\n- Weeks 2 to 4: move up to small pellets and frozen foods.\n- Water changes: 25 to 30% twice a week.\n- Temperature: 78 to 80°F.\n\nFry are released fully formed and eat from day one. They grow quickly and get bossy with each other as they grow.\n\nVenustus fry are bold eaters. Feed small amounts several times a day rather than one large feed, and siphon leftovers from the bottom. Sort out larger fry if they start bullying smaller ones."}, {"heading": "Growing out", "text": "Expect 1 to 1.5 inches by 2 months with good feeding. You will need more tank space fast, as a brood of 60 venustus outgrows a 20 gallon tank quickly. Plan homes for the fry before you start; large broods of a 10 inch predator are hard to rehome.\n\nJuveniles look like small females at first, and males usually take many months to show the blue head. Keep the grow-out tank lightly stocked and well filtered, since these fish produce a lot of waste as they grow."}, {"heading": "Common mistakes", "text": "- A tank that's too small, which leads to injured females.\n- Only one female for the male.\n- Mixing Nimbochromis species, which risks hybrids.\n- Leaving fry with the adults, who will eat them.\n- No plan for where dozens of fry will go."}]$g$::jsonb, $g$[{"q": "How long does a venustus hold eggs?", "a": "Commonly about 3 weeks at 78 to 80°F."}, {"q": "How can you tell a male venustus from a female?", "a": "Mature males develop a blue head and yellow coloring. Females keep a brown, blotched pattern."}, {"q": "How many fry does a venustus have?", "a": "Broods of 30 to 100 are commonly reported, with large females carrying more."}, {"q": "Do venustus eat their own fry?", "a": "Adults will eat fry once the mother releases them, so move the holding female or the fry to their own tank."}]$g$::jsonb, $g$Venustus broods can be large, so a stage 3 photo of the fry in their own tank is easy. For stage 5, catch a few 60-day juveniles into a clear container for a sharp photo next to your challenge code card.$g$),
  ($g$celebes-rainbowfish$g$, $g$ea495575-0e3e-4ecb-9028-ab3ad285f147$g$::uuid, $g$celebes-rainbowfish$g$, null, $g$How to Breed Celebes Rainbowfish: Mops, Eggs and Fry$g$, $g$Celebes rainbowfish lay a few eggs on plants or mops each day; pick the eggs out, hatch them separately and feed tiny foods to raise the fry.$g$, $g$The Celebes rainbowfish from Sulawesi is a lively schooling fish with yellow fins and long male fin rays. Adults spawn readily on fine plants or yarn mops, a few eggs at a time, but they also eat eggs and fry. The Class C challenge is hatching the eggs separately and getting tiny fry onto the right first foods in hard, alkaline water.$g$, $g${"method": "Egg scatterer that sticks eggs on fine plants or mops", "sexing": "Males have longer, extended dorsal and anal fin rays and more yellow color", "group": "1 male to 2 or 3 females, or a small school", "breeding_tank": "20 gallons, sponge filter, spawning mops or fine leaved plants", "conditioning": "Live or frozen foods like daphnia and brine shrimp for 2 weeks", "trigger": "Morning light and mops present; spawns a few eggs daily", "spawn": "A few to a few dozen eggs per day over several days", "eggs": "Commonly hatch in about 7 to 12 days at 76 to 80°F", "fry": "Tiny and swim at the surface right after hatching", "first_foods": "Infusoria or green water, then baby brine shrimp after about a week", "grow_out": "About an inch by 2 to 3 months", "parents": "No care; adults eat eggs and fry, so remove eggs or mops"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well. Use a sponge filter, no gravel or a thin layer, and add two or three yarn spawning mops or bunches of fine leaved plants like java moss.\n\nKeep water hard and slightly alkaline, in line with the care numbers for this fish: pH 7 to 8, GH 8 to 20, and 72 to 82°F. About 76 to 80°F is good for spawning. Bright light and some morning sun or a light on a timer help, since they spawn mainly in the morning.\n\nMany breeders keep adults in the breeding tank and simply rotate mops every few days, moving full mops to a hatching container. This lets the fish spawn steadily without the stress of moving them back and forth."}, {"heading": "Conditioning and choosing fish", "text": "Males are easy to pick out once mature: they have long, trailing rays on the dorsal and anal fins and more yellow color. Females are plainer with shorter fins.\n\nUse 1 male to 2 or 3 females, or spawn a small school. Feed daphnia, brine shrimp and other live or frozen foods for about 2 weeks, along with quality flake.\n\nCelebes rainbowfish are active swimmers, so a longer tank helps. Males display more and spawn better when they have a couple of rival males to show off to, so a school of 6 to 8 with more females than males also works well."}, {"heading": "Spawning: what you'll see", "text": "Males display to females with fins spread, then the pair swim into the mop and release a few eggs, which stick to the strands with fine threads. They spawn a little each day rather than all at once.\n\nCheck the mops every day or two and pick off eggs, or swap the mop for a fresh one. Expect a few to a few dozen eggs a day."}, {"heading": "Eggs and fungus", "text": "Hatch eggs in a small container or tank with water from the breeding tank and a gentle air stone. At 76 to 80°F, hatching commonly takes about 7 to 12 days.\n\nRemove white, fungused eggs daily so fungus doesn't spread. Because eggs are collected over several days, you'll have fry hatching at different times. Keep batches separate by date if you can so bigger fry don't bully smaller ones."}, {"heading": "Raising the fry", "text": "- Days 1 to 7: infusoria, green water or a fine liquid fry food several times a day.\n- Week 2: add baby brine shrimp and microworms.\n- Weeks 3 to 6: baby brine shrimp plus crushed flake.\n- Water changes: small, 10 to 20% every few days, matched in temperature.\n- Temperature: 76 to 80°F.\n\nFry stay near the surface, so a low water level for the first week helps them find food.\n\nStart an infusoria culture or green water a week before you expect hatching, so food is ready on day one. Fry that miss their first feeds in the first few days rarely recover."}, {"heading": "Growing out", "text": "Fry reach about an inch by 2 to 3 months. Males start showing longer fins and yellow color at a few months old. A larger grow-out tank with frequent small meals gives the best growth.\n\nAs fry grow, move them to a bigger tank and add small frozen foods such as daphnia and cyclops. Keep hardness steady at the level they were hatched in, then match it to the adults' tank once they are about an inch long."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults.\n- Feeding baby brine shrimp too early, before fry can eat it.\n- Big water changes that shock tiny fry.\n- Soft, acidic water; this fish prefers hard and alkaline."}]$g$::jsonb, $g$[{"q": "How long do Celebes rainbowfish eggs take to hatch?", "a": "Commonly about 7 to 12 days at 76 to 80°F."}, {"q": "Do rainbowfish eat their eggs?", "a": "Yes. Adults will eat eggs and fry, so remove mops or eggs regularly."}, {"q": "How do you sex Celebes rainbowfish?", "a": "Mature males have long, trailing rays on the dorsal and anal fins and more yellow color than females."}, {"q": "What do Celebes rainbowfish fry eat?", "a": "Infusoria or green water for about the first week, then baby brine shrimp."}]$g$::jsonb, $g$Since eggs are laid a few at a time, date each batch you pull. Use the date of your first hatched batch for stage 3 so your 30 and 60-day grow-out photos line up with real fry ages.$g$),
  ($g$gertrudes-blue-eye$g$, $g$10295778-d4e5-4293-a271-084f3b7bfe90$g$::uuid, $g$gertrudes-blue-eye$g$, null, $g$How to Breed Spotted Blue-eyes (Pseudomugil gertrudae)$g$, $g$Spotted blue-eyes lay a few eggs a day on mops or moss; collect them, hatch them separately for about 2 weeks and feed tiny foods to raise the fry.$g$, $g$Pseudomugil gertrudae is a tiny, spotted blue-eye that spawns almost every day on plants or mops. Eggs are easy to get, and the fry are surprisingly tough once they start eating. The Class C challenge is the long hatch time, tiny fry and the short lives of the adults, so a steady breeding routine matters.$g$, $g${"method": "Egg scatterer that sticks eggs on moss or spawning mops", "sexing": "Males have larger, more heavily spotted fins and more yellow; females are paler", "group": "1 male to 2 or 3 females", "breeding_tank": "10 gallons, sponge filter, java moss or yarn mops", "conditioning": "Small live foods like baby brine shrimp and daphnia for 1 to 2 weeks", "trigger": "Mops or moss present and good feeding; spawns daily in the morning", "spawn": "A few eggs a day, sometimes up to 10 to 20", "eggs": "Commonly hatch in about 10 to 20 days at 75 to 80°F", "fry": "Tiny and swim at the surface right after hatching", "first_foods": "Infusoria or vinegar eels, then baby brine shrimp after a few days", "grow_out": "About half an inch at 1 to 2 months", "parents": "No care; adults eat eggs and fry, so pull eggs or mops"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank is plenty, in line with the care numbers for this fish. Use a gentle sponge filter, a dark bottom and a big clump of java moss or two yarn mops. Floating plants help the fish feel secure.\n\nKeep water soft to medium hard: pH 5.5 to 7.5, GH 3 to 12, and 72 to 82°F, with 75 to 80°F a good spawning range.\n\nSome breeders keep a breeding colony in a well planted tank and let a few fry survive naturally in the moss. That gives fewer fry than pulling eggs, but it's a low effort way to keep a line going. For a breeding log, collecting eggs gives you more control."}, {"heading": "Conditioning and choosing fish", "text": "Males have bigger dorsal and anal fins with bolder dark spots and more yellow color. Females are paler, with smaller and less heavily marked fins. Use 1 male to 2 or 3 females to spread out the male's attention.\n\nFeed small live and frozen foods such as baby brine shrimp, daphnia and cyclops for 1 to 2 weeks, plus fine flake. Spotted blue-eyes are short lived, often only a year or two, so breed them while they're young and healthy."}, {"heading": "Spawning: what you'll see", "text": "Males flare their fins and dance around a female. The pair dive into the moss or mop together and release a few eggs, which stick by fine threads. This repeats most mornings.\n\nYou won't get a big clutch. Most females lay a few eggs a day, sometimes up to 10 to 20 over a good day, so collect over a week or two for a usable batch.\n\nFemales that have spawned recently may look a little thin. Keep feeding them well, and give them breaks by adding more females or rotating them out if the male chases one too hard."}, {"heading": "Eggs and fungus", "text": "Pick eggs off the mop with your fingers or a soft brush and put them in a small container with tank water. A drop of methylene blue or a few almond leaves helps prevent fungus, though many breeders skip it. Remove any eggs that turn white.\n\nHatch time is long for such a small fish: commonly about 10 to 20 days at 75 to 80°F. Warmer water hatches them faster."}, {"heading": "Raising the fry", "text": "- Days 1 to 3: infusoria, vinegar eels or a fine fry powder several times a day.\n- Day 4 to week 3: newly hatched baby brine shrimp and microworms.\n- Week 4 on: add crushed flake.\n- Water changes: 10 to 20% every few days, matched carefully.\n- Temperature: 75 to 80°F.\n\nFry live near the surface, so keep the water level low at first and feed in small amounts often.\n\nKeep each week's batch of fry in its own container if you can. A clean, small container or a 2 to 5 gallon tank with a sponge filter is enough for the first few weeks."}, {"heading": "Growing out", "text": "Fry reach about half an inch at 1 to 2 months and can spawn by 3 to 4 months. Keep batches separated by age so larger fry don't outcompete smaller ones for food.\n\nGrow-out tanks should be well planted and stable. Feed small meals of baby brine shrimp and fine flake several times a day. Males usually show their fin spots and color by about 3 months."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults.\n- Giving up because eggs haven't hatched after a week; they often take longer.\n- Feeding too much at once and fouling the fry tank.\n- Waiting too long to breed short lived adults."}]$g$::jsonb, $g$[{"q": "How long do spotted blue-eye eggs take to hatch?", "a": "Commonly about 10 to 20 days at 75 to 80°F."}, {"q": "How do you tell male and female Pseudomugil gertrudae apart?", "a": "Males have larger, more heavily spotted fins and more yellow color. Females are paler with smaller fins."}, {"q": "How many eggs do spotted blue-eyes lay?", "a": "A few eggs a day, sometimes up to 10 to 20, rather than one big clutch."}, {"q": "What do Pseudomugil fry eat?", "a": "Infusoria or vinegar eels for the first few days, then baby brine shrimp and microworms."}]$g$::jsonb, $g$Open the log before you start collecting eggs, and photograph the moss or mop with eggs for stage 2. Note the hatch date of your first batch for stage 3, since egg collection runs over many days.$g$),
  ($g$threadfin-rainbowfish$g$, $g$2dfa41a5-bde6-4bbe-a380-090d5c8e73de$g$::uuid, $g$threadfin-rainbowfish$g$, null, $g$How to Breed Threadfin Rainbowfish: Mops and Tiny Fry$g$, $g$Threadfin rainbowfish spawn on fine plants or mops; the challenge is hatching the eggs apart from the adults and feeding very tiny fry the right foods.$g$, $g$Iriatherina werneri is famous for the male's long, threadlike fins. Adults spawn readily on mops and fine plants, a few eggs at a time, but the fry are tiny and slow to start eating. That's why this is a Class C fish: the eggs are easy, and getting a group of fry past the first two weeks is the real work.$g$, $g${"method": "Egg scatterer that sticks eggs on fine plants or mops", "sexing": "Males have long threadlike dorsal and anal fins; females are plain silver", "group": "1 male to 2 or 3 females, or a small school", "breeding_tank": "20 gallons, sponge filter, java moss or yarn mops", "conditioning": "Small live foods like baby brine shrimp and daphnia for 2 weeks", "trigger": "Mops or fine plants present; spawns a few eggs most mornings", "spawn": "A few to a dozen or so eggs a day over several days", "eggs": "Commonly hatch in about 7 to 12 days at 78 to 82°F", "fry": "Very tiny and stay at the surface; weak swimmers at first", "first_foods": "Infusoria or paramecium for about 1 to 2 weeks, then baby brine shrimp", "grow_out": "Slow; about half an inch at 2 months", "parents": "No care; adults eat eggs and fry, so remove eggs or mops"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well, in line with the care numbers for this fish. Use a gentle sponge filter, little or no current, and plenty of fine leaved plants, java moss or yarn mops.\n\nKeep water soft to medium: pH 5.5 to 7.5, GH 3 to 12, and 75 to 86°F, with about 78 to 82°F good for spawning. Threadfins are shy, so avoid boisterous tankmates.\n\nMany breeders leave the adults in a planted species tank and simply pull mops or moss every few days. This reduces stress on the adults, who can be skittish and don't move well between tanks."}, {"heading": "Conditioning and choosing fish", "text": "Males are easy to tell: they grow long, trailing dorsal and anal fins. Females are plain silver with short fins. Use 1 male to 2 or 3 females, or keep a small school with more females than males.\n\nThreadfins have tiny mouths. Feed baby brine shrimp, daphnia, cyclops and crushed flake for about 2 weeks.\n\nFeed small meals two or three times a day rather than one larger feed. Threadfins are slow, gentle eaters, and faster tankmates will take most of the food if you don't watch."}, {"heading": "Spawning: what you'll see", "text": "Males flare their fins and display in front of females, often in a jerky dance. The pair dart into the mop or moss together and leave a few eggs that stick with fine threads.\n\nThey spawn a little each day, so check the mops every day or two and move eggs to a hatching container, or swap the mop out.\n\nSpawning is spread over many days, so plan to collect eggs over a week or two. A typical daily haul is small, from a few to a dozen or so eggs, which adds up over time."}, {"heading": "Eggs and fungus", "text": "Hatch the eggs in a small tank or container with water from the breeding tank and gentle aeration. At 78 to 82°F, hatching commonly takes about 7 to 12 days.\n\nRemove white, fungused eggs daily. A few almond leaves or a drop of methylene blue can help with fungus.\n\nSince eggs are collected over several days, label each container with the date. Fry that hatch a week apart are very different in size, and keeping batches apart stops the bigger fry taking all the food."}, {"heading": "Raising the fry", "text": "- Weeks 1 to 2: infusoria or paramecium cultures several times a day. Many fry are too small for baby brine shrimp at first.\n- Weeks 2 to 3: add microworms and newly hatched baby brine shrimp as soon as fry can take them.\n- Weeks 4 on: baby brine shrimp plus finely crushed flake.\n- Water changes: 10% every few days, matched carefully.\n- Temperature: 78 to 82°F.\n\nStart your infusoria cultures before the eggs hatch, since you'll need a steady supply."}, {"heading": "Growing out", "text": "Threadfins grow slowly. Expect about half an inch at 2 months and adult size in several months. Males start to show their trailing fins as they mature. Avoid fin nippers in the grow-out tank.\n\nOnce fry are taking baby brine shrimp well, survival improves a lot. Grow them in a tank with gentle flow and plenty of fine plants. Keep feeding small meals often, as their small mouths limit how much they can take at once."}, {"heading": "Common mistakes", "text": "- No infusoria ready when fry hatch.\n- Feeding only baby brine shrimp from day one, which many fry can't eat yet.\n- Strong filter flow that pushes weak fry around.\n- Leaving eggs with the adults.\n\nMost failures with threadfins happen in the first two weeks after hatching. If you can get a batch past that point on infusoria and microworms, the rest of the grow-out is usually smooth."}]$g$::jsonb, $g$[{"q": "How long do threadfin rainbowfish eggs take to hatch?", "a": "Commonly about 7 to 12 days at 78 to 82°F."}, {"q": "What do threadfin rainbowfish fry eat?", "a": "Infusoria or paramecium for the first 1 to 2 weeks, then microworms and baby brine shrimp."}, {"q": "How can you tell a male threadfin from a female?", "a": "Males grow long, threadlike dorsal and anal fins. Females are plain silver with short fins."}, {"q": "Are threadfin rainbowfish hard to breed?", "a": "Spawning is easy, but raising the tiny fry takes care, especially with first foods."}]$g$::jsonb, $g$Threadfin fry are hard to see, so for stage 3 photograph them against a dark background at the surface. Keep a dated note of each egg batch so your grow-out stages track the right hatch.$g$),
  ($g$bucephalandra$g$, $g$3f0de3b8-f95b-4e04-9f3f-d5c22c4689fb$g$::uuid, null, null, $g$How to Propagate Bucephalandra: Rhizome Division Guide$g$, $g$Bucephalandra propagates by cutting its rhizome into pieces with a few leaves each; it's slow but simple, and needs low light and patience.$g$, $g$Bucephalandra are slow growing rhizome plants from Borneo, prized for their small, shimmering leaves. Propagation is simple: cut the rhizome into sections and attach them to rock or wood. The Class C part is patience, since new growth comes slowly and plants can melt if conditions change suddenly. With patience, one healthy plant can become several.$g$, $g${"method": "Rhizome division", "light": "Low to medium light; strong light can lead to algae on leaves", "co2": "Not required; CO2 and fertilizer speed up growth", "substrate": "Attach to rock or wood; never bury the rhizome", "timeline": "Often a new leaf every 1 to 3 weeks; a division fills in over several months", "first_steps": "Cut a healthy rhizome into pieces with at least 3 to 4 leaves each"}$g$::jsonb, $g$[{"heading": "How Bucephalandra propagates", "text": "Bucephalandra grows from a creeping rhizome, a thick horizontal stem with leaves on top and roots below. As the rhizome grows longer, it branches. You propagate it by cutting the rhizome into pieces, each with leaves and some roots, and each piece grows on as a new plant.\n\nIt grows slowly. Most varieties put out a new leaf every one to three weeks, so a newly split piece takes several months to look full.\n\nThere are many named varieties of Bucephalandra, but they all propagate the same way. Some keep their color and leaf shape better than others when grown submerged, so expect some variation in new growth."}, {"heading": "What you need", "text": "- A healthy, established plant with a long or branching rhizome.\n- Sharp scissors or a clean blade.\n- Rocks or driftwood to attach new pieces to.\n- Cotton thread, fishing line or plant safe glue.\n- Stable water: Bucephalandra does well at about 72 to 82°F and tolerates a wide pH range.\n\nStart from farm or tissue culture grown plants rather than wild-collected ones, since some wild Bucephalandra populations have been heavily over-collected. CO2 isn't required. In a tank with CO2 and fertilizer, growth is noticeably faster.\n\nBucephalandra does well in low tech tanks without CO2. In those tanks, expect slower growth but healthy plants if light stays low to medium and nutrients are steady."}, {"heading": "Step by step", "text": "- Lift the plant out or work in the tank if the rhizome is easy to reach.\n- Find a section with at least 3 to 4 healthy leaves and some roots.\n- Make a clean cut through the rhizome.\n- Tie or glue the new piece to rock or wood, rhizome against the surface.\n- Put it back in a shaded or medium light spot with some water flow.\n\nLeave the parent plant with a good number of leaves so it recovers quickly.\n\nIf the rhizome has side shoots, cut where a shoot meets the main rhizome so each piece keeps its own growing tip. Dividing every few months gives you a steady supply of new plants without stressing the parent."}, {"heading": "Caring for new plants", "text": "New pieces take a few weeks to root onto their surface. Avoid moving them during this time. Keep light at low to medium levels, and keep water flow gentle but steady to stop debris settling on leaves.\n\nRegular weekly water changes and a light dose of fertilizer help. Many keepers see the first new leaf within a few weeks and a fuller plant after 2 to 3 months.\n\nWatch for algae on the leaves, since slow growth means algae has time to settle. Shaded spots, some flow and nerite snails or shrimp help keep leaves clean."}, {"heading": "Dealing with melting", "text": "Bucephalandra sometimes melts, losing leaves after big changes in water, light or temperature. If it happens, check the rhizome. A firm, green rhizome will usually regrow leaves. A soft, mushy rhizome is rotting and should be cut back to healthy tissue. Keep conditions stable for a few weeks after dividing.\n\nNewly bought plants are often grown out of water on farms, and they may lose some leaves as they adjust to life underwater. New submerged leaves usually follow within a few weeks."}, {"heading": "Common mistakes", "text": "- Burying the rhizome in substrate, which leads to rot.\n- Cutting pieces too small, with only one or two leaves.\n- Strong light that lets algae coat the slow growing leaves.\n- Moving new pieces around before they root.\n- Big swings in water conditions right after dividing.\n\nMost problems with Bucephalandra come from impatience. Leave new pieces in one place, keep conditions steady, and give them a few months. Slow and stable is the way this plant grows best."}]$g$::jsonb, $g$[{"q": "How do you propagate Bucephalandra?", "a": "Cut the rhizome into pieces with at least 3 to 4 leaves each and attach them to rock or wood."}, {"q": "Can you bury Bucephalandra rhizome?", "a": "No. Keep the rhizome above the substrate, tied or glued to rock or wood, or it may rot."}, {"q": "How fast does Bucephalandra grow?", "a": "Slowly, often a new leaf every one to three weeks. CO2 and fertilizer speed it up."}, {"q": "Why is my Bucephalandra melting?", "a": "Usually after big changes in water, light or temperature. A firm rhizome will often regrow leaves."}]$g$::jsonb, $g$Photograph the parent plant and the cut pieces on day one with the date shown, then take dated photos of each piece as new leaves appear. That before and after record makes your plant program entry clear.$g$),
  ($g$white-seam-betta$g$, $g$bdeba372-7377-416b-b83f-981765684ff2$g$::uuid, null, null, $g$How to Breed White-seam Bettas: Mouthbrooding Males$g$, $g$Betta albimarginata is a paternal mouthbrooder: a settled pair in a quiet, soft water tank spawns small clutches the male holds for about 10 to 14 days.$g$, $g$The White-seam Betta is a small, wild betta from Borneo, and unlike the familiar Siamese fighter, the male carries the eggs in his mouth. Pairs are peaceful and spawn in a quiet tank, but clutches are small and males sometimes swallow or spit them. That uncertainty is why it's a Class D species, and why every successful brood feels earned.$g$, $g${"method": "Paternal mouthbrooder (male holds the eggs)", "sexing": "Males show red-orange color and white-edged fins with a dark band; females are duller", "group": "One pair", "breeding_tank": "10 to 20 gallons, dim light, leaf litter, plants and a tight lid", "conditioning": "Live or frozen foods like bloodworms, daphnia and brine shrimp for 2 to 3 weeks", "trigger": "A settled, well fed pair in soft, slightly acidic water", "spawn": "Small clutches, commonly reported around 10 to 30 eggs", "eggs": "Male holds for about 10 to 14 days at 75 to 79°F", "fry": "Released free swimming and ready to eat", "first_foods": "Baby brine shrimp and microworms", "grow_out": "About half an inch to 3/4 inch by 2 months", "parents": "Parents usually tolerate fry, but moving fry or the holding male is safer"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 20 gallon tank is enough for one pair. White-seam bettas are shy, so give them dim light, floating plants, dense planting and dried leaf litter on the bottom. A sponge filter keeps the flow gentle. Use a tight lid; like other bettas, they breathe air at the surface and the air above the water should stay warm and humid.\n\nSoft, slightly acidic water suits them. Breeders commonly aim for a pH around 5.5 to 7 and low hardness, at about 75 to 79°F.\n\nWater from a mature tank works better than fresh water for this fish. Many breeders add dried oak or almond leaves, which soften and tint the water and give the fish more cover."}, {"heading": "Choosing and conditioning a pair", "text": "Males show red or orange color with white-edged fins and a dark band inside the white edge. Females are duller and may show horizontal stripes, especially when stressed.\n\nWild bettas are best kept as a single pair in their own tank. Condition with live or frozen foods such as bloodworms, daphnia and brine shrimp for 2 to 3 weeks. Many wild-caught fish refuse dry food at first, so plan on frozen or live foods.\n\nIf you buy a group of young fish, let them pair up naturally, then move the pair to their own tank. Watch for one fish hiding all the time, which may mean the pair isn't compatible."}, {"heading": "Spawning: what you'll see", "text": "The pair circle and embrace near the bottom, with the male wrapping around the female. Eggs fall and the female usually collects them in her mouth, then spits them toward the male, who takes them into his mouth. This repeats until the clutch is complete.\n\nAfterwards the male has a swollen throat and stays still in a quiet spot. Clutches are small; around 10 to 30 eggs is commonly reported.\n\nSpawning often happens in the early morning or late afternoon. It can take an hour or two from the first embraces to the last eggs, so don't disturb the tank if you see the pair circling."}, {"heading": "Holding time", "text": "The male commonly holds for about 10 to 14 days at 75 to 79°F. Don't disturb him during this time. Leave the lid on, avoid netting, and keep tank maintenance light.\n\nYoung or stressed males sometimes swallow or spit the clutch. If that happens, keep conditioning the pair; many males do better on their second or third attempt. Some breeders move the holding male to a separate tank, but this risks him spitting, so leaving him in place is usually safer."}, {"heading": "Raising the fry", "text": "- First week: newly hatched baby brine shrimp and microworms two or three times a day.\n- Weeks 2 to 4: keep up baby brine shrimp and add chopped frozen foods.\n- Water changes: small, 10% every few days, matched in temperature and softness.\n- Temperature: 75 to 79°F, with a tight lid so the air above stays warm.\n\nFry are released ready to eat. Adults often tolerate them, but moving fry to their own tank gives the best survival."}, {"heading": "Growing out", "text": "Fry grow at a modest pace, reaching about half to 3/4 of an inch by 2 months. Keep the grow-out tank covered and well planted. Fry are peaceful with each other, so a single grow-out tank usually works.\n\nFeed small meals of live or frozen foods several times a day. Some fry may accept fine dry foods later, but many wild bettas stay picky, so plan for frozen or live foods throughout grow-out."}, {"heading": "Common mistakes", "text": "- Disturbing a holding male, which leads to swallowed eggs.\n- Open tops; bettas need warm, humid air at the surface.\n- Hard, alkaline water.\n- Busy community tanks; this fish needs a quiet species tank.\n- Giving up after one failed hold."}]$g$::jsonb, $g$[{"q": "Is Betta albimarginata a mouthbrooder?", "a": "Yes. The male holds the eggs in his mouth until the fry are released."}, {"q": "How long does a male White-seam Betta hold eggs?", "a": "Commonly about 10 to 14 days at 75 to 79°F."}, {"q": "How do you tell male and female Betta albimarginata apart?", "a": "Males have red-orange color and white-edged fins with a dark band. Females are duller and often show stripes."}, {"q": "How many eggs do White-seam Bettas have?", "a": "Clutches are small, commonly reported around 10 to 30 eggs."}]$g$::jsonb, $g$For stage 2, a clear side photo of the male's swollen throat is usually the best spawn evidence you can get, since you won't see the eggs. Use a dark background and gentle light to get it without spooking him.$g$),
  ($g$harlequin-rasbora$g$, $g$ab852f90-994f-4f9a-8f8a-3113ebee8fcc$g$::uuid, $g$harlequin-rasbora$g$, null, $g$How to Breed Harlequin Rasboras: Under-Leaf Spawning$g$, $g$Harlequin rasboras lay eggs on the underside of broad leaves in soft, acidic water; with the right setup and tiny first foods, the fry can be raised.$g$, $g$Harlequin rasboras are common in shops, but breeding them at home takes some care. Pairs lay their eggs on the underside of broad leaves, and they need soft, acidic water to do it. That's why they're a Class D species: the spawn is beautiful to see, and raising the tiny fry takes patience.$g$, $g${"method": "Egg depositor (eggs stuck on the underside of broad leaves)", "sexing": "Males are slimmer with a sharper, more extended black patch; females are rounder", "group": "One pair or 2 males to 1 female", "breeding_tank": "10 gallons, sponge filter, broad leaved plants like Cryptocoryne", "conditioning": "Live or frozen foods like daphnia, bloodworms and brine shrimp for 2 weeks", "trigger": "Soft, acidic water and a warm temperature around 78 to 82°F", "spawn": "Commonly reported from a few dozen to around 100 or more eggs", "eggs": "Hatch in about 1 to 2 days at 78 to 82°F", "fry": "Free swimming about 3 to 5 days after hatching; very small", "first_foods": "Infusoria or fine fry powder, then baby brine shrimp after about a week", "grow_out": "About half an inch by 2 months", "parents": "No care; adults eat eggs and fry, so remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank works well. Use a gentle sponge filter and add several broad leaved plants such as Cryptocoryne or Anubias. Keep light dim.\n\nThe care numbers for this fish list pH 6 to 7.5, GH 2 to 12, and 72 to 80°F, which is fine for keeping them. For spawning, use soft, acidic water: drop pH to about 5.5 to 6.5 and keep GH low, around 2 to 4. Many breeders run the spawning tank slightly warmer, about 78 to 82°F.\n\nSet the breeding tank up a week or two early so the plants settle and the water is stable. A layer of peat or a few almond leaves helps lower pH and gives the water a light tint, which many breeders find helps."}, {"heading": "Choosing and conditioning a pair", "text": "Males are slimmer and their black triangle patch is sharper and extends further down the body. Females are rounder and their patch has a straighter edge. Sexing is easiest when the fish are mature and well fed.\n\nCondition the group with daphnia, bloodworms and brine shrimp for about 2 weeks. Then move a pair, or 2 males and 1 female, into the breeding tank in the evening.\n\nHarlequins are slow to mature. Use fish that are at least 9 months old and full sized. If spawning doesn't happen within a few days, return the pair to the main tank, keep conditioning, and try again in a couple of weeks."}, {"heading": "Spawning: what you'll see", "text": "The male displays around the female and leads her to a broad leaf. She turns upside down under the leaf and presses eggs onto its underside while the male wraps around her to fertilize them. They repeat this over several hours.\n\nA spawn commonly yields from a few dozen to around 100 or more eggs. Remove the adults once they're done, since they will eat eggs.\n\nSome breeders prefer to spawn harlequins in a group in a planted tank and remove the leaves with eggs as they're laid. This works well if you check the plants daily."}, {"heading": "Eggs and fungus", "text": "At 78 to 82°F, the eggs commonly hatch in about 1 to 2 days. The fry hang from the leaves or the glass for the next few days while they use up their yolk.\n\nKeep the tank dark during this time. A few almond leaves or a little methylene blue helps prevent fungus, though many breeders use neither. Remove any fungused eggs carefully with a pipette."}, {"heading": "Raising the fry", "text": "- Days 1 to 7 after free swimming: infusoria or a fine fry powder several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp.\n- Weeks 3 to 6: baby brine shrimp and crushed flake.\n- Water changes: 10% every few days with soft water matched in temperature.\n- Temperature: 78 to 82°F.\n\nFry are tiny and grow slowly at first, so steady feeding matters."}, {"heading": "Growing out", "text": "Expect about half an inch by 2 months. The black patch starts to appear as fry grow, and they look like small harlequins after a few months. Move them to a larger tank and slowly raise hardness to normal keeping levels.\n\nExpect harlequins to take 6 months or more to reach adult size. Keep water clean and feed small meals several times a day. Larger fry can quickly outcompete smaller ones, so sort them if needed."}, {"heading": "Common mistakes", "text": "- Hard, alkaline water; spawning usually fails without soft, acidic water.\n- No broad leaved plants for egg laying.\n- Leaving the parents with the eggs.\n- Feeding baby brine shrimp too early.\n- Bright light in the breeding tank."}]$g$::jsonb, $g$[{"q": "How do harlequin rasboras lay eggs?", "a": "The female turns upside down under a broad leaf and sticks her eggs to its underside while the male fertilizes them."}, {"q": "How long do harlequin rasbora eggs take to hatch?", "a": "Commonly about 1 to 2 days at 78 to 82°F."}, {"q": "How can you tell male and female harlequin rasboras apart?", "a": "Males are slimmer and have a sharper, more extended black patch. Females are rounder."}, {"q": "Why are harlequin rasboras hard to breed?", "a": "They need soft, acidic water and a broad leaf to spawn on, and the fry are very small."}]$g$::jsonb, $g$A photo of the eggs on the underside of a leaf makes a great stage 2 record. Keep your stage 1 photo showing the pair in the breeding tank with the broad leaved plants and your challenge code card.$g$),
  ($g$lambchop-rasbora$g$, $g$f997b54f-5f66-445c-ad27-3ce21abc2d06$g$::uuid, $g$lambchop-rasbora$g$, null, $g$How to Breed Lambchop Rasboras: Soft Water and Leaf Spawning$g$, $g$Lambchop rasboras lay eggs under broad leaves in soft, acidic water; remove the adults and feed tiny foods to raise their very small fry.$g$, $g$The Lambchop Rasbora is a smaller, more orange cousin of the harlequin, and it breeds the same way: eggs laid upside down on the underside of broad leaves. Getting a spawn needs soft, acidic water, and the fry are tiny. That combination makes it a Class D species, but the reward is a tank full of glowing orange juveniles.$g$, $g${"method": "Egg depositor (eggs stuck on the underside of broad leaves)", "sexing": "Males are slimmer, more orange, with a bolder black patch; females are rounder and paler", "group": "One pair or 2 males to 1 female", "breeding_tank": "10 gallons, sponge filter, broad leaved plants like Cryptocoryne", "conditioning": "Live or frozen foods like daphnia and baby brine shrimp for 2 weeks", "trigger": "Soft, acidic water and a warm temperature around 78 to 82°F", "spawn": "Commonly reported in the dozens of eggs per spawn", "eggs": "Hatch in about 1 to 2 days at 78 to 82°F", "fry": "Free swimming about 3 to 5 days after hatching; very small", "first_foods": "Infusoria or fine fry powder, then baby brine shrimp after about a week", "grow_out": "About a third to half an inch by 2 months", "parents": "No care; adults eat eggs and fry, so remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank works, in line with the care numbers for this fish. Use a gentle sponge filter, dim light and broad leaved plants like Cryptocoryne or Anubias.\n\nThe care numbers list pH 6 to 7, GH 2 to 10, and 73 to 82°F. For spawning, go softer and more acidic: about pH 5.5 to 6.5 and GH around 2 to 4, at 78 to 82°F.\n\nSet the tank up a week or two before you plan to spawn, so the plants settle in. Peat or almond leaves help soften and acidify the water and give a light tint."}, {"heading": "Choosing and conditioning a pair", "text": "Males are slimmer, with brighter orange color and a bolder, more defined black lambchop patch. Females are rounder, especially when full of eggs, and paler. Sexing is easiest in mature, well fed fish.\n\nCondition with daphnia, baby brine shrimp and fine frozen foods for about 2 weeks. Move a pair or 2 males and 1 female into the breeding tank in the evening.\n\nLambchops are small, so be patient. Use full sized adults at least 6 to 9 months old. If they don't spawn within a few days, return them to the main tank, keep conditioning, and try again."}, {"heading": "Spawning: what you'll see", "text": "Males display to the female, then the pair swim under a broad leaf. The female turns upside down and sticks her eggs to the underside of the leaf while the male fertilizes them. They repeat this over several hours, usually in the morning.\n\nSpawns are commonly reported in the dozens of eggs. Remove the adults once spawning has finished.\n\nSome breeders prefer to keep a group in a planted tank and remove leaves with eggs as they're laid. This works well as long as you check the plants daily."}, {"heading": "Eggs and fungus", "text": "At 78 to 82°F, the eggs commonly hatch in about 1 to 2 days. The fry then hang from leaves and glass for a few days while they use up their yolk.\n\nKeep the tank dark. A few almond leaves or a little methylene blue can help with fungus. Remove any fungused eggs carefully with a pipette."}, {"heading": "Raising the fry", "text": "- Days 1 to 7 after free swimming: infusoria or a fine fry powder several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp.\n- Weeks 3 to 6: baby brine shrimp and crushed flake.\n- Water changes: 10% every few days with soft water matched in temperature.\n- Temperature: 78 to 82°F.\n\nFry are even smaller than harlequin fry, so be ready with infusoria cultures before the spawn.\n\nUse a small container or a 2 to 5 gallon tank with a sponge filter for the first few weeks. Feed small amounts often and remove leftovers with a pipette to keep the water clean."}, {"heading": "Growing out", "text": "Expect about a third to half an inch by 2 months. Orange color and the black patch develop over a few months. Move them to a larger tank and slowly raise hardness to normal keeping levels.\n\nLambchops reach adult size in about 6 months. Keep them in clean, soft water during grow-out and feed small meals several times a day.\n\nSort fry by size if larger ones start taking most of the food."}, {"heading": "Common mistakes", "text": "- Hard, alkaline water.\n- No broad leaved plants for egg laying.\n- Leaving the adults with the eggs.\n- Feeding baby brine shrimp too early.\n- Bright light in the breeding tank.\n\nIf spawns keep failing, check your water hardness first. Most failed lambchop spawns come down to water that isn't soft enough, rather than the fish themselves."}]$g$::jsonb, $g$[{"q": "How do lambchop rasboras breed?", "a": "The female turns upside down under a broad leaf and sticks her eggs to its underside while the male fertilizes them."}, {"q": "How long do lambchop rasbora eggs take to hatch?", "a": "Commonly about 1 to 2 days at 78 to 82°F."}, {"q": "How can you tell male and female lambchop rasboras apart?", "a": "Males are slimmer and more orange, with a bolder black patch. Females are rounder and paler."}, {"q": "Do lambchop rasboras eat their eggs?", "a": "Yes. Remove the adults after spawning so they don't eat eggs or fry."}]$g$::jsonb, $g$A photo of eggs on the underside of a leaf is a strong stage 2 record. Fry are tiny, so for stage 3 photograph them against a dark background with a light from the side.$g$),
  ($g$adolfos-cory$g$, $g$251b4741-cac5-424d-a5fd-4fc6cf43dbc1$g$::uuid, $g$adolfos-cory$g$, null, $g$How to Breed Adolfo's Corydoras (Corydoras adolfoi)$g$, $g$Adolfo's corydoras spawn in soft, acidic water after cool water changes; eggs are few, and fry need clean water and steady feeding to survive.$g$, $g$Corydoras adolfoi is a black and orange cory from the Rio Negro area that needs soft, acidic water. Adults can be coaxed into spawning with the usual cory tricks, but they lay modest numbers of eggs and the fry can be delicate. That's why this is a Class D species and why breeders take pride in every batch they raise.$g$, $g${"method": "Egg depositor (eggs stuck on glass, plants or decor)", "sexing": "Females are larger and broader from above; males are slimmer", "group": "2 males to 1 female, or a group of 6 or more", "breeding_tank": "20 gallons, sponge filter, sand or bare bottom, plants or mops", "conditioning": "Frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks", "trigger": "Large, slightly cooler water change, often around 70 to 72°F water", "spawn": "Usually modest, commonly reported from a few to a few dozen eggs", "eggs": "Commonly hatch in about 3 to 5 days at 73 to 77°F", "fry": "Live on yolk for a few days, then start feeding on the bottom", "first_foods": "Microworms, baby brine shrimp and fine powdered sinking foods", "grow_out": "About half an inch to 3/4 inch by 2 months", "parents": "No care; adults may eat eggs, so move eggs to a separate container"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well, in line with the care numbers for this fish. Use a sponge filter, a sand or bare bottom, and a few plants or spawning mops for the eggs.\n\nKeep water soft and acidic: pH 5 to 7, GH 1 to 10, and 73 to 79°F. Many breeders use pH around 6 and low hardness for spawning.\n\nLeaf litter, such as dried oak or almond leaves, adds cover and lowers pH slightly. Keep the tank in a quiet spot. Corydoras feel safer with some cover and spawn more readily in a calm tank."}, {"heading": "Choosing and conditioning a group", "text": "Females are larger and broader when seen from above, especially when full of eggs. Males are slimmer. Use 2 males to 1 female, or keep a group of 6 or more.\n\nCondition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks. Keep water clean; Adolfo's corydoras can be sensitive to poor water quality.\n\nIf you're unsure of sexes, keep a group of 6 or more and let them sort themselves out. Groups also spawn more readily than single pairs, because the chasing seems to stimulate them."}, {"heading": "Spawning: what you'll see", "text": "A large water change with slightly cooler water often triggers spawning, the way the rainy season does in the wild. Males chase the female, then a male and female form the classic T position. The female holds a few eggs in her pelvic fins and then sticks them on glass, plants or decor.\n\nAdolfo's corydoras usually lay modest numbers, commonly reported from a few to a few dozen eggs, often spread over a day or two.\n\nIf a water change doesn't trigger spawning, try repeating it every few days, or lowering the temperature by a couple of degrees with the change. Barometric pressure changes before storms also seem to trigger corydoras spawns."}, {"heading": "Eggs and fungus", "text": "Move eggs gently with a finger or credit card edge to a hatching container with tank water and an air stone. At 73 to 77°F, the eggs commonly hatch in about 3 to 5 days.\n\nCory eggs are prone to fungus. Remove white eggs daily, and many breeders add a few almond leaves or a little methylene blue to the hatching container."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 10 to 20% every 2 to 3 days with soft water.\n- Temperature: 73 to 77°F.\n\nA thin layer of sand in the fry container helps, but keep it clean of leftover food."}, {"heading": "Growing out", "text": "Fry reach about half an inch to 3/4 inch by 2 months. Their black and orange markings develop as they grow. Keep water clean and feed small meals often, as losses usually come from dirty water rather than lack of food.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep feeding a mix of baby brine shrimp, microworms and crushed sinking foods."}, {"heading": "Common mistakes", "text": "- Hard or alkaline water.\n- Leaving eggs in the main tank.\n- Overfeeding fry, which fouls the water.\n- No cool water change to trigger spawning.\n- Too few males in the group.\n\nAdolfo's corydoras are often wild caught. Give new fish several weeks to settle and feed well before expecting spawns. Captive-bred fish often settle and spawn more readily."}]$g$::jsonb, $g$[{"q": "How long do Corydoras adolfoi eggs take to hatch?", "a": "Commonly about 3 to 5 days at 73 to 77°F."}, {"q": "How can you tell male and female Adolfo's corydoras apart?", "a": "Females are larger and broader from above. Males are slimmer."}, {"q": "How many eggs do Adolfo's corydoras lay?", "a": "Usually a modest number, commonly reported from a few to a few dozen eggs."}, {"q": "How do you trigger corydoras to spawn?", "a": "A large water change with slightly cooler water often triggers spawning, especially after good conditioning."}]$g$::jsonb, $g$Photograph eggs on the glass before you move them for a clear stage 2 record. Keep your stage 1 photo showing the whole group in the breeding tank with your challenge code card.$g$),
  ($g$bearded-cory$g$, $g$0afca047-5ce8-4e8b-98fe-839a6c84e1ab$g$::uuid, $g$bearded-cory$g$, null, $g$How to Breed Bearded Corydoras (Scleromystax barbatus)$g$, $g$Bearded corydoras need cooler water to breed; with a group, good conditioning and a cool water change, they lay eggs that hatch in about 4 to 6 days.$g$, $g$Scleromystax barbatus is a large, cool water corydoras from southeastern Brazil, and males grow bristles on their cheeks. They don't like the warm water most corydoras get, and that alone stops many people breeding them. That's why this is a Class D species: keep them cool and well fed, and they spawn like other corydoras.$g$, $g${"method": "Egg depositor (eggs stuck on glass, plants or decor)", "sexing": "Males are larger with cheek bristles and stronger color; females are plainer", "group": "2 males to 1 female, or a group of 6 or more", "breeding_tank": "30 gallons, sponge filter, sand bottom, plants or mops", "conditioning": "Frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks", "trigger": "Large water change with cooler water, keeping the tank around 64 to 72°F", "spawn": "Commonly reported from a few dozen to over 100 eggs", "eggs": "Commonly hatch in about 4 to 6 days at 68 to 72°F", "fry": "Live on yolk for a few days, then start feeding on the bottom", "first_foods": "Microworms, baby brine shrimp and fine powdered sinking foods", "grow_out": "About an inch by 2 months", "parents": "No care; adults may eat eggs, so move eggs to a separate container"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank works well, in line with the care numbers for this fish. Use a sponge filter, a sand bottom and a few plants or spawning mops.\n\nKeep water cool: 64 to 75°F, with pH 6 to 7.5 and GH 2 to 12. Many breeders keep the tank around 68 to 72°F for spawning. A room that stays cool helps, since heat in summer can stop breeding.\n\nBearded corydoras like more flow and oxygen than many corydoras. An extra air stone or a small powerhead helps. Keep a lid on the tank, since corydoras sometimes jump when spawning."}, {"heading": "Choosing and conditioning a group", "text": "Unusually for corydoras, males of this species are larger than females. Mature males grow bristles on their cheeks, which gives the bearded name, and show stronger color. Females are plainer without bristles.\n\nUse 2 males to 1 female, or keep a group of 6 or more. Condition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks.\n\nKeep a group of 6 or more if you can. Males may squabble over females, but it rarely leads to injury. A group also helps you confirm sexes as the fish mature."}, {"heading": "Spawning: what you'll see", "text": "A large, cooler water change often triggers spawning. Males chase the female, then a pair form the classic T position. The female holds eggs in her pelvic fins and then sticks them on glass, plants or decor.\n\nBreeders commonly report spawns from a few dozen to over 100 eggs. Spawning can be spread over a day or two.\n\nIf spawning doesn't start after one water change, repeat it every few days. A slightly cooler change, a few degrees below tank temperature, is a common trigger."}, {"heading": "Eggs and fungus", "text": "Move eggs gently to a hatching container with tank water and an air stone. At 68 to 72°F, the eggs commonly hatch in about 4 to 6 days.\n\nRemove white, fungused eggs daily. Many breeders add a few almond leaves or a little methylene blue to the hatching container.\n\nCooler water slows development, so eggs kept toward the lower end of the range may take a day or so longer to hatch. That's normal; just keep removing any fungused eggs and keep the water moving."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 10 to 20% every 2 to 3 days.\n- Temperature: 68 to 72°F; keep fry cool too.\n\nA thin layer of sand in the fry container helps, but keep it clean of leftover food.\n\nFry are fairly robust once they start feeding, but they still need clean water. A few small snails or shrimp in the fry container help clean up leftover food."}, {"heading": "Growing out", "text": "Fry reach about an inch by 2 months with steady feeding. Males start showing cheek bristles as they mature. Keep grow-out tanks cool and well filtered.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep the tank cool and feed a mix of baby brine shrimp, microworms and crushed sinking foods."}, {"heading": "Common mistakes", "text": "- Keeping them too warm, which stops breeding and shortens their lives.\n- Leaving eggs in the main tank.\n- Overfeeding fry, which fouls the water.\n- Assuming the larger fish are females, as with most corydoras.\n\nSummer heat is the most common reason bearded corydoras stop spawning. If your room gets warm, plan your breeding attempts for the cooler months of the year."}]$g$::jsonb, $g$[{"q": "How do you tell male and female bearded corydoras apart?", "a": "Males are larger, with bristles on their cheeks and stronger color. Females are plainer without bristles."}, {"q": "What temperature do bearded corydoras breed at?", "a": "Cool water, commonly around 68 to 72°F. They don't do well kept warm."}, {"q": "How long do bearded corydoras eggs take to hatch?", "a": "Commonly about 4 to 6 days at 68 to 72°F."}, {"q": "How many eggs do bearded corydoras lay?", "a": "Breeders commonly report from a few dozen to over 100 eggs."}]$g$::jsonb, $g$Get the male's cheek bristles in your stage 1 photo with your challenge code card, as it shows a true breeding group. Photograph the eggs on the glass before moving them for stage 2.$g$),
  ($g$clown-pleco$g$, $g$ba898fd7-2a9b-4ad2-be3d-71a0119dafa8$g$::uuid, $g$clown-pleco$g$, null, $g$How to Breed Clown Plecos (L104): Caves, Wood and Fry$g$, $g$Clown plecos are cave spawners: the male guards eggs in a narrow cave, and fry need wood and vegetable foods; give them a quiet, well filtered tank.$g$, $g$The Clown Pleco, L104, is a small wood-eating pleco that spawns in caves, with the male guarding the eggs until the fry leave. Pairs need a quiet tank, good flow and the right cave, and the fry need wood to graze on. It's a Class D species because spawns aren't guaranteed, and raising fry takes care, but a successful spawn is a real achievement.$g$, $g${"method": "Cave spawner (male guards eggs inside a cave)", "sexing": "Males have heavy bristles on the rear body and pectoral spines; females are rounder", "group": "One pair, or 1 male to 2 females", "breeding_tank": "20 gallons or more, strong flow, wood and narrow caves", "conditioning": "Driftwood plus vegetables and quality sinking foods for 2 to 3 weeks", "trigger": "A suitable cave, strong flow and a water change with slightly cooler water", "spawn": "Commonly reported around 10 to 40 eggs", "eggs": "Commonly hatch in about 4 to 7 days at 78 to 82°F", "fry": "Stay in the cave on yolk for about a week, then leave to graze", "first_foods": "Wood plus soft vegetables, algae wafers and gel foods", "grow_out": "Slow; about half an inch to 3/4 inch by 2 months", "parents": "Male guards eggs and fry in the cave; fry are usually left alone"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works for a pair, in line with the care numbers for this fish. Panaqolus graze on wood, so include plenty of driftwood. Add a few narrow caves, about 1 to 1.5 inches wide, made of clay or slate. Use good water flow from a sponge filter or powerhead.\n\nThe care numbers list 73 to 82°F, pH 6.5 to 7.8 and GH 4 to 18. Many breeders spawn them at about 78 to 82°F with clean, well oxygenated water.\n\nKeep the tank in a quiet spot. Clown plecos are shy and nocturnal, so a tank with dim light and little traffic gives them the best chance to settle and breed."}, {"heading": "Choosing and conditioning a pair", "text": "Males have heavy bristles, called odontodes, on the rear half of the body and on the pectoral fin spines. Females are rounder with fewer bristles. Sexing is easiest in adults.\n\nUse one pair or 1 male to 2 females. Condition with driftwood plus zucchini, cucumber and quality sinking foods for 2 to 3 weeks. Clean water matters as much as food.\n\nPairs often take months to settle before they spawn. Keep feeding well, keep water clean and stable, and give them time. Many breeders report their first spawn coming long after the pair was set up."}, {"heading": "Spawning: what you'll see", "text": "The male claims a cave and cleans it. When the female is ready, she joins him inside, and you may see her tail sticking out. She lays the eggs inside the cave and leaves. The male stays and fans the eggs.\n\nClutches are commonly reported around 10 to 40 eggs. A water change with slightly cooler water sometimes triggers spawning.\n\nYou may notice the female looks thinner or the male stops coming out to feed. Those are often the first signs of a spawn inside the cave."}, {"heading": "Eggs and guarding", "text": "At 78 to 82°F, the eggs commonly hatch in about 4 to 7 days. The male stays in the cave the whole time and fans the eggs.\n\nDon't disturb the cave. If the male abandons or ejects the eggs, they can be hatched in a tumbler or a container with gentle water flow, though survival is often lower.\n\nFirst-time males sometimes eat or abandon their first clutch. That often improves with experience, so give the pair another chance before you give up on them."}, {"heading": "Raising the fry", "text": "- First week after hatching: fry stay in the cave and live on their yolk.\n- Week 2: fry leave the cave and graze; give wood, algae wafers and blanched zucchini.\n- Weeks 3 to 8: add gel foods and quality sinking foods.\n- Water changes: 20 to 30% weekly with clean, well oxygenated water.\n- Temperature: 78 to 82°F.\n\nRemove uneaten vegetables daily to keep water clean.\n\nFry often stay near the cave for a few days after leaving it. Place food close by so they find it easily."}, {"heading": "Growing out", "text": "Clown pleco fry grow slowly. Expect about half to 3/4 of an inch by 2 months. Keep wood in the tank at all times, since it's part of their diet.\n\nFeed small amounts several times a day and keep plenty of wood in the tank. Fry do best in a tank with good flow and stable water."}, {"heading": "Common mistakes", "text": "- Caves that are too wide or too large.\n- No driftwood for grazing.\n- Weak water flow and low oxygen.\n- Checking the cave too often.\n- Leaving rotting vegetables in the tank.\n\nPatience is the biggest factor with L104. Pairs that seem uninterested for months often start spawning once they feel settled, so keep the tank stable and keep feeding well."}]$g$::jsonb, $g$[{"q": "How can you tell male and female L104 apart?", "a": "Males have heavy bristles on the rear body and pectoral spines. Females are rounder with fewer bristles."}, {"q": "Do clown plecos need caves to breed?", "a": "Yes. They spawn in narrow caves, and the male guards the eggs inside."}, {"q": "How many eggs do clown plecos lay?", "a": "Clutches are commonly reported around 10 to 40 eggs."}, {"q": "What do clown pleco fry eat?", "a": "Driftwood, algae wafers, blanched vegetables and gel foods."}]$g$::jsonb, $g$For stage 2, a quick photo into the cave mouth with a small flashlight showing the egg clump gives clear evidence; take it in one try and never pull the male out. For stage 3, photograph fry grazing on wood outside the cave.$g$),
  ($g$duplicareus-corydoras$g$, $g$d635073b-6aa5-4fa4-aa7b-cff8760f0978$g$::uuid, null, null, $g$How to Breed Corydoras duplicareus: Soft Water and Fry Care$g$, $g$Corydoras duplicareus breeds much like its look-alike C. adolfoi: soft, acidic water, cool water changes, eggs moved to a container and careful fry care.$g$, $g$Corydoras duplicareus is a Rio Negro cory that looks very much like Adolfo's corydoras. It's bred less often in the hobby and fewer detailed reports exist, but breeders report it spawns the same way as its relatives. That makes it a Class D species: the method is familiar, and getting soft water right and raising the fry is where the effort goes.$g$, $g${"method": "Egg depositor (eggs stuck on glass, plants or decor)", "sexing": "Females are larger and broader from above; males are slimmer", "group": "2 males to 1 female, or a group of 6 or more", "breeding_tank": "20 gallons, sponge filter, sand or bare bottom, plants or mops", "conditioning": "Frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks", "trigger": "Large, slightly cooler water change after good conditioning", "spawn": "Usually modest; breeders report small batches, often a few dozen eggs or fewer", "eggs": "Commonly hatch in about 3 to 5 days at 73 to 77°F", "fry": "Live on yolk for a few days, then start feeding on the bottom", "first_foods": "Microworms, baby brine shrimp and fine powdered sinking foods", "grow_out": "About half an inch to 3/4 inch by 2 months", "parents": "No care; adults may eat eggs, so move eggs to a separate container"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank works well. Use a sponge filter, a sand or bare bottom, and a few plants or spawning mops for the eggs.\n\nThis is a soft water fish from the Rio Negro area. Breeders commonly use pH around 5.5 to 6.5, low hardness and a temperature of about 73 to 79°F. Keep the tank clean and stable, since soft water fish can be sensitive to poor water quality.\n\nLeaf litter, such as dried oak or almond leaves, adds cover and lowers pH slightly. Keep the tank in a quiet spot with dim light, as corydoras feel safer with some cover and spawn more readily in a calm tank."}, {"heading": "Choosing and conditioning a group", "text": "Females are larger and broader when seen from above, especially when full of eggs. Males are slimmer. Use 2 males to 1 female, or keep a group of 6 or more.\n\nC. duplicareus is easily confused with C. adolfoi, which has a narrower black band. Make sure your group is all one species before you breed them, so you don't end up with mixed fry.\n\nCondition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks.\n\nSince this species is less common, many breeders start with a group of wild-caught or captive-bred juveniles and grow them up together. Groups spawn more readily than single pairs."}, {"heading": "Spawning: what you'll see", "text": "A large water change with slightly cooler water often triggers spawning, as with most corydoras. Males chase the female, then a male and female form the classic T position. The female holds a few eggs in her pelvic fins and sticks them on glass, plants or decor.\n\nDetailed spawning reports are fewer than for common corydoras, but breeders report small batches, often a few dozen eggs or fewer, sometimes spread over a day or two.\n\nIf a water change doesn't trigger spawning, try repeating it every few days, or lowering the temperature by a couple of degrees with the change."}, {"heading": "Eggs and fungus", "text": "Move eggs gently with a finger to a hatching container with tank water and an air stone. At 73 to 77°F, eggs of related species commonly hatch in about 3 to 5 days, and reports for this species fit that range.\n\nRemove white, fungused eggs daily. Many breeders add a few almond leaves or a little methylene blue to the hatching container."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 10 to 20% every 2 to 3 days with soft water.\n- Temperature: 73 to 77°F.\n\nKeep the fry container clean of leftover food.\n\nA few small snails in the fry container help clean up leftover food without harming the fry."}, {"heading": "Growing out", "text": "Fry reach about half to 3/4 of an inch by 2 months. The dark band develops as they grow. Keep water clean and soft, and feed small meals often.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep feeding a mix of baby brine shrimp, microworms and crushed sinking foods."}, {"heading": "Common mistakes", "text": "- Hard or alkaline water.\n- Mixing C. duplicareus with C. adolfoi in the breeding group.\n- Leaving eggs in the main tank.\n- Overfeeding fry, which fouls the water.\n\nWild-caught fish may take several weeks to settle and condition before they spawn. Keep feeding well and keep the water clean and stable."}]$g$::jsonb, $g$[{"q": "What is the difference between Corydoras duplicareus and adolfoi?", "a": "They look very similar. C. duplicareus has a wider black band on the back than C. adolfoi."}, {"q": "How long do Corydoras duplicareus eggs take to hatch?", "a": "Commonly about 3 to 5 days at 73 to 77°F, like related corydoras."}, {"q": "How can you tell male and female Corydoras duplicareus apart?", "a": "Females are larger and broader from above. Males are slimmer."}, {"q": "Is Corydoras duplicareus hard to breed?", "a": "It needs soft, acidic water and careful fry care, and it's bred less often than common corydoras."}]$g$::jsonb, $g$Because this fish is easily confused with C. adolfoi, take a clear top-down photo of the group for stage 1 that shows the band width, with your challenge code card in the shot.$g$),
  ($g$emerald-cory$g$, $g$23c1a48c-ff4e-4ef5-9475-730cf94af540$g$::uuid, $g$emerald-cory$g$, null, $g$How to Breed Emerald Corydoras (Brochis splendens)$g$, $g$Emerald corydoras need a large tank, a group and cool water changes to spawn; they can lay large clutches, and the fry need clean water and steady feeding.$g$, $g$The Emerald Corydoras, often listed as Brochis splendens, is a big, shiny green catfish. It's bred commercially, but home spawns are less common than with smaller corydoras, and it needs more room. That's why it's a Class D species: once a group settles and spawns, clutches can be large, and raising them is the main job.$g$, $g${"method": "Egg depositor (eggs stuck on plants, glass or under floating plants)", "sexing": "Hard; females are larger and broader from above, males slimmer", "group": "A group of 6 or more with more males than females", "breeding_tank": "30 gallons or more, sponge filter, sand bottom, plants", "conditioning": "Frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks", "trigger": "Large, slightly cooler water change after good conditioning", "spawn": "Breeders report large clutches, sometimes a few hundred eggs", "eggs": "Commonly hatch in about 3 to 5 days at 75 to 79°F", "fry": "Live on yolk for a few days, then start feeding on the bottom", "first_foods": "Microworms, baby brine shrimp and fine powdered sinking foods", "grow_out": "About 3/4 inch to 1 inch by 2 months", "parents": "No care; adults may eat eggs, so move eggs to a separate container"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank or larger is a good start, in line with the care numbers for this fish. Use a sponge filter, a sand bottom and plenty of plants, including some floating plants, since this species often lays eggs on leaves.\n\nThe care numbers list 72 to 82°F, pH 6.5 to 7.5 and GH 2 to 15. Many breeders spawn them at about 75 to 79°F with soft to medium water.\n\nEmerald corydoras are larger than most corydoras, so give them open sand to forage and plenty of room. A lid is a good idea, since corydoras sometimes jump during spawning."}, {"heading": "Choosing and conditioning a group", "text": "Sexing is hard. Females are larger and broader when seen from above, especially when full of eggs. Males are slimmer. Buy a group of 6 or more and let them sort themselves out.\n\nCondition with frozen bloodworms, brine shrimp and quality sinking foods for 2 to 3 weeks. Keep water clean with weekly water changes.\n\nHome spawns of this species are less common than with smaller corydoras, so be patient. Some groups take months to settle before they spawn. Keep conditioning and keep water clean and stable."}, {"heading": "Spawning: what you'll see", "text": "A large water change with slightly cooler water can trigger spawning. Males chase the female, then a pair form a T position like other corydoras. The female sticks eggs to plants, glass or the underside of floating plant leaves.\n\nBreeders report large clutches, sometimes a few hundred eggs, spread over several hours or days. Remove eggs as they're laid, since adults may eat them.\n\nIf a water change doesn't trigger spawning, try repeating it every few days, or lowering the temperature by a couple of degrees with the change."}, {"heading": "Eggs and fungus", "text": "Move eggs gently to a hatching container with tank water and an air stone. At 75 to 79°F, the eggs commonly hatch in about 3 to 5 days.\n\nRemove white, fungused eggs daily. Large clutches mean more fungus risk, so spread eggs over two containers if needed. Almond leaves or a little methylene blue help.\n\nInfertile eggs turn white within a day or so. Remove them quickly, as fungus can spread from them to healthy eggs."}, {"heading": "Raising the fry", "text": "- First few days: fry live on their yolk; don't feed yet.\n- Week 1 of feeding: microworms and fine powdered sinking foods twice a day.\n- Weeks 2 to 4: add baby brine shrimp and crushed sinking pellets.\n- Water changes: 20% every 2 to 3 days.\n- Temperature: 75 to 79°F.\n\nWith big clutches, split the fry over several tanks to keep water clean.\n\nA few small snails in the fry container help clean up leftover food without harming the fry."}, {"heading": "Growing out", "text": "Fry reach about 3/4 inch to an inch by 2 months. Their green shine develops as they grow. Keep the grow-out tank clean and well fed, and plan for space: this species reaches about 3 inches.\n\nMove fry to a larger tank with a sand bottom once they're about half an inch. Keep feeding a mix of baby brine shrimp, microworms and crushed sinking foods.\n\nGrow fry with a few other peaceful fish or on their own, and keep water changes regular so their barbels stay healthy on the sand."}, {"heading": "Common mistakes", "text": "- A tank that's too small for a breeding group.\n- Leaving eggs in the main tank.\n- Overcrowding fry from a large clutch.\n- Overfeeding, which fouls the water.\n\nWild-caught fish may take a long time to settle. Captive-bred fish are often easier to spawn, so they're a good place to start."}]$g$::jsonb, $g$[{"q": "How can you tell male and female emerald corydoras apart?", "a": "It's hard. Females are larger and broader from above, and males are slimmer."}, {"q": "How many eggs do emerald corydoras lay?", "a": "Breeders report large clutches, sometimes a few hundred eggs."}, {"q": "How long do emerald corydoras eggs take to hatch?", "a": "Commonly about 3 to 5 days at 75 to 79°F."}, {"q": "Where do emerald corydoras lay their eggs?", "a": "On plants, glass and often under floating plant leaves."}]$g$::jsonb, $g$Emerald clutches can be large, so take your stage 2 photo of eggs on leaves or glass before you move them. For stage 5, catch a few 60-day juveniles into a clear container for a sharp photo with your challenge code card.$g$),
  ($g$royal-whiptail$g$, $g$cbfe6720-d4c3-41da-b9c6-c943722d591d$g$::uuid, null, null, $g$How to Breed Royal Whiptail Catfish (Sturisoma panamense)$g$, $g$Royal whiptails lay eggs on glass or smooth surfaces in good flow, and the male guards them; fry need clean water and food right after hatching.$g$, $g$The Royal Whiptail (Sturisomatichthys panamensis, long sold as Sturisoma panamense) is a slim catfish from Panama and Colombia, and one of the more regularly bred whiptails. Pairs lay eggs on the glass or smooth surfaces, and the male guards them until they hatch. It's a Class D species because the fry are delicate: they need clean, well oxygenated water and food right away.$g$, $g${"method": "Open spawner on glass or smooth surfaces; male guards eggs", "sexing": "Mature males grow bristles on the sides of the head; females lack them", "group": "One pair, or 2 males to 2 or 3 females", "breeding_tank": "30 gallons or more, strong flow, smooth surfaces, sponge filter", "conditioning": "Vegetables, algae wafers and frozen foods for 2 to 3 weeks", "trigger": "Strong flow, clean water and good conditioning", "spawn": "Commonly reported from several dozen to over 100 eggs", "eggs": "Commonly hatch in about 6 to 9 days at 75 to 79°F", "fry": "Start feeding soon after hatching; delicate in the first weeks", "first_foods": "Green water, fine algae and vegetable powders, microworms and baby brine shrimp", "grow_out": "About an inch to 1.5 inches by 2 months", "parents": "Male guards eggs until hatching; fry are on their own after that"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank or larger gives a pair room. Use good water flow from a powerhead or strong sponge filter, since whiptails like current and oxygen. Add smooth surfaces such as flat stones, driftwood or plastic tubes, though they often spawn on the glass.\n\nKeep water clean and stable. Many breeders use about 75 to 79°F with soft to medium hardness and pH around 6.5 to 7.5.\n\nWhiptails do best with calm tankmates. Fast or boisterous fish compete for food and stress the pair. A species tank or a tank with a few peaceful small fish works best."}, {"heading": "Choosing and conditioning a pair", "text": "Mature males grow bristles, called odontodes, on the sides of the head. Females lack these bristles. Sexing is easy in adults and hard in juveniles.\n\nUse one pair, or a small group with 2 males and 2 or 3 females. Condition with zucchini, cucumber, algae wafers and frozen bloodworms or brine shrimp for 2 to 3 weeks.\n\nWhiptails are slow eaters, so make sure food reaches them, especially in a mixed tank. Feed after lights out if they're shy."}, {"heading": "Spawning: what you'll see", "text": "The male picks a smooth spot, often on the glass near the filter outflow, and cleans it. The female lays eggs in a single layer and the male fertilizes them. The male then sits on or next to the eggs and guards them.\n\nClutches are commonly reported from several dozen to over 100 eggs. The eggs darken as they develop.\n\nMany pairs spawn again within a few weeks if well fed. Once a pair is settled, they often spawn regularly."}, {"heading": "Eggs and guarding", "text": "At 75 to 79°F, the eggs commonly hatch in about 6 to 9 days. The male guards them the whole time. Don't disturb him, and keep water flow over the eggs.\n\nIf the male leaves the eggs, they can be scraped off gently with a razor blade and hatched in a container with an air stone, though survival is usually lower.\n\nAs the eggs develop, they turn darker. That's a sign they are close to hatching. Keep feeding the male lightly during this time; most males guard well when they're undisturbed."}, {"heading": "Raising the fry", "text": "- First few days: fry use up their yolk and start grazing quickly.\n- Week 1: green water, fine algae powder, crushed algae wafers and microworms.\n- Weeks 2 to 4: add baby brine shrimp, blanched vegetables and gel foods.\n- Water changes: 20 to 30% every 2 to 3 days.\n- Temperature: 75 to 79°F.\n\nFry need food available all the time, but uneaten food quickly fouls the water. Small, frequent feeds and gentle siphoning help.\n\nA bare bottom or thin sand layer in the fry tank makes it much easier to see and remove leftover food. Some breeders add a little established biofilm from a mature tank, such as a rock or piece of wood, for fry to graze on."}, {"heading": "Growing out", "text": "Fry reach about 1 to 1.5 inches by 2 months. Keep a steady supply of vegetables and algae foods. Survival improves once they're past the first few weeks.\n\nKeep the grow-out tank clean, with good flow, and feed vegetables and algae foods several times a day. Avoid crowding, since whiptail fry do best with plenty of room."}, {"heading": "Common mistakes", "text": "- Weak flow and low oxygen.\n- Starving fry in the first few days.\n- Leaving uneaten food to rot.\n- Disturbing the guarding male.\n- Fast-moving tankmates that eat eggs or fry.\n\nMost losses happen in the first two weeks after hatching. Keeping food available, water clean and flow steady during that time is the key to raising a batch."}]$g$::jsonb, $g$[{"q": "How do you sex royal whiptail catfish?", "a": "Mature males grow bristles on the sides of the head. Females lack them."}, {"q": "How long do whiptail catfish eggs take to hatch?", "a": "Commonly about 6 to 9 days at 75 to 79°F."}, {"q": "Where do royal whiptails lay their eggs?", "a": "Usually on the glass or smooth surfaces in good water flow."}, {"q": "What do whiptail catfish fry eat?", "a": "Green water, algae powder, crushed algae wafers, microworms and baby brine shrimp."}]$g$::jsonb, $g$Eggs on the glass make an easy stage 2 photo; shoot from outside the tank so you don't disturb the male. For stage 3, photograph the fry grazing on the glass or on vegetables.$g$),
  ($g$congo-tetra$g$, $g$438e0116-a646-480a-833f-357541ceb367$g$::uuid, $g$congo-tetra$g$, null, $g$How to Breed Congo Tetras: Soft Water, Big Eggs and Fry$g$, $g$Congo tetras scatter large eggs in soft, slightly acidic water; remove the adults, wait about 6 days for hatching and raise fry on tiny foods.$g$, $g$Congo tetras are big, shimmering African tetras that scatter their eggs over plants or a mesh. Spawning is not hard with good conditioning, but the eggs take several days to hatch and the adults will eat them. That's why this is a Class D species: patience and soft water get the eggs, and steady care raises the fry.$g$, $g${"method": "Egg scatterer (non-adhesive eggs fall among plants or a mesh)", "sexing": "Males are larger with longer, white-edged fins and more color; females are smaller", "group": "1 male to 2 females, or a small group", "breeding_tank": "30 gallons, sponge filter, spawning mesh or fine plants over the bottom", "conditioning": "Live or frozen foods like bloodworms, brine shrimp and daphnia for 2 to 3 weeks", "trigger": "Soft, slightly acidic water, morning light and a fresh water change", "spawn": "Commonly reported up to about 300 eggs", "eggs": "Commonly hatch in about 5 to 7 days at 75 to 79°F", "fry": "Free swimming a few days after hatching; larger than most tetra fry", "first_foods": "Infusoria or fine fry powder briefly, then baby brine shrimp", "grow_out": "About an inch by 2 months", "parents": "No care; adults eat eggs, so remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 30 gallon tank is a good size, in line with the care numbers for this fish. Use a sponge filter and cover the bottom with a spawning mesh, marbles or a thick layer of fine leaved plants so eggs fall out of reach of the adults.\n\nThe care numbers list pH 6 to 7.5, GH 4 to 18, and 73 to 82°F. For spawning, use softer, slightly acidic water: about pH 6 to 6.5 and low hardness, at 75 to 79°F. Many breeders filter through peat.\n\nSet up the tank a week or two before spawning so it's stable. Morning sunlight or a light on a timer helps, since Congo tetras often spawn as the light comes up."}, {"heading": "Choosing and conditioning fish", "text": "Males are larger with longer fins, white edges, a ragged extension in the middle of the tail, and stronger colors. Females are smaller and plainer.\n\nCondition males and females separately for 2 to 3 weeks with live or frozen foods like bloodworms, brine shrimp and daphnia. Then add 1 male and 2 females to the breeding tank in the evening.\n\nCongo tetras mature at around a year old. Choose full sized, healthy adults. If they don't spawn within a few days, return them to the main tank, keep conditioning, and try again."}, {"heading": "Spawning: what you'll see", "text": "Spawning usually happens in the morning, often helped by sunlight. The male chases the female, then the pair swim side by side and release eggs that fall to the bottom.\n\nCommonly reported spawns are up to about 300 eggs. Remove the adults once spawning has finished, since they will eat the eggs.\n\nSome breeders prefer to spawn a small group, which can give larger spawns. Either way, make sure the bottom is well covered, so eggs fall out of reach."}, {"heading": "Eggs and fungus", "text": "Congo tetra eggs are large and take longer to hatch than most tetra eggs. At 75 to 79°F, they commonly hatch in about 5 to 7 days.\n\nRemove fungused eggs daily with a pipette. Keep the tank dim and add a little methylene blue or almond leaves to help prevent fungus.\n\nCongo eggs are not sticky, so they fall to the bottom and stay there. A mesh or marbles on the bottom keeps them safe from the adults while they develop."}, {"heading": "Raising the fry", "text": "- First few days of swimming: infusoria or a fine fry powder.\n- Week 1 to 3: newly hatched baby brine shrimp and microworms.\n- Weeks 3 to 6: add crushed flake.\n- Water changes: 10 to 20% every few days.\n- Temperature: 75 to 79°F.\n\nCongo fry are bigger than most tetra fry, so they move onto baby brine shrimp fairly quickly.\n\nKeep the fry tank lightly lit. Too much light can encourage algae and stress young fish."}, {"heading": "Growing out", "text": "Expect about an inch by 2 months. Fry grow quickly with good feeding and clean water. Males start showing longer fins and color as they mature over several months.\n\nMove fry to a larger tank as they grow, and keep water clean with frequent changes. Feed small meals several times a day.\n\nJuveniles are peaceful but active, so a longer tank gives them room to swim."}, {"heading": "Common mistakes", "text": "- Leaving the adults with the eggs.\n- Giving up before the eggs hatch; they take about a week.\n- Hard, alkaline water.\n- Fungus spreading from dead eggs.\n\nIf spawns keep failing, check that both fish are mature and well conditioned. Young Congo tetras often fail to spawn even in good conditions."}]$g$::jsonb, $g$[{"q": "How long do Congo tetra eggs take to hatch?", "a": "Commonly about 5 to 7 days at 75 to 79°F, longer than most tetras."}, {"q": "How can you tell male and female Congo tetras apart?", "a": "Males are larger with longer, white-edged fins and stronger colors. Females are smaller and plainer."}, {"q": "How many eggs do Congo tetras lay?", "a": "Commonly reported up to about 300 eggs."}, {"q": "Do Congo tetras eat their eggs?", "a": "Yes. Remove the adults after spawning."}]$g$::jsonb, $g$Photograph the eggs on the mesh or bottom for stage 2. Eggs take about a week to hatch, so log stage 3 once the fry are actually swimming freely; that will be well past the 3 day minimum after stage 2.$g$),
  ($g$neon-tetra$g$, $g$5d0a6911-40b4-4112-9927-393f62c7e2f5$g$::uuid, $g$neon-tetra$g$, null, $g$How to Breed Neon Tetras: Soft Water, Darkness and Fry$g$, $g$Neon tetras spawn in very soft, acidic water in dim light; eggs hatch in about a day, and fry need darkness and tiny foods for the first week or two.$g$, $g$Neon tetras are one of the most popular aquarium fish, but home breeding is trickier than you might expect. They need very soft, acidic water and dim light, and both eggs and fry are light sensitive. That's why neons are a Class D species: get the water right and they spawn, and careful fry care does the rest.$g$, $g${"method": "Egg scatterer (slightly adhesive eggs scattered over fine plants or mops)", "sexing": "Females are rounder with a bent blue stripe; males are slimmer with a straight stripe", "group": "One pair or 2 males to 1 female", "breeding_tank": "5 to 10 gallons, sponge filter, dim light, fine plants or mops", "conditioning": "Live or frozen foods like daphnia and brine shrimp for 2 weeks", "trigger": "Very soft, acidic water and dim light", "spawn": "Commonly reported about 60 to 130 eggs", "eggs": "Hatch in about 1 day at 75 to 77°F", "fry": "Free swimming about 3 to 5 days after hatching; very small", "first_foods": "Infusoria or fine fry powder, then baby brine shrimp after about a week", "grow_out": "About half an inch by 2 months", "parents": "No care; adults eat eggs, so remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A small 5 to 10 gallon tank works. Use a gentle sponge filter, a dark bottom, fine plants or spawning mops, and cover the sides to keep it dim.\n\nThe care numbers list pH 5 to 7, GH 1 to 10 and 70 to 81°F. For spawning, use very soft, acidic water: about pH 5 to 6 and GH around 1 to 2, at about 75 to 77°F. RO or rain water is commonly used to get it soft enough.\n\nSet up the breeding tank a week or two early, so it's stable. Peat or almond leaves help lower pH and tint the water. Clean everything well, since soft water has little buffering and bacteria and fungus can grow quickly."}, {"heading": "Choosing and conditioning a pair", "text": "Females are rounder, which makes their blue stripe look bent. Males are slimmer with a straight stripe. Choose adult fish that are at least 6 months old.\n\nCondition with live or frozen foods like daphnia and brine shrimp for about 2 weeks. Move a pair or 2 males and 1 female into the breeding tank in the evening.\n\nIf a pair doesn't spawn within a few days, return them to the main tank, keep conditioning, and try again in a couple of weeks."}, {"heading": "Spawning: what you'll see", "text": "Spawning usually happens in the early morning. The male chases the female into the plants and the pair release eggs that stick lightly to the plants or fall to the bottom.\n\nCommonly reported spawns are about 60 to 130 eggs. Remove the adults once they've finished, since they eat eggs.\n\nSome breeders cover the tank with dark paper or a cloth, leaving only a little light. This keeps eggs and fry from light and helps the adults feel secure."}, {"heading": "Eggs and fungus", "text": "Keep the tank dark. Neon eggs and fry are sensitive to light. At 75 to 77°F, the eggs commonly hatch in about a day.\n\nRemove white, fungused eggs with a pipette. Keep the water still and clean, and avoid big changes.\n\nSoft, acidic water helps keep fungus down, but it also has little buffering, so keep an eye on pH. Avoid adding anything that could cause sudden changes."}, {"heading": "Raising the fry", "text": "- Days 1 to 5: fry hang on plants and glass and use up their yolk.\n- Week 1 of swimming: infusoria or a fine fry powder several times a day.\n- Week 2: add microworms and newly hatched baby brine shrimp.\n- Weeks 3 to 6: baby brine shrimp and crushed flake.\n- Water changes: 10% every few days, matched carefully.\n- Temperature: 75 to 77°F.\n\nKeep the light low for the first week or two, then slowly increase it.\n\nUse an infusoria culture started a week before spawning, so you have food ready when the fry need it."}, {"heading": "Growing out", "text": "Expect about half an inch by 2 months. The blue and red stripes develop as fry grow. Slowly raise hardness to normal keeping levels over a few weeks.\n\nGrow fry in a tank with gentle flow and some cover. Keep feeding small meals several times a day. Neon tetras grow slowly, reaching adult size in about 6 months."}, {"heading": "Common mistakes", "text": "- Hard water; neons rarely spawn without very soft water.\n- Bright light on eggs and fry.\n- Leaving the adults with the eggs.\n- Feeding baby brine shrimp too early.\n\nPatience matters with neons. Many breeders need several attempts before their first successful spawn, and getting water soft enough is usually the key."}]$g$::jsonb, $g$[{"q": "How long do neon tetra eggs take to hatch?", "a": "Commonly about a day at 75 to 77°F."}, {"q": "How can you tell male and female neon tetras apart?", "a": "Females are rounder and their blue stripe looks bent. Males are slimmer with a straight stripe."}, {"q": "Why are neon tetras hard to breed?", "a": "They need very soft, acidic water and dim light, and their fry are tiny."}, {"q": "Do neon tetras eat their eggs?", "a": "Yes. Remove the adults after spawning."}]$g$::jsonb, $g$Neon eggs and fry are light sensitive, so take stage 2 and stage 3 photos quickly with low light. For stage 5, catch a few fish into a small container for a clear photo with your challenge code card.$g$),
  ($g$silver-dollar$g$, $g$62ea6c97-6591-4c12-80c8-b115f0523ec1$g$::uuid, $g$silver-dollar$g$, null, $g$How to Breed Silver Dollars: Big Tanks, Soft Water and Fry$g$, $g$Silver dollars scatter large numbers of eggs in soft, warm water; you need a big tank and a group, and the fry are easy to feed once free swimming.$g$, $g$Silver dollars are big, peaceful schooling fish, and breeding them mostly comes down to space. Given a large tank, soft water and a settled group, they can lay large numbers of eggs among plants. That's why they're a Class D species: the hard part is the setup, not the fry.$g$, $g${"method": "Egg scatterer (non-adhesive eggs fall among plants)", "sexing": "Males have a longer, lobed anal fin edged in red; females have a plain anal fin", "group": "A school of 6 or more with mixed sexes", "breeding_tank": "75 gallons or more, soft water, plants and dim light", "conditioning": "Vegetables, plant-based foods and some frozen foods for 2 to 3 weeks", "trigger": "Soft, slightly acidic water and a warm temperature", "spawn": "Commonly reported in the hundreds, sometimes up to about 2000 eggs", "eggs": "Commonly hatch in about 3 days at 79 to 82°F", "fry": "Free swimming roughly a week after hatching", "first_foods": "Infusoria and baby brine shrimp, then crushed flake", "grow_out": "About an inch by 2 months", "parents": "No care; adults usually don't eat many eggs, but moving eggs is safer"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Silver dollars need a big tank. The care numbers for this fish list 75 gallons as a minimum, and breeding groups do better in larger tanks. Use a sponge or canister filter, dim light and fine leaved plants or floating plants for cover.\n\nThe care numbers list pH 5.5 to 7.5, GH 4 to 15 and 75 to 82°F. Many breeders use soft, slightly acidic water for spawning, about pH 6 to 6.5, at around 79 to 82°F.\n\nPlastic or hardy plants are a good choice, since silver dollars eat most soft plants. Floating plants also help the fish feel secure. Keep a tight lid on, since they can jump when startled."}, {"heading": "Choosing and conditioning a group", "text": "Males have a longer, lobed anal fin with a red edge. Females have a plain, straight anal fin. Keep a school of 6 or more so pairs can form.\n\nCondition with vegetables, plant-based foods and some frozen foods like bloodworms for 2 to 3 weeks. Silver dollars eat plants, so live plants in the breeding tank may be eaten.\n\nSilver dollars mature at around a year old and several inches long. Keep a mixed group and be patient; pairs form on their own once the fish are settled and mature."}, {"heading": "Spawning: what you'll see", "text": "Males chase females and the pair swim side by side, releasing eggs that drop among plants and to the bottom. Spawning often happens in the morning.\n\nSpawns are commonly reported in the hundreds, sometimes up to about 2000 eggs. Adults usually don't eat many eggs, but moving the eggs or adults gives better results.\n\nIf you want to raise a lot of fry, siphon eggs from the bottom into a separate tank or move the adults after spawning. Leaving eggs in a busy tank with other fish usually means few survive."}, {"heading": "Eggs and fungus", "text": "At 79 to 82°F, the eggs commonly hatch in about 3 days. Fry then rest on the bottom while they use up their yolk.\n\nRemove white, fungused eggs. A little methylene blue or almond leaves can help prevent fungus spreading.\n\nSilver dollar eggs are not sticky, so they fall to the bottom. If you siphon them into a separate tank, use water from the breeding tank to avoid any shock."}, {"heading": "Raising the fry", "text": "- First few days of swimming: infusoria or a fine fry powder.\n- Weeks 1 to 3: newly hatched baby brine shrimp several times a day.\n- Weeks 3 to 6: crushed flake and blanched vegetables.\n- Water changes: 20% every few days.\n- Temperature: 79 to 82°F.\n\nFry usually start swimming roughly a week after hatching, once the yolk is used up.\n\nFry grow fast and eat a lot. Keep the water clean with regular changes, and remove uneaten food every day."}, {"heading": "Growing out", "text": "Expect about an inch by 2 months. Fry grow quickly with good feeding and clean water. Plan ahead: silver dollars reach about 6 inches, and a big spawn needs a lot of space.\n\nFeed small amounts several times a day and keep water clean. Move fry to larger tanks as they grow, since crowded fry grow slowly.\n\nSilver dollars grow fast in their first year, so check that grow-out tanks have enough filtration and space. Splitting large batches over several tanks keeps water quality up and growth even."}, {"heading": "Common mistakes", "text": "- A tank that's too small for a breeding group.\n- Hard, alkaline water.\n- Not planning for hundreds of fry.\n- Leaving fungused eggs to spread.\n\nMost failed attempts come from tanks that are too small or crowded. Silver dollars need space and calm to breed well."}]$g$::jsonb, $g$[{"q": "How many eggs do silver dollars lay?", "a": "Commonly reported in the hundreds, sometimes up to about 2000 eggs."}, {"q": "How can you tell male and female silver dollars apart?", "a": "Males have a longer, lobed anal fin with a red edge. Females have a plain anal fin."}, {"q": "How long do silver dollar eggs take to hatch?", "a": "Commonly about 3 days at 79 to 82°F."}, {"q": "Do silver dollars eat their eggs?", "a": "They usually don't eat many, but moving eggs or adults gives better survival."}]$g$::jsonb, $g$For stage 1, show the whole school in the tank with your challenge code card. Take your stage 2 photo of eggs on the bottom or among plants before you move them.$g$),
  ($g$german-blue-ram$g$, $g$f23bf5d7-0df6-440a-b9a1-f8342d7dc029$g$::uuid, $g$german-blue-ram$g$, null, $g$How to Breed German Blue Rams: Pairs, Eggs and Raising Fry$g$, $g$Breeding German blue rams takes a bonded pair, warm soft water and spotless conditions. A Class D guide to spawning, hatching and raising the tiny fry.$g$, $g$German blue rams spawn more readily than their reputation suggests, but getting fry to grow up is the real test. Pairs lay on flat stones in warm, soft, clean water, and young pairs often eat their first few clutches. With stable water, small daily feedings and patience, you can raise a batch of these little jewels and earn one of the more respected dwarf cichlid certificates.$g$, $g${"method": "Substrate spawner (open spawner on flat stones or in shallow pits)", "sexing": "Males larger with longer front dorsal rays; females show a pink to red belly. Not foolproof", "group": "One bonded pair, ideally formed from a group of 6 juveniles", "breeding_tank": "15 to 20 gallons, sponge filter, flat stone, soft water, no tankmates", "conditioning": "Two to three weeks of frozen bloodworms, brine shrimp and quality small pellets", "trigger": "Stable 82 to 85°F water, soft acidic conditions and a clean flat surface", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 2 to 3 days at 82 to 85°F", "fry": "Free swimming roughly 3 to 5 days after hatching; very small", "first_foods": "Infusoria or vinegar eels, then microworms and newly hatched brine shrimp", "grow_out": "Roughly 1 inch in about 2 to 3 months with frequent water changes", "parents": "Good pairs guard eggs and fry; young pairs often eat early clutches"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 15 to 20 gallon tank is plenty for one pair. Use a mature sponge filter so fry are not sucked in, a thin layer of fine sand or a bare bottom, and one or two flat stones or slate pieces as spawning sites. A few plants and a piece of driftwood help the pair feel secure.\n\nKeep the water at 82 to 85°F, which sits within the 78 to 85°F range rams live in, and aim for pH 5.5 to 6.5 with GH under about 8. Rams are very sensitive to nitrate and ammonia, so the tank should be fully cycled and you should plan on 25 to 30 percent water changes at least twice a week. Keep the tank free of other fish so the pair are not stressed into eating eggs."}, {"heading": "Choosing and conditioning a pair", "text": "The easiest way to get a compatible pair is to grow up 6 young rams and let two pair off on their own. Males are usually larger, with the second and third dorsal spines extended. Females tend to be rounder and show a pink, red or orange belly, especially when ready to spawn. Many keepers also say females have blue spangles in the black dorsal spot, but this is not reliable on its own.\n\nCondition for two to three weeks with small meals two or three times a day: frozen bloodworms, brine shrimp, daphnia and a good small pellet. Remove uneaten food quickly, since leftovers foul soft water fast."}, {"heading": "Spawning: what you will see", "text": "A ready pair cleans a flat stone or digs a shallow pit, shimmering and tail slapping at each other. The female develops a short, blunt breeding tube and lays rows of small eggs, with the male following to fertilize them. Clutches are commonly 100 to 300 eggs.\n\nAfterward the pair take turns fanning the eggs and chasing away anything that comes near. Do not move decorations or do big water changes for a few days."}, {"heading": "Eggs and fungus", "text": "At 82 to 85°F the eggs hatch in about 2 to 3 days. Good parents pick off white, fungused eggs. If your pair keeps eating clutches, many breeders move the stone to a small hatching container filled with water from the same tank, with gentle aeration beside the eggs. A light dose of methylene blue in the hatching container helps prevent fungus.\n\nThe wrigglers hang on the stone or get moved into pits for several days while they use up their yolk. Roughly 3 to 5 days after hatching they become free swimming."}, {"heading": "Raising the fry", "text": "Ram fry are tiny. For the first few days feed infusoria, vinegar eels or a fine powdered fry food several times a day, then add microworms and newly hatched brine shrimp. By the end of the second week most fry can take baby brine shrimp as their main food.\n\nKeep the temperature steady at 82 to 85°F and do small 10 to 20 percent water changes every day or two with matched, aged water. Siphon leftover food from the bottom daily. Sudden swings in temperature or a buildup of waste are the most common reasons a whole batch is lost."}, {"heading": "Growing out", "text": "From week three, add crushed flake and micro pellets alongside the brine shrimp. Move the fry to a larger grow out tank once they are about half an inch, and keep up frequent water changes. Expect them to reach roughly 1 inch in about 2 to 3 months, with color showing as they grow. Growth is slower and losses are higher if nitrates are allowed to climb."}, {"heading": "Common mistakes", "text": "- Breeding rams in a community tank where they are stressed and eat eggs\n- Running the water too cool, or letting temperature swing\n- Letting nitrate build up by skipping water changes\n- Giving up after one or two eaten clutches; young pairs often improve\n- Overfeeding fry and leaving food to rot on the bottom"}]$g$::jsonb, $g$[{"q": "How long does it take German blue ram eggs to hatch?", "a": "At 82 to 85°F the eggs usually hatch in about 2 to 3 days. The fry become free swimming roughly 3 to 5 days after that."}, {"q": "Why do my German blue rams keep eating their eggs?", "a": "Young pairs, stress from tankmates and poor water are the usual causes. Many pairs settle down after a few spawns; otherwise you can hatch the eggs artificially."}, {"q": "How can you tell a male German blue ram from a female?", "a": "Males are larger with longer front dorsal spines. Females are usually rounder with a pink or red belly, though no single sign is foolproof."}, {"q": "What temperature do German blue rams breed at?", "a": "Most breeders keep spawning pairs at 82 to 85°F in soft, slightly acidic water."}]$g$::jsonb, $g$Open your log as soon as your pair is settled in the breeding tank and photograph both fish with the challenge code card beside them. Rams often eat early clutches, so photograph each spawn on the stone right away as stage 2 evidence.$g$),
  ($g$black-finned-pearl-killifish$g$, $g$576963db-5442-493a-a6b1-4f74c92d1891$g$::uuid, null, null, $g$How to Breed Black-finned Pearl Killifish (Austrolebias)$g$, $g$The black-finned pearl killifish is an annual species: eggs rest in damp peat for months before hatching. A Class D guide to the full breeding cycle.$g$, $g$Austrolebias nigripinnis is an annual killifish from seasonal pools in Uruguay and Argentina, so breeding it means working through its natural cycle: spawning into peat, storing the eggs damp for months, then wetting them to hatch. It takes patience and good record keeping rather than fancy equipment. Recent work places it in the genus Argolebias, and you may see either name.$g$, $g${"method": "Annual killifish (eggs stored in damp peat)", "sexing": "Males dark blue to black with pale spots; females brownish with darker marks", "group": "1 male to 2 or 3 females", "breeding_tank": "5 to 10 gallons with a deep layer of boiled peat, cool room temperature", "conditioning": "Live or frozen bloodworms, blackworms and brine shrimp for 1 to 2 weeks", "trigger": "Mature, well fed fish and a peat layer to dive into", "spawn": "A few eggs per dive, laid daily; dozens build up over several weeks", "eggs": "Commonly stored about 3 to 5 months in damp peat at room temperature", "fry": "Hatch on wetting and swim within hours; fairly large for killifish", "first_foods": "Newly hatched brine shrimp or microworms from day one", "grow_out": "Grow fast; often mature in about 2 to 3 months", "parents": "No care; eggs are removed with the peat and adults would eat any fry"}$g$::jsonb, $g$[{"heading": "How this annual killifish breeds", "text": "In the wild, Austrolebias live in pools that dry out each year. Adults spawn by diving into the mud, the pools dry, the adults die, and the eggs wait in the damp mud until rain returns. In the aquarium you copy this by letting the fish spawn into peat, removing the peat, storing it damp for a few months and then adding water.\n\nThese fish are short lived, often around a year in captivity, so start breeding as soon as they mature."}, {"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank with a gentle sponge filter is ideal. Add a layer of boiled, squeezed peat 2 to 3 inches deep, or place a large container of peat on the bottom. Austrolebias are cool water fish: breeders commonly keep them around 64 to 72°F, and they do poorly kept warm for long. Soft to medium, slightly acidic to neutral water works well. A tight lid is essential.\n\nIf your room runs warm in summer, a cooler spot in the house or a basement often works better than a chiller. Avoid strong lighting, which warms small tanks quickly. Boil the peat first to soften it and remove pests, then rinse and squeeze it before adding."}, {"heading": "Choosing and conditioning a group", "text": "Males are striking: dark blue to nearly black with pale spots and dark fins. Females are brown or olive with darker markings and are smaller. Males can be rough with each other and with females, so use 1 male with 2 or 3 females and give the females some cover.\n\nAustrolebias are predators that rarely accept dry food. Feed live or frozen bloodworms, blackworms and brine shrimp generously for a week or two before and during spawning."}, {"heading": "Spawning and collecting eggs", "text": "A ready male displays to a female and leads her into the peat, where both dive in and lay a few eggs. This repeats daily. After 2 to 4 weeks, net the fish out, pour the peat into a fine net and squeeze it until it is damp but not dripping.\n\nLabel a sealed bag or container with the species and collection date, then store it in a dark place at room temperature, roughly 70 to 75°F. Breeders commonly report incubation of about 3 to 5 months for this species. You can check eggs through a magnifier: well developed eggs show a dark eye ring."}, {"heading": "Hatching and raising the fry", "text": "When the eggs show eyes, place the peat in a shallow container and add cool, soft water a few inches deep. Many hatch within hours; others may need the peat dried and rewetted a few weeks later.\n\nAustrolebias fry are large enough to take newly hatched brine shrimp from the first day; microworms make a good backup. Feed small amounts several times a day and change 20 to 30 percent of the water every couple of days. Keep the temperature in the mid to upper 60s°F.\n\nIf some fry swim at the surface with tails pointing down and cannot dive, they may be belly sliders that never filled their swim bladders. This happens more often when eggs hatch too early or the water is too deep, so keep the first water shallow at 1 to 2 inches."}, {"heading": "Growing out", "text": "Fry grow fast on brine shrimp, then chopped blackworms and frozen foods. Separate by size if some get much bigger, as larger siblings can eat smaller ones. Males usually show color within about 6 to 8 weeks, and the fish are commonly mature in about 2 to 3 months, ready to start the cycle again."}, {"heading": "Common mistakes", "text": "- Keeping them too warm, which shortens their lives\n- Storing peat too wet, which lets eggs rot or hatch early\n- Wetting eggs too early, before eyes show\n- Forgetting to label bags with species and date\n- Waiting too long to breed short lived adults"}]$g$::jsonb, $g$[{"q": "How long do Austrolebias nigripinnis eggs incubate?", "a": "Breeders commonly report about 3 to 5 months in damp peat at room temperature. Check for visible eyes in the eggs before wetting."}, {"q": "Is the black-finned pearl killifish an annual?", "a": "Yes. It comes from seasonal pools and its eggs normally go through a dry resting period before hatching."}, {"q": "What temperature do black-finned pearl killifish need?", "a": "They are cool water fish, commonly kept around 64 to 72°F. Long periods of warm water shorten their lives."}, {"q": "What do Austrolebias fry eat?", "a": "The fry are fairly large and can usually eat newly hatched brine shrimp from the first day."}]$g$::jsonb, $g$Photograph your trio in the peat tank with the challenge code at stage 1, and for stage 2 take a clear photo of eggs in the peat with the collection date. Keep your storage bags labeled, since the long incubation means your log will stay open for months.$g$),
  ($g$hillstream-loach$g$, $g$bae97ecd-ac7d-4bf8-afa6-78a0c0cd2525$g$::uuid, $g$hillstream-loach$g$, null, $g$Breeding Hillstream Loaches (Sewellia lineolata): A Guide$g$, $g$Sewellia lineolata spawns in mature, fast flowing tanks with algae for the fry. A Class D guide to sexing, spawning conditions and raising tiny fry.$g$, $g$The reticulated hillstream loach is one of the few hillstream species that breeds in home aquaria, usually in mature, well oxygenated tanks where fry suddenly appear on the rocks. Spawning is rarely watched closely and many details are still poorly documented. The real challenge is keeping the tiny grazing fry fed, which is why this is a Class D species.$g$, $g${"method": "Egg scatterer over gravel and stones in current", "sexing": "Males have broader, squarer pectoral areas, often with rough ridges; females rounder", "group": "A group of 5 or more of mixed sex", "breeding_tank": "30 gallons or more, strong flow, smooth rocks, algae covered surfaces", "conditioning": "Algae, biofilm, quality sinking foods and frozen bloodworms or daphnia", "trigger": "Mature tank, high oxygen and steady current; cooler water changes may help", "spawn": "Clutch size is not well documented; small numbers of eggs are commonly reported", "eggs": "Hatch timing is poorly documented; eggs are scattered and rarely seen", "fry": "Tiny, flat fry that cling to rocks and graze biofilm", "first_foods": "Biofilm and soft algae, plus fine powdered fry food", "grow_out": "Slow; several months to reach 1 inch", "parents": "No parental care; adults may eat eggs but often ignore fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 30 gallons, matching the minimum for this species. Hillstream loaches need cool, clean, oxygen rich water: 68 to 77°F, pH 6.5 to 7.5. A powerhead or river style flow across smooth rocks and pebbles over sand or fine gravel copies their streams. Let algae and biofilm grow on the rocks and glass, because both adults and fry graze it. Mature tanks that have run for several months are where most spawns happen.\n\nTurn over the full tank volume many times an hour, but leave a few calmer pockets behind rocks where food can settle. An air stone or surface agitation keeps oxygen high in summer. If your room gets warm, a fan across the surface helps more than you might expect. Use sand or small rounded gravel rather than sharp stones, since these fish spend their lives pressed against the bottom."}, {"heading": "Sexing and choosing a group", "text": "Viewed from above, males usually look squarer at the front, with broader pectoral fins, and many show rough ridges or tubercles on the pectoral area. Females are rounder and wider through the body. Sexing is easiest on adults and is not perfect, so keeping a group of 5 or more improves your odds.\n\nMales defend small territories and spar by pressing against each other, which is normal. Plenty of flat rocks gives everyone room."}, {"heading": "Conditioning and spawning", "text": "Feed a mix of algae based sinking foods, blanched vegetables and frozen bloodworms or daphnia, alongside natural algae. Spawning is seldom observed. Breeders describe a male pressing his body and fin over a female against the substrate, with eggs scattered over the gravel in the current. Clutch size is not well documented, and many keepers only discover a spawn when tiny fry appear.\n\nSome keepers report spawning after cool water changes, but there is no proven trigger."}, {"heading": "Eggs", "text": "The eggs are small and fall into gaps in the gravel, so they are rarely seen and hatch times are poorly documented. Leaving the eggs in place in a mature tank with good flow is the usual approach. Adults may eat some eggs, but enough often survive in the gravel. If you find eggs, avoid vacuuming the substrate for a few weeks."}, {"heading": "Raising the fry", "text": "Newly hatched fry are tiny and stick to rocks and glass, grazing biofilm. Do not add powerful new filtration that could pull them in; cover intakes with sponge. Keep plenty of algae covered stones in the tank and add fine powdered fry food or crushed algae wafers daily so it settles where they graze.\n\nKeep the water clean with 20 to 30 percent weekly changes, matched in temperature, and never let the tank run warm.\n\nMany breeders keep a few extra rocks in a sunny spot or a bright spare tank to grow algae, then rotate them into the fry tank as the fry clean them off. A thin layer of green film on the glass is a good sign, not a mess to scrub. Watch the fry bellies: rounded bellies mean they are finding enough to eat."}, {"heading": "Growing out", "text": "Growth is slow. Expect several months before the young reach around 1 inch and show the adult pattern. If you want to raise more of them, move algae covered rocks with fry into a small mature tank with gentle current and its own algae, so they do not have to compete with adults for food.\n\nYoung loaches look like miniature adults but with a fainter pattern. Keep tankmates peaceful and small, as larger fish will compete for food and may pick off fry. Wait until they are at least 1 inch before rehoming them, since tiny juveniles struggle in new tanks."}, {"heading": "Common mistakes", "text": "- Expecting spawns in a new tank without established algae\n- Running the water too warm or too still\n- Unprotected filter intakes that catch fry\n- Cleaning all the algae off rocks and glass\n- Deep gravel vacuuming that removes eggs and fry"}]$g$::jsonb, $g$[{"q": "Do hillstream loaches breed in aquariums?", "a": "Sewellia lineolata does breed in home tanks, usually in mature, cool tanks with strong flow and lots of algae."}, {"q": "How do you tell male and female hillstream loaches apart?", "a": "From above, males look squarer at the front with broader pectoral fins, often with rough ridges. Females are rounder and wider."}, {"q": "What do baby hillstream loaches eat?", "a": "They graze biofilm and soft algae. Fine powdered fry food and crushed algae wafers help supplement this."}, {"q": "Do hillstream loaches eat their fry?", "a": "They give no care and may eat eggs, but many keepers find adults largely ignore the fry."}]$g$::jsonb, $g$Since spawns are rarely seen, keep a close eye on rocks and glass for tiny fry and photograph them clearly with dates. Open your log before spawning with the group and the challenge code card in view.$g$),
  ($g$dojo-loach$g$, $g$0f0e0376-a5ba-4ad3-b025-2f27ec686d33$g$::uuid, $g$dojo-loach$g$, null, $g$Breeding Weather Loaches (Dojo Loach): What Works and Why$g$, $g$Weather loaches rarely spawn indoors but can with seasonal cooling, space and a well conditioned group. A Class D guide to sexing, spawning and fry.$g$, $g$Weather loaches are hardy and easy to keep, but breeding them indoors is uncommon. Most spawns happen in ponds or large tanks after a cool winter period followed by spring warming. Sexing is easy once you know what to look for, and the fry are simple to feed, so the hard part is getting adults to spawn at all.$g$, $g${"method": "Egg scatterer over plants and substrate", "sexing": "Males have larger, pointed pectoral fins with a thick second ray; females larger and plumper", "group": "A group of 4 to 6 with at least 2 males", "breeding_tank": "40 gallons or more, soft sand, fine plants or spawning mops, tight lid", "conditioning": "Months of cool winter water, then frozen bloodworms, worms and sinking foods", "trigger": "Seasonal cool period then warming into the 70s°F, with large fresh water changes", "spawn": "Large clutches, commonly hundreds and sometimes thousands of eggs", "eggs": "Commonly hatch in about 2 to 3 days at around 72 to 75°F", "fry": "Tiny; free swimming a few days after hatching", "first_foods": "Infusoria and fine fry food, then baby brine shrimp after about a week", "grow_out": "Fast; often 2 inches within a few months", "parents": "No care; adults eat eggs, so remove adults or eggs after spawning"}$g$::jsonb, $g$[{"heading": "Why breeding them is uncommon", "text": "Weather loaches are temperate fish that spawn seasonally. In heated aquariums held at one temperature all year they rarely breed. Commercial farms often use hormone injections, which home breeders should not attempt. The natural way is to give them a real winter and spring.\n\nThis is also a species you must never release. It is invasive in many places, and some US states restrict keeping it, so check local rules."}, {"heading": "Setting up the breeding tank", "text": "Use at least 40 gallons, matching the minimum for adults that can reach 8 inches. Soft sand lets them burrow. Add bunches of fine plants or spawning mops for eggs. A tight lid is essential because weather loaches are skilled escape artists. Good filtration and gentle current keep oxygen high. Outdoor ponds in mild climates often succeed where tanks fail.\n\nIf you keep a pond, a shallow planted margin with fine leaved plants gives eggs somewhere to land, and fry may grow up unnoticed among the plants. In a tank, place spawning mops in a corner near the surface as well as on the bottom, because these loaches often spawn up in the water column."}, {"heading": "Sexing and conditioning", "text": "Sexing adults is fairly easy. Males have larger, more pointed pectoral fins, and the second ray of each pectoral fin is thickened with a small bony plate at its base. Females are usually larger and noticeably plumper, with smaller, rounded pectorals.\n\nGive the group a cool winter period of several weeks in the 50s to low 60s°F, within their 50 to 77°F range. Feed lightly during that time, then warm gradually and feed heavily with frozen bloodworms, earthworm pieces and sinking pellets.\n\nAn unheated tank in a cool room, or a garage that stays above freezing, is often enough to give the winter rest. Many keepers also see the fish become restless before storms, which is how they earned the name weather loach. That restlessness alone does not mean they are about to spawn."}, {"heading": "Spawning: what you will see", "text": "As water warms into the low to mid 70s°F, often after a big cool water change, males chase females and one wraps around a female's body near the surface or among plants. Eggs are scattered over plants and substrate, and clutches commonly run to hundreds of eggs and can reach thousands. Spawning activity tends to be short and easy to miss."}, {"heading": "Eggs and fry", "text": "Remove the adults or move the mops to a separate tank as soon as you see eggs, since adults eat them. Eggs commonly hatch in about 2 to 3 days at 72 to 75°F. Remove any white, fungused eggs to keep them from spreading.\n\nThe fry hang on surfaces at first, then swim a few days later. Feed infusoria and fine powdered fry food, then add newly hatched brine shrimp after about a week. Do 20 percent water changes every couple of days.\n\nUse an air driven sponge filter in the fry tank, keep the water around 72 to 75°F, and add a few floating plants to grow infusoria. Fry spend much of their time on the bottom, so make sure food reaches them by feeding near the substrate and in several spots."}, {"heading": "Growing out", "text": "Fry grow quickly and are not fussy. By weeks three and four they take crushed flake, micro pellets and chopped frozen foods. Spread them out as they grow; many reach about 2 inches within a few months. Plan ahead for numbers, as this species gets large and needs big tanks.\n\nBy two to three months juveniles look like small versions of the adults and can be kept with peaceful fish. Sort out any runts and give them their own space so they catch up."}, {"heading": "Common mistakes", "text": "- Keeping them heated all year with no seasonal cooling\n- Leaving adults with the eggs\n- No lid, leading to loaches on the floor\n- Producing more fry than you can rehome responsibly\n- Ever releasing fish or fry outdoors into the wild"}]$g$::jsonb, $g$[{"q": "Do weather loaches breed in aquariums?", "a": "They can, but it is uncommon. Most success comes from a cool winter period followed by warming, or from outdoor ponds."}, {"q": "How do you sex dojo loaches?", "a": "Males have larger, pointed pectoral fins with a thickened second ray. Females are larger and plumper with smaller, rounded pectorals."}, {"q": "How long do weather loach eggs take to hatch?", "a": "Commonly about 2 to 3 days at around 72 to 75°F."}, {"q": "Can I release extra weather loaches into a pond or stream?", "a": "No. They are invasive in many regions. Only keep them in closed tanks or secure private ponds where allowed, and rehome extras to other hobbyists."}]$g$::jsonb, $g$Photograph the group with the challenge code card at the start, including a clear shot of a male's pectoral fins to show you have both sexes. Spawns are short and easy to miss, so photograph eggs on the mops right away.$g$),
  ($g$checkerboard-cichlid$g$, $g$83766076-2218-4931-a2bd-a1df37ba0734$g$::uuid, $g$checkerboard-cichlid$g$, null, $g$How to Breed Checkerboard Cichlids: Soft Water and Harems$g$, $g$Checkerboard cichlids breed in very soft, acidic water, with the female guarding eggs on a leaf. A Class D guide to harems, spawning and raising fry.$g$, $g$The checkerboard cichlid, Dicrossus filamentosus, is a gorgeous dwarf cichlid that spawns on leaves with the female doing almost all the care. It needs very soft, acidic water for its eggs to develop, and that is where most breeders struggle. Get the water right and a harem of one male with a few females can be productive and fascinating to watch.$g$, $g${"method": "Substrate spawner, usually on a leaf or flat surface", "sexing": "Males larger with lyre shaped, filament tipped tails; females smaller, rounded tails", "group": "1 male to 2 or 3 females", "breeding_tank": "20 to 30 gallons, soft acidic water, broad leaves, dim light, sponge filter", "conditioning": "Frozen and live bloodworms, brine shrimp and daphnia for 2 to 3 weeks", "trigger": "Very soft water around pH 5 or lower and GH under 2, at 80 to 84°F", "spawn": "Commonly around 60 to 150 eggs", "eggs": "Commonly hatch in about 2 to 3 days at 80 to 84°F", "fry": "Free swimming about 5 to 7 days after hatching", "first_foods": "Newly hatched brine shrimp and microworms", "grow_out": "About 2 to 3 months to around 1 inch", "parents": "Female guards eggs and fry; male stays away. Leave fry with her a few weeks"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 to 30 gallon tank works for a small harem, with 30 gallons giving females space. Use fine sand, broad leaved plants and some leaf litter, plus driftwood for cover. Keep lighting dim. A sponge filter is safest for fry.\n\nThe water is the key. These fish live in 4.5 to 6.5 pH and very low hardness. For breeding, drop to pH 5 or lower with GH under 2 and very low conductivity, which in practice means RO or rain water. Keep it at 80 to 84°F. Leaf litter adds tannins that many breeders believe help.\n\nTest your water before you start rather than guessing. A TDS or conductivity meter is helpful because very low readings matter as much as pH. Lower the hardness gradually over a week or two so the adults adjust safely. Floating plants help keep the light soft and give the female a sense of security."}, {"heading": "Choosing and conditioning a harem", "text": "Males are larger and develop a lyre shaped tail with long filaments, plus bright blue and red markings. Females are smaller with rounded tails, and when ready to spawn they show bold checkerboard markings and often bright red pelvic fins.\n\nKeep 1 male with 2 or 3 females. Condition with frozen and live bloodworms, brine shrimp and daphnia for 2 to 3 weeks. These are carnivores and do not do well on dry food alone.\n\nBuying 6 to 8 juveniles and letting them grow up together is a good way to end up with a natural harem. Remove extra males once the dominant one is clear, since subordinate males get harassed. Make sure each female has a cave or leaf area of her own, and give the group a few weeks to settle before expecting eggs."}, {"heading": "Spawning: what you will see", "text": "The male displays with fins spread. The female chooses a leaf or flat surface, cleans it, and lays her eggs, commonly around 60 to 150. After spawning she drives the male away and guards the eggs alone. Females sometimes move eggs or larvae to a different leaf or into small pits."}, {"heading": "Eggs and fungus", "text": "At 80 to 84°F eggs commonly hatch in about 2 to 3 days. If your water is too hard, eggs often turn white and fungus within a day, which is the most common failure. If that happens, lower hardness and pH before the next spawn rather than adding chemicals.\n\nThe larvae hang on the leaf or in pits for several days, then become free swimming roughly 5 to 7 days after hatching."}, {"heading": "Raising the fry", "text": "Feed newly hatched brine shrimp and microworms two or three times a day from the first day of free swimming. The female leads the school around and protects them. Do 10 to 15 percent water changes every two or three days with the same soft, acidic water, matched in temperature. Siphon uneaten food daily.\n\nThe female keeps her fry close at first and gradually lets them wander farther. Any sudden movement or reflection can make her move them, which is normal. If she seems overly stressed, add more cover rather than removing her, since fry left with their mother usually grow better and feed more confidently than fry raised alone."}, {"heading": "Growing out", "text": "After 3 to 4 weeks move the fry to their own tank so the female can rest. Keep feeding brine shrimp and add crushed frozen foods and fine pellets. Expect around 1 inch in roughly 2 to 3 months. Juveniles can tolerate slightly harder water, but change it gradually."}, {"heading": "Common mistakes", "text": "- Water that is not soft or acidic enough, causing fungused eggs\n- Only one female, so the male harasses her constantly\n- Bright light and no cover\n- Big, sudden water changes during brooding\n- Feeding only dry food\n- Removing the female too early, before fry are feeding well on their own"}]$g$::jsonb, $g$[{"q": "What pH do checkerboard cichlids need to breed?", "a": "Most breeders use very soft water around pH 5 or lower with very low hardness. Eggs often fungus in harder water."}, {"q": "How do you tell male and female checkerboard cichlids apart?", "a": "Males are larger with lyre shaped, filament tipped tails. Females are smaller with rounded tails and bold checker markings when breeding."}, {"q": "Do checkerboard cichlids guard their eggs?", "a": "Yes. The female guards the eggs and fry alone and usually chases the male away."}, {"q": "How long do checkerboard cichlid eggs take to hatch?", "a": "Commonly about 2 to 3 days at 80 to 84°F."}]$g$::jsonb, $g$Show the male and his females together with the challenge code at stage 1. For stage 2, a photo of the female guarding eggs on her chosen leaf works well, and note your pH and hardness in the log.$g$),
  ($g$discus-domestic-strains$g$, $g$5366d315-ad55-45c8-9d72-7fcaeb4240e5$g$::uuid, $g$discus$g$, null, $g$How to Breed Discus: Pairs, Cones and Fry on the Parents$g$, $g$Breeding discus means a bonded pair, warm soft water and fry that feed on the parents' skin at first. A Class D guide from spawning cone to grow out.$g$, $g$Discus are famous for an unusual habit: for their first week or two of free swimming, the fry feed on a special secretion on their parents' skin. Domestic strains spawn fairly readily once a pair forms, but keeping eggs from being eaten and raising fry to a healthy size takes warm, clean water and a lot of water changes. It is demanding but deeply rewarding.$g$, $g${"method": "Substrate spawner on vertical surfaces such as cones, pipes or slate", "sexing": "Hard to sex by looks; most reliable is breeding tube shape at spawning time", "group": "One bonded pair, usually chosen from a group of 6 or more", "breeding_tank": "30 to 40 gallons, bare bottom, spawning cone, sponge filter", "conditioning": "Beef heart mixes, frozen bloodworms, brine shrimp and quality pellets for weeks", "trigger": "Bonded pair, stable 84 to 86°F, soft water and a clean spawning cone", "spawn": "Commonly 100 to 300 eggs", "eggs": "Hatch in about 2 to 3 days at 84 to 86°F", "fry": "Free swimming roughly 2 to 4 days after hatching; they swim to the parents to feed", "first_foods": "Parents' skin secretion, then newly hatched brine shrimp from about day 5 to 7", "grow_out": "Several months of heavy feeding and daily water changes to reach 2 inches", "parents": "Both parents guard and feed fry; young pairs often eat early clutches"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Most breeders use a 30 to 40 gallon bare bottom tank for a pair, which makes cleaning easy. Add a spawning cone, a length of PVC pipe or a piece of slate leaned against the glass. Use one or two air driven sponge filters and a heater sized to hold 84 to 86°F steadily, inside the 82 to 88°F range discus live in.\n\nFor breeding, use soft water with pH around 6 to 6.5 and low hardness, within the library range of pH 6 to 7. Very soft water helps eggs develop, so many breeders blend RO water with tap water. Keep the tank in a quiet spot with few people walking past."}, {"heading": "Choosing and conditioning a pair", "text": "Discus are very hard to sex by appearance. Males are sometimes larger with a thicker lip and bigger forehead, but none of this is reliable. The best way is to grow up a group of 6 or more young discus and watch for two fish that pair off, clean a surface together and chase others away. When they spawn, the female's breeding tube is blunt and thick, and the male's is smaller and pointed.\n\nCondition with several small meals a day: beef heart based mixes, frozen bloodworms, brine shrimp and a high quality discus pellet. Daily water changes of 25 to 50 percent are normal for discus breeders."}, {"heading": "Spawning: what you will see", "text": "The pair clean the cone thoroughly, then start trembling and bowing at each other. The female makes passes up the cone laying lines of eggs, and the male follows to fertilize them. Clutches are commonly 100 to 300 eggs. Both parents then fan the eggs and remove any that go bad."}, {"heading": "Eggs and wrigglers", "text": "At 84 to 86°F the eggs hatch in about 2 to 3 days. The parents often move the wrigglers to a different spot on the cone. Roughly 2 to 4 days after hatching, the fry become free swimming and head straight for the parents.\n\nYoung pairs commonly eat their first few clutches. Patience usually pays off, and many pairs get it right after a few tries. Some breeders place a mesh cone guard around the eggs so the parents can fan but not eat them, then remove it once the fry swim."}, {"heading": "Raising the fry", "text": "For the first days of free swimming the fry eat only the slime on their parents' skin. From about day 5 to 7, start offering newly hatched brine shrimp several times a day while they stay with the parents. Keep the temperature steady and do daily water changes, siphoning carefully around the fry.\n\nThe parents' skin can become worn as the fry grow. Most breeders separate the fry at about 3 to 4 weeks, once they are eating brine shrimp well."}, {"heading": "Growing out", "text": "After separation, feed baby brine shrimp, then crushed flake and fine discus pellets, and later beef heart mixes, five or six times a day. Large daily water changes are what drive good growth. Even with good care, expect several months for juveniles to reach around 2 inches and show strain color, and stunting is common if water quality slips.\n\nRaise fry in a bare bottom tank so you can siphon every scrap of food, and spread them out as they grow. Overcrowded fry tanks are the most common cause of stunted discus with large eyes and small bodies. Stick to one strain per pair so the young breed true to their parents."}, {"heading": "Common mistakes", "text": "- Assuming two fish are a pair before they spawn together\n- Hard water, which leads to eggs that never hatch\n- Too few water changes, causing stunted growth\n- Separating fry before they eat brine shrimp well\n- Moving a pair or the cone mid spawn"}]$g$::jsonb, $g$[{"q": "Do baby discus eat their parents' slime?", "a": "Yes. For their first week or two of free swimming, discus fry feed on a special secretion on the parents' skin."}, {"q": "How long do discus eggs take to hatch?", "a": "About 2 to 3 days at 84 to 86°F. The fry become free swimming a few days later."}, {"q": "How can you tell male and female discus apart?", "a": "It is hard by appearance. The clearest sign is at spawning: females have a blunt breeding tube and males a smaller, pointed one."}, {"q": "Why do my discus eat their eggs?", "a": "Young pairs, stress and poor water are common reasons. Most pairs improve after a few spawns."}]$g$::jsonb, $g$Discus pairs often eat several clutches before raising fry, so open your log early and photograph each spawn on the cone. Stage 3 photos of fry grazing on a parent's side make great evidence.$g$),
  ($g$dwarf-pike-cichlid$g$, $g$7b2d6681-2040-486d-a114-9611b2d9f1be$g$::uuid, $g$dwarf-pike-cichlid$g$, null, $g$How to Breed Dwarf Pike Cichlids (Crenicichla compressiceps)$g$, $g$Dwarf pike cichlids spawn in caves and both parents guard the fry, but pairs can be aggressive. A Class D guide to pairing, spawning and raising fry.$g$, $g$Crenicichla compressiceps is the smallest pike cichlid in the hobby, a cave spawning predator that becomes a devoted parent once a pair settles. Forming a peaceful pair is the hardest part, because these fish can be very aggressive toward mates they do not accept. Information on this species is less complete than for common cichlids, so expect some trial and error.$g$, $g${"method": "Cave spawner", "sexing": "Not easy; males often larger with longer fins, females rounder when ripe", "group": "One pair, ideally formed from a group of juveniles", "breeding_tank": "40 gallons, several small caves, sand, plants and a tight lid", "conditioning": "Live and frozen foods such as bloodworms, brine shrimp and small fish foods", "trigger": "A bonded pair, soft acidic water around 80°F and secure caves", "spawn": "Clutch size is not well documented; usually several dozen eggs are reported", "eggs": "Commonly hatch in about 3 days at 78 to 82°F", "fry": "Free swimming roughly a week after spawning", "first_foods": "Newly hatched brine shrimp and microworms", "grow_out": "Several months to around 1 to 1.5 inches", "parents": "Both parents guard; aggression toward each other can rise, so watch closely"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 40 gallons for a pair, matching the minimum for this species. Pike cichlids are territorial, and space plus broken sight lines reduce fights. Provide fine sand, several small caves or clay pots, driftwood and plants. A tight lid matters as they can jump.\n\nKeep the water at 78 to 82°F, within the 75 to 82°F range for this species, with pH 5.5 to 6.5 and low hardness. Use gentle filtration with a pre filter sponge.\n\nPlace the caves at opposite ends of the tank and use driftwood or plants to block the view between them, so a fish that loses a squabble can get out of sight. Floating plants dim the light, which helps these shy hunters settle. A divider cut to fit the tank is worth having on hand before you start."}, {"heading": "Choosing and conditioning a pair", "text": "Sexing dwarf pike cichlids is not easy, and appearance alone is unreliable. Males often grow a little larger with longer fins, while ripe females look rounder. The safest route is to grow up a small group of juveniles and let a pair form, then remove the others.\n\nThese are carnivores. Condition with live and frozen foods: bloodworms, brine shrimp, mysis and other meaty foods, several small meals a day for a few weeks. Watch the pair carefully. If one fish hides constantly or shows torn fins, separate them with a divider.\n\nIf you can only buy adults, introduce them with a clear divider first for a week or two, so they can see each other without contact. Remove the divider when both fish are displaying calmly rather than charging the glass. Adding the female first, so she can claim a cave, often goes better than the reverse."}, {"heading": "Spawning: what you will see", "text": "A ready pair spends time in and around a chosen cave, cleaning it and displaying with fins spread. The female becomes noticeably rounder. Eggs are laid inside the cave, usually on the ceiling or walls, so you may not see them. Clutch size is not well documented; breeders usually report several dozen eggs.\n\nThe female tends the eggs inside the cave while the male guards the area."}, {"heading": "Eggs and wrigglers", "text": "At 78 to 82°F eggs commonly hatch in about 3 days. The wrigglers stay in the cave for several more days, and the fry are typically free swimming about a week after spawning. Avoid checking the cave often, as disturbance can lead to eggs being eaten.\n\nSoft, clean water reduces fungus, and good parents remove bad eggs themselves."}, {"heading": "Raising the fry", "text": "Once the fry swim out, feed newly hatched brine shrimp and microworms two or three times a day. Both parents usually guard the school. Do 15 to 20 percent water changes twice a week, matched in temperature, and siphon leftover food.\n\nPair aggression can increase as the fry grow. Many breeders move the fry to their own tank at 2 to 3 weeks.\n\nIf the parents are moving the fry from cave to cave or digging pits in the sand, that is normal guarding behavior. Do not panic if you briefly see fewer fry. Sponge filters are the safest choice, because fry spend a lot of time near the bottom and in corners where power filter intakes sit."}, {"heading": "Growing out", "text": "Fry grow steadily on brine shrimp, then chopped frozen foods and small pellets. Pike cichlids are predators from a young age, so sort them by size to prevent larger siblings from eating smaller ones. Expect several months to reach around 1 to 1.5 inches.\n\nOnce juveniles are about an inch long, they can take bloodworms and mysis. Keep them in a planted grow out tank with lots of hiding spots, because they become territorial early."}, {"heading": "Common mistakes", "text": "- Forcing two adults together without watching for aggression\n- Too small a tank, leading to fights\n- Checking the cave constantly during brooding\n- Keeping fry together without sorting by size\n- Feeding mostly dry food"}]$g$::jsonb, $g$[{"q": "Are dwarf pike cichlids aggressive when breeding?", "a": "Yes, they can be. Pairs sometimes fight, so give them space, caves and cover, and be ready to separate them."}, {"q": "How do you sex Crenicichla compressiceps?", "a": "It is not easy. Males are often larger with longer fins and females rounder when ripe, but grow up a group to be sure."}, {"q": "Where do dwarf pike cichlids lay their eggs?", "a": "Inside a cave, usually on the ceiling or walls."}, {"q": "What do dwarf pike cichlid fry eat?", "a": "Newly hatched brine shrimp and microworms are good first foods."}]$g$::jsonb, $g$Photograph your pair with the challenge code early, as eggs are hidden in the cave. For stage 2, a clear shot of eggs or wrigglers in the cave counts; a flashlight helps but keep checks brief.$g$),
  ($g$indian-glassfish$g$, $g$c479433e-04e1-460e-84d3-cc8171b50278$g$::uuid, $g$indian-glassfish$g$, null, $g$How to Breed Indian Glassfish: Eggs, Fry and Live Foods$g$, $g$Indian glassfish spawn among plants readily, but the tiny fry need constant live foods to survive. A Class D guide to spawning, hatching and fry care.$g$, $g$Indian glassfish spawn more easily than many expect, scattering eggs among fine plants, often in the morning light. The challenge is the fry: they are tiny and seem to eat only food that drifts right past them, so raising them takes a steady supply of very small live foods. Get that right and you will have a rare and rewarding success.$g$, $g${"method": "Egg scatterer on fine leaved plants", "sexing": "Males have blue edged dorsal and anal fins and a more pointed swim bladder", "group": "A group of 6 or more, or a pair moved to a spawning tank", "breeding_tank": "20 gallons with fine plants or mops, gentle filtration, morning light", "conditioning": "Live and frozen brine shrimp, daphnia and bloodworms for 2 weeks", "trigger": "Warming to around 80°F, fresh water changes and morning sunlight", "spawn": "Commonly up to around 200 eggs over a spawning", "eggs": "Commonly hatch in about 24 hours at around 80°F", "fry": "Free swimming after a few days; tiny and slow to hunt", "first_foods": "Infusoria, rotifers or paramecium, then baby brine shrimp after 1 to 2 weeks", "grow_out": "Slow at first; several months to 1 inch", "parents": "No care; adults eat eggs, so remove adults or plants after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank is a good size, matching the minimum for this species. Fill one side with fine leaved plants such as java moss, or use spawning mops. A sponge filter keeps flow gentle. Place the tank where it gets some morning light, as spawning often happens soon after lights come on.\n\nKeep the water at 76 to 80°F with pH 7 to 8 and moderate hardness, matching the conditions this species is kept in. Raising the temperature slightly toward 80°F often helps trigger spawning.\n\nA bare bottom or thin layer of sand makes it easier to see eggs and fry. Add a few floating plants to soften the light and grow infusoria in the tank. Start the breeding tank a few weeks ahead so the sponge filter is fully cycled and covered in the tiny life fry will graze."}, {"heading": "Sexing and conditioning", "text": "Males usually show blue edges on the soft dorsal and anal fins and a slightly golden tint. Because the fish are transparent, you can see the swim bladder: in males it tends to be pointed at the rear, in females rounder. Females get fuller when carrying eggs.\n\nCondition with live and frozen foods such as brine shrimp, daphnia and bloodworms for about 2 weeks. Many glassfish refuse dry food, so plan on live and frozen foods throughout.\n\nBecause sexing is easier on mature fish, buy a group of 6 or more and let them settle before choosing a pair. You can also let the whole group spawn in a planted tank and collect plants with eggs each morning. Females that look full and are being followed by a male are good candidates to move."}, {"heading": "Spawning: what you will see", "text": "A male chases a female into the plants, where they press together and release eggs. Small batches are scattered over several hours, and over a spawning a female commonly lays up to around 200 eggs. The eggs are small and stick to plant leaves. Spawns often happen early in the day."}, {"heading": "Eggs", "text": "Remove the adults or move the plants to a separate tank right after spawning, as adults eat eggs. Eggs commonly hatch in about 24 hours at around 80°F. Remove any white eggs to keep fungus from spreading. Keep the water still and clean for the next few days."}, {"heading": "Raising the fry", "text": "This is the hard part. Fry become free swimming after a few days and are tiny. They tend to stay still and eat only food that drifts past, so food must be dense in the water. Have infusoria, rotifers or paramecium cultures going before the spawn, and add them several times a day.\n\nAfter 1 to 2 weeks, start adding newly hatched brine shrimp. Keep the temperature steady at about 80°F and do small 10 percent water changes every day or two with matched water.\n\nLeaving the lights on or adding a small light at one end can concentrate infusoria and fry together, making it easier for them to find food. A tank with mature plants, mulm and algae gives a steady background of tiny foods between feedings. Gentle aeration only, as fry are weak swimmers."}, {"heading": "Growing out", "text": "Once fry take brine shrimp, losses drop and growth picks up. Add finely chopped frozen foods over time. Expect slow growth, with several months to reach around 1 inch. Keep the group together, as glassfish feel safest in numbers.\n\nWhen fry are a month old, start offering finely crushed frozen daphnia and cyclops. Most young glassfish never take dry food well, so plan on live and frozen foods for the long term. Keep them away from larger fish, which see them as food."}, {"heading": "Common mistakes", "text": "- Not having live foods ready before the spawn\n- Leaving adults with the eggs\n- Strong filter flow that sweeps tiny fry away\n- Big, sudden water changes\n- Buying dyed or painted glassfish, which should never be supported"}]$g$::jsonb, $g$[{"q": "Are Indian glassfish hard to breed?", "a": "Spawning is fairly easy, but raising the tiny fry is hard because they need dense live foods for the first couple of weeks."}, {"q": "How long do glassfish eggs take to hatch?", "a": "Commonly about 24 hours at around 80°F."}, {"q": "How can I tell male and female Indian glassfish apart?", "a": "Males usually have blue edged dorsal and anal fins and a more pointed swim bladder. Females are rounder when full of eggs."}, {"q": "Do Indian glassfish eat their eggs?", "a": "Yes. Remove the adults or move the plants after spawning."}]$g$::jsonb, $g$Plan your stage 3 photos as the fry first swim, because fry losses are highest in the first two weeks. A dated photo of fry next to the challenge code card at stage 5 shows you got past the hard part.$g$),
  ($g$pea-puffer$g$, $g$0540c7d9-ba2c-4e4c-ab36-93a4d5983bb0$g$::uuid, $g$pea-puffer$g$, null, $g$How to Breed Pea Puffers: Sexing, Eggs and Tiny Fry$g$, $g$Pea puffers spawn in moss and fine plants, but eggs and fry need separate care. A Class D guide to sexing, spawning and feeding tiny puffer fry.$g$, $g$Pea puffers, the tiniest freshwater puffers, will spawn in a well planted tank with good food. The trick is collecting the small batches of eggs before adults eat them, then raising fry that need very small live foods and will eat each other if sizes differ. With a heavily planted setup and a steady supply of live food, breeding them is very achievable.$g$, $g${"method": "Egg scatterer in moss and fine plants", "sexing": "Males have a dark belly stripe and wrinkles behind the eyes; females rounder, spotted", "group": "1 male to 2 or 3 females", "breeding_tank": "10 to 20 gallons, heavily planted with java moss, sponge filter", "conditioning": "Live snails, frozen bloodworms and brine shrimp for 2 to 3 weeks", "trigger": "Good feeding and courtship; male displays to a female", "spawn": "Small batches, commonly about 5 to 10 eggs", "eggs": "Commonly hatch in about 3 to 5 days at 78 to 80°F", "fry": "Free swimming a few days after hatching; very small", "first_foods": "Infusoria, vinegar eels or rotifers, then baby brine shrimp", "grow_out": "Around 2 to 3 months to half an inch", "parents": "No care; adults eat eggs and fry"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 to 20 gallon tank works well, matching the 10 gallon minimum for this species. Plant it heavily: java moss, fine stem plants and floating plants give cover and spawning sites. Use a sponge filter for gentle flow.\n\nKeep the water at 78 to 80°F, pH 6.5 to 7.5 and moderate hardness. Pea puffers are sensitive to waste, so do regular water changes.\n\nLots of plants matter more than tank size. Males claim small territories, and broken sight lines reduce chasing. A few leaves or a piece of driftwood give females somewhere to rest. Keep a culture of small snails going in a separate container, since you will need a steady supply for adults and later for juveniles."}, {"heading": "Sexing and choosing a group", "text": "Pea puffers are easy to sex as adults. Males have a dark stripe along the belly, often show fine wrinkle lines behind the eyes, and tend to be more colorful. Females are rounder and spotted, without a belly stripe.\n\nUse 1 male with 2 or 3 females. Males can be pushy, and more females spread his attention. Lots of plants keep the peace."}, {"heading": "Conditioning", "text": "Feed small live snails, frozen bloodworms and brine shrimp several times a day for 2 to 3 weeks. Pea puffers rarely accept dry foods. Snails help keep their beaks worn, and a well fed group is more likely to spawn.\n\nVary the diet through the week, offering live blackworms or daphnia when you can. Remove leftover frozen food after a few minutes, because uneaten bloodworms quickly raise ammonia in small, heavily stocked tanks."}, {"heading": "Spawning and eggs", "text": "The male displays to a female and leads her into the moss. Eggs are laid in small batches, commonly about 5 to 10, and fall into the moss. Some keepers report the male hanging around the spot for a short time, but adults generally eat eggs and fry.\n\nMove the moss into a hatching container after each spawn, filled with water from the main tank. Add a gentle air stone. Eggs commonly hatch in about 3 to 5 days at 78 to 80°F, though reports vary. Remove any white, fungused eggs.\n\nThe eggs are tiny and clear, so check the moss with a flashlight or magnifier. Some breeders simply move a clump of moss to the hatching container every few days and wait to see what hatches, which saves hunting for individual eggs."}, {"heading": "Raising the fry", "text": "The fry are tiny. After their yolk is used up, offer infusoria, vinegar eels or rotifers several times a day. After about a week, add newly hatched brine shrimp. Small daily water changes of 10 to 20 percent keep fry healthy.\n\nPuffer fry are cannibalistic. If you collect eggs from several spawns, keep each batch apart, or sort fry by size as they grow.\n\nKeep the fry container lightly planted with moss to grow microorganisms between feedings. Keep the water at 78 to 80°F and avoid any sudden change. A thin film of algae and mulm on the bottom is normal and gives fry extra grazing. Feed small amounts often rather than large amounts once a day."}, {"heading": "Growing out", "text": "From about week 3, add chopped bloodworms and baby brine shrimp, and introduce tiny snails. Expect around 2 to 3 months for juveniles to reach about half an inch. Sort by size regularly to keep larger fry from eating smaller ones.\n\nThey will need their own tank long term. Plan to rehome extras to other keepers once they are eating well and are about half an inch. Juveniles are just as feisty as adults, so give them plenty of plants and avoid overcrowding."}, {"heading": "Common mistakes", "text": "- Not moving eggs away from the adults\n- Mixing fry from different spawns\n- No live foods ready for tiny fry\n- Too many males in the group\n- Expecting large spawns; batches are small"}]$g$::jsonb, $g$[{"q": "How do you tell male and female pea puffers apart?", "a": "Males have a dark belly stripe and wrinkles behind the eyes. Females are rounder and spotted with no belly stripe."}, {"q": "How many eggs do pea puffers lay?", "a": "Small batches, commonly about 5 to 10 eggs per spawning."}, {"q": "Do pea puffers eat their babies?", "a": "Yes. Move eggs or moss to a separate container right after spawning."}, {"q": "What do pea puffer fry eat?", "a": "Infusoria, vinegar eels or rotifers first, then newly hatched brine shrimp after about a week."}]$g$::jsonb, $g$Clutches are small, so collect eggs from a few spawns in separate dated containers. Keep one batch as your main log entry and photograph it at each stage with the challenge code.$g$),
  ($g$calvus-cichlid$g$, $g$bf94ab51-6ce0-44c3-887b-8e2b9756526c$g$::uuid, $g$calvus-cichlid$g$, null, $g$How to Breed Calvus Cichlids: Shells, Caves and Slow Fry$g$, $g$Calvus females spawn in shells or crevices too small for the male. A Class D guide to pairing, spawning and raising slow growing Altolamprologus fry.$g$, $g$Altolamprologus calvus is a Lake Tanganyika cichlid with a clever breeding trick: the much smaller female lays her eggs in a shell or narrow crevice the male cannot enter. Pairs breed fairly readily once established, but young are slow to grow and the adults take time to mature. It is a patient breeder's project with a very rewarding result.$g$, $g${"method": "Cave spawner (female uses shells or narrow crevices)", "sexing": "Males much larger; females smaller and fit into shells", "group": "One pair, or one male with a couple of females", "breeding_tank": "40 gallons or more, rockwork, several shells, hard alkaline water", "conditioning": "Mysis, brine shrimp, krill and quality carnivore pellets", "trigger": "Mature, settled pair with shells or narrow caves available", "spawn": "Commonly reported up to around 200 eggs", "eggs": "Commonly hatch in about 3 days at 78 to 80°F", "fry": "Free swimming roughly 8 to 10 days after spawning", "first_foods": "Newly hatched brine shrimp and crushed flake", "grow_out": "Slow; several months to reach 1 inch", "parents": "Female guards; fry can usually stay with parents"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 40 gallons, the minimum for this species. Build rockwork with narrow crevices and add several large snail shells. Calvus are Lake Tanganyika fish, so keep the water hard and alkaline: pH 7.8 to 9, GH 10 to 25, and 76 to 82°F. Use good filtration but avoid strong flow.\n\nShells should be large enough for the female to fit inside but too small for the male. Large escargot or whelk shells are popular, and narrow gaps between stacked rocks work too. Use sand or fine substrate, which lets fish adjust their shells. Calvus are calm but predatory, so avoid tankmates small enough to eat. Peaceful Tanganyikan fish such as shell dwellers or Cyprichromis can share a large tank, but a species tank makes it easier to raise fry."}, {"heading": "Sexing and pairing", "text": "Adult males are much larger than females, often close to twice the length of a female. Females stay small enough to fit into shells. Young calvus are hard to sex, so many breeders grow up a group of 5 or 6 and let pairs form.\n\nOnce a pair forms, remove extras unless the tank is large. Calvus grow slowly, and it can take a couple of years to reach breeding size.\n\nCalvus can be kept as a pair or as a male with two females in a larger tank. Females in a shared tank need plenty of shells and crevices to avoid each other. Many keepers find established pairs stay together for years."}, {"heading": "Conditioning", "text": "Feed mysis shrimp, brine shrimp, krill and a good carnivore pellet once or twice a day. Avoid overfeeding, as leftovers foul the water. Good feeding helps the female fill with eggs.\n\nCalvus are carnivores but can suffer from a diet too rich in fatty foods. Mix meaty frozen foods with quality pellets, and keep one fasting day a week to help digestion. Feed from the surface so food reaches the calmer fish."}, {"heading": "Spawning and eggs", "text": "The female chooses a shell or narrow crevice and lays her eggs inside, where the larger male cannot reach. The male fertilizes them from the entrance. Clutches are commonly reported up to around 200 eggs.\n\nAt 78 to 80°F, eggs commonly hatch in about 3 days. The fry stay inside the shell and become free swimming roughly 8 to 10 days after spawning.\n\nYou may not see spawning at all. Signs include the female spending more time near one shell and the male guarding the area. Avoid moving shells or decor during this time. Keep the lights on a regular schedule and avoid big water changes for a week or so."}, {"heading": "Raising the fry", "text": "When the fry emerge, feed newly hatched brine shrimp and crushed flake two or three times a day. The female usually guards the fry, and many breeders leave them with the parents.\n\nKeep up 20 to 30 percent weekly water changes, matching hardness and pH carefully. Calvus fry are sensitive to sudden water changes.\n\nAdd fine powdered fry food or crushed flake near the shell. Fry stay close to cover for a while, so make sure food reaches them by feeding in several spots. Keep tankmates to a minimum while fry are small."}, {"heading": "Growing out", "text": "Calvus are notoriously slow growers. Feed frozen and live foods, plus small pellets. Expect several months to reach 1 inch, and much longer to reach adult size. Patience pays off, as well grown calvus are always in demand.\n\nYou can leave fry with the parents for a couple of months if the tank is large enough. Move them to their own grow out tank when they are around half an inch. Keep the same hard, alkaline water there and feed small meals several times a day. Expect it to take a year or more before young calvus look like miniature adults."}, {"heading": "Common mistakes", "text": "- Expecting fast growth from fry\n- Too few shells or crevices for the female\n- Soft, acidic water unsuited to Tanganyikan fish\n- Overfeeding rich foods\n- Mixing calvus with aggressive tankmates"}]$g$::jsonb, $g$[{"q": "How do calvus cichlids breed?", "a": "The female lays eggs in a shell or narrow crevice the male cannot enter, and he fertilizes them from outside."}, {"q": "How can you tell male and female calvus apart?", "a": "Adult males are much larger. Females stay small enough to fit into shells."}, {"q": "How long do calvus fry take to grow?", "a": "They grow slowly, taking several months to reach 1 inch."}, {"q": "Do calvus cichlids eat their fry?", "a": "Usually not. Many breeders leave fry with the parents."}]$g$::jsonb, $g$Take stage 1 photos showing the pair and the shells. Eggs are hidden, so for stage 2 a photo of the female guarding the shell entrance with fry or eggs visible helps.$g$),
  ($g$cyprichromis$g$, $g$981dfe5f-97f2-4928-b64a-d1f24365e86d$g$::uuid, $g$cyprichromis$g$, null, $g$How to Breed Cyprichromis leptosoma: Midwater Mouthbrooders$g$, $g$Cyprichromis leptosoma spawn in open water and females hold the eggs for about three weeks. A Class D guide to colonies, holding females and fry.$g$, $g$Cyprichromis leptosoma are graceful Lake Tanganyika sardine cichlids that live in schools and spawn in open water, with the female catching the eggs in her mouth. Broods are small, but the fry are large and easy to feed once released. The real work is keeping a big enough, calm school in a long tank with stable hard water, which is why this is a Class D species.$g$, $g${"method": "Maternal mouthbrooder that spawns in midwater", "sexing": "Males show bright tail and fin colors; females are plainer, silvery or brownish", "group": "A school of 8 or more, with more females than males", "breeding_tank": "55 gallons or more, long tank, rockwork at back, open swimming space", "conditioning": "Small frozen foods such as cyclops, brine shrimp and mysis, plus quality flake", "trigger": "A settled school, stable hard alkaline water and good feeding", "spawn": "Small broods, commonly around 10 to 20 fry", "eggs": "Females commonly hold for about 3 weeks at 76 to 80°F", "fry": "Released fully formed and free swimming, roughly half an inch", "first_foods": "Newly hatched brine shrimp and crushed flake", "grow_out": "A few months to reach 1.5 to 2 inches", "parents": "No care after release; adults may eat fry, so many breeders move fry out"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 55 gallons, with a long footprint. Cyprichromis swim in the middle and upper water, so open swimming space matters more than decor. Stack some rockwork at the back for males to claim, and leave the front open. A tight lid is important, as they can jump when startled.\n\nKeep the water hard and alkaline like Lake Tanganyika: pH 7.8 to 9, GH 10 to 25, and 76 to 82°F. Good filtration and steady water changes keep conditions stable.\n\nA 4 to 6 foot tank is ideal for a proper school, and many breeders keep them in 75 gallons or larger. Shell dwellers or a small group of peaceful bottom dwellers can share the tank, but avoid fish that dominate the upper water. A steady light schedule helps, since sudden lights on can startle the school into the glass. Some keepers leave a dim room light on before the tank lights come on."}, {"heading": "Choosing and conditioning a group", "text": "Keep a school of 8 or more, with more females than males. Males develop bright colors in the fins and tail, which vary by population. Females are plainer, silvery or brownish. Keeping one population together avoids mixing color forms.\n\nFeed small frozen foods such as cyclops, brine shrimp and mysis, along with a quality flake, two or three small meals a day. Cyprichromis have small mouths and do best on fine foods.\n\nSchools of 12 to 20 often look and behave most natural, and many breeders keep several males in a large school so no single male harasses females constantly. Males in a big group spread their displays out and each defends a small patch of open water near the rocks."}, {"heading": "Spawning: what you will see", "text": "Males claim small territories in open water near rocks and display to females with fins spread. When a female is ready, she follows the male. Spawning happens in midwater: the female releases eggs, which she catches in her mouth, and the male fertilizes them. Over the next days she will show a full, slightly bulging throat from holding."}, {"heading": "Holding females", "text": "Females commonly hold the eggs for about 3 weeks at 76 to 80°F. Broods are small, commonly around 10 to 20 fry. Holding females usually keep feeding lightly, but you may see them eat less.\n\nMany breeders move a holding female to a separate tank after about 2 weeks, so the fry are released somewhere safe. Move her gently in a container rather than a net to avoid stress. Some breeders leave fry to survive in the colony among the rocks, but fewer make it that way.\n\nA small floating breeder box or a 10 to 20 gallon tank with the same water works for the release. Keep the light soft and give her a few rocks for cover. Do not strip eggs or fry from her mouth unless you know the technique well; a calm female left alone usually releases on her own."}, {"heading": "Raising the fry", "text": "Fry are released fully formed, roughly half an inch long, and free swimming. Feed newly hatched brine shrimp and crushed flake two or three times a day. Do 20 to 30 percent water changes weekly, matching hardness and pH carefully.\n\nReturn the female to the group once the fry are released and she is eating well.\n\nFry tend to hang in midwater rather than hiding on the bottom, which is unusual among mouthbrooders and makes them easy to watch. Add fine foods where they swim, and use a sponge filter in the fry tank so food is not swept away. Several small feedings a day work better than one large one."}, {"heading": "Growing out", "text": "Fry grow steadily on brine shrimp and fine foods. Expect a few months to reach around 1.5 to 2 inches. Keep them in their own grow out tank until they can join the colony without being eaten. Males start showing color within a few months."}, {"heading": "Common mistakes", "text": "- Too small a school or tank\n- Too many males\n- Netting holding females roughly\n- Mixing different color populations\n- Soft or acidic water\n- Skipping a lid on a tank with a nervous school"}]$g$::jsonb, $g$[{"q": "How long do Cyprichromis females hold eggs?", "a": "Females commonly hold for about 3 weeks at 76 to 80°F."}, {"q": "How many fry do Cyprichromis have?", "a": "Broods are small, commonly around 10 to 20 fry."}, {"q": "How do you tell male and female Cyprichromis apart?", "a": "Males show bright tail and fin colors. Females are plainer, silvery or brownish."}, {"q": "Do Cyprichromis eat their fry?", "a": "Adults may eat fry, so many breeders move holding females to a separate tank before release."}]$g$::jsonb, $g$Photograph the school with the challenge code at stage 1. For stage 2, a clear photo of a holding female's full throat is good evidence of a spawn.$g$),
  ($g$tropheus-duboisi$g$, $g$30f2400a-e383-4c5c-a460-4dbf4ea7661f$g$::uuid, $g$tropheus-duboisi$g$, null, $g$How to Breed Tropheus duboisi: Colonies and Mouthbrooding$g$, $g$Tropheus duboisi females hold a few large eggs for about four weeks. A Class D guide to colonies, diet, holding females and spotted juvenile fry.$g$, $g$Tropheus duboisi is a Lake Tanganyika mouthbrooder known for its striking black juveniles covered in white spots. Females hold a small number of large eggs for about four weeks, and the fry are large and hardy. The challenge is keeping a stable colony with the right herbivore diet and managed aggression, which makes this a Class D species.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Hard to sex; males often larger and more dominant, females smaller", "group": "A colony of 10 or more, with 1 or 2 males", "breeding_tank": "55 gallons or more, rockwork caves, hard alkaline water", "conditioning": "Spirulina based flakes and pellets, algae; avoid high protein foods", "trigger": "A settled colony with plenty of space and stable water", "spawn": "Small broods, commonly around 5 to 15 eggs", "eggs": "Females commonly hold for about 4 weeks at 76 to 80°F", "fry": "Released fully formed, roughly half an inch", "first_foods": "Crushed spirulina flake and fine vegetable based foods", "grow_out": "A few months to around 1.5 inches", "parents": "No care after release; fry often survive in rocks"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 55 gallons, matching the minimum for this species. Build rockwork caves across the tank so fish can break sight lines. Keep water hard and alkaline: pH 8 to 9, GH 10 to 20, and 75 to 81°F. Strong filtration and weekly water changes keep water clean.\n\nA long tank, 4 feet or more, gives subordinate fish room to escape, and many keepers prefer 75 gallons or larger for a full colony. Arrange the rockwork into several separate piles so each male can hold a territory without seeing every other fish. Duboisi come from slightly deeper water than some Tropheus and are often said to be a little calmer, but aggression still needs managing."}, {"heading": "Choosing a colony", "text": "Tropheus duboisi are hard to sex. Males are often larger and more dominant, and females smaller. The safest approach is to buy a colony of 10 or more juveniles and let them grow up together. Remove extra males once they mature, keeping one or two.\n\nTropheus are aggressive toward their own kind. Larger groups spread aggression. Avoid adding single new fish later, which can cause fights.\n\nSome breeders check vents on larger juveniles to confirm sex, though this takes practice. When in doubt, keep the group together and remove extra males only once you see clear dominance and spawning activity. Signs of trouble include one fish hiding constantly, torn fins or a pale color; remove that fish to its own tank before it is badly hurt."}, {"heading": "Diet and conditioning", "text": "Tropheus are herbivores. Feed spirulina based flakes and pellets, and let algae grow on rocks. Avoid high protein foods like bloodworms and beef heart, which can lead to bloat, a serious problem in Tropheus. Feed small amounts two or three times a day.\n\nIf a fish stops eating, hangs at the surface or shows a swollen belly, act quickly, as bloat can spread through a colony. Clean water with frequent changes is the best prevention. Many breeders do 25 to 30 percent water changes weekly and avoid sudden diet changes. A small amount of frozen mysis once a week is about as rich as most experienced keepers go."}, {"heading": "Spawning and holding", "text": "Spawning happens near rocks. The female lays a few large eggs, picks them up, and the male fertilizes them. Broods are small, commonly around 5 to 15 eggs.\n\nFemales commonly hold for about 4 weeks at 76 to 80°F. Holding females may hide and eat little. Many breeders leave them in the colony, as stress from moving can cause the female to spit the eggs early.\n\nYou can spot a holding female by her full, squared off throat and the way she avoids eating or chews without swallowing. Note the date you first see her holding so you know when release is due. If you choose to move her near the end of the hold, do it gently in a container and leave her alone in a quiet tank with some cover. Return her to the colony soon after release, since Tropheus can have trouble rejoining a group after a long absence."}, {"heading": "Raising the fry", "text": "Fry are released fully formed, roughly half an inch long. They are black with white spots. Feed crushed spirulina flake and fine vegetable based foods. In a colony with good rockwork, many fry survive. You can also move fry to their own tank for faster growth.\n\nThe fry tank should have the same hard, alkaline water and plenty of small rocks. Do 20 to 30 percent water changes weekly, matching hardness and pH. Feed small amounts often and remove leftovers."}, {"heading": "Growing out", "text": "Fry grow steadily on vegetable foods. Expect a few months to reach around 1.5 inches. Juveniles keep their spots until they start changing into adult colors. Feed small amounts often and keep water clean.\n\nDuboisi juveniles are very popular with buyers for their spotted pattern, and grow out colonies can be kept together until they are big enough to rehome. Raise them as a group, since isolated juveniles are more likely to be bullied when introduced later."}, {"heading": "Common mistakes", "text": "- Feeding high protein foods, which causes bloat\n- Too small a group, leading to fights\n- Adding single new fish later\n- Moving holding females roughly\n- Mixing different Tropheus species or color forms"}]$g$::jsonb, $g$[{"q": "How long do Tropheus duboisi hold eggs?", "a": "Females commonly hold for about 4 weeks at 76 to 80°F."}, {"q": "How many fry does Tropheus duboisi have?", "a": "Broods are small, commonly around 5 to 15 eggs."}, {"q": "How do you tell male and female Tropheus duboisi apart?", "a": "It is hard. Males are often larger and more dominant, but buying a group of juveniles is safest."}, {"q": "What do Tropheus duboisi fry eat?", "a": "Crushed spirulina flake and fine vegetable based foods."}]$g$::jsonb, $g$Photograph the colony with the challenge code at stage 1. Holding females are easy to miss, so a clear photo of a female's full throat, with the date, is good stage 2 evidence.$g$),
  ($g$frontosa$g$, $g$500eaa9f-9f3f-4a79-bb27-1be5c4417d54$g$::uuid, $g$frontosa$g$, null, $g$How to Breed Frontosa: Colonies, Holding and Slow Growth$g$, $g$Frontosa breed in colonies, with females holding eggs for several weeks. A Class D guide to setup, sexing, holding females and slow growing fry.$g$, $g$Frontosa are big, slow growing Lake Tanganyika cichlids that take years to mature, but a settled colony will breed regularly. Females hold the eggs for several weeks and release large, hardy fry. The challenge is space and patience: a big tank, a colony of adults and the time to let them grow, which is why this is a Class D species.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Males larger with a bigger hump and longer fins; vent check is more reliable", "group": "One male with 3 to 5 females", "breeding_tank": "125 gallons or more, large caves, sand, hard alkaline water", "conditioning": "Quality pellets, krill, mysis and shrimp", "trigger": "A mature, settled colony with space and stable water", "spawn": "Commonly around 20 to 50 eggs", "eggs": "Females commonly hold for about 4 to 6 weeks at 76 to 80°F", "fry": "Released fully formed, roughly half an inch", "first_foods": "Newly hatched brine shrimp and crushed pellets", "grow_out": "Slow; several months to 1.5 to 2 inches", "parents": "No care after release; fry often survive in the colony"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 125 gallons, matching the minimum for this species, as adults can reach 13 inches. Build large caves with rock or pipe and use sand as substrate. Keep water hard and alkaline: pH 7.8 to 9, GH 10 to 20, and 75 to 82°F. Strong filtration and weekly water changes keep conditions stable.\n\nFrontosa are calm fish that dislike fast movement and bright light. Use moderate lighting and place the tank where people do not constantly walk past. Large rock caves or wide PVC pipe sections give holding females somewhere to retreat. Frontosa can be kept with other calm Tanganyikans, but tankmates small enough to fit in an adult's mouth will be eaten."}, {"heading": "Choosing a colony", "text": "Males are usually larger with a bigger hump on the head and longer fins, but these signs are not reliable on younger fish. Venting, checking the shape of the genital openings, is more reliable but takes practice. Many breeders buy 6 to 10 juveniles and let them grow up.\n\nFrontosa are slow to mature, often taking 2 to 3 years to breed. Keep one male with 3 to 5 females.\n\nOnce a dominant male emerges, he will display with fins spread and claim a cave. Extra males can be removed or kept in a very large tank. Look for several females spending time near the male's cave as a sign the colony is maturing."}, {"heading": "Diet and conditioning", "text": "Feed quality pellets, krill, mysis and shrimp once or twice a day. Avoid feeder fish, which can bring disease. A varied diet helps females fill with eggs.\n\nFeed moderate amounts so the fish clean up within a couple of minutes. Overfeeding fouls the water and can lead to health problems. Krill and mysis are good conditioning foods. Remove leftover food promptly, as frontosa are slow eaters compared with many cichlids."}, {"heading": "Spawning and holding", "text": "Spawning often happens in caves or at night, and you may not see it. The female lays eggs, picks them up, and the male fertilizes them. Clutches are commonly around 20 to 50 eggs.\n\nFemales commonly hold for about 4 to 6 weeks at 76 to 80°F. Holding females may hide and eat little. Many breeders leave them in the colony, as frontosa are generally calm.\n\nA holding female has a swollen throat and stays in or near a cave. Write down the date you first notice her holding so you know when release is due. If you want to move her for the release, do so near the end of the hold and gently, in a container. Many breeders say frontosa hold longer than most mouthbrooders, so be patient and avoid disturbing her."}, {"heading": "Raising the fry", "text": "Fry are released fully formed, roughly half an inch long. Feed newly hatched brine shrimp and crushed pellets two or three times a day. In a colony with good caves, many fry survive. Moving fry to their own tank helps them grow faster.\n\nFrontosa fry are big for cichlid fry and very hardy. Do 25 to 30 percent water changes weekly in the fry tank, matching hardness and pH. Use a sponge filter or prefilter so fry are not pulled in. Fry hold together in a loose group near the bottom and become more confident as they grow."}, {"heading": "Growing out", "text": "Frontosa grow slowly. Expect several months to reach 1.5 to 2 inches. Keep fry in a grow out tank with regular water changes and good feeding.\n\nFrontosa do not show their stripes and hump until they are much older. Keep fry together in a larger tank as they grow, and upgrade tank size as needed. Many breeders keep juveniles in 55 or 75 gallon tanks before moving them to larger tanks. Expect it to take a year or more to reach a size that buyers want, and several years before they breed themselves."}, {"heading": "Common mistakes", "text": "- Expecting breeding from young fish\n- Too small a tank\n- Too many males\n- Feeding feeder fish\n- Moving holding females roughly"}]$g$::jsonb, $g$[{"q": "How long do frontosa hold eggs?", "a": "Females commonly hold for about 4 to 6 weeks at 76 to 80°F."}, {"q": "How many fry do frontosa have?", "a": "Clutches are commonly around 20 to 50 eggs."}, {"q": "How old are frontosa when they breed?", "a": "Often 2 to 3 years old, as they are slow to mature."}, {"q": "How do you tell male and female frontosa apart?", "a": "Males are usually larger with a bigger hump and longer fins. Venting is more reliable."}]$g$::jsonb, $g$Frontosa hold for weeks and spawns are rarely seen, so open your log before you expect a spawn and photograph the colony with the challenge code. A dated photo of the holding female and later of the fry helps your log.$g$),
  ($g$tropheus$g$, $g$f6efddfe-9751-494c-b904-82d82f05d0e9$g$::uuid, $g$tropheus$g$, null, $g$How to Breed Tropheus moorii: Colonies, Diet and Fry$g$, $g$Tropheus moorii females hold a few large eggs for about four weeks. A Class D guide to keeping a stable colony, avoiding bloat and raising fry.$g$, $g$Tropheus moorii are colorful, active Lake Tanganyika mouthbrooders that breed readily once a large colony settles. Broods are small but the fry are big and hardy. The real challenge is managing aggression with a big group and feeding a strict herbivore diet to avoid bloat, which makes this a Class D species.$g$, $g${"method": "Maternal mouthbrooder", "sexing": "Hard to sex; males often larger and more dominant", "group": "A colony of 12 or more, with 1 or 2 males", "breeding_tank": "75 gallons or more, rockwork caves, hard alkaline water", "conditioning": "Spirulina based flakes and pellets, algae; avoid high protein foods", "trigger": "A settled colony with space and stable water", "spawn": "Small broods, commonly around 5 to 15 eggs", "eggs": "Females commonly hold for about 4 weeks at 76 to 80°F", "fry": "Released fully formed, roughly half an inch", "first_foods": "Crushed spirulina flake and fine vegetable based foods", "grow_out": "A few months to around 1.5 inches", "parents": "No care after release; fry often survive in rocks"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least 75 gallons, matching the minimum for this species. Build rockwork caves across the tank. Keep water hard and alkaline: pH 7.8 to 9, GH 10 to 25, and 76 to 82°F. Strong filtration and weekly water changes keep conditions stable.\n\nA 4 foot or longer tank gives subordinate fish room to escape. Many keepers prefer 100 gallons or more for a full colony. Arrange the rockwork into several piles so each male can hold his own space without seeing every other fish. Strong, clean water flow and high oxygen suit these fish, which come from the surf zone of Lake Tanganyika. Keep tankmates to other robust Tanganyikans or none at all."}, {"heading": "Choosing a colony", "text": "Tropheus moorii are hard to sex. Males are often larger and more dominant. Buy a colony of 12 or more juveniles of one population and let them grow up together. Remove extra males once they mature.\n\nTropheus fight with their own kind. Larger groups spread aggression. Avoid adding single new fish later.\n\nThere are many color forms of Tropheus moorii from different locations, and keeping one form per tank avoids crossbreeding. Some breeders check vents on larger juveniles to confirm sex, though this takes practice. Many keepers overstock slightly to spread aggression further. Watch for fish hiding constantly, with torn fins or pale coloring, and remove them to recover."}, {"heading": "Diet and conditioning", "text": "Tropheus are herbivores. Feed spirulina based flakes and pellets and let algae grow on rocks. Avoid high protein foods like bloodworms and beef heart, which can lead to bloat. Feed small amounts two or three times a day.\n\nIf a fish stops eating, hangs at the surface or shows a swollen belly, act quickly, as bloat can spread through a colony. Clean water and a steady diet are the best prevention. Many breeders do 25 to 30 percent water changes weekly. Avoid sudden diet changes, and keep frozen foods such as mysis to rare treats at most."}, {"heading": "Spawning and holding", "text": "Spawning happens near rocks. Broods are small, commonly around 5 to 15 eggs. Females commonly hold for about 4 weeks at 76 to 80°F. Holding females may hide and eat little. Many breeders leave them in the colony to avoid stress.\n\nSpawning often starts with the male circling the female and quivering near rocks. The female lays a few eggs at a time and picks them up, and the male fertilizes them. You can spot a holding female by her full throat and the way she avoids food. Note the date you first see her holding so you know when release is due. If you choose to move her near the end of the hold, do it gently in a container and return her to the colony soon after release."}, {"heading": "Raising the fry", "text": "Fry are released fully formed, roughly half an inch long. Feed crushed spirulina flake and fine vegetable based foods. In a colony with good rockwork, many fry survive. Moving fry to their own tank speeds growth.\n\nThe fry tank should have the same hard, alkaline water and plenty of small rocks. Do 20 to 30 percent water changes weekly, matching hardness and pH. Fry eat algae from rocks along with prepared foods, so let a little algae grow. Avoid rich foods for fry too."}, {"heading": "Growing out", "text": "Fry grow steadily on vegetable foods. Expect a few months to reach around 1.5 inches. Keep water clean and feed small amounts often.\n\nJuveniles often show different colors from adults, and color develops as they grow. Grow out colonies can be kept together until they are big enough to rehome. Raising them as a group helps them stay calm, as isolated juveniles are more likely to be bullied when introduced later. Expect to wait a year or so before they breed themselves."}, {"heading": "Common mistakes", "text": "- Feeding high protein foods\n- Too small a group\n- Adding single new fish later\n- Moving holding females roughly\n- Mixing color forms"}]$g$::jsonb, $g$[{"q": "How long do Tropheus moorii hold eggs?", "a": "Females commonly hold for about 4 weeks at 76 to 80°F."}, {"q": "How many fry do Tropheus moorii have?", "a": "Broods are small, commonly around 5 to 15 eggs."}, {"q": "Why do Tropheus need large groups?", "a": "Large groups spread aggression so no single fish is bullied."}, {"q": "What causes bloat in Tropheus?", "a": "High protein foods and stress are common causes. Stick to a vegetable based diet."}]$g$::jsonb, $g$Show the whole colony and the challenge code at stage 1, and name the color form in your log. For stage 2, a dated photo of a female with a full throat is good evidence.$g$),
  ($g$chocolate-gourami$g$, $g$dac4c681-92a3-4a40-b0b2-25ff42251e24$g$::uuid, $g$chocolate-gourami$g$, null, $g$How to Breed Chocolate Gouramis: A Mouthbrooding Challenge$g$, $g$Chocolate gouramis are delicate mouthbrooders that need very soft, acidic water and spotless care. A Class E guide for experienced breeders.$g$, $g$The chocolate gourami is one of the more delicate fish in the hobby, and breeding it is a true expert project. Unlike most gouramis it builds no bubble nest: the female carries the eggs in her mouth for about two weeks. It needs very soft, acidic, tannin stained water and excellent water quality, and few keepers manage to raise a brood, which is why it sits in Class E.$g$, $g${"method": "Maternal mouthbrooder (female holds the eggs)", "sexing": "Subtle; males often have more pointed fins with yellowish or gold edging", "group": "A group of 4 to 6 so pairs can form, or one pair in a species tank", "breeding_tank": "20 gallons, very soft acidic water, leaf litter, dim light, gentle filter", "conditioning": "Live and frozen foods such as daphnia, brine shrimp and small bloodworms", "trigger": "Very soft water near pH 5 to 6, warm 80 to 84°F, calm surroundings", "spawn": "Small broods; breeders commonly report a few dozen eggs or fewer", "eggs": "Female commonly holds for about 14 days at 80 to 84°F", "fry": "Released free swimming and well formed", "first_foods": "Newly hatched brine shrimp and microworms, with infusoria as backup", "grow_out": "Slow; several months to reach about 1 inch", "parents": "No care after release; move the female or fry to protect the young"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 gallon tank, the minimum for this species, works well for a small group or pair. Use a dark substrate, plenty of leaf litter, driftwood and floating plants to keep the light dim. Filtration should be very gentle, ideally an air driven sponge filter.\n\nChocolate gouramis come from peat swamp waters. The library range is pH 4 to 6.5 and GH 1 to 8, at 78 to 86°F. For breeding, aim for the soft, acidic end: pH around 5 to 6, very low hardness and conductivity, and 80 to 84°F. This usually means RO or rain water with leaf litter for tannins. Change water carefully, in small amounts, with water matched for temperature and chemistry."}, {"heading": "Sexing and choosing fish", "text": "Sexing is subtle. Males often have a more pointed dorsal fin and yellowish or gold edges on the dorsal and anal fins, while females tend to be plainer. These differences are easier to see in mature, well conditioned fish. Many breeders keep a group of 4 to 6 and let pairs form, then move a pair to a species tank. Avoid tankmates; chocolate gouramis are shy and easily outcompeted.\n\nBuy from a source that keeps them in soft water if you can, since fish moved suddenly from hard water often struggle. Quarantine new fish carefully in the same soft water before adding them, because chocolate gouramis are prone to skin and gill infections when stressed."}, {"heading": "Conditioning", "text": "Feed small live and frozen foods: daphnia, brine shrimp, small bloodworms and mosquito larvae. Many specimens refuse dry food at first. Feed small portions two or three times a day and remove leftovers, as decaying food quickly harms these sensitive fish. Watch for any signs of disease, which spreads quickly in this species, and keep the tank stable rather than chasing perfect numbers."}, {"heading": "Spawning and holding", "text": "Spawning usually happens near the bottom. The male courts the female with fins spread, and after the eggs are released and fertilized, the female collects them in her mouth. Breeders commonly report broods of a few dozen eggs or fewer.\n\nThe female commonly holds for about 14 days at 80 to 84°F. During this time she eats little or nothing and may hide. Disturbance can make her swallow or spit the brood, so keep the tank quiet and avoid moving her if you can.\n\nWrite down the date you first notice the female holding so you know when release is due. If you must move her, do it near the end of the hold, gently, in a container of tank water rather than a net, into a small tank with identical water."}, {"heading": "Raising the fry", "text": "When the fry are released, they are free swimming and fairly well developed. Feed newly hatched brine shrimp and microworms several times a day, with infusoria as a backup for the smallest fry. Keep water quality excellent with small, careful water changes every couple of days, matched for temperature and chemistry.\n\nMany breeders move the female to her own tank before release so the fry are safe, or move the fry out after release. Fry are sensitive to changes, so treat their tank just as carefully as the adults' tank."}, {"heading": "Growing out", "text": "Fry grow slowly. Continue with brine shrimp and add crushed frozen foods over time. Expect several months to reach about 1 inch. Keep the water soft and acidic, and avoid overcrowding. Losses are common even for skilled breeders, so expect to try several times.\n\nA small, mature grow out tank with leaf litter, floating plants and an established sponge filter is better than a bare new tank. Feed several small meals a day and keep the population modest so water quality stays high."}, {"heading": "Common mistakes", "text": "- Hard or neutral water\n- Big, sudden water changes\n- Busy tanks with active tankmates\n- Moving a holding female too early\n- Feeding only dry foods"}]$g$::jsonb, $g$[{"q": "Do chocolate gouramis build bubble nests?", "a": "No. The female carries the eggs in her mouth instead."}, {"q": "How long do chocolate gouramis hold eggs?", "a": "The female commonly holds for about 14 days at 80 to 84°F."}, {"q": "How do you tell male and female chocolate gouramis apart?", "a": "It is subtle. Males often have more pointed fins with yellow or gold edging, while females are plainer."}, {"q": "Why are chocolate gouramis hard to breed?", "a": "They need very soft, acidic water and excellent water quality, and they are sensitive to disease and disturbance."}]$g$::jsonb, $g$Photograph the pair with the challenge code at stage 1, and note your pH and hardness in the log. A clear photo of the holding female's full throat is good stage 2 evidence, since you will not see the eggs.$g$),
  ($g$licorice-gourami$g$, $g$fcd6f465-9a01-4e4f-97d3-0014dce31f76$g$::uuid, $g$licorice-gourami$g$, null, $g$How to Breed Licorice Gouramis (Parosphromenus deissneri)$g$, $g$Licorice gouramis spawn in tiny caves under a bubble nest, guarded by the male. A Class E guide to blackwater setup, spawning and raising tiny fry.$g$, $g$Licorice gouramis are tiny blackwater fish that spawn upside down in small caves, with the male guarding the eggs under a small bubble nest. They need very soft, acidic water, small live foods and a quiet tank, and the fry are tiny. It is a demanding project for experienced breeders, which is why this is a Class E species.$g$, $g${"method": "Cave spawner; male builds a small bubble nest inside the cave", "sexing": "Males have brighter fins with colored edges; females plainer with darker stripes", "group": "One pair in a species tank", "breeding_tank": "10 gallons, very soft acidic water, small caves, leaf litter, dim light", "conditioning": "Live foods such as daphnia, cyclops, microworms and baby brine shrimp", "trigger": "Very soft, acidic water near pH 5, low light and a suitable cave", "spawn": "Small clutches; breeders commonly report a few dozen eggs or fewer", "eggs": "Commonly hatch in about 1 to 2 days at 77 to 80°F", "fry": "Free swimming about 4 to 7 days after hatching; very small", "first_foods": "Infusoria or paramecium, then microworms and baby brine shrimp", "grow_out": "Several months to reach about half an inch", "parents": "Male guards eggs; remove adults or fry once fry are free swimming"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 10 gallon tank, the minimum for this species, is enough for a pair. Use a dark substrate or bare bottom, leaf litter, small caves such as tiny clay pots or film canisters, and floating plants to keep the light dim. Use a gentle sponge filter.\n\nLicorice gouramis come from blackwater peat swamps. The library range is pH 4.5 to 6.5 and GH 1 to 5, at 75 to 82°F. For breeding, aim for the soft, acidic end: pH around 5, very low hardness and conductivity, and 77 to 80°F. This usually means RO or rain water with leaf litter. Change water carefully, in small amounts, with matched water.\n\nPlace two or three caves around the tank so the male can choose. Many breeders lay the caves on their side with the opening facing the front so they can glance in without disturbing the fish. Keep the tank in a quiet room with no vibration or sudden light changes."}, {"heading": "Choosing and conditioning a pair", "text": "Males have brighter fins with colored edges, which look more striking when they display. Females are plainer, with darker horizontal stripes. Keep one pair in a species tank so the male can claim a cave without competition.\n\nMany fish sold as licorice gouramis are other Parosphromenus species, which look very similar. Keep fish from one source together and avoid mixing species or populations.\n\nFeed small live foods such as daphnia, cyclops, microworms and baby brine shrimp two or three times a day. Many licorice gouramis refuse dry food. Feed small portions and remove leftovers, since decaying food harms these sensitive fish quickly."}, {"heading": "Spawning: what you will see", "text": "The male claims a small cave and builds a small bubble nest on the ceiling. He displays to the female with fins spread, and the pair spawn upside down in the cave. Eggs stick to the ceiling and the male guards them. Clutches are small; breeders commonly report a few dozen eggs or fewer.\n\nYou may not see spawning at all, since it happens inside the cave. A male hanging near the cave entrance and chasing the female away is a good sign."}, {"heading": "Eggs and fry", "text": "At 77 to 80°F eggs commonly hatch in about 1 to 2 days. The fry hang in the cave for a few more days, becoming free swimming about 4 to 7 days after hatching. The male usually guards the brood until then. Avoid checking the cave often, as disturbance can make the male eat the eggs.\n\nOnce the fry are free swimming, many breeders move the adults out so the fry are safe."}, {"heading": "Raising the fry", "text": "The fry are very small. Offer infusoria or paramecium several times a day for the first week, then add microworms and newly hatched brine shrimp. Keep water quality excellent with small, careful water changes every couple of days, matched for temperature and chemistry. A lightly planted tank with leaf litter grows microorganisms between feedings.\n\nKeep the fry tank covered to hold warmth and humidity, as many labyrinth fry are sensitive to cold air while their labyrinth organ develops. Start brine shrimp only once the fry can clearly take it, usually after the first week."}, {"heading": "Growing out", "text": "Fry grow slowly. Continue with brine shrimp and microworms, adding crushed frozen foods such as cyclops over time. Expect several months to reach about half an inch, and longer before males show their adult colors. Keep the water soft and acidic, and avoid overcrowding."}, {"heading": "Common mistakes", "text": "- Hard or neutral water\n- Bright light and no cover\n- Checking the cave constantly\n- Mixing similar looking Parosphromenus species\n- No live foods ready for tiny fry"}]$g$::jsonb, $g$[{"q": "How do licorice gouramis breed?", "a": "They spawn upside down in small caves, and the male guards the eggs under a small bubble nest."}, {"q": "How long do licorice gourami eggs take to hatch?", "a": "Commonly about 1 to 2 days at 77 to 80°F."}, {"q": "How can you tell male and female licorice gouramis apart?", "a": "Males have brighter fins with colored edges, while females are plainer with darker stripes."}, {"q": "What do licorice gourami fry eat?", "a": "Infusoria or paramecium first, then microworms and newly hatched brine shrimp."}]$g$::jsonb, $g$Photograph your pair with the challenge code at stage 1 and note the source of your fish, since many are sold under the wrong species name. Eggs are hidden in the cave, so a brief flashlight photo of the eggs or fry is your best stage 2 evidence.$g$),
  ($g$denison-barb$g$, $g$83e06a2d-cc96-404f-9ad8-10f1db225575$g$::uuid, $g$denison-barb$g$, null, $g$Breeding Denison Barbs: What Is Known and What to Try$g$, $g$Denison barbs are rarely bred in home aquariums, and most are farm bred. A Class E guide to what is known, setup, sexing and raising fry if you succeed.$g$, $g$Denison barbs, also called roseline sharks, are rarely bred in home aquariums. Most fish in the trade come from commercial farms that use hormone induced spawning, something home breeders should not attempt. Wild populations are endangered, so breeding them naturally is worthwhile, but it takes a large tank, a mature group and patience, which is why it sits in Class E.$g$, $g${"method": "Egg scatterer", "sexing": "Females larger and rounder; males slimmer. Hard to sex reliably", "group": "A group of 6 or more", "breeding_tank": "55 gallons or more, strong flow, fine plants or mops, clean water", "conditioning": "Frozen bloodworms, brine shrimp and quality flakes and pellets", "trigger": "Not well documented; breeders report cool water changes and high oxygen", "spawn": "Not well documented in home aquariums", "eggs": "Hatch timing in home aquariums is not well documented", "fry": "Small; little hobby data on free swimming age", "first_foods": "Infusoria, then baby brine shrimp", "grow_out": "Several months to reach about 2 inches", "parents": "No care; adults eat eggs, so remove adults or eggs after spawning"}$g$::jsonb, $g$[{"heading": "What is known about breeding them", "text": "Denison barbs come from fast flowing, oxygen rich rivers in southern India and are listed as endangered in the wild. Commercial farms produce them using hormone induced spawning. Home breeding reports are rare, and many details such as clutch size, hatch time and fry development in home aquariums are not well documented.\n\nThis guide focuses on what is known and what breeders commonly try. If you succeed, your notes will be valuable to other keepers."}, {"heading": "Setting up the breeding tank", "text": "Use at least 55 gallons, matching the minimum for this species, as adults reach about 4.5 inches. Provide strong flow, high oxygen and clean water, with fine leaved plants or spawning mops. Keep the water at 68 to 75°F, within the 65 to 77°F range, with pH 6.5 to 7.8 and moderate hardness.\n\nA long tank works best, with a powerhead or strong filter outlet creating current along its length. Place the spawning mops or plants in a calmer area downstream. Keep the lid on, since these active fish can jump. A separate, smaller hatching tank of 10 to 20 gallons with a mature sponge filter should be ready before you try."}, {"heading": "Choosing and conditioning a group", "text": "Females are usually larger and rounder, especially when full of eggs. Males are slimmer. Color is similar in both sexes, so sexing is hard. Keep a group of 6 or more mature fish.\n\nFeed a varied diet of frozen bloodworms, brine shrimp and quality flakes and pellets two or three times a day. Good conditioning is likely the most important step.\n\nDenison barbs mature slowly and do best in larger groups. A school of 8 to 10 or more is calmer and may give you a better mix of sexes. Fish that have been in your care for a year or more and are full sized are the best candidates. Add a little vegetable matter, such as spirulina flake, to their diet."}, {"heading": "Spawning: what to try", "text": "There is no proven trigger in home aquariums. Breeders commonly try large, cool water changes, strong flow and high oxygen to mimic monsoon conditions. Watch for males chasing females through plants.\n\nAs egg scatterers, adults will eat eggs. Use spawning mops or mesh over the bottom so eggs fall out of reach, and remove adults after spawning.\n\nSome breeders let a group live in a large, planted tank with good flow and simply check mops every few days for eggs. Others move a ripe female and a couple of males into a separate tank with mops. Record water temperature, changes and feeding so you can see what worked."}, {"heading": "Eggs and fry", "text": "Hatch timing in home aquariums is not well documented. Keep the eggs in clean, well oxygenated water at the same temperature as the spawning tank. Remove any white, fungused eggs.\n\nOnce fry are free swimming, offer infusoria several times a day, then newly hatched brine shrimp. Do small daily water changes with matched water.\n\nAdd a little gentle aeration near the eggs, but avoid strong currents in the hatching tank, which can sweep away tiny fry. Keep the hatching tank dim and covered."}, {"heading": "Growing out", "text": "Fry grow steadily on brine shrimp and crushed flakes. Expect several months to reach about 2 inches. Move juveniles to a larger tank with strong flow as they grow, and keep them in a group.\n\nJuveniles start to show the red stripe as they grow. Keep them in a group in clean, cool, well oxygenated water and feed several small meals a day. Rehome young fish only to keepers with large enough tanks, as adults need plenty of space."}, {"heading": "Common mistakes", "text": "- Too small a tank\n- Warm, still water\n- Leaving adults with the eggs\n- Expecting quick results\n- Using hormones, which is not something home breeders should attempt"}]$g$::jsonb, $g$[{"q": "Can you breed Denison barbs at home?", "a": "It is rare but possible. Most fish in the trade are farm bred using hormones."}, {"q": "How do you tell male and female Denison barbs apart?", "a": "Females are usually larger and rounder, especially when full of eggs. Males are slimmer."}, {"q": "Are Denison barbs endangered?", "a": "Yes. Wild populations are listed as endangered, so captive bred fish are the best choice."}, {"q": "What do Denison barb fry eat?", "a": "Infusoria first, then newly hatched brine shrimp."}]$g$::jsonb, $g$A home spawn of Denison barbs is rare, so open your log before you try and photograph the group with the challenge code. Detailed dated photos of eggs and fry make your log valuable to other members.$g$),
  ($g$red-tail-shark$g$, $g$0e374468-6a3a-4b41-b8d7-fccb03e27d75$g$::uuid, $g$red-tail-shark$g$, null, $g$Breeding Red-tailed Black Sharks: What Is Known and Why It's Rare$g$, $g$Red-tailed black sharks are rarely bred at home; most are farm bred with hormones. A Class E guide to what is known, setup and managing aggression.$g$, $g$Red-tailed black sharks are popular but are rarely bred in home aquariums. Commercial farms produce them using hormone induced spawning, which home breeders should not attempt. The biggest obstacle is aggression: these fish are territorial and often fight with their own kind. Breeding them naturally is a real achievement, which is why this species sits in Class E.$g$, $g${"method": "Egg scatterer", "sexing": "Females larger and rounder; males slimmer. Hard to sex reliably", "group": "A pair in a large tank, but aggression is a serious risk", "breeding_tank": "55 gallons or more, caves, plants, strong filtration", "conditioning": "Algae based foods, frozen bloodworms and brine shrimp", "trigger": "Not well documented in home aquariums", "spawn": "Not well documented in home aquariums", "eggs": "Hatch timing in home aquariums is not well documented", "fry": "Little hobby data on free swimming age", "first_foods": "Infusoria, then baby brine shrimp", "grow_out": "Several months to reach about 2 inches", "parents": "No care; adults eat eggs, so remove adults or eggs after spawning"}$g$::jsonb, $g$[{"heading": "What is known about breeding them", "text": "Red-tailed black sharks come from Thailand and are very rare in the wild. Commercial farms produce them using hormone induced spawning. Home breeding reports are very rare, and details such as clutch size and hatch time in home aquariums are not well documented.\n\nThis guide focuses on what is known and what breeders commonly try.\n\nThis species is considered critically endangered in the wild, so nearly all fish in shops come from farms. A natural spawn in a home aquarium would be a notable achievement, and good notes help other keepers."}, {"heading": "Setting up the breeding tank", "text": "Use at least 55 gallons, matching the minimum for this species. Provide caves, rockwork, driftwood and plants to break sight lines. Keep the water at 74 to 79°F, within the 72 to 79°F range, with pH 6.5 to 7.8 and moderate hardness. Strong filtration and weekly water changes keep water clean.\n\nA long tank is better than a tall one, because these sharks claim territory along the bottom. Give each fish its own cave at opposite ends, and break up sight lines so they can avoid each other. A divider is useful to have on hand if fighting starts."}, {"heading": "Choosing a pair", "text": "Females are usually larger and rounder. Males are slimmer. Sexing is hard. Red-tailed black sharks are territorial and often fight with their own kind. Keeping two in the same tank is risky, and many keepers keep only one. If you try a pair, use a large tank with many hiding places and watch closely for fights.\n\nIf you want to try, buy a few juveniles and grow them up together in a very large tank. Two fish that tolerate each other once mature are the best candidates. Separate any fish that is being constantly chased, as stress can quickly lead to injury or death."}, {"heading": "Conditioning", "text": "Feed algae based foods, frozen bloodworms and brine shrimp two or three times a day. Let algae grow on rocks. A varied diet supports good condition.\n\nGood conditioning involves frequent small meals and clean water. Add blanched vegetables such as zucchini or spinach. Keep up 25 to 30 percent weekly water changes."}, {"heading": "Spawning and eggs", "text": "There is no proven trigger in home aquariums. If eggs appear, remove adults or move eggs to a separate tank, as adults eat eggs. Keep the eggs in clean, well oxygenated water. Remove any white, fungused eggs.\n\nWatch for unusual behavior, such as a pair swimming close together without fighting or a female looking noticeably rounder. Spawning mops or fine plants give eggs somewhere to land. Record water conditions, temperature and feeding, as these notes are valuable."}, {"heading": "Raising the fry", "text": "Once fry are free swimming, offer infusoria several times a day, then newly hatched brine shrimp. Do small daily water changes with matched water. Fry grow steadily on brine shrimp and crushed flakes.\n\nKeep fry tanks dim and covered, with an established sponge filter. Feed small meals several times a day and siphon leftovers. Juveniles are likely to become territorial as they grow, so give them plenty of space and hiding places.\n\nIf you do raise fry, expect several months for them to reach about 2 inches. Rehome them only to keepers who understand how territorial adults become."}, {"heading": "Common mistakes", "text": "- Keeping several sharks in a small tank\n- Too few hiding places\n- Leaving adults with eggs\n- Expecting quick results\n- Using hormones, which is not something home breeders should attempt"}]$g$::jsonb, $g$[{"q": "Can you breed red-tailed black sharks at home?", "a": "It is very rare. Most fish in the trade are farm bred using hormones."}, {"q": "How do you tell male and female red-tailed black sharks apart?", "a": "Females are usually larger and rounder. Males are slimmer. Sexing is hard."}, {"q": "Can two red-tailed black sharks live together?", "a": "It is risky. They are territorial and often fight with their own kind."}, {"q": "What do red-tailed black shark fry eat?", "a": "Infusoria first, then newly hatched brine shrimp."}]$g$::jsonb, $g$A home spawn of red-tailed black sharks is very rare, so open your log before you try and photograph the pair with the challenge code. Detailed dated photos of eggs and fry make your log valuable to other members.$g$),
  ($g$synodontis-multipunctatus$g$, $g$c6c93f6a-d76b-4604-9861-75da6d69199e$g$::uuid, $g$synodontis-multipunctatus$g$, null, $g$How to Breed Cuckoo Catfish: Brood Parasites and Host Cichlids$g$, $g$Cuckoo catfish lay eggs among spawning mouthbrooding cichlids, which carry the catfish young. A Class E guide to hosts, setup and raising fry.$g$, $g$The cuckoo catfish has one of the most unusual breeding strategies in the hobby. It sneaks its eggs into the spawning of mouthbrooding cichlids, and the cichlid female carries them in her mouth. The catfish eggs hatch first and the young eat the cichlid's eggs. Breeding them means keeping a group of catfish with a colony of mouthbrooders, which is why it sits in Class E.$g$, $g${"method": "Brood parasite of mouthbrooding cichlids", "sexing": "Females larger and plumper; males slimmer with a visible genital papilla", "group": "3 or more catfish with a colony of mouthbrooding cichlids", "breeding_tank": "50 gallons or more, rockwork, hard alkaline water, active host colony", "conditioning": "Sinking pellets, frozen bloodworms and brine shrimp", "trigger": "Host cichlids spawning; the catfish join in", "spawn": "A few catfish young per host brood, varying widely", "eggs": "Hatch inside the host's mouth before the host eggs, per breeder reports", "fry": "Released by the host female, well formed and free swimming", "first_foods": "Baby brine shrimp and crushed sinking foods", "grow_out": "Several months to reach about 2 inches", "parents": "No care; host cichlid carries the young"}$g$::jsonb, $g$[{"heading": "How cuckoo catfish breed", "text": "When mouthbrooding cichlids spawn, cuckoo catfish rush in and release their own eggs among the cichlid eggs. The cichlid female picks up the catfish eggs with her own. Breeders report that the catfish eggs hatch first, and the young catfish eat the cichlid eggs or fry in the female's mouth. The cichlid then releases catfish young instead of her own.\n\nCuckoo catfish come from Lake Tanganyika, where they use local mouthbrooding cichlids as hosts. In aquariums they have been bred with a range of African mouthbrooders. This strategy means you cannot breed them without a regularly spawning host colony."}, {"heading": "Setting up the breeding tank", "text": "Use at least 50 gallons, matching the minimum for this species. Build rockwork caves for the catfish and space for the cichlids to spawn. Keep the water hard and alkaline: pH 7.8 to 9, GH 10 to 25, and 75 to 82°F. Strong filtration and weekly water changes keep water clean.\n\nA long tank of 75 gallons or more gives room for both a host colony and a group of catfish. Use sand and rockwork with plenty of caves and gaps, as the catfish are shy during the day. Keep lighting moderate and feed some food after lights out so the catfish eat well."}, {"heading": "Choosing catfish and hosts", "text": "Keep 3 or more cuckoo catfish, matching the minimum group size. Females are larger and plumper, while males are slimmer and show a visible genital papilla near the vent.\n\nHosts are mouthbrooding cichlids that spawn regularly. Lake Tanganyika and Lake Malawi mouthbrooders are commonly used. Choose a host species that breeds readily in your tank.\n\nMany breeders keep 5 or more catfish so several are ready whenever the hosts spawn. Choose host cichlids that are compatible with the catfish and with your water. Avoid very aggressive or very large cichlids that may harm the catfish. Keep host species pure and avoid mixing species that could crossbreed."}, {"heading": "Conditioning", "text": "Feed sinking pellets, frozen bloodworms and brine shrimp once or twice a day, usually after lights out when catfish are most active. Make sure the catfish get enough food, as cichlids may eat most of it."}, {"heading": "Spawning: what you will see", "text": "When host cichlids spawn, the catfish rush in and swim through the spawning site, releasing eggs. This is quick and easy to miss. The host female then holds the eggs as usual.\n\nYou may notice catfish gathering around spawning cichlids, darting into the spawning site and then quickly retreating. Over time, you may notice host females releasing catfish young instead of cichlid fry, which confirms success."}, {"heading": "Raising the fry", "text": "The host female releases the young after holding. Many breeders move holding females to a separate tank before release so the catfish young are safe. Feed baby brine shrimp and crushed sinking foods. Do weekly water changes, matching hardness and pH.\n\nCatfish young hide in rockwork and grow steadily. Expect several months to reach about 2 inches.\n\nNote the date each host female starts holding. Moving a host female to a separate tank near the end of her hold lets you see what she releases. Catfish young are usually darker and spotted, quite different from cichlid fry. Return the host female to the colony once she has released and is eating well.\n\nKeep catfish young in a tank with sand and small caves, and feed several times a day, including after lights out."}, {"heading": "Common mistakes", "text": "- No regularly spawning host cichlids\n- Too few catfish\n- Not feeding enough for the catfish\n- Leaving host females in the main tank before release\n- Soft or acidic water"}]$g$::jsonb, $g$[{"q": "How do cuckoo catfish breed?", "a": "They sneak their eggs into mouthbrooding cichlid spawns. The cichlid female carries the catfish eggs."}, {"q": "Do cuckoo catfish need cichlids to breed?", "a": "Yes. They rely on mouthbrooding cichlids as hosts."}, {"q": "How do you tell male and female cuckoo catfish apart?", "a": "Females are larger and plumper. Males are slimmer with a visible genital papilla."}, {"q": "What do cuckoo catfish fry eat?", "a": "Baby brine shrimp and crushed sinking foods."}]$g$::jsonb, $g$Photograph the catfish group and host cichlids with the challenge code at stage 1. For stage 2, a photo of a holding host female plus the catfish near the spawning site is your best evidence.$g$),
  ($g$king-tiger-pleco$g$, $g$a58f5f39-d9e7-4b2d-b5c3-11680f5ff473$g$::uuid, $g$king-tiger-pleco$g$, null, $g$How to Breed King Tiger Plecos (L333): Caves, Flow and Fry$g$, $g$Breeding L333 king tiger plecos means warm, well oxygenated water, snug caves and patience while the male guards the eggs. An expert level catfish project.$g$, $g$The king tiger pleco is one of the more willing Hypancistrus to spawn, but it is still a patient, expert level project. Males guard eggs deep inside a cave, so most of what you see is a bulging male and, weeks later, tiny striped plecos at the entrance. Getting adults settled, setting up good flow and caves, and growing the slow fry are the real work, and every patterned youngster is different.$g$, $g${"method": "Cave spawner (male guards eggs and fry inside the cave)", "sexing": "Males have broader heads and more bristles on pectoral spines and cheeks; females rounder from above", "group": "1 male to 2 or 3 females, or several of each with a cave for every male", "breeding_tank": "20 to 40 gallon long tank, strong flow, several snug caves facing the current", "conditioning": "Meaty foods like bloodworms, shrimp, mysis and quality sinking pellets for 4 to 8 weeks", "trigger": "Settled adults, warm water, strong current, high oxygen and regular large water changes", "spawn": "Commonly reported around 15 to 40 eggs per clutch", "eggs": "Hatch in about 5 to 7 days at 82 to 84°F, guarded by the male", "fry": "Live off a large yolk sac for about 10 to 14 days more, then leave the cave and graze", "first_foods": "Sinking pellets, crushed wafers, frozen bloodworms and baby brine shrimp", "grow_out": "Slow: often several months to reach about 1 inch", "parents": "Male guards well; if he keeps ejecting eggs, hatch them in a tumbler or mesh basket"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 to 40 gallon long tank is plenty for one male and a couple of females. What matters most is water quality, current and caves. Run a canister or strong sponge filter plus a powerhead so water moves across the caves, and add an air stone for oxygen.\n\nKeep the temperature around 82 to 84°F, within the 78 to 86°F range in our care data. Soft to moderately hard water, pH 6.0 to 7.5, works. Offer several clay or slate caves with one open end, just wide enough for the male to turn in, placed so the entrance faces the flow."}, {"heading": "Choosing and conditioning breeders", "text": "Start with adult fish, usually 3 inches or more and a couple of years old. Mature males show broader, heavier heads and more noticeable bristles (odontodes) on the pectoral spines and behind the gill covers. Females look rounder and fuller from above and have narrower heads. Young fish are hard to sex, so buying 4 to 6 juveniles and growing them up is a good way to get pairs.\n\nThese are meat eaters at heart. Feed sinking pellets, frozen bloodworms, mysis and chopped shrimp daily, with a vegetable wafer now and then. Give conditioning 4 to 8 weeks and keep up weekly water changes of 30 to 50 percent."}, {"heading": "What spawning looks like", "text": "A male claims a cave and spends most of his time there. When a female is ready, he lures her in and they spawn inside, sometimes over a day or more. Afterward the female leaves and the male stays at the entrance, fanning the clutch with his fins.\n\nMany breeders find big water changes with slightly cooler water and a stronger current help start things. Don't keep checking the cave with a flashlight; a disturbed new male may eject or eat the eggs."}, {"heading": "Eggs and the male's care", "text": "Clutches are commonly reported at about 15 to 40 large yellowish eggs, stuck together in a clump. At 82 to 84°F they hatch in roughly 5 to 7 days. The male keeps fanning and cleaning them the whole time.\n\nIf a male repeatedly kicks out eggs, gently move the clump to an egg tumbler or a mesh breeder box in strong flow, and remove any white, fungused eggs. A drop of air in a tumbler is enough to keep eggs rolling without damaging them."}, {"heading": "Raising the fry", "text": "Newly hatched fry carry a large orange yolk sac and stay in the cave for another 10 to 14 days or so. Do not feed until the yolk is nearly gone, or you will only foul the water.\n\n- Week 1 after the yolk is used: crushed sinking pellets, wafer crumbs and frozen baby brine shrimp, a little twice a day.\n- Weeks 2 to 4: add chopped bloodworms and small sinking pellets.\n- Do daily small water changes or 30 to 50 percent every few days, and siphon leftovers.\n\nKeep fry at the same warm temperature with good flow. A bare bottom tank or a breeder net in the main tank makes cleaning easy."}, {"heading": "Growing out", "text": "Hypancistrus are slow. Expect several months for fry to reach about an inch and longer to reach a size people will buy. Feed several small meals a day and keep water very clean, because poor water stunts them quickly. Give growing fish small caves or pieces of pipe so they can hide. Keep L333 lines separate from other Hypancistrus so you never produce hybrids, and label your fish honestly when you pass them on."}, {"heading": "Common mistakes", "text": "- Caves that are too big or too small. The male should fit snugly with just enough room to turn.\n- Weak flow and low oxygen. These are river fish and often won't spawn in still water.\n- Feeding fry before the yolk sac is gone.\n- Keeping several Hypancistrus types together, which risks hybrid fry.\n- Disturbing a new male so he abandons or eats the clutch."}]$g$::jsonb, $g$[{"q": "How do I tell a male L333 from a female?", "a": "Adult males have broader heads and more prominent bristles on the pectoral fin spines and cheeks. Females are rounder through the belly when seen from above and have slimmer heads."}, {"q": "How long do L333 eggs take to hatch?", "a": "Breeders commonly report about 5 to 7 days at 82 to 84°F. The fry then live on their yolk sac for roughly another 10 to 14 days before feeding."}, {"q": "How many eggs does a king tiger pleco lay?", "a": "Clutches are commonly reported around 15 to 40 eggs, with young pairs often laying fewer."}, {"q": "Can L333 breed in a community tank?", "a": "It can happen if there are good caves and strong flow, but fry survival is much better in a dedicated tank where they are not competing with other fish for food."}]$g$::jsonb, $g$For stage 1, photograph the male and females together with your challenge code card, and photograph the cave entrance once he starts guarding. A clear shot of eggs or yolk sac fry in the cave or tumbler works well for stage 2.$g$),
  ($g$synodontis-lucipinnis$g$, $g$a7e93bf4-9a80-43ac-b333-f40871171557$g$::uuid, $g$synodontis-lucipinnis$g$, null, $g$Breeding Synodontis lucipinnis: Lake Tanganyika Catfish Guide$g$, $g$Synodontis lucipinnis is an egg scatterer from Lake Tanganyika with no parental care. Hard water, a group and an egg trap give you a chance. Expert level.$g$, $g$Synodontis lucipinnis, the dwarf petricola catfish, is a rarely bred aquarium catfish, and most fish in shops come from commercial farms. Hobbyists do report spawns in rocky, hard water tanks, but the adults scatter the eggs and give no care, so eggs must be caught before they are eaten. Expect an expert level project with little written detail, small slow growing fry, and a real sense of achievement if you raise them.$g$, $g${"method": "Egg scatterer, no parental care", "sexing": "Hard; males slimmer with a pointed genital papilla, females plumper and rounder when ripe", "group": "A group of 4 to 6 adults so pairs can form", "breeding_tank": "30 gallons or more, sand, rockwork, caves and a dish of marbles to catch eggs", "conditioning": "Varied foods: sinking pellets, bloodworms, brine shrimp and some vegetable matter for several weeks", "trigger": "Not well understood; hobbyists credit stable hard water, good conditioning and water changes", "spawn": "Not well documented; reports vary from a few dozen eggs upward", "eggs": "Breeders report hatching in roughly 2 to 3 days at about 77 to 79°F", "fry": "Live on a yolk sac for a few days, then begin feeding; small and secretive", "first_foods": "Baby brine shrimp, microworms and finely crushed sinking pellets", "grow_out": "Commonly reported as very slow growing; plan on many months to reach sellable size", "parents": "No care; adults and tankmates eat eggs, so trap eggs or remove them promptly"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use at least a 30 gallon tank with fine sand, stacked rocks and a few caves, like a small Lake Tanganyika setup. Our care data lists 75 to 82°F, pH 7.8 to 9.0 and hard water (GH 10 to 25), and breeding attempts should stay right in that range. Many keepers aim for about 77 to 79°F.\n\nBecause the adults give no care, many breeders place a shallow dish filled with glass marbles or coarse gravel near the caves. Eggs scattered over it fall between the marbles where the adults can't reach them. Gentle filtration and a sponge prefilter keep eggs and fry out of the intake."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is difficult. Mature males are usually slimmer, and when you look closely at the vent, males show a small pointed genital papilla. Ripe females are noticeably plumper. The easiest route is to keep a group of 4 to 6 adults and let them sort themselves out.\n\nThese are omnivores. Feed sinking pellets, frozen bloodworms, brine shrimp and mysis, plus some algae or vegetable based food, once or twice a day for several weeks. Keep the group well fed so they are less likely to hunt eggs."}, {"heading": "What spawning looks like", "text": "Spawning in this species is not well documented in home tanks. Reports describe fish chasing each other around the rockwork, often at night or early morning, and eggs turning up on the substrate or in the marble dish afterward. You may only discover a spawn when you see eggs or tiny fry.\n\nCheck the egg trap each morning with a flashlight. Regular water changes with matched hard water are the most common factor hobbyists mention before a spawn."}, {"heading": "Eggs", "text": "Collect any eggs you find into a small hatching container with water from the breeding tank, an air stone and a matching temperature. Breeders report that eggs hatch in roughly 2 to 3 days at about 77 to 79°F.\n\nInfertile eggs turn white and grow fungus quickly. Remove them with a pipette every day so the fungus doesn't spread to good eggs. Gentle aeration helps keep the remaining eggs healthy."}, {"heading": "Raising the fry", "text": "Newly hatched fry live on their yolk sac for a few days. Once they start moving around and the yolk is gone, begin feeding.\n\n- First 2 weeks: baby brine shrimp and microworms, two or three small feedings a day.\n- Weeks 3 to 6: add finely crushed sinking pellets and frozen foods.\n- Change 20 to 30 percent of the water every few days with hard, matched water, and siphon leftover food.\n\nFry are shy, so give them small hiding places such as pieces of pipe or shells."}, {"heading": "Growing out", "text": "Juveniles of this species are commonly reported to grow very slowly. Plan on many months before they look like small adults. Keep them in a dedicated grow out tank with steady water quality, several small meals a day and plenty of cover. Keep the young away from other Synodontis so there is no question about what they are when you pass them on. Once they reach about an inch, move them onto small sinking pellets and frozen foods, and keep water changes regular so hardness and pH stay steady."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults, who will eat them.\n- Soft or acidic water. This is a hard water lake species.\n- Mixing with other Synodontis, especially the cuckoo catfish, and causing confusion over fry.\n- Overfeeding tiny fry, which fouls their small container."}]$g$::jsonb, $g$[{"q": "Has Synodontis lucipinnis been bred in aquariums?", "a": "Yes, hobbyists have reported spawns, but it is rare and not well documented. Most fish sold come from commercial farms."}, {"q": "Do Synodontis lucipinnis look after their eggs?", "a": "No. They scatter eggs with no parental care, and adults will eat them, so collect eggs or use a marble dish as an egg trap."}, {"q": "How do you sex Synodontis lucipinnis?", "a": "It is hard. Males tend to be slimmer with a pointed genital papilla, while ripe females are plumper."}, {"q": "Is Synodontis lucipinnis a cuckoo catfish?", "a": "No. The cuckoo catfish is Synodontis multipunctatus, which lays eggs among mouthbrooding cichlids. Synodontis lucipinnis is a free egg scatterer."}]$g$::jsonb, $g$Because spawns are easy to miss, open your log as soon as your group is settled and photograph the group with the challenge code card. Photograph eggs in the marble dish or hatching container on the day you find them for stage 2.$g$),
  ($g$otocinclus$g$, $g$68a74843-e048-4b38-8d97-946430e659e7$g$::uuid, $g$otocinclus$g$, null, $g$How to Breed Otocinclus: Eggs, Algae and Raising Tiny Fry$g$, $g$Otocinclus lay eggs on plants and glass and give no care. Spawning is possible in a mature planted tank, but raising the tiny fry is the expert part.$g$, $g$Otocinclus are rarely bred in home tanks, and almost all of them sold are wild caught. A well fed group in a mature, planted tank will sometimes lay small eggs on leaves and glass. The hard part is the fry: they are tiny, need constant algae and biofilm, and are lost easily to dirty water or starvation. That is why they are an expert level fish, and why every raised batch is worth logging.$g$, $g${"method": "Egg depositor: single eggs stuck to leaves and glass, no parental care", "sexing": "Females larger and broader, males slimmer with a small genital papilla", "group": "A group of 6 or more adults", "breeding_tank": "10 to 20 gallon mature planted tank with algae, biofilm and a sponge filter", "conditioning": "Plenty of algae and biofilm plus blanched zucchini and algae wafers for several weeks", "trigger": "Large, slightly cooler water changes after good feeding", "spawn": "Reports vary, commonly a few dozen eggs laid over a day or two", "eggs": "Commonly reported to hatch in about 2 to 3 days at 75 to 78°F", "fry": "Very small fry that start grazing within a few days", "first_foods": "Algae and biofilm on surfaces, green water, powdered algae foods", "grow_out": "Several months to reach about an inch", "parents": "No care; adults don't usually hunt fry but compete with them for algae"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 10 to 20 gallon tank that has been running for months, with live plants, rocks and glass covered in soft algae and biofilm. The fry depend on this growth, so a new, clean tank is the wrong choice.\n\nRun a sponge filter so fry are not sucked up. Our care data lists 72 to 79°F, pH 6.0 to 7.5 and soft to medium water. Many breeders keep about 75 to 78°F. Leave the back and sides of the glass uncleaned to grow food."}, {"heading": "Choosing and conditioning breeders", "text": "Buy a group of at least 6 healthy, well fed fish and quarantine them, since wild caught otos often arrive thin. Females are larger and rounder from above. Males are slimmer and, up close, show a small genital papilla behind the vent.\n\nFeed heavily for several weeks: natural algae, blanched zucchini or cucumber, and algae wafers, with an occasional small meaty treat. Fat, rounded bellies are a sign the fish are ready. Thin fish will not spawn, and many die in the first weeks, so get them strong before trying to breed."}, {"heading": "What spawning looks like", "text": "Spawning is often triggered by a large water change with slightly cooler water, imitating rain. Males chase females, and pairs take up a T position similar to Corydoras. The female then places single, sticky, clear to pale eggs on plant leaves, wood or glass. This can continue over a day or two.\n\nYou may only notice the small eggs afterward. Look on the undersides of broad leaves and on the glass near the water line."}, {"heading": "Eggs", "text": "Eggs are commonly reported to hatch in about 2 to 3 days at 75 to 78°F. Adults usually leave the eggs alone, so many breeders simply leave them in the planted tank. If you prefer to move them, cut the leaf or gently roll eggs off the glass with a finger and place them in a container of tank water with a light air stone.\n\nRemove any white, fuzzy eggs each day so fungus doesn't spread."}, {"heading": "Raising the fry", "text": "Fry are tiny and spend their time grazing on surfaces. Starvation is the most common cause of loss, so food must be available all day.\n\n- Days 1 to 7: algae and biofilm on surfaces, green water and powdered algae food.\n- Weeks 2 to 4: add finely crushed algae wafers, blanched vegetables and a little baby brine shrimp or microworms.\n- Change 10 to 20 percent of water every couple of days, matching temperature and chemistry closely.\n\nKeep rocks and leaves from the main tank cycling into the fry tank to supply fresh algae."}, {"heading": "Growing out", "text": "Fry grow slowly and take several months to reach about an inch. Keep feeding several times a day, keep nitrates low and avoid sudden swings. Losses are common in the first month even in good conditions, so a batch that survives two months is a real result. Keep a steady supply of algae rocks or blanched vegetables in the grow out tank. Once the young reach about half an inch they become much hardier and can share a quiet planted tank with small, peaceful fish."}, {"heading": "Common mistakes", "text": "- Trying to breed thin, newly imported fish.\n- A spotless new tank with no algae for fry.\n- Big, sudden water changes in the fry tank.\n- Strong filters without a sponge cover.\n- Assuming every oto is the same species. Several look alike, so record what you have as best you can."}]$g$::jsonb, $g$[{"q": "Do otocinclus breed in aquariums?", "a": "Occasionally, usually in mature planted tanks with a well fed group. It is uncommon, and most otos in shops are wild caught."}, {"q": "What do otocinclus eggs look like?", "a": "Small, clear to pale single eggs stuck to leaves, wood or glass. They are commonly reported to hatch in about 2 to 3 days."}, {"q": "What do baby otocinclus eat?", "a": "Algae and biofilm on surfaces, green water and powdered algae foods, with crushed wafers added as they grow."}, {"q": "How can you tell male and female otocinclus apart?", "a": "Females are larger and rounder, especially from above. Males are slimmer and have a small genital papilla."}]$g$::jsonb, $g$Photograph your group in the planted tank with the challenge code card when you open the log, then take close photos of eggs on leaves or glass for stage 2. Fry are tiny, so a magnifier or macro lens helps for stage 3.$g$),
  ($g$rubber-lip-pleco$g$, $g$88a0f1b6-8844-444f-a54a-557fe3d2a33f$g$::uuid, $g$rubber-lip-pleco$g$, null, $g$Breeding Rubberlip Plecos (Chaetostoma formosae): What We Know$g$, $g$Rubberlip plecos have been spawned by a few hobbyists in cool, fast, oxygen rich tanks with caves. Breeding is rare and poorly documented. Expert level.$g$, $g$The rubberlip or bulldog pleco is rarely bred in home aquariums, and only a handful of spawning reports exist. Breeders who have succeeded describe cool, fast flowing, very well oxygenated water and caves or flat stones where a male guards the eggs. Treat this as an expert level project: set up stream conditions, keep a group of mature adults, and be ready to learn as you go.$g$, $g${"method": "Cave or crevice spawner; breeders report the male guards eggs", "sexing": "Unreliable; mature males reported to have broader heads, females fuller bellies", "group": "A group of 4 to 6 adults with more caves than fish", "breeding_tank": "30 gallons or more, strong current, high oxygen, caves and flat stones", "conditioning": "Algae, biofilm, vegetable wafers and blanched vegetables with some small meaty foods", "trigger": "Not well understood; cool, fast, clean water and large water changes are mentioned", "spawn": "Poorly documented; reported clutches are small to moderate", "eggs": "Breeders report roughly a week to hatch, depending on temperature", "fry": "Start grazing after the yolk sac is used up", "first_foods": "Biofilm, algae, crushed algae wafers and blanched vegetables", "grow_out": "Slow; several months to reach 1 to 2 inches", "parents": "Male guards eggs; adults are not known as fry eaters but compete for food"}$g$::jsonb, $g$[{"heading": "What is known", "text": "Chaetostoma formosae comes from fast, cool streams in Colombia. Captive spawns have been reported by a small number of hobbyists, but there is little detailed, repeatable information. What follows is based on those reports and on how related Chaetostoma breed. Where numbers are given, treat them as a guide rather than a promise.\n\nThe good news is that these fish are hardy, long lived and easy to keep healthy in the right conditions, so you can keep a group for years while you work toward a spawn. Patience and steady conditions matter far more than any special trick."}, {"heading": "Setting up the breeding tank", "text": "Use 30 gallons or more with lots of current: a canister or strong filter plus one or two powerheads. Oxygen is critical, so add air stones too. Keep the temperature on the cool side of our care range, about 68 to 74°F, with pH 6.5 to 7.5.\n\nProvide smooth river stones, flat slates propped up to make crevices, and clay or slate caves facing the current. A lid helps keep temperatures stable and fish in. In warm rooms you may need a fan or a chiller, since these fish struggle when the water climbs into the high 70s °F for long periods. Mature algae covered rocks give both adults and future fry something to graze."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is unreliable. Mature males are often described as having broader heads, while females look fuller through the belly when ripe. Keeping 4 to 6 adults gives the best chance of a pair. Provide more caves than fish to reduce squabbles.\n\nThese are grazers. Let algae grow on rocks, and feed vegetable wafers, blanched zucchini and spinach, with small meaty foods like bloodworms a few times a week. Condition for at least 6 to 8 weeks with large weekly water changes."}, {"heading": "Spawning and eggs", "text": "In reports, eggs are laid in a cave or under a flat stone, and the male stays with them, fanning and guarding. You may first notice a male refusing to leave his spot.\n\nBreeders report hatching in roughly a week, faster in warmer water. If eggs are abandoned, move them to a tumbler or a mesh basket in strong flow with an air stone, and remove white, fungused eggs daily."}, {"heading": "Raising the fry", "text": "Fry live on their yolk sac first and should not be fed until it is nearly gone. After that they graze constantly.\n\n- Weeks 1 to 2: biofilm, algae covered stones from the main tank, finely crushed algae wafers.\n- Weeks 3 to 6: blanched vegetables, algae wafers and a little crushed sinking pellet.\n- Change 20 to 30 percent every few days and keep the water cool, clean and well oxygenated.\n\nWarm, low oxygen water is the biggest danger for both fry and adults."}, {"heading": "Growing out", "text": "Growth is slow. Expect several months for fry to reach 1 to 2 inches. Keep stones with algae rotating through the grow out tank, feed several times a day and keep up strong flow. Keep good notes, since detailed reports for this species are scarce and useful to other breeders. Record temperature, flow, foods and dates, plus how many fry survive at each stage. Growing youngsters do best in their own tank with no larger grazers competing for the same food."}, {"heading": "Common mistakes", "text": "- Warm, still tropical tank conditions. These are cool stream fish.\n- Too few caves, which leads to fighting.\n- Feeding fry before the yolk is gone.\n- Assuming species: several Chaetostoma look alike in the trade, so record what you have carefully.\n- Skipping oxygen. An air stone or two is cheap insurance in warm weather.\n- Giving up too soon. Groups may take a long time to settle before they spawn."}]$g$::jsonb, $g$[{"q": "Has the rubberlip pleco been bred in captivity?", "a": "Yes, but rarely. A few hobbyists have reported spawns, and detailed information is limited."}, {"q": "How do you sex a rubberlip pleco?", "a": "It is unreliable. Mature males are often described as having broader heads, and ripe females look fuller in the belly."}, {"q": "What temperature do rubberlip plecos need to breed?", "a": "They come from cool streams. Most reports describe cool, fast, well oxygenated water, about 68 to 74°F."}, {"q": "Do rubberlip plecos eat their eggs?", "a": "Breeders report that the male guards the eggs. If eggs are abandoned, hatch them separately in a tumbler or mesh basket with strong flow."}]$g$::jsonb, $g$Photograph your group and caves with the challenge code card for stage 1, and if you find eggs, a clear photo of the clutch under the stone or in the cave is your stage 2 proof. Notes on temperature and flow make your log especially useful for this rarely bred fish.$g$),
  ($g$twig-catfish$g$, $g$e6820f7b-29b1-486a-88db-f9779bd3c833$g$::uuid, $g$twig-catfish$g$, null, $g$How to Breed Twig Catfish (Farlowella): Eggs, Fry and Algae$g$, $g$Twig catfish lay rows of eggs on glass and the male guards them. Spawning is achievable, but the delicate, algae hungry fry make this an expert job.$g$, $g$Twig catfish are surprisingly willing to spawn in a calm, well kept tank, laying neat patches of eggs on the glass that the male guards. The real challenge comes after hatching: the fry are delicate, need a steady supply of algae and biofilm, and suffer quickly in dirty water. Raising even a handful to adulthood is an expert level result and a great story to log.$g$, $g${"method": "Egg depositor on glass or wood; male guards the eggs", "sexing": "Mature males grow bristles (odontodes) along the sides of the snout; females lack them", "group": "One pair or a small group with more than one female", "breeding_tank": "30 gallons or more, gentle current, mature with algae, wood and plants", "conditioning": "Algae, biofilm, algae wafers and blanched vegetables for several weeks", "trigger": "Good conditioning and cooler water changes; eggs often placed near the water flow", "spawn": "Commonly reported around 40 to 60 eggs", "eggs": "Commonly reported to hatch in about 7 to 10 days at 75 to 78°F", "fry": "Thin, tiny fry that start grazing soon after hatching", "first_foods": "Biofilm, green water, powdered algae food and blanched vegetables", "grow_out": "Slow; several months to reach 2 inches", "parents": "Male guards eggs; after hatching move fry or keep them where food is plentiful"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A mature tank of 30 gallons or more works well, with driftwood, plants and plenty of soft algae on surfaces. Twig catfish like gentle flow from a sponge or covered filter, and clean, well oxygenated water.\n\nOur care data lists 73 to 79°F, pH 6.0 to 7.5 and soft to medium water, and breeding attempts can stay in that range. Many keepers spawn them at around 75 to 78°F. Avoid fast, boisterous tankmates that stress them and steal food. Calm companions like small tetras are fine, but a species only tank gives eggs and fry the best chance. Keep a tight lid and stable temperature, and test water weekly so nitrates stay low."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing adults is fairly easy. Mature males develop a fringe of bristles, called odontodes, along the sides of the long snout. Females have a plain snout and look fuller when carrying eggs.\n\nFeed algae wafers, blanched zucchini, spinach and cucumber, and let natural algae grow on rocks and glass. A few small meaty foods help. Thin fish are a common problem with new arrivals, so give several weeks of steady feeding before expecting spawns. Watch the belly: a flat or sunken belly means the fish needs more food before you think about breeding."}, {"heading": "What spawning looks like", "text": "The pair usually spawns on the glass, often near a filter outlet or in a spot with some current, or on wood. Eggs are laid in a neat patch or rows. The male then stays on or near them, fanning and cleaning.\n\nClutches are commonly reported around 40 to 60 eggs. A cool water change after a period of heavy feeding is often mentioned as a trigger."}, {"heading": "Eggs and hatching", "text": "Hatch time is commonly reported as about 7 to 10 days at 75 to 78°F. Leave eggs with a guarding male if the tank is calm. If he leaves them, or tankmates show interest, carefully remove the eggs by gently rolling them off the glass with a razor blade into a container of tank water with an air stone.\n\nCheck daily and remove any eggs that turn white or fuzzy."}, {"heading": "Raising the fry", "text": "Fry are tiny, thin and need food in front of them all the time. Starvation and poor water are the main killers.\n\n- Week 1: biofilm, green water and fine powdered algae foods.\n- Weeks 2 to 4: add blanched zucchini or spinach, crushed algae wafers and a little baby brine shrimp.\n- Change 10 to 20 percent of the water every day or two, matching temperature.\n\nAdding algae covered stones from established tanks is one of the best ways to keep fry fed."}, {"heading": "Growing out", "text": "Growth is slow, and it takes several months for young twig cats to reach 2 inches. Keep feeding vegetables and algae foods several times a day, and keep nitrates low. Avoid sudden changes, since young Farlowella are delicate. A grow out tank with only their siblings is safest. Leave algae to grow on the back and side glass, and add blanched vegetables every day. Once they pass about an inch, survival improves a lot and they can be fed much like the adults."}, {"heading": "Common mistakes", "text": "- Starting with thin, stressed new fish.\n- A tank too clean to support grazing fry.\n- Large, sudden water changes in the fry tank.\n- Housing with aggressive or fast feeding fish that outcompete them.\n- Cleaning the egg patch area or glass while the male is guarding.\n- Leaving vegetable food in too long. Remove uneaten pieces within a day so water stays clean."}]$g$::jsonb, $g$[{"q": "How do you sex twig catfish?", "a": "Mature males have bristles along the sides of their snout. Females have smooth snouts."}, {"q": "Where do twig catfish lay eggs?", "a": "Usually on the glass or on wood, often near some current. The male guards the eggs."}, {"q": "How long do twig catfish eggs take to hatch?", "a": "Commonly about 7 to 10 days at 75 to 78°F."}, {"q": "What do baby twig catfish eat?", "a": "Biofilm, algae, green water and fine algae foods, then blanched vegetables and crushed wafers as they grow."}]$g$::jsonb, $g$Photograph the pair showing the male's snout bristles alongside your challenge code card for stage 1. A clear photo of the egg patch on the glass with the male guarding makes a strong stage 2 entry.$g$),
  ($g$zebra-pleco$g$, $g$cda60e9f-3a51-405d-86fd-a61402517aaa$g$::uuid, $g$zebra-pleco$g$, null, $g$How to Breed Zebra Plecos (L046): Caves, Warm Water and Fry$g$, $g$Zebra plecos spawn in caves where the male guards a small clutch of large eggs. Warm, oxygen rich water and patience are key. An expert level catfish.$g$, $g$The zebra pleco is one of the most admired catfish in the hobby, and breeding it is a real milestone. Pairs spawn inside a cave, and the male guards a small clutch of large eggs until the fry can feed. Spawns are small and growth is slow, so this is an expert level, patient project, but captive bred fish are now the main legal source outside Brazil, which makes every successful batch valuable.$g$, $g${"method": "Cave spawner (male guards eggs and fry inside the cave)", "sexing": "Males have broader heads and bristles behind the gill covers; females rounder from above", "group": "1 male to 1 or 2 females, or a group with a cave for every fish", "breeding_tank": "20 to 30 gallon tank, strong flow, extra aeration, snug slate or clay caves", "conditioning": "Frozen bloodworms, mysis, chopped shrimp and meaty sinking pellets for 6 to 8 weeks", "trigger": "Warm, very clean, well oxygenated water with strong current and steady water changes", "spawn": "Small clutches, commonly reported around 7 to 15 large eggs", "eggs": "Hatch in about 5 to 7 days at 82 to 86°F", "fry": "Live on a yolk sac for about another 2 weeks before feeding", "first_foods": "Crushed meaty sinking pellets, frozen baby brine shrimp, chopped bloodworms", "grow_out": "Very slow; many months to reach 1.5 to 2 inches", "parents": "Male guards well once experienced; young males may eject eggs, so be ready with a tumbler"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "A 20 to 30 gallon tank is enough for a pair or trio, though our care data suggests 30 gallons for keeping them long term. These fish come from the fast flowing, warm Rio Xingu, so think current and oxygen. Use a strong filter plus a powerhead, and add air stones.\n\nKeep the water at 82 to 86°F, inside the 79 to 86°F range in our care data, with soft water and pH 6.0 to 7.2. Provide several slate or clay caves just wide enough for an adult to turn around in, with one open end facing the flow. A sand or bare bottom is easiest to keep clean."}, {"heading": "Choosing and conditioning breeders", "text": "Use adults of at least 2.5 to 3 inches, which often means fish 2 or more years old. Mature males have broader, heavier heads and noticeable bristles (odontodes) behind the gill covers and on the pectoral spines. Females are rounder through the belly when seen from above, with slimmer heads.\n\nZebras are meat eaters. Feed frozen bloodworms, mysis, chopped shrimp and good sinking pellets once or twice a day. Do 30 to 50 percent water changes weekly. Many breeders condition for 6 to 8 weeks before expecting spawns."}, {"heading": "What spawning looks like", "text": "The male claims a cave and calls a female in. Spawning happens inside and can take a day or more. When it is done, the female leaves and the male stays in the cave, often blocking the entrance and fanning with his fins.\n\nAvoid shining lights into the cave. Young or nervous males may abandon or eat their first few clutches, and that usually improves with experience."}, {"heading": "Eggs and hatching", "text": "Clutches are small, commonly reported at about 7 to 15 large, pale yellow eggs. At 82 to 86°F, eggs hatch in about 5 to 7 days.\n\nIf the male ejects eggs, move them to an egg tumbler or a mesh basket hung in strong flow, and remove any white or fuzzy eggs. Many breeders leave clutches with good fathers, since males do a better job than most tumblers."}, {"heading": "Raising the fry", "text": "Fry carry a large yolk sac and stay in the cave for roughly another 2 weeks. Begin feeding when the yolk is nearly gone and fry move out to graze.\n\n- Weeks 1 to 2 of feeding: crushed meaty sinking pellets and frozen baby brine shrimp, twice a day.\n- Weeks 3 to 6: chopped bloodworms and small sinking pellets.\n- Change 20 to 30 percent of the water every 2 to 3 days and siphon leftovers.\n\nKeep fry as warm and well oxygenated as the adults."}, {"heading": "Growing out", "text": "Zebra plecos grow slowly. It takes many months for fry to reach 1.5 to 2 inches, the size most people want to buy. Several small meals a day and very clean water make the biggest difference. Provide small caves or pipe pieces in the grow out tank. Keep zebras away from other Hypancistrus at all times, since they can hybridize, and pure L046 lines are what breeders want.\n\nHealthy young zebras are active, bold feeders with crisp black and white bands. If fry look pinched or hide constantly, check temperature, oxygen and nitrates before anything else."}, {"heading": "Common mistakes", "text": "- Caves that are too large or too small.\n- Low oxygen or weak current.\n- Water that is too cool for this warm water species.\n- Housing with other Hypancistrus, which risks hybrids.\n- Overfeeding tiny fry before the yolk is gone, which fouls the water."}]$g$::jsonb, $g$[{"q": "How many eggs do zebra plecos lay?", "a": "Clutches are small, commonly about 7 to 15 eggs. Young pairs often lay fewer."}, {"q": "How long do zebra pleco eggs take to hatch?", "a": "About 5 to 7 days at 82 to 86°F. Fry then live on their yolk for around 2 more weeks."}, {"q": "How do you sex zebra plecos?", "a": "Adult males have broader heads and more bristles behind the gill covers and on the pectoral fins. Females are rounder when viewed from above."}, {"q": "Why are zebra plecos so expensive?", "a": "Brazil has long banned wild exports and the species is listed under CITES, small clutches and slow growth limit captive supply, and demand stays high."}]$g$::jsonb, $g$Photograph your pair or trio and their cave with the challenge code card when you open the log. For stage 2, a quick, careful photo of the egg clump with the male, or of eggs in a tumbler, is ideal.$g$),
  ($g$cardinal-tetra$g$, $g$a7051fb4-91b2-4b51-a00a-4472dc95c1fa$g$::uuid, $g$cardinal-tetra$g$, null, $g$How to Breed Cardinal Tetras: Soft Water, Darkness and Fry$g$, $g$Cardinal tetras need very soft, acidic water and darkness for eggs and fry. Spawning is possible, but raising the tiny fry makes it an expert project.$g$, $g$Cardinal tetras are among the most kept fish in the hobby, yet most sold are still wild caught or farm raised. Breeding them at home means very soft, acidic water, dim light and close attention to tiny, light sensitive eggs and fry. It is an expert level project because water chemistry has to be right, but a tank full of baby cardinals is one of the best results a tetra breeder can earn.$g$, $g${"method": "Egg scatterer, no parental care", "sexing": "Females deeper and rounder in the belly; males slimmer", "group": "One pair, or a small group of 3 to 4 of each sex", "breeding_tank": "5 to 10 gallon bare tank, spawning mops or fine plants, dim light", "conditioning": "Live or frozen foods like brine shrimp, daphnia and blackworms for 1 to 2 weeks", "trigger": "Very soft, acidic water near pH 5.0 to 6.0, dim light, usually spawning at dusk", "spawn": "Commonly reported in the low hundreds", "eggs": "Hatch in about 24 to 36 hours at 78 to 82°F; eggs are light sensitive", "fry": "Free swimming about 4 to 5 days after spawning; extremely small", "first_foods": "Infusoria or paramecium, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "About 2 to 3 months to reach 0.75 to 1 inch", "parents": "Adults eat eggs; remove them right after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a small bare tank of 5 to 10 gallons. Cover the bottom with spawning mops, java moss or a mesh grid so eggs fall out of reach. Use a gentle sponge filter or just an air stone. Cover the sides with paper or dark material, as cardinals spawn in dim light.\n\nWater is the key. Use reverse osmosis or rain water with almost no hardness (GH and KH near zero) and a pH of about 5.0 to 6.0, which sits inside the 4.5 to 6.8 range in our care data. Peat or leaf litter helps soften and acidify. Keep the temperature at about 78 to 82°F."}, {"heading": "Choosing and conditioning breeders", "text": "Pick mature fish over an inch long. Females are deeper and rounder, especially from the side, while males are slimmer with a straighter belly line. Separate males and females for 1 to 2 weeks and feed live or frozen brine shrimp, daphnia and chopped blackworms several times a day.\n\nPut a well rounded female and the best male into the breeding tank in the evening. Some breeders use small groups of each sex instead."}, {"heading": "What spawning looks like", "text": "Cardinals usually spawn at dusk or in the dark. The male chases the female into the plants, and the pair release small adhesive eggs that stick to plants or fall through the mesh. Spawns are commonly reported in the low hundreds of eggs.\n\nRemove the adults as soon as you see eggs, or the next morning, because they will eat them."}, {"heading": "Eggs and fungus prevention", "text": "Eggs and fry are very light sensitive, so keep the tank dark. Eggs hatch in about 24 to 36 hours at 78 to 82°F, and the fry hang on surfaces until they become free swimming around day 4 to 5 after spawning.\n\nInfertile eggs turn white and fuzzy. In very soft, acidic water fungus is less of a problem, which is one reason the low pH matters. Siphon out bad eggs gently if you can do it without disturbing the rest."}, {"heading": "Raising the fry", "text": "Fry are tiny and need the smallest foods for the first week.\n\n- Days 1 to 7 of free swimming: infusoria or paramecium cultures, several times a day.\n- Week 2: vinegar eels or microworms.\n- Week 3 on: newly hatched baby brine shrimp.\n\nRaise the light slowly over the first two weeks. Start small water changes of about 10 percent every couple of days after the first week, using the same soft water, and slowly allow a little more hardness as fry grow."}, {"heading": "Growing out", "text": "Fry show the start of their blue stripe after a few weeks. Expect about 2 to 3 months for them to reach 0.75 to 1 inch. Feed small amounts of baby brine shrimp and fine flakes several times a day, and move them to a larger tank with gentle filtration once they are eating well.\n\nKeep the water soft while they grow, and only raise hardness slowly over weeks if you plan to move them into regular tank water. Sorting larger fry from smaller ones helps the slower growers get their share of food."}, {"heading": "Common mistakes", "text": "- Water that is too hard. Eggs often fail in anything but very soft water.\n- Bright light on eggs and fry.\n- Leaving the parents in the tank.\n- Starting fry on baby brine shrimp, which is too large at first.\n- Moving fry into hard tap water too quickly, which stresses them badly."}]$g$::jsonb, $g$[{"q": "Are cardinal tetras hard to breed?", "a": "Yes, compared with most tetras. They need very soft, acidic water and darkness for eggs, and the fry are tiny."}, {"q": "How long do cardinal tetra eggs take to hatch?", "a": "About 24 to 36 hours at 78 to 82°F, with fry free swimming around 4 to 5 days after spawning."}, {"q": "How do you tell male and female cardinal tetras apart?", "a": "Females have a deeper, rounder belly. Males are slimmer with a straighter underside."}, {"q": "Do cardinal tetras eat their eggs?", "a": "Yes. Remove the adults right after spawning."}]$g$::jsonb, $g$Photograph the conditioned pair in the dimmed breeding tank with your challenge code card for stage 1. Eggs are tiny and the tank is dark, so a quick, close photo with a small flashlight is fine for stage 2; just don't leave the light on.$g$),
  ($g$green-neon-tetra$g$, $g$42471cee-f1d7-4d8d-8722-e95af5ebd80b$g$::uuid, $g$green-neon-tetra$g$, null, $g$Breeding Green Neon Tetras: Blackwater Spawning and Tiny Fry$g$, $g$Green neon tetras are rarely bred. Success needs very soft, acidic blackwater, darkness for eggs and the tiniest fry foods. An expert level project.$g$, $g$Green neon tetras are among the smallest tetras in the hobby, and breeding them at home is rarely reported. Hobbyists who have succeeded used very soft, acidic, blackwater conditions similar to cardinal tetra breeding, with eggs scattered in fine plants and tiny fry that need microscopic foods. Treat this as an expert level challenge where good notes are as valuable as the fish.$g$, $g${"method": "Egg scatterer, no parental care", "sexing": "Hard; ripe females fuller and rounder, males slimmer", "group": "A small group, such as 3 to 4 males and females, or one pair", "breeding_tank": "5 gallon dark tank, fine moss or mops, soft acidic water", "conditioning": "Tiny live or frozen foods: daphnia, cyclops, baby brine shrimp for 1 to 2 weeks", "trigger": "Very soft, acidic blackwater and dim light", "spawn": "Not well documented; reports describe small numbers of eggs", "eggs": "Breeders report hatching in about a day at 78 to 82°F; eggs are light sensitive", "fry": "Extremely small; free swimming a few days after hatching", "first_foods": "Infusoria or paramecium, then vinegar eels, then baby brine shrimp", "grow_out": "Several months to reach adult size", "parents": "Adults eat eggs; remove them after spawning"}$g$::jsonb, $g$[{"heading": "What is known", "text": "Green neons come from blackwater habitats in South America. Spawns in home tanks are uncommon, and detailed reports are few. Breeders who have succeeded generally used methods similar to cardinal tetra breeding. The guidance here follows that approach, and any numbers should be seen as a starting point."}, {"heading": "Setting up the breeding tank", "text": "Use a small tank of around 5 gallons with dark sides, a dark bottom, and clumps of java moss or spawning mops. A gentle sponge filter or air stone is enough.\n\nUse soft water from reverse osmosis or rain, with GH near zero and pH about 4.5 to 6.0, within the 4.0 to 6.5 range in our care data. Leaf litter or peat helps. Keep the temperature around 78 to 82°F, inside our care range of 75 to 84°F."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is difficult in these tiny fish. Ripe females look fuller and rounder from the side, while males stay slim. Condition a group for 1 to 2 weeks on tiny live or frozen foods such as daphnia, cyclops and baby brine shrimp, and keep them in stable soft water.\n\nMove the best looking fish into the breeding tank in the evening, either as a pair or as a small group.\n\nChoose fish that are active, fully colored and eating well. Wild caught green neons can arrive thin, so quarantine new fish and give them a few weeks to settle in soft water before conditioning. A group of 8 or more, as our care data suggests, keeps them calm and confident."}, {"heading": "Spawning and eggs", "text": "Spawning is reported to happen in dim light or early in the morning, with eggs scattered in fine plants or moss. Remove adults as soon as possible.\n\nKeep the tank dark, since eggs and fry are light sensitive. Breeders report hatching in about a day at 78 to 82°F. Remove white, fungused eggs if you can do it without disturbing the rest. Very soft, acidic water helps prevent fungus.\n\nIf you can't see eggs, leave the tank dark and untouched for a few days and then look closely for tiny fry clinging to the glass or moss. Many spawns of small tetras are only noticed this way. Keep the hatching tank at the same temperature and chemistry as the spawning tank."}, {"heading": "Raising the fry", "text": "Fry are extremely small and need microscopic foods first.\n\n- First week of free swimming: infusoria or paramecium, several times a day.\n- Week 2: vinegar eels or microworms.\n- Week 3 on: newly hatched baby brine shrimp.\n\nDo small, careful water changes of 10 percent every few days with the same soft water. Raise the light slowly as fry grow. A few small snails can help clean up leftover food."}, {"heading": "Growing out", "text": "Fry grow slowly and take several months to reach adult size, usually under an inch. Feed baby brine shrimp and fine crushed foods several times a day. As they color up, you can move them into a larger tank with gentle flow and the same soft, acidic water. Keep detailed notes on water values and dates, as reports for this species are scarce and useful to others."}, {"heading": "Common mistakes", "text": "- Hard or neutral water.\n- Bright light on eggs and fry.\n- Food that is too large for the fry.\n- Leaving adults in with the eggs.\n- Big water changes that swing the pH.\n- Using tap water softened only partly. Measure GH and pH rather than guessing."}]$g$::jsonb, $g$[{"q": "Have green neon tetras been bred in aquariums?", "a": "Yes, but rarely. A small number of hobbyists report spawns in very soft, acidic water."}, {"q": "How do you tell male and female green neon tetras apart?", "a": "It is hard. Ripe females look fuller and rounder, while males stay slim."}, {"q": "What water do green neon tetras need to breed?", "a": "Very soft, acidic blackwater, with a pH around 4.5 to 6.0 and almost no hardness."}, {"q": "What do green neon tetra fry eat?", "a": "Infusoria or paramecium at first, then vinegar eels, and baby brine shrimp after about two weeks."}]$g$::jsonb, $g$Open your log as soon as your group is in the breeding tank and photograph them with the challenge code card. Fry are tiny, so a magnifying glass or close up photo against a dark background helps for stage 3.$g$),
  ($g$marbled-hatchetfish$g$, $g$44d12d9b-3e2f-47d2-a4e7-e6ad7910f9b3$g$::uuid, $g$marbled-hatchetfish$g$, null, $g$Breeding Marbled Hatchetfish: A Rare Challenge Guide$g$, $g$Marbled hatchetfish are rarely bred. This guide covers what breeders report: soft water, floating plants, insect foods and tiny fry. Expert level.$g$, $g$Marbled hatchetfish are surface dwelling characins that are seldom bred in home aquariums, and most sold are wild caught. The few reported spawns involved well conditioned groups in soft, acidic water with floating plants, fed on live insects. Information is limited, so treat this as an expert level experiment, and record what you learn carefully.$g$, $g${"method": "Egg scatterer, no parental care", "sexing": "Very hard; ripe females look fuller from above, males slimmer", "group": "A group of 6 or more", "breeding_tank": "10 to 20 gallons, tight lid, floating plants and fine plants near the surface", "conditioning": "Live fruit flies, mosquito larvae, daphnia and brine shrimp for several weeks", "trigger": "Not well understood; soft acidic water, dim light and rich live foods are reported", "spawn": "Not well documented; reports vary", "eggs": "Breeders report hatching in roughly 1 to 2 days at 78 to 80°F", "fry": "Tiny fry that stay near the surface", "first_foods": "Infusoria, then vinegar eels or microworms, then baby brine shrimp", "grow_out": "Several months to reach adult size", "parents": "Adults likely to eat eggs and fry; remove eggs or adults"}$g$::jsonb, $g$[{"heading": "What is known", "text": "Captive breeding of Carnegiella strigata is rare and poorly documented. There are scattered reports of spawning in soft, acidic water, with eggs laid among fine plants or floating plant roots near the surface. There is little reliable data on clutch size or exact hatch times, so this guide focuses on the conditions breeders describe.\n\nHatchetfish are also nervous and spend almost all their time at the very top of the water, so anything that stresses them, such as bright light, strong surface current or busy tankmates, makes breeding even less likely. A quiet, dedicated tank is your best starting point."}, {"heading": "Setting up the breeding tank", "text": "Use a tank of 10 to 20 gallons with a tight fitting lid, as hatchetfish jump. Add floating plants with long roots and some fine leaved plants near the surface. A sponge filter keeps flow gentle.\n\nKeep soft, acidic water around pH 5.5 to 6.5, within the 5.5 to 7.0 range in our care data, and temperatures of 78 to 80°F. Dim lighting helps the fish settle.\n\nKeep the water level a few inches below the lid so fish have open swimming space at the surface. Leaf litter or peat can help keep the water soft and slightly tinted, which many wild fish seem to find comforting. Avoid tankmates in the breeding tank."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is very hard. Ripe females look fuller in the belly from above, and males are slimmer. Keep a group of at least 6 so pairs can form on their own.\n\nThese fish feed at the surface on insects. Feed live fruit flies, mosquito larvae, daphnia and brine shrimp, with good flakes. Several weeks of rich feeding is a must. Healthy, plump fish are the starting point.\n\nQuarantine new fish, since wild caught hatchetfish can carry parasites and often arrive thin. Only start breeding attempts once the group is eating eagerly at the surface and has filled out."}, {"heading": "Spawning and eggs", "text": "Reports describe chasing near the surface and eggs scattered among roots or fine plants. Check the plants each morning with a flashlight.\n\nMove any eggs or plants with eggs to a small hatching tank with the same water and an air stone. Breeders report hatching in roughly 1 to 2 days at 78 to 80°F. Remove white, fungused eggs daily, and keep the hatching tank dim."}, {"heading": "Raising the fry", "text": "Fry are tiny and stay near the surface.\n\n- First week: infusoria, several times a day.\n- Week 2: vinegar eels or microworms.\n- Week 3 on: newly hatched baby brine shrimp.\n\nUse small water changes of about 10 percent every few days, matched for pH and temperature. Keep a lid on the fry tank too, as surface fish can jump as they grow.\n\nFry are delicate and easily lost to poor water, so siphon uneaten food daily and keep the temperature steady. A small amount of floating plant in the fry tank gives cover and grows infusoria."}, {"heading": "Growing out", "text": "Growth is slow, and it takes several months for fry to reach adult size. Feed small live foods and fine flake several times a day. Floating plants give young fish cover. Keep notes on water values, foods and dates, since every report helps other hobbyists.\n\nOnce young fish are eating small flakes and baby brine shrimp with confidence, you can move them into a larger tank with a tight lid and floating plants. Keep their water soft and stable."}, {"heading": "Common mistakes", "text": "- No lid. Hatchetfish jump, and adults are often lost this way.\n- Poorly fed wild fish.\n- Hard, alkaline water.\n- Strong surface current that pushes fish around.\n- Food too large for the fry."}]$g$::jsonb, $g$[{"q": "Can marbled hatchetfish be bred in aquariums?", "a": "Yes, but it is rare and poorly documented. Most fish sold are wild caught."}, {"q": "How do you sex marbled hatchetfish?", "a": "It is very difficult. Ripe females look fuller in the belly from above, while males are slimmer."}, {"q": "What do marbled hatchetfish eat for breeding?", "a": "Live insects like fruit flies and mosquito larvae, plus daphnia, brine shrimp and quality flakes."}, {"q": "Do hatchetfish need a lid?", "a": "Yes. They are strong jumpers and a tight lid is essential."}]$g$::jsonb, $g$Photograph your group under the floating plants with your challenge code card when you open the log. Since spawns are rarely seen, photograph any eggs in the roots or hatching tank on the day you find them.$g$),
  ($g$brilliant-rummynose-tetra$g$, $g$9ea26296-7760-43f2-9a8a-6493a7af2384$g$::uuid, $g$brilliant-rummynose-tetra$g$, null, $g$How to Breed Rummynose Tetras: Soft Water Spawning Guide$g$, $g$Rummynose tetras need very soft, acidic water and careful fry care. Spawns are possible but small and fragile. An expert level tetra project.$g$, $g$Rummynose tetras are a favorite schooling fish, but they are much harder to breed than most tetras. They need very soft, acidic water, well conditioned adults and dim conditions, and they can be fussy about spawning. Fry are tiny and slow growing. It is an expert level project, but breeding these red nosed fish is a satisfying achievement.$g$, $g${"method": "Egg scatterer, no parental care", "sexing": "Hard; ripe females rounder and deeper bodied, males slimmer", "group": "One pair or a small group", "breeding_tank": "10 gallon dim tank, fine plants or mops, soft acidic water", "conditioning": "Live and frozen foods like daphnia, brine shrimp and bloodworms for 1 to 2 weeks", "trigger": "Very soft water, pH about 5.5 to 6.5, dim light, warm temperatures", "spawn": "Often modest, commonly reported in the dozens to low hundreds", "eggs": "Commonly reported to hatch in about 24 to 36 hours at 80 to 84°F", "fry": "Free swimming a few days after hatching, very small", "first_foods": "Infusoria or paramecium, then microworms or vinegar eels, then baby brine shrimp", "grow_out": "Slow; about 3 months to reach 1 inch", "parents": "Adults eat eggs; remove them after spawning"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use a 10 gallon tank with dark sides and a sponge filter. Add spawning mops or clumps of fine leaved plants like java moss, and a mesh above the bottom if you like.\n\nUse very soft water with GH under 4 and pH around 5.5 to 6.5, inside the 5.5 to 7.0 range in our care data. Reverse osmosis or rain water with peat or leaf litter works. Keep the temperature at 80 to 84°F, within our care range of 75 to 84°F.\n\nA dim room or a towel over the tank helps, as eggs and fry are light sensitive. Let the water settle for a few days before adding fish so pH and temperature are stable. Remove snails and other tankmates that might eat eggs."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is hard. Females are rounder and deeper bodied when ripe, while males are slimmer. Buy a group so you can pick a well rounded female and an active male.\n\nCondition with live and frozen foods such as daphnia, brine shrimp and bloodworms, plus quality flakes, for 1 to 2 weeks. Separating sexes during conditioning can help. Make sure the fish are healthy, with bright red noses, before trying.\n\nHealthy rummynose have bright red heads, so a pale nose is a sign of stress or poor water. Fix that first. Fish at least a year old and close to full size are the best breeders."}, {"heading": "What spawning looks like", "text": "Spawning usually happens early in the morning. The pair swims side by side into the plants, scattering eggs that stick to leaves or fall to the bottom. Spawns are often modest, commonly reported from dozens to the low hundreds of eggs.\n\nRemove the adults as soon as spawning ends, since they eat eggs.\n\nIf nothing happens after two or three days, return the fish to the conditioning tank, feed them well for another week and try again. A slight rise in temperature or a soft water change sometimes helps."}, {"heading": "Eggs and fungus prevention", "text": "Eggs are commonly reported to hatch in about 24 to 36 hours at 80 to 84°F. Keep the tank dark during this time, since eggs and fry are light sensitive.\n\nRemove white, fungused eggs with a pipette. Very soft, acidic water helps keep fungus down, and gentle aeration helps the good eggs."}, {"heading": "Raising the fry", "text": "Fry are very small and need the tiniest foods.\n\n- First week: infusoria or paramecium several times a day.\n- Week 2: microworms or vinegar eels.\n- Week 3 on: baby brine shrimp.\n\nStart 10 percent water changes after the first week, using the same soft water, every couple of days. Keep the temperature steady and lighting low.\n\nCheck the fry daily with a flashlight from the side. Round, full bellies mean they are eating. If bellies stay thin, offer smaller foods more often. Siphon uneaten food from the bottom so the water stays clean."}, {"heading": "Growing out", "text": "Rummynose fry grow slowly and take about 3 months to reach an inch. Feed baby brine shrimp and fine crushed flakes several times a day, and keep the water clean and soft. The red nose develops as they mature. Once they are around an inch, move them into a larger tank with gentle flow.\n\nKeep fry in soft water through grow out, and if you need to move them to harder water later, do it slowly over several weeks."}, {"heading": "Common mistakes", "text": "- Hard water, which often stops eggs from hatching.\n- Leaving the parents with the eggs.\n- Bright light on eggs and fry.\n- Giving up after one try. Pairs often take a few attempts."}]$g$::jsonb, $g$[{"q": "Are rummynose tetras hard to breed?", "a": "Yes. They need very soft, acidic water and careful fry care, and spawns are often small."}, {"q": "How long do rummynose tetra eggs take to hatch?", "a": "About 24 to 36 hours at 80 to 84°F is commonly reported."}, {"q": "How do you sex rummynose tetras?", "a": "It is hard. Ripe females are rounder and deeper bodied, and males are slimmer."}, {"q": "What do rummynose tetra fry eat?", "a": "Infusoria or paramecium first, then microworms or vinegar eels, then baby brine shrimp."}]$g$::jsonb, $g$Photograph your chosen pair or group in the breeding tank with your challenge code card for stage 1. Rummynose fry grow slowly, so keep up clean water to reach the 60 day stage, and photograph them against a dark background so their size is clear.$g$),
  ($g$discus$g$, $g$9f7fbc05-4052-4bed-98df-a2e31442996b$g$::uuid, $g$discus$g$, null, $g$How to Breed Discus: Pairs, Cones and Raising Fry on Parents$g$, $g$Discus pairs spawn on cones and feed fry with skin mucus. Soft, warm, very clean water and steady routines are key. An expert level cichlid project.$g$, $g$Breeding discus is one of the great goals in the hobby. A bonded pair cleans a cone, lays a neat spiral of eggs, guards the wrigglers, and then feeds the fry from the slime on their own bodies. It is an expert level project because discus need warm, soft, very clean water, pairs can be fussy, and young pairs often eat their first spawns. When it works, it is unforgettable.$g$, $g${"method": "Substrate spawner on vertical surfaces; both parents guard and feed fry", "sexing": "Hard by looks; most reliable by breeding tubes at spawning, female blunt, male pointed", "group": "One bonded pair, chosen from a group of 5 or more young fish", "breeding_tank": "30 to 40 gallon tall bare tank, sponge filter, spawning cone or slate", "conditioning": "Beefheart mix, bloodworms, quality pellets and flakes, several meals a day for weeks", "trigger": "Soft, acidic, clean water at 82 to 86°F with frequent water changes", "spawn": "Commonly reported around 100 to 300 eggs, sometimes more", "eggs": "Hatch in about 2 to 3 days at 84 to 86°F", "fry": "Free swimming about 5 to 6 days after spawning; feed off parents' skin mucus", "first_foods": "Parents' mucus for the first week, then newly hatched baby brine shrimp", "grow_out": "Roughly 2 to 3 months of heavy feeding to reach 1 to 2 inches", "parents": "Excellent parents once experienced; young pairs may eat eggs a few times"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Most breeders use a 30 to 40 gallon tall, bare bottomed tank for a single pair, even though our care data lists 55 gallons for keeping a group. A bare tank is easy to keep spotless. Use one or two sponge filters, a heater and a ceramic spawning cone, slate or a section of pipe stood upright.\n\nKeep the temperature at 82 to 86°F, within our care range of 82 to 88°F. Water should be soft and acidic. Many breeders lower the pH to about 6.0 to 6.5 for spawning, inside our care range of 6.0 to 7.0, with very low hardness. Very hard water often stops eggs from hatching."}, {"heading": "Choosing a pair", "text": "Sexing discus by looks is unreliable. Males are sometimes larger with thicker lips and a steeper forehead, but that's not consistent. The surest way is the breeding tube that appears just before spawning: the female's is short and blunt, the male's thinner and pointed.\n\nThe easiest route is to grow 5 or more young discus together and let a pair form. A pair stays near each other, cleans surfaces together and chases other fish away. Move them to their own tank once they are clearly bonded."}, {"heading": "Conditioning and spawning", "text": "Feed several times a day with beefheart mix, frozen bloodworms, quality pellets and flakes. Do 30 to 50 percent water changes daily or every other day with matched soft water.\n\nBefore spawning, the pair cleans the cone, shivers, and shows their breeding tubes. The female lays rows of eggs up the cone, and the male follows to fertilize them. Spawns are commonly reported around 100 to 300 eggs, sometimes more."}, {"heading": "Eggs and wrigglers", "text": "Both parents fan the eggs and remove bad ones. At 84 to 86°F, eggs hatch in about 2 to 3 days. The hatched wrigglers stay attached to the cone and are moved around by the parents.\n\nAbout 5 to 6 days after spawning, fry become free swimming and swarm onto the parents' sides. Keep the light low and avoid disturbing the pair during this time. Young pairs may eat the eggs a few times before they get it right. Be patient."}, {"heading": "Raising the fry", "text": "For the first week, fry feed on mucus the parents produce on their skin. This is normal and important.\n\n- Days 5 to 7 of free swimming: start offering newly hatched baby brine shrimp a few times a day.\n- Weeks 2 to 3: baby brine shrimp several times a day, plus finely crushed flake.\n- Week 3 to 4: remove the parents or the fry, as the parents' mucus runs low and fry can nip at them.\n\nKeep doing water changes of 30 to 50 percent daily with matched water, and siphon leftovers carefully."}, {"heading": "Growing out", "text": "Discus fry grow fast with lots of food and clean water. Expect roughly 2 to 3 months of heavy feeding for them to reach 1 to 2 inches. Feed several times a day, change water daily, and sort fry by size so smaller ones aren't left behind. A bare tank with sponge filters keeps cleaning simple. Keep water warm, around 82 to 86°F, through grow out.\n\nHealthy fry are round, active and dark eyed. If some stay thin or hang near the surface, they are often not getting enough food, so offer more frequent, smaller meals and move the biggest fish to a separate tank."}, {"heading": "Common mistakes", "text": "- Water that is too hard, which stops eggs from hatching.\n- Moving a pair too often, which stresses them.\n- Removing eggs from young pairs too quickly. Let them learn.\n- Infrequent water changes. Discus are very sensitive to poor water.\n- Raising fry without the parents. It is possible but very difficult; leave fry with parents if you can."}]$g$::jsonb, $g$[{"q": "How do you tell male and female discus apart?", "a": "By looks it is unreliable. The best way is to compare breeding tubes at spawning: the female's is short and blunt, the male's is thinner and pointed."}, {"q": "How long do discus eggs take to hatch?", "a": "About 2 to 3 days at 84 to 86°F, and fry are free swimming about 5 to 6 days after spawning."}, {"q": "What do discus fry eat?", "a": "For the first week, they feed on mucus from their parents' skin. After that, they can eat baby brine shrimp."}, {"q": "Why do my discus eat their eggs?", "a": "It's common with young pairs, stress or poor water. Most pairs stop after a few spawns once conditions are right."}]$g$::jsonb, $g$Photograph the bonded pair beside their cone with your challenge code card when you open the log. A photo of fry grazing on the parents' sides makes a clear stage 3 record.$g$),
  ($g$amano-shrimp$g$, $g$d7492890-088a-4f35-89fc-bc28c3fcd7ed$g$::uuid, $g$amano-shrimp$g$, null, $g$How to Breed Amano Shrimp: Saltwater Larvae Step by Step$g$, $g$Amano shrimp larvae need saltwater to develop, then a slow return to fresh water. Possible at home, but this is an expert level shrimp project.$g$, $g$Amano shrimp breed readily in freshwater, and berried females are common. The catch is that their tiny larvae need salt water to survive and develop, and then must be moved back to fresh water once they turn into shrimp. That makes this an expert level project, but with a plan, patience and steady feeding, hobbyists do raise them at home.$g$, $g${"method": "Egg carrier; larvae need brackish to full saltwater to develop", "sexing": "Females larger with a line of long dashes; males smaller with evenly spaced dots", "group": "A group of 5 or more, with several females", "breeding_tank": "Freshwater adult tank, plus a 2 to 5 gallon saltwater larval tank", "conditioning": "Algae, biofilm, blanched vegetables and shrimp foods", "trigger": "Mature females molt and mate; berried females are common in healthy tanks", "spawn": "Hundreds to a few thousand larvae", "eggs": "Carried for about 4 to 6 weeks at 72 to 78°F", "fry": "Tiny larvae that drift and need salt water until they change into shrimp", "first_foods": "Green water or powdered algae foods in salt water", "grow_out": "Larvae take about 3 to 6 weeks to settle; adult size takes several months", "parents": "No care; move the berried female to the larval setup or collect larvae at hatch"}$g$::jsonb, $g$[{"heading": "How Amano shrimp breed", "text": "Female Amanos carry eggs under their tail for several weeks, just like other shrimp. But when the eggs hatch, the young are tiny larvae, not baby shrimp. In nature they drift down to the sea, develop there and then return to fresh water. In the aquarium that means you need a saltwater stage, then a careful move back to fresh water."}, {"heading": "What you need", "text": "Keep the adults in their regular freshwater tank. Our care data lists 65 to 80°F, pH 6.5 to 7.8 and GH 6 to 18. For the larvae, set up a 2 to 5 gallon tank or container with an air stone and a heater.\n\nMany breeders raise larvae in full marine salinity, around 1.020 to 1.025 specific gravity, using marine salt mix. Others use brackish water with good results. Pick one approach and keep it stable. Keep the larvae at 72 to 78°F with a light on, which helps green water grow and keeps the larvae active.\n\nYou will also need a reliable way to grow green water or a supply of fine powdered algae food, a hydrometer or refractometer to check salinity, and a small turkey baster or pipette for moving larvae. Set everything up before the female is ready to release, so you aren't rushing on hatch night."}, {"heading": "Sexing and egg carrying", "text": "Females are larger, with a line of long dashes along their sides and a saddle of eggs developing behind the head. Males are smaller with evenly spaced dots.\n\nA berried female carries eggs for about 4 to 6 weeks. Late in that time, the eggs change color and eyes become visible. Move her to a separate container or net breeder in fresh water when you see eyes, so you can catch the larvae as they hatch, often at night."}, {"heading": "Moving larvae into saltwater", "text": "Larvae hatch over a night or two. Use a flashlight to attract them, then gently siphon or scoop them out. Move them into the saltwater tank either all at once or over a few hours, depending on your method. Remove the female and return her to her normal tank.\n\nLarvae are tiny and float near the light. Avoid strong filters; a gentle air stone is enough."}, {"heading": "Raising the larvae", "text": "- First weeks: feed green water (phytoplankton) or fine powdered algae foods so the water looks slightly cloudy.\n- Keep the light on to help the green water grow.\n- Change 10 percent of the water every few days with matched salt water.\n\nAfter about 3 to 6 weeks, larvae change and settle to the bottom as tiny shrimp. Once most have settled, start moving them back to fresh water slowly, over about a week, by adding fresh water bit by bit.\n\nCount on losses. Many breeders start with hundreds of larvae and end with a much smaller number of shrimp, and that is still a success. Keep notes on salinity, temperature and feeding so you can repeat what works."}, {"heading": "Growing out", "text": "Young shrimp can now live in freshwater. Keep them in a planted tank with biofilm and algae, and feed powdered shrimp food and blanched vegetables. It takes several months for them to reach full size. Keep the water stable and clean, and avoid copper based products.\n\nDuring the move back to fresh water, watch the young shrimp closely. If many stop moving or float, slow down. Keep the tank covered, since young shrimp can climb out through gaps. Once they are fully in fresh water and eating well, they are as hardy as adult Amanos."}, {"heading": "Common mistakes", "text": "- Leaving larvae in fresh water, where they die within days.\n- Not feeding enough green water.\n- Moving young shrimp back to fresh water too quickly.\n- Strong filters that suck up larvae.\n- Letting salinity drift as water evaporates. Top off with fresh water, not salt water, and check salinity every few days."}]$g$::jsonb, $g$[{"q": "Can Amano shrimp breed in freshwater?", "a": "They mate and carry eggs in fresh water, but the larvae need salt water to develop. They won't survive in a regular freshwater tank."}, {"q": "How long are Amano shrimp berried?", "a": "Usually about 4 to 6 weeks."}, {"q": "How do you tell male and female Amano shrimp apart?", "a": "Females are larger with long dashes along their sides. Males are smaller with evenly spaced dots."}, {"q": "How long do Amano shrimp larvae stay in salt water?", "a": "About 3 to 6 weeks, until they change into tiny shrimp and settle on the bottom."}]$g$::jsonb, $g$Photograph your adult group with your challenge code card for stage 1, then a berried female for stage 2. For stage 3, a clear shot of the larvae under a flashlight works, and the 30 and 60 day stages are best shown once the young shrimp are back in fresh water.$g$),
  ($g$dwarf-chain-loach$g$, $g$9f4e4369-9951-408b-994a-9ad4d8ff0374$g$::uuid, $g$dwarf-chain-loach$g$, null, $g$Breeding Dwarf Chain Loaches: What Hobbyists Have Learned$g$, $g$Dwarf chain loaches are rarely bred in home aquariums. A mature planted tank and a well fed group give the best chance. An expert level challenge.$g$, $g$Dwarf chain loaches are rarely bred in home aquariums, and most sold come from commercial farms. A few hobbyists have found fry in mature, heavily planted tanks with a well fed group, but how and when they spawn is still poorly understood. This is an expert level project where patience, good conditions and careful notes are your best tools.$g$, $g${"method": "Egg scatterer, no parental care", "sexing": "Hard; mature females larger and rounder, males slimmer", "group": "A group of 6 or more adults", "breeding_tank": "30 gallons or more, mature, planted, with fine substrate and hiding spots", "conditioning": "Small snails, bloodworms, brine shrimp, daphnia and sinking pellets for several weeks", "trigger": "Not well understood; hobby spawns usually noticed in mature, well fed tanks", "spawn": "Not well documented", "eggs": "Not well documented; hatch time not reliably reported", "fry": "Tiny fry usually found hiding in plants", "first_foods": "Infusoria, then microworms, then baby brine shrimp", "grow_out": "Several months to reach 1 inch", "parents": "Adults likely eat eggs and fry; dense plants and moss give cover"}$g$::jsonb, $g$[{"heading": "What is known", "text": "Ambastaia sidthimunki is threatened in the wild and rarely bred by hobbyists. Commercial farms produce most of the fish sold, using methods that aren't suitable for home breeders. Hobby spawns are uncommon, and most are noticed only when tiny fry appear in a mature tank. There is little reliable data on clutch size or hatch times.\n\nBecause they are threatened in the wild, every captive spawn helps. Even if you don't succeed right away, keeping a healthy, well fed group in good conditions is the right foundation, and these lively loaches are a pleasure to watch while you wait."}, {"heading": "Setting up the breeding tank", "text": "Use a mature tank of 30 gallons or more, as our care data recommends. Keep soft to medium water with pH 6.0 to 7.5 and a temperature of 76 to 82°F.\n\nPlant heavily with fine leaved plants and moss, and include caves and wood for hiding. Use sand or fine gravel. A sponge filter or covered intake keeps any fry safe. The tank should have been running for months, with plenty of biofilm and microorganisms.\n\nKeep tankmates few and peaceful, or set up a species only tank, so any eggs or fry are not eaten. Snails are welcome, since the loaches eat small ones and they show you the tank is well fed."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is hard. Mature females are larger and rounder in the belly, while males are slimmer. Keep a group of at least 6 adults so they feel secure and pairs can form.\n\nFeed a rich, varied diet: small snails, frozen bloodworms, brine shrimp, daphnia and quality sinking pellets. Condition for several weeks, with weekly water changes of 25 to 30 percent.\n\nBuy healthy fish from a reliable source and quarantine them. Look for active fish with full bellies and no clamped fins. Groups bought together and grown up together seem most likely to settle and spawn."}, {"heading": "Spawning and eggs", "text": "Hobby spawns are seldom seen. Breeders who have had fry usually report finding them in dense plants or moss after a period of heavy feeding and water changes. Spawning probably involves scattering eggs among plants, with no parental care.\n\nIf you spot eggs, move them with the plant into a small container of tank water with gentle aeration. Remove any white, fungused eggs."}, {"heading": "Raising the fry", "text": "Fry are tiny and hide well.\n\n- First week: infusoria several times a day.\n- Week 2: microworms.\n- Week 3 on: baby brine shrimp and finely crushed foods.\n\nIf fry are found in the main tank, you can move them to a small grow out tank or leave them with lots of cover and feed the tank more often. Do 10 to 20 percent water changes every few days.\n\nCheck the fry daily with a flashlight. Full bellies mean they are finding food. If they look thin, add more infusoria and feed more often. Keep the temperature steady at 76 to 80°F."}, {"heading": "Growing out", "text": "Young dwarf chain loaches take several months to reach an inch. Feed baby brine shrimp, crushed pellets and small snails as they grow. Keep them in a quiet, planted tank with hiding places. Record water values, foods and dates, since detailed reports for this species are scarce."}, {"heading": "Common mistakes", "text": "- A new, sterile tank with no microorganisms for fry.\n- Too few fish. These loaches need a group to feel secure.\n- Strong filters that suck up fry.\n- Expecting quick results. Spawns can take a long time or not happen at all.\n- Changing too much water at once in a tank where you suspect fry.\n- Housing them with fast, greedy tankmates that eat everything first."}]$g$::jsonb, $g$[{"q": "Can dwarf chain loaches breed in an aquarium?", "a": "Yes, but it is rare. A few hobbyists have found fry in mature, planted tanks."}, {"q": "How do you sex dwarf chain loaches?", "a": "It is hard. Mature females are larger and rounder, while males are slimmer."}, {"q": "Why are dwarf chain loaches rare in the wild?", "a": "They are threatened in their native Thailand, and captive bred fish now make up most of the supply."}, {"q": "What do dwarf chain loach fry eat?", "a": "Infusoria at first, then microworms and baby brine shrimp as they grow."}]$g$::jsonb, $g$Open your log as soon as your group is settled and photograph them in the planted tank with your challenge code card. If you find fry before eggs, photograph them on the day you find them and note it clearly in your log.$g$),
  ($g$kuhli-loach$g$, $g$7912b4a6-0d90-43d7-8483-68a327ca9445$g$::uuid, $g$kuhli-loach$g$, null, $g$How to Breed Kuhli Loaches: Soft Water, Plants and Green Eggs$g$, $g$Kuhli loaches occasionally spawn in soft, acidic, heavily planted tanks, laying green eggs among roots. Rare in home tanks and expert level.$g$, $g$Kuhli loaches are popular, peaceful bottom dwellers, but home spawns are uncommon and usually a happy surprise. Groups have been known to spawn in soft, acidic, heavily planted tanks, laying bright green eggs among floating plant roots. Fry are tiny and secretive, so this is an expert level project, but a mature planted tank gives you a real chance.$g$, $g${"method": "Egg scatterer; eggs often laid among floating plant roots", "sexing": "Males have larger, paddle shaped pectoral fins; ripe females look fuller and greenish", "group": "A group of 6 or more adults", "breeding_tank": "20 gallons or more, soft sand, dense plants, floating plants and caves", "conditioning": "Bloodworms, blackworms, brine shrimp, daphnia and sinking pellets for several weeks", "trigger": "Soft acidic water, dim light, and cooler water changes or rising water level", "spawn": "Not well documented; reports vary", "eggs": "Breeders report bright green eggs hatching in about 1 to 2 days at 78 to 80°F", "fry": "Tiny fry that hide among plants and roots", "first_foods": "Infusoria, then microworms and baby brine shrimp", "grow_out": "Several months to reach 1 to 2 inches", "parents": "Adults may eat eggs; dense plants or moving eggs improves survival"}$g$::jsonb, $g$[{"heading": "Setting up the breeding tank", "text": "Use 20 gallons or more, as our care data suggests, with soft sand so they can dig. Plant densely and add floating plants with long roots, plus caves and leaf litter. Keep the lights dim.\n\nUse soft, acidic water with pH around 5.5 to 6.5 and temperatures of 78 to 80°F, within our care range of 75 to 86°F. Use a sponge filter or covered intake to keep fry safe.\n\nA species only tank gives the best chance, since many tankmates will eat eggs and tiny fry. Leaf litter and moss add hiding places and grow microorganisms that young kuhlis can graze on. Keep the lid tight, as kuhlis can squeeze through small gaps."}, {"heading": "Choosing and conditioning breeders", "text": "Sexing is possible with a close look. Males have larger, more paddle shaped pectoral fins with a thicker first ray. Ripe females look fuller, and their green eggs may show through the skin.\n\nKeep a group of 6 or more. Feed frozen bloodworms, blackworms, brine shrimp, daphnia and quality sinking pellets for several weeks. Feeding at night, when they are most active, helps them get enough.\n\nMost kuhlis sold are a mix of similar Pangio species, so try to buy your group from one batch that all look the same. Quarantine new fish and give them time to settle before you expect spawning. Healthy kuhlis are active at night and eat eagerly."}, {"heading": "Spawning", "text": "Spawning is rarely seen, as it often happens at night. Reports describe groups gathering near the surface and laying eggs among floating plant roots. Triggers often mentioned include a cooler water change, raising the water level, or soft rainwater style changes.\n\nIf you find green eggs, gently move the roots or plants into a hatching container with tank water and an air stone.\n\nSpawning is often noticed after a large, soft, slightly cooler water change, which imitates the rainy season. Check floating plant roots in the morning with a flashlight for green eggs. If you never find eggs, look for tiny fry in moss and leaf litter instead."}, {"heading": "Eggs and fungus prevention", "text": "The eggs are bright green and easy to recognize. Breeders report hatching in about 1 to 2 days at 78 to 80°F. Remove white, fungused eggs daily. Keep the hatching container dim, and use very gentle aeration.\n\nIf you leave eggs in the main tank, dense plants and moss give some fry a chance to survive."}, {"heading": "Raising the fry", "text": "Fry are tiny and hide all the time.\n\n- First week: infusoria several times a day.\n- Week 2: microworms.\n- Week 3 on: baby brine shrimp.\n\nDo small water changes of 10 to 20 percent every few days, and siphon carefully. Moss and leaf litter grow microorganisms that fry can graze on.\n\nKeep the fry tank dark and quiet, and add a small piece of moss or a few leaves so they have cover. Fry that hide constantly still need food nearby, so spread food across the bottom rather than in one spot."}, {"heading": "Growing out", "text": "Kuhli fry grow slowly, taking several months to reach 1 to 2 inches. Feed baby brine shrimp, microworms and crushed sinking pellets several times a day. Give them soft sand and lots of cover. Keep the water clean and soft through grow out.\n\nOnce the young are about an inch long, they can move into a larger tank with sand and plenty of cover. Keep feeding at night, when they are most active."}, {"heading": "Common mistakes", "text": "- Hard or alkaline water.\n- No floating plants for spawning.\n- Bright light, which keeps kuhlis hidden and stressed.\n- Strong filters that suck up fry.\n- Mixing Pangio species, as many look alike in the trade."}]$g$::jsonb, $g$[{"q": "Do kuhli loaches breed in aquariums?", "a": "Yes, but it is uncommon. Most spawns happen in soft, acidic, heavily planted tanks."}, {"q": "What do kuhli loach eggs look like?", "a": "They are bright green and are usually laid among floating plant roots."}, {"q": "How do you tell male and female kuhli loaches apart?", "a": "Males have larger, paddle shaped pectoral fins. Ripe females are fuller, and their green eggs may show through the skin."}, {"q": "What do kuhli loach fry eat?", "a": "Infusoria first, then microworms and baby brine shrimp."}]$g$::jsonb, $g$Photograph your group in the planted tank with your challenge code card when you open the log. The bright green eggs among roots make a striking stage 2 photo.$g$),
  ($g$banggai-cardinalfish$g$, $g$5aaf2f35-290e-45c9-ba88-0cf1df1f6042$g$::uuid, null, null, $g$How to Breed Banggai Cardinalfish: Mouthbrooding Males and Fry$g$, $g$Banggai cardinalfish males mouthbrood for about 3 weeks and release fully formed young. No larval stage makes them a rewarding marine project.$g$, $g$Banggai cardinalfish are one of the most rewarding marine fish to breed. The male holds the eggs in his mouth for about three weeks, then releases miniature fish that can eat baby brine shrimp right away, with no tiny larval stage to manage. The hard parts are finding a compatible pair and keeping the young safe. Wild populations are endangered from overcollection, so every captive bred Banggai helps.$g$, $g${"method": "Paternal mouthbrooder; male holds eggs until fully formed young are released", "sexing": "Hard; males often have a larger jaw, and the male's throat bulges when brooding", "group": "One bonded pair, chosen from a small group", "breeding_tank": "20 to 30 gallon marine tank, live rock, gentle flow, spiny shelter for young", "conditioning": "Enriched mysis, brine shrimp and quality marine foods several times a day", "trigger": "A settled pair in stable water; pairs often spawn every few weeks", "spawn": "Commonly reported around 20 to 50 eggs", "eggs": "Held by the male for about 3 weeks (commonly reported as 19 to 30 days) at 76 to 80°F", "fry": "Released as fully formed miniature fish, no larval stage", "first_foods": "Newly hatched or enriched brine shrimp and live copepods", "grow_out": "A few months to reach 1 inch", "parents": "Adults may eat young; move juveniles or the male soon after release"}$g$::jsonb, $g$[{"heading": "A marine fish on the Society list", "text": "Banggai cardinalfish come from a small island group in Indonesia and are listed as endangered, largely because of collection for the aquarium trade. They are on the Society list even though Underground Aquarium is mostly freshwater. You will need a stable saltwater setup: specific gravity about 1.023 to 1.026, temperature about 76 to 80°F, live rock and good filtration."}, {"heading": "Setting up the breeding tank", "text": "A 20 to 30 gallon tank with live rock, gentle flow and a protein skimmer or good filtration works well. Add a shelter with spines or branches, such as a long spined sea urchin or artificial branching decor, where young fish can hide. Banggai young hide among urchin spines in the wild.\n\nKeep tankmates out of the breeding tank, since almost any fish will eat the young.\n\nUse gentle flow, as Banggai are slow swimmers that hover in one spot. Keep the lighting moderate. Stable water matters more than any special equipment: check salinity and temperature daily and top off evaporation with fresh water. A separate small tank for the brooding male or the young makes things much easier."}, {"heading": "Choosing a pair", "text": "Sexing by looks is hard. Males often have a larger jaw, and when brooding, the male's throat bulges and he stops eating. Females may show a small papilla before spawning.\n\nThe usual approach is to keep a small group of young fish and watch for two that stay together and drive others away. Remove the rest once a pair forms, as they can be aggressive to the others. Feed enriched mysis, brine shrimp and quality marine foods several times a day.\n\nBuy captive bred fish if you can. They adapt better to aquarium foods and are less likely to carry disease than wild fish. Quarantine new arrivals for several weeks before adding them to the breeding tank."}, {"heading": "Spawning and mouthbrooding", "text": "The pair courts for hours or days, swimming side by side. The female then releases a mass of eggs, and the male takes it into his mouth. Clutches are commonly reported around 20 to 50 eggs.\n\nThe male holds the eggs for about 3 weeks (commonly reported as 19 to 30 days) at 76 to 80°F. He does not eat during this time. You will see his mouth stretched and full. Avoid stress, as a disturbed male may swallow or spit the eggs.\n\nPairs often spawn again within a few weeks of release, so a well fed pair can produce many batches in a year. If a male swallows his first clutches, give him time; many improve with experience."}, {"heading": "Release and raising the young", "text": "The male releases fully formed young, usually at night. They are tiny miniature Banggai and can eat right away.\n\n- First weeks: newly hatched or enriched brine shrimp, plus live copepods, several times a day.\n- Weeks 3 to 6: add chopped mysis and fine marine foods.\n- Change 10 to 20 percent of water weekly, and siphon leftovers.\n\nMove the young or the male right after release, because adults may eat them. Some breeders move the male to a separate tank a few days before release.\n\nYoung Banggai are slow, careful feeders. Offer food several times a day in a calm spot, and keep flow low so they can catch it. A small grow out tank, around 10 gallons, keeps food close to them."}, {"heading": "Growing out", "text": "Young Banggai grow steadily, reaching about an inch in a few months. Keep them in a grow out tank with branching shelter, gentle flow and clean water. Feed several times a day. Captive bred Banggai are hardier than wild fish and in demand, which helps reduce pressure on wild populations."}, {"heading": "Common mistakes", "text": "- Keeping more than one pair in a small tank, which leads to fighting.\n- Leaving young with the adults.\n- Disturbing a brooding male.\n- Poor nutrition, which leads to small or failed spawns.\n- Adding young to a tank with filters that can trap them. Cover intakes with sponge.\n- Buying wild caught adults instead of captive bred stock."}]$g$::jsonb, $g$[{"q": "How long does a Banggai cardinalfish hold eggs?", "a": "About 3 weeks; commonly reported as 19 to 30 days at 76 to 80°F."}, {"q": "Do Banggai cardinalfish fry have a larval stage?", "a": "No. The male releases fully formed young that can eat baby brine shrimp right away."}, {"q": "How can you tell a male Banggai from a female?", "a": "It is hard. Males often have a larger jaw, and a brooding male's throat bulges with eggs."}, {"q": "Why are Banggai cardinalfish endangered?", "a": "Their natural range is very small, and overcollection for the aquarium trade has reduced wild populations."}]$g$::jsonb, $g$Photograph the bonded pair with your challenge code card when you open the log. A photo of the male with his full, stretched mouth is your stage 2 proof, and photos of the young after release work well for stage 3.$g$),
  ($g$clarks-clownfish$g$, $g$4ef0dbb1-372f-4079-b767-0f011169a4f5$g$::uuid, null, null, $g$How to Breed Clark's Clownfish: Pairs, Eggs and Larvae$g$, $g$Clark's clownfish lay eggs on rock and guard them, but the larvae need rotifers and careful care. An expert level marine breeding project.$g$, $g$Clark's clownfish are hardy, adaptable and willing to spawn in home tanks once a pair is settled. The male guards eggs on a rock or tile near the pair's chosen home, and they often spawn every couple of weeks. The challenge is the larvae: they need live rotifers and green water before they can eat brine shrimp. That makes this an expert level project, but a rewarding one.$g$, $g${"method": "Substrate spawner; male guards eggs on rock or tile", "sexing": "Female is the larger fish of a pair; clownfish start male and the largest becomes female", "group": "One bonded pair", "breeding_tank": "30 gallons or more, live rock, a tile or flat rock near the pair's home", "conditioning": "Mysis, enriched brine shrimp, quality pellets and flakes several times a day", "trigger": "A settled pair in stable water; pairs often spawn every 2 to 3 weeks", "spawn": "Commonly a few hundred eggs, sometimes more from large pairs", "eggs": "Hatch in about 6 to 9 days at 78 to 82°F, usually just after dark", "fry": "Tiny larvae that need live food; metamorphosis around day 8 to 12", "first_foods": "Enriched rotifers and green water, then newly hatched brine shrimp", "grow_out": "About 3 to 4 months to reach 1 inch", "parents": "Parents guard eggs; larvae must be removed to a separate tank at hatch"}$g$::jsonb, $g$[{"heading": "A marine fish on the Society list", "text": "Clownfish are marine fish, so you will need a stable saltwater setup: specific gravity about 1.023 to 1.026, temperature about 78 to 82°F, good live rock or filtration, and regular water changes with marine salt mix. They are on the Society list even though Underground Aquarium is mostly freshwater, and marine breeders are very welcome."}, {"heading": "Setting up the breeding tank and pair", "text": "Use 30 gallons or more with live rock and a flat tile or rock near the pair's chosen spot. Anemones aren't required.\n\nYoung clownfish mature as males first, and the largest fish in a pair becomes female. The easiest pair is two young fish, or a larger and smaller fish. The female is the larger of the two. Clark's can be aggressive toward other clownfish, so keep only one pair per tank.\n\nClark's clownfish naturally host many kinds of anemones, but pairs spawn happily without one. Place the tile where the pair spends most of its time, and keep tankmates few and peaceful so the pair feels secure."}, {"heading": "Conditioning and spawning", "text": "Feed mysis, enriched brine shrimp, quality pellets and flakes several times a day. Pairs often spawn every 2 to 3 weeks once settled.\n\nBefore spawning, the pair cleans a flat surface. The female lays rows of orange eggs, and the male fertilizes them. Clutches are commonly a few hundred eggs, sometimes more from large pairs."}, {"heading": "Eggs and hatching", "text": "The male fans and guards the eggs. They darken and show silver eyes as they develop. At 78 to 82°F, they hatch in about 6 to 9 days, usually an hour or two after dark.\n\nOn hatch night, either move the tile to the larval tank before lights out or turn off pumps and use a flashlight to draw larvae to a corner, then scoop them out gently."}, {"heading": "Raising the larvae", "text": "Larvae are about the size of an eyelash and need live food from the first night.\n\n- Days 1 to 7: enriched rotifers kept at a steady density, with green water (live phytoplankton) added to keep the rotifers fed and the water lightly tinted.\n- From around day 5 to 7: add newly hatched brine shrimp nauplii alongside the rotifers.\n- Days 8 to 12: metamorphosis. Larvae turn into tiny clownfish with their first white bars and settle toward the bottom.\n\nUse a 10 to 20 gallon larval tank with black sides, a gentle air stone and no filter for the first days. Siphon the bottom daily and change 10 to 20 percent of the water with matched salt water. Keep the temperature steady around 80°F.\n\nStart cultures at least two to three weeks before you expect a hatch. Keep two or more rotifer cultures going in case one crashes, feed them live phytoplankton or a concentrated algae paste, and enrich them before feeding larvae. Set up a daily brine shrimp hatchery too, so fresh nauplii are ready when larvae can take them. Running out of food in the first week is the most common reason a batch fails."}, {"heading": "Growing out", "text": "After metamorphosis, start weaning onto fine dry foods while still feeding brine shrimp. Expect about 3 to 4 months to reach an inch. Keep water clean, feed several times a day, and sort by size.\n\nMany breeders move juveniles to a grow out tank with a sponge filter and bare bottom for easy cleaning. Watch for the white bars filling in and the body shape rounding out. Small water changes several times a week keep growth steady, and it is normal for some fish in a batch to grow faster than others."}, {"heading": "Common mistakes", "text": "- Leaving larvae in the display, where filters and fish take them all.\n- Running out of rotifers or green water in the first week.\n- Strong aeration that batters larvae.\n- Feeding brine shrimp too early, before larvae can eat it.\n- Mixing with other clownfish species in the breeding tank."}]$g$::jsonb, $g$[{"q": "How long do Clark's clownfish eggs take to hatch?", "a": "About 6 to 9 days at 78 to 82°F, usually just after dark."}, {"q": "How do you tell male and female Clark's clownfish apart?", "a": "The female is the larger fish in a pair. Clownfish start as males and the dominant one becomes female."}, {"q": "Do Clark's clownfish need an anemone to breed?", "a": "No. Pairs spawn on rock or tile without an anemone."}, {"q": "What do clownfish larvae eat?", "a": "Enriched rotifers and green water first, then newly hatched brine shrimp from about day 5 to 7."}]$g$::jsonb, $g$Photograph your pair near their tile with your challenge code card when you open the log. A clear shot of the eggs on the tile is your stage 2 proof, and settled juveniles with white bars make a great 30 day photo.$g$),
  ($g$dwarf-seahorse$g$, $g$0797698d-18c8-435c-90c6-45d3fe44d32d$g$::uuid, null, null, $g$How to Breed Dwarf Seahorses: Pairs, Pregnancy and Fry Care$g$, $g$Dwarf seahorse males carry young in a pouch for about 10 to 14 days. Fry eat baby brine shrimp from birth, but clean live food is the hard part.$g$, $g$Dwarf seahorses are tiny, fascinating fish, and the male really does give birth. Pairs court each morning, the female passes eggs to the male's pouch, and about two weeks later he releases tiny seahorses. Unlike most seahorses, the fry can eat newly hatched brine shrimp from birth. Their constant need for clean live food and a pest free tank is what makes this an expert level project.$g$, $g${"method": "Male pregnancy; eggs carried in the male's brood pouch", "sexing": "Males have a brood pouch on the belly; females lack a pouch", "group": "One pair, or a small colony of pairs", "breeding_tank": "5 to 10 gallon marine tank, sponge filter, gentle flow, many hitching posts", "conditioning": "Newly hatched brine shrimp, enriched, fed several times a day", "trigger": "Settled, well fed pairs in stable water; courtship usually in the morning", "spawn": "Small broods, commonly a few to a few dozen young", "eggs": "Gestation about 10 to 14 days at 72 to 78°F", "fry": "Fully formed miniature seahorses that hitch to posts", "first_foods": "Newly hatched brine shrimp from birth", "grow_out": "Commonly reported to reach maturity in about 3 months", "parents": "Adults usually ignore fry; many keepers raise them in the same tank"}$g$::jsonb, $g$[{"heading": "A marine fish on the Society list", "text": "Dwarf seahorses are marine fish from seagrass beds around Florida, the Bahamas, Bermuda and the Gulf of Mexico. They are on the Society list even though Underground Aquarium is mostly freshwater. You need a small, stable saltwater tank with specific gravity about 1.020 to 1.025 and temperatures around 72 to 78°F. Choose captive bred stock."}, {"heading": "Setting up the breeding tank", "text": "A 5 to 10 gallon tank is ideal, as dwarfs need food close by. Use a sponge filter with gentle flow and add lots of hitching posts like artificial plants or seagrass. Live rock can bring in pests, so many keepers use a bare or sand bottom.\n\nKeep tankmates out. Even small shrimp or fish can compete for food or harm fry.\n\nDwarf seahorses are weak swimmers that spend their time holding onto posts, so place hitching posts throughout the tank and keep flow very gentle. A tight lid and a stable room temperature help keep conditions steady. Because they need such frequent feeding, many keepers set up a simple daily brine shrimp hatchery before they buy fish."}, {"heading": "Pairs and courtship", "text": "Sexing is easy in adults. Males have a brood pouch on the belly below the tail, and females don't. Pairs are often formed by keeping a small group together.\n\nCourtship usually happens in the morning. Pairs change color, hold tails, and dance around a hitching post. The female then passes eggs into the male's pouch.\n\nA small colony with several males and females gives the most spawns. Watch the morning displays; pairs that greet each other every day are likely to spawn soon. Well fed females are more likely to produce good broods."}, {"heading": "Pregnancy and birth", "text": "The male's pouch swells as the young develop. Gestation is about 10 to 14 days at 72 to 78°F. Broods are small, commonly a few to a few dozen young.\n\nBirth usually happens at night or early morning. The young are tiny, fully formed seahorses that grab onto hitching posts right away.\n\nMales are often ready to mate again soon after giving birth, so a healthy pair can produce several broods in a row. Count the fry when you can, since broods differ a lot from one birth to the next."}, {"heading": "Raising the fry", "text": "Unlike most seahorses, dwarf fry can eat newly hatched brine shrimp from birth.\n\n- From day 1: newly hatched brine shrimp, several times a day.\n- Week 2 on: enriched brine shrimp to help growth.\n- Change 10 to 20 percent of water every few days, matching salinity.\n\nKeep the food dense enough that fry can catch it easily, but siphon leftovers so the water stays clean.\n\nMake sure the brine shrimp you feed are freshly hatched, rinsed and free of shells, and hatch a new batch every day. Old, unenriched brine shrimp lose food value quickly. Fry should have visibly full bellies after feeding."}, {"heading": "Growing out", "text": "Dwarf seahorses are commonly reported to reach maturity in about 3 months. Keep feeding enriched brine shrimp several times a day and keep water clean. Many keepers raise fry with the adults, since adults usually ignore them. Separate them if you see problems."}, {"heading": "Common mistakes", "text": "- Hydroids and other pests, often brought in with live food or rock. They can sting and kill dwarf seahorses.\n- Not enough food. Dwarfs need to eat often.\n- Strong flow or filters.\n- Tanks that are too large, which makes food hard to find.\n- Adding tankmates that steal food or bother the seahorses.\n- Letting salinity drift. Top off evaporation with fresh water daily."}]$g$::jsonb, $g$[{"q": "How long are dwarf seahorses pregnant?", "a": "About 10 to 14 days at 72 to 78°F."}, {"q": "Do male seahorses really give birth?", "a": "Yes. The female passes eggs into the male's pouch, and he carries and releases the young."}, {"q": "What do baby dwarf seahorses eat?", "a": "Newly hatched brine shrimp, from birth."}, {"q": "How many babies do dwarf seahorses have?", "a": "Broods are small, commonly from a few to a few dozen young."}]$g$::jsonb, $g$Photograph your pair on a hitching post with your challenge code card when you open the log. A side photo of the male's swollen pouch works as your stage 2 evidence.$g$),
  ($g$maroon-clownfish$g$, $g$6ab9d875-00f9-4b5e-b976-da0f71ee9612$g$::uuid, null, null, $g$How to Breed Maroon Clownfish: Pairing, Eggs and Larvae$g$, $g$Maroon clownfish spawn on rock and guard eggs, but pairing is tricky and larvae need rotifers. A rewarding but expert level marine project.$g$, $g$Maroon clownfish are the largest and most aggressive clownfish, and breeding them starts with the tricky job of pairing a large female with a small male without fighting. Once settled, pairs spawn regularly on rock near their home, and the male guards the eggs. Like other clowns, the larvae need live rotifers and green water. This is an expert level project with stunning results.$g$, $g${"method": "Substrate spawner; male guards eggs on rock or tile", "sexing": "Female is much larger and darker; male is small and often brighter", "group": "One bonded pair", "breeding_tank": "40 gallons or more, live rock, tile or flat rock near the pair's home", "conditioning": "Mysis, enriched brine shrimp, quality pellets and flakes several times a day", "trigger": "A settled pair in stable water; pairs often spawn every 2 to 3 weeks", "spawn": "Commonly several hundred eggs", "eggs": "Hatch in about 6 to 9 days at 78 to 82°F, usually just after dark", "fry": "Tiny larvae that need live food; metamorphosis commonly reported around day 8 to 15", "first_foods": "Enriched rotifers and green water, then newly hatched brine shrimp", "grow_out": "About 3 to 4 months to reach 1 inch", "parents": "Parents guard eggs; larvae must be removed to a separate tank at hatch"}$g$::jsonb, $g$[{"heading": "A marine fish on the Society list", "text": "Clownfish are marine fish, so you will need a stable saltwater setup: specific gravity about 1.023 to 1.026, temperature about 78 to 82°F, good live rock or filtration, and regular water changes with marine salt mix. They are on the Society list even though Underground Aquarium is mostly freshwater, and marine breeders are very welcome."}, {"heading": "Pairing maroon clownfish", "text": "Maroons are very aggressive, and a large female can injure or kill a new male. The size difference between a pair is dramatic: the female is much larger and darker, the male small and often brighter.\n\nTo pair them, use a divider or clear container so the fish can see each other for days or weeks. Choose a small male and a larger female. Watch closely after release and separate them if fighting continues."}, {"heading": "Setting up and spawning", "text": "Use 40 gallons or more with live rock and a tile or flat rock near the pair's home. A bubble tip anemone is often used but isn't required.\n\nFeed mysis, enriched brine shrimp, quality pellets and flakes several times a day. Pairs clean a surface before spawning, and the female lays orange eggs. Clutches are commonly several hundred eggs."}, {"heading": "Eggs and hatching", "text": "The male fans and guards the eggs. They darken and show silver eyes as they develop. At 78 to 82°F, they hatch in about 6 to 9 days, usually an hour or two after dark.\n\nOn hatch night, move the tile to the larval tank or turn off pumps and use a light to collect larvae. Be careful, as maroons defend eggs fiercely and can bite."}, {"heading": "Raising the larvae", "text": "Larvae are about the size of an eyelash and need live food from the first night.\n\n- Days 1 to 7: enriched rotifers kept at a steady density, with green water (live phytoplankton) added to keep the rotifers fed and the water lightly tinted.\n- From around day 5 to 7: add newly hatched brine shrimp nauplii alongside the rotifers.\n- Days 8 to 15: metamorphosis (breeders report maroons can take a little longer than ocellaris). Larvae turn into tiny maroon clownfish with their first white bars and settle toward the bottom.\n\nUse a 10 to 20 gallon larval tank with black sides, a gentle air stone and no filter for the first days. Siphon the bottom daily and change 10 to 20 percent of the water with matched salt water. Keep the temperature steady around 80°F.\n\nStart cultures at least two to three weeks before you expect a hatch. Keep two or more rotifer cultures going in case one crashes, feed them live phytoplankton or a concentrated algae paste, and enrich them before feeding larvae. Set up a daily brine shrimp hatchery too, so fresh nauplii are ready when larvae can take them. Running out of food in the first week is the most common reason a batch fails."}, {"heading": "Growing out", "text": "After metamorphosis, start weaning onto fine dry foods while feeding brine shrimp. Expect 3 to 4 months to reach an inch. Young maroons can be aggressive toward each other, so give them space and sort by size.\n\nMany breeders move juveniles to a grow out tank with a sponge filter and bare bottom for easy cleaning. Watch for the white bars filling in and the body shape rounding out. Small water changes several times a week keep growth steady, and it is normal for some fish in a batch to grow faster than others."}, {"heading": "Common mistakes", "text": "- Leaving larvae in the display, where filters and fish take them all.\n- Running out of rotifers or green water in the first week.\n- Strong aeration that batters larvae.\n- Feeding brine shrimp too early, before larvae can eat it.\n- Forcing a pair together without a divider, which can lead to injury or death."}]$g$::jsonb, $g$[{"q": "How do you tell male and female maroon clownfish apart?", "a": "The female is much larger and darker. The male is small and often brighter."}, {"q": "How long do maroon clownfish eggs take to hatch?", "a": "About 6 to 9 days at 78 to 82°F, usually just after dark."}, {"q": "Are maroon clownfish hard to pair?", "a": "Yes. Females are very aggressive, so use a divider and introduce a small male slowly."}, {"q": "Do maroon clownfish need an anemone to spawn?", "a": "No, though many pairs host a bubble tip anemone. They spawn on rock or tile."}]$g$::jsonb, $g$Photograph the pair with your challenge code card when you open the log; the size difference shows the pairing clearly. A photo of the eggs on the tile is your stage 2 proof.$g$),
  ($g$ocellaris-clownfish$g$, $g$b844377f-0ea1-4a89-9cf0-15f06ddec4f5$g$::uuid, null, null, $g$How to Breed Ocellaris Clownfish: From Eggs to Juveniles$g$, $g$Ocellaris clownfish spawn readily, but raising the larvae needs rotifers, green water and steady care. An expert level marine breeding project.$g$, $g$Ocellaris clownfish are the best known marine fish in the hobby and one of the most commonly bred. Settled pairs spawn on a rock or tile every couple of weeks, and the male tends the eggs. The real challenge is the larvae, which need rotifers and green water before they can eat brine shrimp. It is an expert level project, but thousands of hobbyists have done it.$g$, $g${"method": "Substrate spawner; male guards eggs on rock or tile", "sexing": "Female is the larger fish of a pair; clownfish start male and the largest becomes female", "group": "One bonded pair", "breeding_tank": "20 to 30 gallon marine tank, live rock, tile or flat rock near the pair's home", "conditioning": "Mysis, enriched brine shrimp, quality pellets and flakes several times a day", "trigger": "A settled pair in stable water; pairs often spawn every 2 to 3 weeks", "spawn": "Commonly a few hundred eggs, sometimes more from large pairs", "eggs": "Hatch in about 6 to 9 days at 78 to 82°F, usually just after dark", "fry": "Tiny larvae that need live food; metamorphosis around day 8 to 12", "first_foods": "Enriched rotifers and green water, then newly hatched brine shrimp", "grow_out": "About 3 to 4 months to reach 1 inch", "parents": "Parents guard eggs; larvae must be removed to a separate tank at hatch"}$g$::jsonb, $g$[{"heading": "A marine fish on the Society list", "text": "Clownfish are marine fish, so you will need a stable saltwater setup: specific gravity about 1.023 to 1.026, temperature about 78 to 82°F, good live rock or filtration, and regular water changes with marine salt mix. They are on the Society list even though Underground Aquarium is mostly freshwater, and marine breeders are very welcome."}, {"heading": "Setting up the breeding tank and pair", "text": "A 20 to 30 gallon tank with live rock and a flat tile or rock near the pair's home is enough. Anemones aren't needed.\n\nClownfish start as males, and the larger fish becomes the female. Two young fish will usually pair up. The female is the larger fish. Pairs can take months to start spawning.\n\nKeep tankmates few and peaceful so the pair feels secure, and place the tile near where they sleep. A stable tank with steady salinity and temperature is more important than any special decor."}, {"heading": "Conditioning and spawning", "text": "Feed mysis, enriched brine shrimp, quality pellets and flakes several times a day. Pairs often spawn every 2 to 3 weeks once settled.\n\nBefore spawning, the pair cleans a flat surface. The female lays rows of orange eggs, and the male fertilizes them. Clutches are commonly a few hundred eggs, sometimes more from large pairs."}, {"heading": "Eggs and hatching", "text": "The male fans and guards the eggs. They darken and show silver eyes as they develop. At 78 to 82°F, they hatch in about 6 to 9 days, usually an hour or two after dark.\n\nOn hatch night, either move the tile to the larval tank before lights out or turn off pumps and use a flashlight to collect larvae."}, {"heading": "Raising the larvae", "text": "Larvae are about the size of an eyelash and need live food from the first night.\n\n- Days 1 to 7: enriched rotifers kept at a steady density, with green water (live phytoplankton) added to keep the rotifers fed and the water lightly tinted.\n- From around day 5 to 7: add newly hatched brine shrimp nauplii alongside the rotifers.\n- Days 8 to 12: metamorphosis. Larvae turn into tiny clownfish with their first white bars and settle toward the bottom.\n\nUse a 10 to 20 gallon larval tank with black sides, a gentle air stone and no filter for the first days. Siphon the bottom daily and change 10 to 20 percent of the water with matched salt water. Keep the temperature steady around 80°F.\n\nStart cultures at least two to three weeks before you expect a hatch. Keep two or more rotifer cultures going in case one crashes, feed them live phytoplankton or a concentrated algae paste, and enrich them before feeding larvae. Set up a daily brine shrimp hatchery too, so fresh nauplii are ready when larvae can take them. Running out of food in the first week is the most common reason a batch fails."}, {"heading": "Growing out", "text": "After metamorphosis, wean onto fine dry foods while still feeding brine shrimp. Expect about 3 to 4 months to reach an inch. Keep water clean, feed several times a day, and sort by size.\n\nMany breeders move juveniles to a grow out tank with a sponge filter and bare bottom for easy cleaning. Watch for the white bars filling in and the body shape rounding out. Small water changes several times a week keep growth steady, and it is normal for some fish in a batch to grow faster than others. Captive bred ocellaris are popular, but make sure your fish are healthy and eating dry food before passing any on."}, {"heading": "Common mistakes", "text": "- Leaving larvae in the display, where filters and fish take them all.\n- Running out of rotifers or green water in the first week.\n- Strong aeration that batters larvae.\n- Feeding brine shrimp too early, before larvae can eat it.\n- Expecting a pair to spawn immediately. Many take months to settle."}]$g$::jsonb, $g$[{"q": "How long do ocellaris clownfish eggs take to hatch?", "a": "About 6 to 9 days at 78 to 82°F, usually just after dark."}, {"q": "How do you tell male and female ocellaris clownfish apart?", "a": "The female is the larger fish in a pair. Clownfish start as males and the dominant one becomes female."}, {"q": "Do ocellaris clownfish need an anemone to breed?", "a": "No. They spawn on rock or tile without an anemone."}, {"q": "What do clownfish larvae eat?", "a": "Enriched rotifers and green water first, then newly hatched brine shrimp from about day 5 to 7."}]$g$::jsonb, $g$Photograph your pair near their tile with your challenge code card when you open the log. A clear shot of the eggs on the tile is your stage 2 proof.$g$),
  ($g$percula-clownfish$g$, $g$6cad3cd5-9860-4a38-9c1a-cb2f8de9b79c$g$::uuid, null, null, $g$How to Breed Percula Clownfish: Pairs, Eggs and Larvae$g$, $g$Breeding percula clownfish means a bonded saltwater pair, eggs on a tile and a week of rotifers and greenwater. Expert level, but very doable.$g$, $g$Percula clownfish are one of the few marine fish a home hobbyist can realistically breed, and a bonded pair may spawn every couple of weeks for years. The catch is the larvae: they hatch tiny, live in open water for over a week and need live rotifers from the first night. It is an expert-level project on the Society list, but it is the classic first step into marine breeding.$g$, $g${"method": "Demersal egg layer: eggs stuck to rock or tile near the anemone, guarded by the male", "sexing": "Not visible by color; the larger, dominant fish is the female, and the smaller is the male", "group": "One bonded pair; two juveniles will usually sort themselves into male and female", "breeding_tank": "Saltwater, 20 to 30 gallons for the pair, plus a 10 to 20 gallon larval tank", "conditioning": "Two or three meals a day of mysis, quality pellets and enriched brine for several weeks", "trigger": "A mature, well-fed pair with a flat spawning site and a stable day and night cycle", "spawn": "Commonly a few hundred eggs, roughly 100 to 500+, increasing as the pair matures", "eggs": "Hatch in about 6 to 10 days at 78 to 82°F, usually soon after the lights go out", "fry": "Tiny larvae drift in open water and settle and color up at about 8 to 12 days", "first_foods": "Enriched rotifers from day 1, then newly hatched brine shrimp from about day 5 to 8", "grow_out": "About 3 to 4 months to reach a small sellable size of around 1 inch", "parents": "Male fans and mouths the eggs; move the egg tile to a hatching tank on hatch night"}$g$::jsonb, $g$[{"heading": "The saltwater setup", "text": "Percula clownfish need full marine conditions: specific gravity around 1.023 to 1.026, temperature 78 to 82°F and stable, clean water. They are on the Society list even though most of the site is freshwater, so plan for two systems. The pair tank can be a simple 20 to 30 gallon tank with live rock, a terracotta tile or flat rock for spawning, and an anemone if you keep one, although many pairs spawn happily without.\n\nThe larval tank is separate: 10 to 20 gallons, bare bottom, black or dark sides, gentle aeration from an airline with no airstone, and no filter for the first week. Most breeders add phytoplankton paste or live algae to tint the water green, which keeps the rotifers fed and helps the larvae see their food."}, {"heading": "Getting a bonded pair", "text": "The easiest route is to buy two small juveniles, or a pair sold as bonded. Clownfish are born without a fixed sex; the larger fish becomes the female and the smaller stays male, and the change from male to female cannot be undone. Two juveniles placed together will usually sort this out within weeks.\n\nCondition with two or three small meals a day of frozen mysis, quality marine pellets and enriched brine shrimp. A young pair may take 6 to 12 months before the first spawn."}, {"heading": "What spawning looks like", "text": "A day or two before spawning the pair will clean a patch of rock or tile intensely, and the female's belly looks rounder. You may see a small breeding tube from each fish. Spawning often happens in the afternoon or early evening, with the female making passes to lay rows of orange eggs and the male following to fertilize them.\n\n- First clutches are often small, under 100 eggs\n- Mature pairs commonly lay a few hundred\n- A healthy pair may spawn every 2 to 3 weeks"}, {"heading": "Eggs and hatch night", "text": "The male fans and mouths the eggs, removing any that go bad. Over 7 to 10 days at 78 to 82°F the eggs turn from orange to dark and then silver as the eyes develop. Hatching happens on the evening of the last night, usually within an hour or two of darkness.\n\nOn the expected night, move the tile to the larval tank with gentle aeration near the eggs, or siphon the larvae out of the parents' tank with a flashlight after dark. Losing a clutch to the filter or the cleanup crew is a very common first mistake."}, {"heading": "Raising the larvae", "text": "Larvae need enriched rotifers at a density high enough that food is always within reach, so start rotifer cultures weeks before the first spawn. Keep the larval tank at the same temperature as the parents and leave it dim but not dark.\n\n- Days 1 to 5: rotifers and green water, no water changes, small top-ups only\n- Days 5 to 8: start newly hatched brine shrimp alongside rotifers\n- Days 8 to 12: larvae settle, show their white bars and become juveniles\n- After settlement: siphon the bottom and change 10 to 20% every day or two"}, {"heading": "Growing out", "text": "Once settled, the juveniles are tough little fish. Feed small meals four or five times a day: baby brine, crushed pellets and frozen cyclops, moving to larger foods as they grow. Expect roughly 3 to 4 months to reach about an inch. Give them enough room and you will see far less fighting and stunting."}, {"heading": "Common mistakes", "text": "- Starting rotifer cultures after the eggs are already on the tile\n- Leaving larvae with the parents, where the filter or tank mates take them\n- Strong aeration that batters the larvae\n- Crashing water quality in the larval tank by overfeeding brine too early\n- Expecting every clutch to succeed; most first batches fail, and that is normal"}]$g$::jsonb, $g$[{"q": "How long do clownfish eggs take to hatch?", "a": "Clownfish eggs usually hatch in about 6 to 10 days at 78 to 82°F, with warmer water at the shorter end. They hatch soon after the lights go out on the final night."}, {"q": "How can you tell a male from a female clownfish?", "a": "In a pair the larger, dominant fish is the female and the smaller one is the male. There is no reliable color difference."}, {"q": "Do clownfish need an anemone to breed?", "a": "No. Many captive pairs spawn on rock or a tile without an anemone, although a pair that hosts one will usually spawn beside it."}, {"q": "What do baby clownfish eat?", "a": "Newly hatched clownfish larvae eat enriched rotifers for the first several days, then newly hatched brine shrimp. They are too small for flakes or pellets at first."}]$g$::jsonb, $g$Open your log as soon as you have a pair settled on a spawning site, with the challenge code card next to the tile for the stage 1 photo. Date your photos on hatch night and at settlement so your stage 3 timing is clear.$g$),
  ($g$uaru$g$, $g$7a6be34a-1975-4068-a8e0-efba33e91377$g$::uuid, $g$uaru$g$, null, $g$How to Breed Uaru Cichlids: Pairs, Spawning and Fry Care$g$, $g$Breeding uaru takes a large tank, soft warm water and a pair that forms on its own. Fry feed on parent slime at first. An expert-level cichlid project.$g$, $g$Uaru are big, gentle, plant-eating cichlids, and a pair raising a cloud of fry that graze on their sides is a real sight. The hard parts are space and patience: you need a large tank, a group to let a pair form, and soft, warm water. Few members will log one, which is why uaru sit in Society class E.$g$, $g${"method": "Substrate spawner: eggs laid on flat rock or wood, both parents guard", "sexing": "Very hard; papilla shape at spawning time is the only reliable sign", "group": "Grow out a group of 4 to 6 and let one pair form naturally", "breeding_tank": "125 gallons or more, flat stones or slate, soft acidic water", "conditioning": "Vegetable-heavy diet plus some protein for 4 to 8 weeks", "trigger": "Stable soft, warm water at 82 to 86°F and regular water changes", "spawn": "Commonly reported around 100 to 300 eggs", "eggs": "Hatch in about 2 to 4 days at 82 to 86°F; free swimming roughly 4 to 6 days later", "fry": "Fry graze the slime coat on the parents' bodies during the first weeks", "first_foods": "Parental slime first, plus newly hatched brine shrimp once free swimming", "grow_out": "Slow; often 3 months or more to reach about 1 to 1.5 inches", "parents": "Good guardians once settled; first spawns are often eaten, so be patient"}$g$::jsonb, $g$[{"heading": "Space and water", "text": "Uaru reach about 10 inches and live in groups, so the site's guide calls for at least 125 gallons and a group of four or more. For breeding, keep the water at the warm end of their range, 82 to 86°F, with pH around 5.5 to 6.5 and soft water. Provide a few large flat stones, slate or smooth wood as spawning sites, and a canister or sponge filter that will not suck up tiny fry.\n\nUaru eat a lot of greens, which means a lot of waste. Plan on large weekly water changes of 30 to 50% with matched temperature."}, {"heading": "Forming a pair", "text": "Sexing uaru by sight is unreliable. Some keepers point to body shape or a slight forehead bump in males, but these signs often mislead. The practical answer is to raise a group of four to six juveniles together and wait for two fish to start claiming and cleaning a stone together. Once a pair has formed, rehome the others or give the pair the tank.\n\nCondition with a diet rich in vegetables, such as blanched zucchini, spinach and algae-based pellets, plus some protein like krill or quality cichlid pellets, for 4 to 8 weeks."}, {"heading": "Spawning", "text": "Before spawning, the pair darkens and both fish scrub a flat surface for a day or more. The breeding tubes become visible: the female's is broad and blunt, the male's narrower and pointed. The female lays rows of eggs and the male follows to fertilize them. Breeders commonly report clutches of around 100 to 300 eggs."}, {"heading": "Eggs and wrigglers", "text": "Both parents fan the eggs and pick out any that turn white. At 82 to 86°F the eggs hatch in about 2 to 4 days. The wrigglers are moved to pits or another surface and stay there for several more days while they use their yolk.\n\nIf you prefer to hatch eggs away from the parents, you lose the slime feeding stage, which makes the fry much harder to raise. Most breeders leave uaru eggs with the pair."}, {"heading": "Raising the fry", "text": "Like discus, uaru fry feed on the mucus on their parents' sides during the first weeks. This is why a settled pair matters so much.\n\n- Free swimming: fry swarm the parents and graze their bodies\n- From the first days of free swimming: add newly hatched brine shrimp two or three times a day\n- Weeks 2 to 4: add crushed flake, powdered algae pellets and microworms\n- Change 20 to 30% of the water every few days, gently, at the same temperature"}, {"heading": "Growing out", "text": "Uaru fry grow slowly. Juveniles develop the spotted juvenile pattern first and take months to show adult coloring. Move them to a grow-out tank at around 4 to 6 weeks if the parents start to spawn again. Feed plenty of greens alongside protein, keep the water clean, and expect at least 3 months before they are a comfortable 1 to 1.5 inches.\n\nUaru are social, so raise the young in a group rather than singly, and give them hiding places such as wood and plants they can't uproot easily. Plan ahead for where they will go: each one grows into a large fish that needs a big tank, and local clubs and members are the best homes."}, {"heading": "Common mistakes", "text": "- Buying two fish and hoping they are a pair\n- Hard or alkaline water, which often gives poor fertility\n- Pulling the eggs, so the fry miss the slime feeding stage\n- Too small a tank, which leads to fights and stress\n- Giving up after the first few eaten clutches"}]$g$::jsonb, $g$[{"q": "How do you tell male and female uaru apart?", "a": "There is no reliable outward difference. The breeding tubes seen at spawning time are the only dependable way: the female's is broad and blunt, the male's thinner and pointed."}, {"q": "Do uaru fry eat from their parents?", "a": "Yes. Like discus, young uaru graze the slime coat on their parents' sides during their first weeks, alongside any small foods you offer."}, {"q": "How big a tank do uaru need to breed?", "a": "Plan for at least 125 gallons. They are large, social fish and a pair raising fry needs room away from tank mates."}, {"q": "How many eggs do uaru lay?", "a": "Breeders commonly report around 100 to 300 eggs per spawn, with younger pairs laying fewer."}]$g$::jsonb, $g$Because pairs form in a group, open your log once a pair is clearly guarding a stone and show them together with the challenge code card for stage 1. A photo of fry grazing on a parent makes a clear stage 3 record.$g$),
  ($g$wild-discus$g$, $g$983cb458-e91a-47e5-b149-220b10540dfc$g$::uuid, $g$discus$g$, null, $g$How to Breed Wild Discus: Soft Water, Pairs and Fry$g$, $g$Breeding wild discus means very soft, acidic water, a true pair and fry that feed on parent slime. Harder than tank-bred discus. Expert level.$g$, $g$Wild-type discus are far fussier than the colorful tank-bred strains, and getting a pair to raise fry is a real achievement. The key differences are water and patience: wild fish usually need very soft, acidic water for the eggs to develop, and pairs can take a long time to settle. Expect setbacks along the way, which is why wild discus sit in Society class E.$g$, $g${"method": "Substrate spawner: eggs on a vertical surface such as a cone, both parents guard", "sexing": "Unreliable by sight; breeding tube shape at spawning is the best guide", "group": "One proven pair, usually chosen from a group of 5 or more raised together", "breeding_tank": "30 to 40 gallon tank per pair, bare bottom, spawning cone, sponge filter", "conditioning": "Beef heart mix, frozen bloodworms and quality granules, several weeks", "trigger": "Very soft water, pH dropped to about 5 to 6, warm 84 to 88°F and stability", "spawn": "Commonly about 100 to 300 eggs", "eggs": "Hatch in roughly 2 to 3 days at 84 to 86°F; wrigglers free swim 2 to 3 days later", "fry": "Fry swarm the parents and eat the slime on their sides for the first 1 to 2 weeks", "first_foods": "Parental slime, then newly hatched brine shrimp from about 5 days free swimming", "grow_out": "Around 2 to 3 months to reach roughly 1.5 to 2 inches with heavy feeding", "parents": "Eggs are often eaten in first spawns; most pairs improve with practice"}$g$::jsonb, $g$[{"heading": "Breeding tank and water", "text": "The site's care guide lists 82 to 88°F and pH 6 to 7. For breeding wild fish, most breeders go softer and more acidic: pH about 5 to 6, general hardness close to zero, and low conductivity. Wild discus eggs in harder water often fail to develop, so a reverse osmosis unit is close to essential.\n\nUse a 30 to 40 gallon tank per pair with a bare bottom, a sponge filter, a heater set to 84 to 88°F and a spawning cone or upright slate. Keep the tank in a quiet spot, and change 30 to 50% of the water several times a week with matched temperature and chemistry."}, {"heading": "Finding a pair", "text": "You cannot reliably sex discus by shape or color. The usual method is to raise a group of five or more together and watch for two fish that stay together and start cleaning a surface. Once they are paired, move them to their own tank.\n\nCondition with several small meals a day: a beef heart based mix, frozen bloodworms and quality discus granules. Wild fish can be shy feeders at first, so be patient.\n\nKeep the pair tank calm: no busy tank mates, steady lighting and a cover on the front glass if people walk past often. Wild fish that feel exposed tend to eat their eggs. Give a new pair several weeks to settle in before you expect a spawn, and keep water changes regular so the chemistry does not swing."}, {"heading": "Spawning", "text": "A pair about to spawn will clean the cone repeatedly, shake and bow to each other, and show their breeding tubes. The female's tube is broad and blunt, the male's thinner and more pointed. She lays lines of eggs and he follows to fertilize. Breeders commonly report about 100 to 300 eggs."}, {"heading": "Eggs and wrigglers", "text": "At 84 to 86°F eggs hatch in roughly 2 to 3 days. The parents move the wrigglers, which hang on the cone for another 2 to 3 days. Eggs that turn white are infertile or fungused; a few are normal, but a whole clutch going white usually points to water that is too hard, or an inexperienced male.\n\nEgg eating is common with new pairs. Give them several chances before trying anything else. A mesh guard around the cone helps some pairs."}, {"heading": "Raising the fry", "text": "Discus fry feed on the slime coat on their parents' sides. This is the most important stage, and wild pairs sometimes fail at it at first.\n\n- Days 1 to 5 free swimming: fry graze the parents, no extra food needed\n- From about day 5: add newly hatched brine shrimp several times a day\n- Weeks 2 to 3: remove the parents gently once fry are eating well on their own\n- Throughout: small, frequent water changes, keeping the temperature steady"}, {"heading": "Growing out", "text": "Young discus need lots of food and lots of clean water. Feed five or more small meals a day of baby brine, then a beef heart mix and fine granules as they grow. Change water daily if you can. With good care they can reach around 1.5 to 2 inches in 2 to 3 months, but stunting is common if water quality slips."}, {"heading": "Common mistakes", "text": "- Using tap water that is too hard for wild fish eggs\n- Disturbing the pair during the first spawns\n- Pulling the parents too early, before fry eat brine well\n- Skipping water changes in the grow-out tank\n- Mixing wild and tank-bred strains when your goal is wild-type stock"}]$g$::jsonb, $g$[{"q": "Are wild discus harder to breed than tank-bred discus?", "a": "Yes. Wild fish usually need much softer, more acidic water for their eggs to develop, and pairs often take longer to settle and raise fry."}, {"q": "How long do discus eggs take to hatch?", "a": "Discus eggs usually hatch in about 2 to 3 days at 84 to 86°F, and the fry become free swimming about 2 to 3 days after that."}, {"q": "What do discus fry eat?", "a": "For the first days they eat the slime coat on their parents' bodies. From about five days free swimming you can add newly hatched brine shrimp."}, {"q": "Why do my discus eggs turn white?", "a": "White eggs are infertile or fungused. With wild discus, water that is too hard is a common cause, and new pairs often take a few tries to get it right."}]$g$::jsonb, $g$Show the pair beside their cone with the challenge code card for stage 1, and note the water you used in your log. A clear photo of fry grazing on a parent is a strong stage 3 record.$g$),
  ($g$african-butterfly-fish$g$, $g$01e66ef1-fa11-4fbe-87b9-7b16f5b0dfbd$g$::uuid, $g$african-butterfly-fish$g$, null, $g$How to Breed African Butterflyfish: Floating Eggs and Fry$g$, $g$African butterflyfish lay floating eggs and the tiny fry only take food at the surface. A rarely completed, expert-level breeding project.$g$, $g$African butterflyfish are surface-hunting oddballs, and their breeding is just as unusual: eggs float, and the fry will only take food from the surface. Spawns do happen in home tanks, but raising the fry is where most attempts fail. It is a Society class E fish for that reason, and anyone who gets young ones to grow out has done something few hobbyists manage.$g$, $g${"method": "Egg layer: buoyant eggs float at the surface; fertilization is thought to be internal", "sexing": "Male's anal fin has a curved edge with tube-like central rays; female's edge is straight", "group": "One male with one or two females in a calm, covered tank", "breeding_tank": "30 gallons or more, long and shallow, floating plants, tight lid", "conditioning": "Live and frozen insects, crickets, fruit flies and mosquito larvae for weeks", "trigger": "Breeders report softer, slightly acidic water around 77 to 82°F and rich feeding", "spawn": "Eggs are released over several days; numbers vary widely", "eggs": "Breeders commonly report hatching in about 2 to 3 days at 77 to 82°F", "fry": "Tiny fry stay at the surface and only take food that floats", "first_foods": "Very small floating live foods such as springtails; sinking foods are ignored", "grow_out": "Slow and poorly documented; several months to a recognizable juvenile", "parents": "Adults are predators and may eat eggs; skim eggs off into a separate container"}$g$::jsonb, $g$[{"heading": "The breeding tank", "text": "Butterflyfish live at the surface, so surface area matters more than depth. A 30 gallon or larger tank, long and shallow, works well. Cover part of the surface with floating plants, keep flow gentle and fit a tight lid, because these fish jump.\n\nThe site's care guide lists 73 to 86°F and pH 6 to 7.5. For breeding, breeders report better results at about 77 to 82°F with soft, slightly acidic water, around pH 6.5."}, {"heading": "Sexing and conditioning", "text": "Sexing is possible with a close look at the anal fin. In males the rear edge is curved and the central rays form a tube-like structure; in females the edge is straight. This difference is well described, but it can be hard to see on young fish.\n\nCondition with a varied insect diet: crickets, fruit flies, mosquito larvae and small floating foods, offered daily for several weeks. Butterflyfish rarely take food from the bottom, so offer it at the surface.\n\nA well-conditioned female looks fuller through the belly. Keep only one male per tank if you can, since males may squabble at the surface. Avoid fast or fin-nipping tank mates during breeding attempts; quiet, bottom-dwelling companions or a species-only tank work best."}, {"heading": "Spawning", "text": "Pairs embrace near the surface, and eggs are released over several days rather than all at once. Fertilization is thought to happen inside the female. The eggs float, which makes them easy to spot as small round beads among the plants. Numbers vary a lot between reports, so don't worry about matching a figure."}, {"heading": "Eggs", "text": "Collect floating eggs each day with a spoon or small cup and move them to a shallow container with water from the breeding tank, plus gentle aeration or a small airline nearby. Breeders commonly report hatching in about 2 to 3 days at 77 to 82°F. Remove any eggs that turn white or fuzzy to stop fungus spreading. Leaving eggs with the adults usually means losing many of them.\n\nKeep the egg container in dim light at the same temperature as the breeding tank, and change a little of its water daily with water from the main tank. Clean, matched water matters more than anything you add to it."}, {"heading": "Raising the fry", "text": "This is the hard part. Fry stay right at the surface and, like the adults, will not chase food that sinks. Breeders report the best results with tiny floating live foods.\n\n- First feeding: springtails and other very small floating live foods\n- As they grow: fruit flies, small floating insects and mosquito larvae at the surface\n- Keep the water shallow, a few inches, so food stays near them\n- Small, gentle water changes every few days at the same temperature\n\nNewly hatched brine shrimp sink and are often ignored, which is why many attempts fail at this stage."}, {"heading": "Growing out", "text": "Grow-out is slow and not well documented. Keep fry in shallow, covered containers, sort them by size because larger fry may eat smaller ones, and step up food size as they grow. Expect several months before they look like small adults."}, {"heading": "Common mistakes", "text": "- Offering sinking foods to fry that only eat at the surface\n- Leaving eggs with the adults\n- Deep containers where fry can't find food\n- No lid, so adults jump during spawning\n- Expecting a full clutch to survive; even a few grown fry is a success\n- Mixing fry of very different sizes, which invites cannibalism"}]$g$::jsonb, $g$[{"q": "Do African butterflyfish lay eggs?", "a": "Yes. They lay eggs that float at the surface, and fertilization is thought to happen inside the female before the eggs are released."}, {"q": "How do you sex African butterflyfish?", "a": "Look at the anal fin: males have a curved rear edge with tube-like central rays, while females have a straight edge."}, {"q": "What do African butterflyfish fry eat?", "a": "They only take food at the surface. Breeders report the best results with springtails and other tiny floating live foods."}, {"q": "Are African butterflyfish hard to breed?", "a": "Spawning happens in home tanks, but raising the fry is difficult and rarely completed, mostly because of their surface-only feeding."}]$g$::jsonb, $g$Open your log once your pair is set up and show them near the surface with the challenge code card. Photograph the floating eggs on the day you collect them so your stage 2 date is clear.$g$),
  ($g$freshwater-stingray$g$, $g$9903e57a-37fd-44a3-838d-331ab6aeed24$g$::uuid, $g$freshwater-stingray$g$, null, $g$How to Breed Motoro Stingrays: Pairs, Pregnancy and Pups$g$, $g$Motoro stingrays give birth to live pups after a few months of pregnancy. You need a huge tank, spotless water and a careful pairing. Expert level.$g$, $g$Motoro stingrays give birth to fully formed pups that eat almost straight away, so the challenge is not the babies but everything before them. You need a very large tank, pristine water and a male and female that tolerate each other through rough courtship. Few hobbyists have the space, which is why motoros are a Society class E species.$g$, $g${"method": "Livebearer: pups develop inside the mother and are born fully formed", "sexing": "Easy: males have two claspers beside the tail; females do not", "group": "One male with one or two females, all well fed and settled", "breeding_tank": "180 gallons or more, wide footprint, fine sand, strong filtration", "conditioning": "Varied meaty foods such as shrimp, mussel, earthworms and fish, daily", "trigger": "Mature, healthy adults in stable, clean water at 75 to 82°F", "spawn": "Litters commonly reported around 3 to 12 pups, more from larger females", "eggs": "Gestation commonly reported at around 3 months", "fry": "Pups are born ready to swim and usually start feeding within days", "first_foods": "Bloodworms, blackworms, chopped earthworms and small shrimp", "grow_out": "Pups grow quickly with frequent feeding; several months to a robust juvenile", "parents": "Adults rarely target pups, but a separate tank keeps pups fed and safe"}$g$::jsonb, $g$[{"heading": "Tank and water", "text": "Motoros reach around 18 inches across, and the site's guide calls for at least 180 gallons. Floor space matters more than height, so choose a wide, long tank with a fine sand bottom and no sharp decor. Keep the water at 75 to 82°F, pH 6 to 7.5, with very low nitrate. Stingrays are sensitive to poor water, so heavy filtration and large weekly water changes are normal.\n\nBefore you start, check your local rules. Some US states restrict freshwater stingrays."}, {"heading": "Safety first", "text": "Every motoro, including newborn pups, has a venomous barb on the tail. Use nets and containers to move rays, never bare hands, and keep your hands visible to them during maintenance. A sting is very painful and needs medical attention."}, {"heading": "Pairing and conditioning", "text": "Sexing is simple: males have two claspers on either side of the tail base, visible even in young rays. Females should be well grown and mature before breeding; a large, well-fed female handles courtship better.\n\nCondition both sexes with daily meals of varied meaty foods: shrimp, mussel, earthworms and chunks of white fish. Thin rays should not be bred.\n\nWatch the rays at feeding time. A healthy ray has a rounded back and a disc that lies flat on the sand. Rays that hide all day, skip meals or show curled disc edges are telling you something is wrong with the water or the tank, and need that fixed before any breeding attempt. Tank mates should be calm, mid-water fish that won't nip the rays or steal all their food."}, {"heading": "Mating and pregnancy", "text": "Courtship is rough. The male bites the edge of the female's disc to hold on, and some damage to her margins is normal. If she is badly hurt or harassed constantly, separate them for a while. One male with two females spreads the attention.\n\nGestation is commonly reported at around 3 months. A pregnant female becomes noticeably thicker across the back, and breeders report she may eat less near the end. Keep the water stable during this time.\n\nAvoid moving a heavily pregnant female, and don't make big changes to the tank layout or water. Some breeders add a divider or move the male once the female is well along, so she can rest without being chased. Have the pup tank cycled and running well before the birth date."}, {"heading": "The pups", "text": "Litters are commonly reported at about 3 to 12 pups, and larger females tend to have more. Pups are born rolled up and quickly flatten out and swim. They have a small yolk reserve and usually start eating within a few days.\n\n- First foods: bloodworms, blackworms and chopped earthworms\n- Feed small amounts two or three times a day\n- Keep pups in a separate tank or a large protected area\n- Test water often, since pups eat a lot and foul water fast"}, {"heading": "Growing out", "text": "Pups grow quickly when fed often and kept in clean water. Move them onto chopped shrimp, mussel and larger worms as they grow. A pup that stops eating or curls up the edges of its disc is a warning sign; check water quality first. Plan where the pups will go before they are born, since each will need a large tank as an adult."}, {"heading": "Common mistakes", "text": "- Breeding in a tank that is too small, leading to stress and injury\n- Letting nitrate creep up during pregnancy\n- Pairing a small or thin female\n- Handling rays by hand and getting stung\n- Having no plan for where the pups will live"}]$g$::jsonb, $g$[{"q": "How long are motoro stingrays pregnant?", "a": "Gestation is commonly reported at around 3 months, although it can vary with temperature and the individual female."}, {"q": "How many pups do motoro stingrays have?", "a": "Litters are commonly reported at about 3 to 12 pups, with larger females usually having more."}, {"q": "How do you tell a male stingray from a female?", "a": "Males have two claspers beside the base of the tail. Females have none, and this is visible even on young rays."}, {"q": "Do stingrays eat their babies?", "a": "Adults rarely target their pups, but pups can lose out at feeding time, so many breeders move them to their own tank."}]$g$::jsonb, $g$For stage 1, show the male's claspers and the female together with the challenge code card. Since there are no eggs, a dated photo of the newborn pups works as clear evidence of the birth.$g$),
  ($g$brunei-beauty$g$, $g$4bfdb0ce-294c-4656-88ef-77fc4e7f5aa7$g$::uuid, null, null, $g$Breeding Betta macrostoma: The Brunei Beauty Mouthbrooder$g$, $g$The Brunei beauty is a mouthbrooding wild betta that needs very soft, acidic water and a calm, compatible pair. Rarely bred and expert level.$g$, $g$Betta macrostoma is one of the most striking wild bettas, and one of the hardest to breed. The male carries the eggs in his mouth for weeks, pairs must get along, and the water has to be very soft and acidic. Captive spawns are rare, which is why it sits in Society class F, the top of the list.$g$, $g${"method": "Paternal mouthbrooder: the male carries the eggs and fry", "sexing": "Males show brighter orange-red color and bolder fin edges; females are duller", "group": "One compatible pair, ideally a pair that formed in a small group", "breeding_tank": "20 to 30 gallons, dim, leaf litter, caves, tight lid", "conditioning": "Live and frozen foods such as daphnia, mosquito larvae and bloodworms", "trigger": "Very soft, acidic water, quiet surroundings and a settled pair", "spawn": "Broods are usually modest, often a few dozen fry", "eggs": "Breeders report the male holds for roughly 2 to 3 weeks", "fry": "Fry are released fully formed and fairly large", "first_foods": "Newly hatched brine shrimp and microworms right away", "grow_out": "Slow; several months to reach a recognizable juvenile size", "parents": "Stressed males often swallow the brood; don't disturb a holding male"}$g$::jsonb, $g$[{"heading": "About this species", "text": "Betta macrostoma comes from a small area of northern Borneo and is protected in its home range. Only buy fish that are legally sourced, ideally captive bred by other hobbyists. This species is rarely bred in home aquariums, so the advice below reflects what breeders report rather than a well-worn method."}, {"heading": "The breeding tank", "text": "Use a 20 to 30 gallon tank with a tight lid, dim lighting, a layer of leaf litter, wood and a few caves. Breeders report success in cool to moderate temperatures, around 72 to 79°F, with very soft, acidic water, often pH 4.5 to 6 and almost no hardness. Tannins from leaves help. Use a gentle sponge filter and change water in small, matched amounts.\n\nPrepare your water in advance: reverse osmosis or rain-quality water, softened with leaf litter or peat, and stored at tank temperature. Sudden swings in pH or temperature are more harmful than water that is slightly off target. Keep the room quiet and the tank away from foot traffic, because nervous fish rarely spawn. Floating plants help soften the light and give the fish cover."}, {"heading": "Choosing a pair", "text": "Males are brighter, with orange-red bodies and bold fin edges. Females are duller and more patterned. The real challenge is compatibility; a forced pair may fight. Many breeders raise a small group and remove the extra fish once a pair forms.\n\nCondition with live and frozen foods: daphnia, mosquito larvae, bloodworms and brine shrimp. Avoid overfeeding, which fouls soft water fast.\n\nWatch for the female rounding out and both fish showing stronger color, especially in the evening. Pairs that hold their ground side by side near a cave, without chasing each other, are usually the ones ready to spawn."}, {"heading": "Spawning and holding", "text": "Spawning involves a long embrace. The female collects the eggs and spits them toward the male, who takes them into his mouth. Breeders report the male then holds for roughly 2 to 3 weeks, eating little or nothing.\n\nA holding male has a swollen throat. Leave the tank alone, cover the front if needed, and avoid water changes for the first days. Stress is the main reason males swallow or spit out a brood."}, {"heading": "Raising the fry", "text": "When the male releases them, the fry are fully formed and large enough to eat right away.\n\n- First weeks: newly hatched brine shrimp and microworms, two or three times a day\n- Small water changes of 10 to 20% every few days, matched carefully\n- Weeks 4 and on: frozen daphnia and crushed foods\n\nMost breeders move the father out, or the fry into a grow-out tank, soon after release."}, {"heading": "Growing out", "text": "Fry grow slowly and need clean, soft water. Keep feeding small meals often and sort by size if any start to bully. Expect several months before they show adult color.\n\nThis species grows into a fairly large betta, so give juveniles room as they grow and avoid overcrowding, which leads to fin damage and stunting. Keep the same soft, acidic water you used for spawning, and change it regularly in small amounts. Because so few are bred, share young fish with other serious keepers so the captive population stays healthy."}, {"heading": "Common mistakes", "text": "- Forcing two fish together that don't get along\n- Hard or alkaline water\n- Disturbing a holding male, causing him to swallow the brood\n- Buying fish of unclear origin; choose legal, captive-bred stock\n- Expecting quick results; many pairs take months to spawn, and first broods are often lost"}]$g$::jsonb, $g$[{"q": "Is Betta macrostoma a mouthbrooder?", "a": "Yes. The male carries the eggs and developing fry in his mouth until they are released fully formed."}, {"q": "How long does a Betta macrostoma male hold eggs?", "a": "Breeders report roughly 2 to 3 weeks. It varies with temperature and the individual male."}, {"q": "How do you sex Betta macrostoma?", "a": "Males show brighter orange-red color and bolder fin edges. Females are duller and more patterned."}, {"q": "Why is the Brunei beauty so hard to breed?", "a": "It needs very soft, acidic water, a compatible pair and a calm male that won't swallow the brood. Captive spawns are rare."}]$g$::jsonb, $g$Open your log once the pair is settled, with the challenge code card in your stage 1 photo. A clear photo of the male's swollen throat while holding works as stage 2 evidence.$g$),
  ($g$nerite-snail$g$, $g$2c0fa0c6-5db6-44b7-bc35-a2f21c9d66fb$g$::uuid, $g$nerite-snail$g$, null, $g$How to Breed Nerite Snails: Eggs, Larvae and Salt Water$g$, $g$Nerite snails lay eggs in freshwater, but the larvae need brackish to marine water to develop. Raising them is rare and very hard. Expert only.$g$, $g$Every nerite keeper has seen the little white egg capsules on the glass, and wondered why no baby snails ever appear. The answer is that nerite larvae need salt water to develop, drifting as plankton before they settle. Raising them in captivity is rarely achieved by hobbyists, which is why nerites sit at the top of the Society list in class F.$g$, $g${"method": "Egg layer: females lay capsules on hard surfaces; larvae need brackish to marine water", "sexing": "Separate sexes, but males and females can't be told apart by eye", "group": "A group of 5 or more to raise the chance of having both sexes", "breeding_tank": "Freshwater adult tank, plus a separate saltwater larval container", "conditioning": "Plenty of algae, blanched vegetables and calcium-rich food", "trigger": "Healthy, well-fed adults of both sexes; capsules appear readily in freshwater", "spawn": "Each capsule holds many tiny eggs; females lay capsules steadily", "eggs": "Hatch time varies and is poorly documented; larvae released are tiny swimming veligers", "fry": "Microscopic swimming larvae that drift as plankton before settling as snails", "first_foods": "Live microalgae (phytoplankton) in salt water, as reported by successful breeders", "grow_out": "Settled baby snails are tiny and grow slowly over months on algae films", "parents": "No parental care; adults ignore the capsules"}$g$::jsonb, $g$[{"heading": "Why nerite eggs don't hatch into snails", "text": "Neritina natalensis lives in rivers and estuaries in Africa. Adults live in fresh or slightly brackish water, but their larvae are swept downstream and develop in brackish or sea water before young snails travel back up. In a freshwater aquarium the capsules may hatch, but the larvae can't develop, so you never see baby snails.\n\nThis also means nerites won't overrun a tank, which is part of their appeal. Captive raising is rarely reported, and published hobby methods are thin. Treat this guide as an outline of what is known."}, {"heading": "Keeping the adults", "text": "The site's care guide lists 72 to 80°F, pH 7 to 8.5 and moderate to hard water. Hard, alkaline water keeps their shells strong. Feed algae wafers, blanched zucchini and spinach, and leave some algae growing on the glass and rocks.\n\nNerites have separate sexes, but there is no reliable way to tell them apart by eye. Keep a group of five or more to improve the odds of having both. Capsules can appear even from a single snail kept alone, so capsules alone don't prove you have both sexes.\n\nWell-fed adults lay more capsules, so keep algae and vegetables on the menu and supplement calcium if your water is soft. Healthy nerites are active, keep their trapdoor (operculum) closed tightly when disturbed and have smooth, unpitted shells. Pitting or white erosion on the shell usually means the water is too soft or acidic."}, {"heading": "The egg capsules", "text": "Females lay small, white, sesame-seed capsules on hard surfaces: glass, wood, rocks and even other snails. Each capsule holds many tiny eggs. Breeders who have raised nerites usually move capsule-covered rocks or wood into salt water rather than scraping the capsules off, because scraped capsules are easily damaged.\n\nHatch time varies with temperature and is not well documented for this species, so check the larval container daily.\n\nSet up the larval container before you move any capsules: a small tank or jar with an air line, a heater, a light and pre-mixed salt water at the starting salinity. Have a phytoplankton culture running too, since there is no time to start one once larvae appear."}, {"heading": "The larval stage", "text": "Larvae hatch as microscopic swimming veligers. Successful breeders report raising salinity from brackish toward full sea water, and feeding live phytoplankton so the larvae always have food. They need gentle aeration to stay in suspension and stable temperature.\n\n- Keep the larval container in light, with no filter that could catch larvae\n- Add live microalgae daily to keep the water lightly green\n- Do small, careful water changes with matched salinity\n- Watch with a magnifying glass for settled snails on the walls\n\nThe larval stage can last several weeks or longer. Losses are high."}, {"heading": "Raising the baby snails", "text": "Once larvae settle, they become tiny crawling snails grazing on algae films. Breeders report slowly lowering salinity over weeks before moving them back toward fresh water. Give them glass or rocks coated with soft algae, and never let the water quality swing. Growth is slow, and it takes months before they look like small adults.\n\nKeep a dated record as you go: salinity, temperature and what you fed. With so few reports out there, your notes are valuable to other members."}, {"heading": "Common mistakes", "text": "- Expecting capsules in freshwater to produce snails\n- Scraping capsules off glass and damaging them\n- Using a filter in the larval container\n- Changing salinity too fast in either direction\n- Not having live phytoplankton ready before the larvae hatch"}]$g$::jsonb, $g$[{"q": "Why do nerite snail eggs never hatch?", "a": "Nerite larvae need brackish to marine water to develop. In freshwater the larvae can't survive, so no baby snails appear."}, {"q": "Can nerite snails breed in freshwater?", "a": "Females will lay egg capsules in freshwater, but the young can't develop there. They need salt water for the larval stage."}, {"q": "How do you tell male and female nerite snails apart?", "a": "You can't reliably tell them apart by looking. Nerites have separate sexes, so keep a group to improve the odds of having both."}, {"q": "Will nerite snails overrun my tank?", "a": "No. Because their larvae need salt water, nerites don't multiply in a freshwater aquarium, although the egg capsules can be unsightly."}]$g$::jsonb, $g$Show your adult group and capsule-covered rock with the challenge code card for stage 1, and photograph the capsules for stage 2. For stage 3, a clear magnified photo or video of swimming larvae or newly settled snails is the best evidence.$g$),
  ($g$peppermint-shrimp$g$, $g$0bfd9c1a-6861-4473-bdab-b6db9e0479db$g$::uuid, null, null, $g$Breeding Peppermint Shrimp: Hermaphrodite Pairs and Larvae$g$, $g$Peppermint shrimp breed readily in reef tanks, but raising the larvae takes weeks of careful saltwater feeding. A difficult, expert-level project.$g$, $g$Peppermint shrimp carry eggs often in home reef tanks, and the larvae hatch at night as a cloud of tiny swimmers. Raising them is the hard part: the larval stage lasts weeks and needs a dedicated tank and live foods. It sits in Society class F because so few hobbyists get the larvae through to settled shrimp.$g$, $g${"method": "Egg carrier: protandric simultaneous hermaphrodite, eggs carried under the tail", "sexing": "Not by sex: young shrimp act as males, older ones can both carry eggs and fertilize", "group": "Two or more adults; any two mature shrimp can usually breed", "breeding_tank": "Saltwater reef or species tank, plus a dark-sided larval tank", "conditioning": "Varied marine foods such as mysis, pellets and flake, daily", "trigger": "Mating happens right after the egg-carrying shrimp molts", "spawn": "Commonly hundreds of eggs per batch", "eggs": "Carried roughly 10 to 14 days at reef temperatures, hatching at night", "fry": "Tiny swimming larvae that are drawn to light and live in open water for weeks", "first_foods": "Enriched rotifers, then newly hatched brine shrimp as larvae grow", "grow_out": "Larval stage commonly lasts several weeks to a couple of months", "parents": "Adults and tank mates eat larvae; collect them on hatch night"}$g$::jsonb, $g$[{"heading": "Which shrimp you have", "text": "Several similar Lysmata species are sold as peppermint shrimp, and they are hard to tell apart. This guide covers Lysmata wurdemanni, but the breeding method is similar across the group. Peppermint shrimp are marine animals; they are on the Society list even though most of the site is freshwater.\n\nKeep them in stable salt water: specific gravity around 1.023 to 1.026, 76 to 80°F and good water quality. Avoid copper medications, which kill invertebrates."}, {"heading": "How they reproduce", "text": "Peppermint shrimp are protandric simultaneous hermaphrodites. Young shrimp function as males. As they grow, they become hermaphrodites that can carry eggs and still fertilize others. In practice, any two adults will usually breed, and you don't need to sex them.\n\nAn egg-carrying shrimp molts, then mates within hours, and the new eggs appear under its tail. Condition with daily feedings of mysis, quality pellets and flake.\n\nA group of three or four adults gives you more egg-carrying shrimp and more batches to work with. Watch for molts: a fresh, empty shell on the rock work is often followed within a day by new green eggs under the tail of the shrimp that shed it."}, {"heading": "Eggs and hatching", "text": "The eggs are carried under the tail and turn from green toward silver as they develop. They are commonly carried roughly 10 to 14 days at reef temperatures. Hatching usually happens at night, shortly before the shrimp molts again.\n\nWhen the eggs are silvery with visible eyes, you can move the shrimp to a hatching container for the night, or collect larvae from the main tank using a flashlight. Larvae are drawn to light, so a light at one end of the tank pulls them to where you can siphon them gently."}, {"heading": "The larval tank", "text": "Use a 10 to 20 gallon tank or a round container with dark sides, gentle aeration and no filter. Larvae need constant access to food and clean water without being battered.\n\n- Weeks 1 to 2: enriched rotifers kept at high density, plus green water\n- Weeks 2 and on: add newly hatched brine shrimp, then enriched brine as they grow\n- Daily: siphon the bottom gently and replace a small part of the water\n- Keep temperature stable at 76 to 80°F"}, {"heading": "Settlement", "text": "The larval stage commonly lasts several weeks to a couple of months, and larvae molt many times. As they near settlement they look more and more like tiny shrimp and start sitting on the bottom and walls. At that point, add some live rock rubble or a few surfaces for them to cling to, and switch to small frozen foods and crushed pellets.\n\nLosses are normal. Breeders often see most of a batch die off at certain molts, and the surviving few are the reward."}, {"heading": "Growing out", "text": "Once settled, juveniles grow quickly on mysis, pellets and enriched brine. They molt often, and each shed skin is a good sign. Keep them away from fish until they are big enough not to be eaten, and keep water quality high. Many reefers value captive-bred peppermint shrimp for eating nuisance anemones."}, {"heading": "Common mistakes", "text": "- Leaving larvae in the main tank, where filters and fish eat them\n- Feeding too little, so larvae starve between meals\n- Using unenriched brine shrimp for the whole larval stage\n- Strong aeration that damages the larvae\n- Copper medications anywhere near the shrimp\n- Moving the berried shrimp too early, which can stress it into dropping eggs\n- Giving up after one failed batch; most breeders lose several before one settles"}]$g$::jsonb, $g$[{"q": "Are peppermint shrimp hermaphrodites?", "a": "Yes. They start as males and later become hermaphrodites that can carry eggs and fertilize others, so any two adults can usually breed."}, {"q": "How long do peppermint shrimp carry eggs?", "a": "Eggs are commonly carried for roughly 10 to 14 days at reef temperatures, hatching at night."}, {"q": "What do peppermint shrimp larvae eat?", "a": "Larvae need tiny live foods. Breeders start with enriched rotifers and add newly hatched brine shrimp as the larvae grow."}, {"q": "How long until peppermint shrimp larvae settle?", "a": "The larval stage commonly lasts several weeks to a couple of months, depending on food, temperature and conditions."}]$g$::jsonb, $g$Open your log with your adults and the challenge code card in view for stage 1, and photograph a shrimp carrying eggs for stage 2. Dated photos of larvae in the larval tank make a clear stage 3 record.$g$),
  ($g$clown-loach$g$, $g$193b4fa8-3d09-45e3-bb78-1cce3d756408$g$::uuid, $g$clown-loach$g$, null, $g$Can You Breed Clown Loaches? What Is Known About Spawning$g$, $g$Clown loaches are almost never bred in home tanks. Here is what is known, what has worked for the rare successes and why it earns top points.$g$, $g$Clown loaches are among the most popular aquarium fish, yet almost all of them are wild caught or commercially farmed. Spawning in a home aquarium is extremely rare, and only a handful of hobbyist successes have been reported. This guide is honest about what is known. If you manage it, you will have one of the hardest entries on the Society list.$g$, $g${"method": "Egg scatterer; home spawns are extremely rare and poorly documented", "sexing": "Unreliable; some keepers say males have more curved tail tips, but this is debated", "group": "A large, mature group of 5 or more, ideally many more", "breeding_tank": "125 gallons or more, strong flow, fine gravel, plants and wood", "conditioning": "Varied foods such as snails, worms, shrimp and quality sinking pellets", "trigger": "Thought to relate to seasonal rains; breeders try large cool water changes", "spawn": "Not well documented for home aquaria", "eggs": "Not well documented; remove eggs from adults if you see any", "fry": "Very little hobby information exists", "first_foods": "Breeders would start with infusoria or rotifers, then newly hatched brine", "grow_out": "Slow growing; clown loaches take years to reach full size", "parents": "No parental care; adults are likely to eat eggs"}$g$::jsonb, $g$[{"heading": "The honest picture", "text": "Clown loaches come from rivers in Sumatra and Borneo, where they are thought to spawn during the rainy season. The fish sold in shops are wild caught or produced on farms that use hormone injections. Hormone use is not something we suggest; this guide is about natural spawning only.\n\nNatural spawns in home aquariums have been reported, but only a handful, and details are thin. That is why clown loaches are a class F species."}, {"heading": "What you need", "text": "Clown loaches grow to 12 inches and live a long time. The site's care guide calls for at least 125 gallons and a group of five or more, and breeding attempts need mature adults, which can mean fish several years old.\n\n- A large tank with strong, oxygen-rich flow\n- Fine gravel or sand, wood and plenty of hiding places\n- Temperature 75 to 85°F, pH 6 to 7.5\n- Excellent water quality with large regular water changes"}, {"heading": "Sexing and conditioning", "text": "Sexing clown loaches is difficult. Some keepers report that males have more inward-curving tail tips and that ripe females are plumper, but these signs are debated and unreliable. A large group is the best way to make sure you have both sexes.\n\nCondition with a varied diet: snails, bloodworms, blackworms, shrimp and quality sinking pellets, several times a week.\n\nKeep the group as stable as you can. Clown loaches are social and do best in larger numbers, with plenty of caves and wood to squeeze into. Healthy fish are active during the day, click when feeding and show bright orange and black color. Thin or pale fish should be brought back to full condition first."}, {"heading": "Spawning attempts", "text": "Since spawning is thought to follow seasonal rains, some keepers simulate a rainy season. This usually means a period of stable warm conditions followed by large, slightly cooler water changes, higher flow and heavier feeding. There's no proven recipe. Watch for unusual chasing, fish swimming together near plants or the substrate, and plumper females.\n\nReported home spawns have often been in very large tanks with mature groups, sometimes after years with no sign of breeding. Some spawns have been noticed only when fry appeared. Fine-leaved plants or spawning mops near the bottom give scattered eggs somewhere to land, and a heavily planted area may let a few fry survive unnoticed."}, {"heading": "If you find eggs", "text": "Clown loaches are egg scatterers with no parental care. If you see eggs, remove them or the adults as soon as you can, because adults are likely to eat them. Move eggs to a bare container with water from the main tank and gentle aeration, and remove any that turn white or fuzzy. Hatch time and egg counts for home spawns are not well documented, so keep notes."}, {"heading": "Raising the fry", "text": "With so few reports, fry care is based on general practice for small egg-scattering fish.\n\n- First days: infusoria or rotifers once the fry start to swim\n- After a few days: newly hatched brine shrimp and microworms\n- Small, frequent water changes with matched temperature\n- Fine sponge filtration so fry are not sucked up\n\nAny breeder who raises clown loaches should record everything, from water to foods to dates."}, {"heading": "Common mistakes", "text": "- Trying with a few young fish in a small tank\n- Using hormones, which we don't recommend\n- Leaving eggs with the adults\n- Expecting quick results; this can take years\n- Small, infrequent water changes, which leave the water stale for big, messy fish\n- Overlooking fry in a planted tank; check carefully with a flashlight"}]$g$::jsonb, $g$[{"q": "Can clown loaches breed in an aquarium?", "a": "It is extremely rare. Only a handful of home spawns have been reported, and most clown loaches sold are wild caught or farmed."}, {"q": "How do you tell male and female clown loaches apart?", "a": "There's no reliable way. Some keepers say males have more curved tail tips and females are plumper, but this is debated."}, {"q": "Why are clown loaches so hard to breed?", "a": "They grow large, mature slowly and are thought to spawn with seasonal rains in the wild, which is hard to copy in a home tank."}, {"q": "Are clown loaches farmed?", "a": "Yes. Farms in Southeast Asia produce clown loaches using hormone injections, which isn't a method we suggest for hobbyists."}]$g$::jsonb, $g$Open your log early with the group and challenge code card in view, since spawns are unpredictable. If you do get eggs, photograph them right away with a date so your stage 2 is clear.$g$),
  ($g$flame-angelfish$g$, $g$4eec3899-c070-49c9-aac6-59c0ee0ebcc4$g$::uuid, null, null, $g$Breeding Flame Angelfish: Pelagic Eggs and Copepod Larvae$g$, $g$Flame angelfish spawn in open water at dusk and their tiny larvae need copepod nauplii for weeks. Raised by few hatcheries. Expert only.$g$, $g$Flame angelfish spawn readily in some reef tanks, rising up together at dusk to release floating eggs. Raising the larvae is the real challenge: they are tiny, need copepod nauplii and take weeks to settle. Captive-bred flame angels come from specialist hatcheries, and very few hobbyists have raised them, which is why they sit in Society class F.$g$, $g${"method": "Pelagic spawner: pair rises at dusk and releases floating eggs", "sexing": "Hard; males are usually larger, and females can change into males", "group": "One male with one or more females, or a bonded pair", "breeding_tank": "Mature saltwater tank of 70 gallons or more, plus an egg collector", "conditioning": "Varied marine foods, algae and frozen mysis several times a day", "trigger": "Mature, well-fed fish with a regular day and night cycle", "spawn": "Daily spawns of small floating eggs are commonly reported", "eggs": "Tiny floating eggs hatch in less than a day", "fry": "Extremely small larvae that live in open water for weeks", "first_foods": "Copepod nauplii, such as cultured Parvocalanus, are commonly used", "grow_out": "Larvae take weeks to settle; months to sellable size", "parents": "No parental care; eggs float and are lost to filters and fish"}$g$::jsonb, $g$[{"heading": "A saltwater challenge", "text": "Flame angelfish are marine fish from the Pacific. They are on the Society list even though most of the site is freshwater, and breeding them is a project for experienced reefers. You need a mature reef or fish-only tank with stable salt water: specific gravity around 1.023 to 1.026, 76 to 80°F and high water quality. Captive raising is rare outside specialist hatcheries.\n\nBefore you start, think about space. You will need the display tank for the adults, a larval tank or two, and several live food cultures running at once: phytoplankton, copepods and rotifers, plus brine shrimp later on. Most breeders plan for weeks of daily work before they see a single settled fish."}, {"heading": "Forming a pair or harem", "text": "Flame angels are protogynous hermaphrodites: they start as females, and the dominant fish in a group can become a male. Males are usually larger. Sexing by color is unreliable.\n\nThe common approach is to add two fish of clearly different sizes at the same time, or a small harem of one male and a couple of smaller females in a large tank. Fighting can be serious, so watch closely and have a backup plan.\n\nCondition with several feedings a day of mysis, marine pellets, algae and enriched brine."}, {"heading": "What spawning looks like", "text": "Around dusk, the male courts the female, and the pair rises off the rock work together, releasing eggs and sperm in open water. Spawns are commonly reported nearly every evening in a well-conditioned pair. The eggs are small and float.\n\nTo collect them, many breeders use an egg collector on the overflow or a fine mesh in the return. Collect the eggs soon after spawning."}, {"heading": "Eggs and hatching", "text": "The floating eggs hatch in less than a day. Move them into the larval tank right away. Discard eggs that sink, which are usually unfertilized. The newly hatched larvae are extremely small, too small for most rotifers.\n\nCount or estimate the eggs each time you collect them and keep notes on water temperature and how many hatch. Patterns in these notes help you spot problems, such as poor fertility in a young pair. Stock the larval tank at a modest density; too many larvae in one tank can crash water quality and food supply quickly."}, {"heading": "Raising the larvae", "text": "This is where most attempts fail. Larvae need tiny live copepod nauplii from the start, so you need to culture copepods such as Parvocalanus for weeks before the first spawn.\n\n- First days: high densities of copepod nauplii and green water\n- Later: larger copepod stages and small rotifers\n- After several weeks: newly hatched brine shrimp as larvae grow\n- Gentle aeration, stable temperature, no filter\n\nThe larval stage lasts weeks before settlement. Survival rates are low."}, {"heading": "Settlement and growing out", "text": "When larvae settle, they take on juvenile color and start hiding near rock. Feed them several times a day with small frozen foods and crushed pellets, and keep them in clean, stable water. It takes months for them to reach a size most reefers would buy."}, {"heading": "Common mistakes", "text": "- Starting without established copepod cultures\n- Using rotifers alone as a first food\n- Letting eggs go down the overflow\n- Adding two fish of the same size, which can fight to the death\n- Expecting success on the first try\n- Moving eggs into a larval tank with different temperature or salinity\n- Overstocking the larval tank, so food and water quality crash"}]$g$::jsonb, $g$[{"q": "Can flame angelfish be bred in captivity?", "a": "Yes, but it is rare. Captive-bred flame angels come from specialist hatcheries, and very few hobbyists have raised them."}, {"q": "How do flame angelfish spawn?", "a": "The pair rises together at dusk and releases eggs and sperm in open water. The floating eggs hatch in less than a day."}, {"q": "What do flame angelfish larvae eat?", "a": "They need copepod nauplii, such as cultured Parvocalanus, because they are too small for most rotifers when they first hatch."}, {"q": "How do you tell male and female flame angels apart?", "a": "It's hard. Males are usually larger, and a female can change into a male if she becomes dominant."}]$g$::jsonb, $g$Show the pair or harem with the challenge code card for stage 1, and photograph floating eggs in your collector for stage 2. Dated photos of larvae in the larval tank work for stage 3.$g$),
  ($g$lined-seahorse$g$, $g$43718ac6-addb-4d83-a382-9bfadc4c2cc2$g$::uuid, null, null, $g$How to Breed Lined Seahorses: Male Pregnancy and Fry$g$, $g$Male lined seahorses carry the young in a pouch and give birth to hundreds of tiny fry. Raising them needs live foods and careful water. Expert.$g$, $g$Lined seahorses breed surprisingly readily in a well-run seahorse tank, and watching a male give birth is unforgettable. The hard part is the fry: hundreds of tiny, open-water babies that need live food and clean water from day one. It is a demanding project on the Society list in class F.$g$, $g${"method": "Male pregnancy: the female transfers eggs into the male's brood pouch", "sexing": "Easy in adults: males have a brood pouch below the belly; females don't", "group": "One pair, or a small group with equal numbers", "breeding_tank": "Tall saltwater tank of 30 gallons or more, hitching posts, gentle flow", "conditioning": "Enriched frozen mysis two or three times a day", "trigger": "A settled, well-fed pair performs a morning courtship dance", "spawn": "Broods commonly number in the hundreds, larger males having more", "eggs": "Gestation commonly reported at about 2 to 4 weeks, shorter in warmer water", "fry": "Born free swimming, tiny and pelagic; they stay up in the water for a time", "first_foods": "Enriched newly hatched brine shrimp, with rotifers or copepods to help", "grow_out": "Several months to reach a small juvenile size", "parents": "Parents don't care for the young; separate fry from the adults right away"}$g$::jsonb, $g$[{"heading": "The seahorse tank", "text": "Lined seahorses are marine fish from the western Atlantic. They are on the Society list even though most of the site is freshwater. Keep them in a tall saltwater tank of 30 gallons or more, with specific gravity around 1.023 to 1.026 and temperature around 72 to 78°F. Provide hitching posts such as macroalgae, artificial plants or rope, with gentle flow and very clean water.\n\nCaptive-bred lined seahorses are widely available and adapt to frozen food far better than wild fish."}, {"heading": "Pairs and conditioning", "text": "Sexing adults is easy. Males have a smooth brood pouch on the lower belly. Females have no pouch and a more pointed area near the vent.\n\nCondition with enriched frozen mysis two or three times a day. A well-fed pair usually starts courting within weeks to months.\n\nKeep tank mates few and slow. Seahorses are slow eaters and lose out to fast fish, and stressed seahorses rarely breed. Choose healthy animals with good body weight, upright posture and steady feeding, and watch for any signs of illness such as white patches or labored breathing. A quarantined, settled pair is the best start."}, {"heading": "Courtship and pregnancy", "text": "Courtship is often in the morning. The pair brightens, link tails and dance around the tank. When ready, they rise up together and the female transfers her eggs into the male's pouch. The male fertilizes them and the pouch swells.\n\nGestation is commonly reported at about 2 to 4 weeks, shorter in warmer water. The male's pouch grows steadily, and you may see the shapes of the young inside near the end."}, {"heading": "Birth", "text": "Birth often happens overnight or early in the morning. The male pumps out fry in bursts. Broods commonly number in the hundreds. Parents don't care for the young, and the fry can be eaten or sucked into filters, so move them to a nursery tank right away or set one up in advance and move the male before birth.\n\nA good approach is to move the male to a birthing tank a few days before his due date, using a cup rather than a net. Have the nursery water ready, matched to the main tank, and have brine shrimp hatching and enriching so the first feed is waiting."}, {"heading": "Raising the fry", "text": "Newborns are tiny and stay up in the water column for a time before hitching. Many breeders use a kreisel or a round tank with gentle circular flow to keep them from getting stuck at the surface.\n\n- First days: enriched newly hatched brine shrimp, with rotifers or copepods to help the smallest\n- Feed several times a day so food is always present\n- Daily: siphon uneaten food and change a small part of the water\n- Weeks 2 and on: larger enriched brine and then tiny mysis\n\nSurface air bubbles can kill fry, so keep the surface clean and avoid fine bubbles."}, {"heading": "Growing out", "text": "As the young grow, they begin hitching and hunting more steadily. Move them gradually onto frozen mysis, starting with chopped pieces. It takes several months before they reach a small juvenile size, and growth depends on feeding."}, {"heading": "Common mistakes", "text": "- Leaving fry with the parents or near filters\n- Feeding unenriched brine shrimp\n- Fine bubbles in the nursery\n- Overcrowding the fry tank\n- Letting water quality slip from overfeeding\n- Netting a pregnant male, which can cause a premature birth; use a cup\n- Running out of hatched brine shrimp in the first busy weeks"}]$g$::jsonb, $g$[{"q": "Do male seahorses get pregnant?", "a": "Yes. The female puts her eggs into the male's brood pouch, where he fertilizes and carries them until birth."}, {"q": "How long are seahorses pregnant?", "a": "Gestation in lined seahorses is commonly reported at about 2 to 4 weeks, shorter in warmer water."}, {"q": "How many babies do seahorses have?", "a": "Lined seahorse broods commonly number in the hundreds, and larger males can have more."}, {"q": "What do baby seahorses eat?", "a": "Breeders feed enriched newly hatched brine shrimp, often with rotifers or copepods for the smallest fry."}]$g$::jsonb, $g$Show the male and female together with the challenge code card for stage 1. A clear photo of the pregnant male's swollen pouch works as stage 2 evidence, and dated photos of fry in the nursery work for stage 3.$g$),
  ($g$mandarin-dragonet$g$, $g$44da2c70-7a95-443c-8892-bae1e4cebb54$g$::uuid, null, null, $g$How to Breed Mandarin Dragonets: Dusk Spawns and Larvae$g$, $g$Mandarin dragonets spawn at dusk, releasing tiny floating eggs. The larvae need very small live foods. A rare, expert-level saltwater project.$g$, $g$Mandarin dragonets are a reef favorite, and a pair rising at dusk to spawn is one of the most beautiful things in the hobby. Collecting the eggs is the easy part. Raising the tiny larvae needs very small live foods and steady care, and few hobbyists succeed. That is why they sit in Society class F.$g$, $g${"method": "Pelagic spawner: pair rises at dusk and releases floating eggs", "sexing": "Males are larger with a tall, extended first dorsal spine", "group": "One male and one female; males fight", "breeding_tank": "Mature reef tank with copepods, plus an egg collector", "conditioning": "Live copepods plus any frozen foods they accept", "trigger": "Mature, well-fed pair with a regular day and night cycle", "spawn": "Spawns are commonly reported often, with a few hundred eggs or fewer", "eggs": "Floating eggs hatch in less than a day", "fry": "Tiny larvae that live in open water before settling", "first_foods": "Rotifers and copepod nauplii", "grow_out": "Larvae settle in weeks; months to reach juvenile size", "parents": "No parental care; collect eggs before they reach the filter"}$g$::jsonb, $g$[{"heading": "The reef tank", "text": "Mandarins are marine fish from the Pacific. They are on the Society list even though most of the site is freshwater. Keep them in a mature reef tank with stable salt water: specific gravity around 1.023 to 1.026, 74 to 80°F and a healthy population of copepods. Many keepers add a refugium to keep copepods flowing.\n\nYou will also need a separate larval tank of 10 to 20 gallons with dark sides, a heater and gentle aeration, plus cultures of phytoplankton, rotifers and copepods. Set these up weeks before you expect a spawn. Mandarins are slow, careful feeders, so avoid fast, aggressive tank mates that would compete for copepods."}, {"heading": "Pairs and conditioning", "text": "Males are larger, with a tall, extended first dorsal spine. Females are smaller with a shorter dorsal. Two males will fight, so keep a single pair.\n\nCondition with a strong supply of live copepods, plus frozen foods such as small mysis and enriched brine if they accept them. A well-fed female looks plump.\n\nThin mandarins are a common problem, because many wild fish only eat live copepods. Check your pair's belly every week. If they look pinched, boost the copepod supply before trying to breed. Captive-bred fish are often easier to keep plump."}, {"heading": "Spawning", "text": "Around dusk, the male displays to the female with his fins raised. The pair rises together and releases eggs and sperm in open water. Spawns are commonly reported often in well-conditioned pairs, with a few hundred eggs or fewer.\n\nCollect eggs using an egg collector on the overflow or fine mesh in the return line. Check the collector soon after spawning.\n\nEgg collectors can be as simple as a fine mesh bag or a container with fine mesh sides placed where the overflow flows. Many breeders switch off skimmers and filter socks during the evening spawning window so eggs end up in the collector rather than the sump."}, {"heading": "Eggs", "text": "The floating eggs hatch in less than a day. Move them to the larval tank quickly, with gentle aeration. Discard eggs that sink, which are usually unfertilized. Keep the larval tank at the same temperature and salinity as the display, and keep it dimly lit so the larvae can see their food."}, {"heading": "Raising the larvae", "text": "Larvae are tiny and need small live foods from the first day.\n\n- First days: rotifers and copepod nauplii, kept at high density\n- Green water to keep foods healthy and help the larvae see\n- Gentle aeration and no filter\n- Small daily water changes with matched salinity\n\nSurvival is low, so culture rotifers and copepods well before your first spawn.\n\nAs larvae grow, add larger copepods and newly hatched brine shrimp. Watch for larvae with full, colored guts after feeding, which tells you they are eating. If guts look empty, the food is probably too large or too sparse."}, {"heading": "Settlement and grow-out", "text": "Larvae settle within weeks. Once settled, juveniles hunt on the bottom and accept small copepods, baby brine and frozen foods. Captive-bred mandarins often take frozen foods better than wild ones. Growth is slow, and it takes months to reach a juvenile size.\n\nKeep juveniles in a small grow-out tank with live rock or a sponge filter so copepods can breed alongside them. Feed several times a day and keep a close eye on body weight, the same way you do with the adults."}, {"heading": "Common mistakes", "text": "- Keeping two males together\n- No copepod population in the main tank\n- Letting eggs go down the overflow\n- Starting without live food cultures\n- Strong aeration that batters the larvae"}]$g$::jsonb, $g$[{"q": "How do you tell male and female mandarins apart?", "a": "Males are larger with a tall, extended first dorsal spine. Females are smaller with a short dorsal."}, {"q": "How do mandarin dragonets spawn?", "a": "At dusk the pair rises together and releases eggs and sperm in open water. The floating eggs hatch in less than a day."}, {"q": "What do mandarin larvae eat?", "a": "They need very small live foods such as rotifers and copepod nauplii from the first day."}, {"q": "Can mandarin dragonets be bred in captivity?", "a": "Yes, but raising the larvae is hard. A few hobbyists and hatcheries have succeeded."}]$g$::jsonb, $g$Show the pair with the challenge code card for stage 1, and photograph eggs from your collector for stage 2. Dated photos of larvae work for stage 3.$g$),
  ($g$neon-goby$g$, $g$9f536837-3e62-4782-9792-6fb96bc5fedf$g$::uuid, null, null, $g$How to Breed Neon Gobies: Pairs, Egg Caves and Larvae$g$, $g$Neon gobies pair up, lay eggs in a tube or cave and the male guards them. Larvae need rotifers for weeks. Among the more doable marine projects.$g$, $g$Neon gobies are small, cleaner fish that pair readily and lay eggs inside a tube or cave, where the male guards them until they hatch. Larvae need live rotifers and a few weeks of steady care before they settle. They are often counted among the more achievable marine fish to raise, but on the Society list they sit in class F because the larval stage still takes skill.$g$, $g${"method": "Cave spawner: eggs laid inside a tube or cave, guarded by the male", "sexing": "Hard; females look fuller when ripe, and the breeding tube shape differs", "group": "One bonded pair; buying a pair or two small juveniles works best", "breeding_tank": "Saltwater, 10 to 30 gallons, with a short tube or small cave", "conditioning": "Enriched brine, mysis and fine pellets two or three times a day", "trigger": "A settled, well-fed pair with a suitable tube to claim", "spawn": "Commonly reported in the low hundreds, varying with the pair's size", "eggs": "Hatch in roughly 7 to 10 days at reef temperatures, usually after dark", "fry": "Tiny larvae live in open water for several weeks", "first_foods": "Enriched rotifers, then newly hatched brine shrimp", "grow_out": "Larvae commonly settle in about 3 to 6 weeks; months to sell size", "parents": "Male guards and fans eggs; larvae must be collected on hatch night"}$g$::jsonb, $g$[{"heading": "The saltwater setup", "text": "Neon gobies are marine fish from the western Atlantic. They are on the Society list even though most of the site is freshwater. Keep stable salt water: specific gravity around 1.023 to 1.026, temperature 76 to 80°F and excellent water quality.\n\nA 10 to 30 gallon tank works for a pair. Provide a short PVC tube, a ceramic tube or a small cave that you can lift out. A removable spawning site makes it much easier to move the eggs or collect larvae. Keep tank mates few and peaceful."}, {"heading": "Getting a pair", "text": "Sexing neon gobies is hard by eye. Ripe females look fuller, and the breeding tubes differ when you can see them, but most breeders buy a known pair or raise two small fish together. Neon gobies are widely captive bred, so captive-bred stock is easy to find and usually settles fast.\n\nCondition with two or three feedings a day of enriched brine, mysis and fine marine pellets. A well-fed pair often starts spawning within weeks of settling.\n\nNeon gobies are short-lived compared with many reef fish, often only a couple of years, so it pays to start with young fish and begin breeding attempts soon after they settle. Keep the pair well fed and avoid fish that would bully them away from food."}, {"heading": "Spawning", "text": "The pair cleans the inside of the tube or cave, and the female lays eggs on the inside surface. The male fertilizes them and then guards, fanning and cleaning the clutch. Clutches are commonly reported in the low hundreds, and pairs may spawn again every week or two.\n\nYou may only see the male hanging at the cave entrance. Use a flashlight to check the inside without moving the tube."}, {"heading": "Eggs and hatch night", "text": "Eggs commonly hatch in roughly 7 to 10 days at reef temperatures, usually soon after the lights go out. As hatching nears, the eggs turn silver with visible eyes.\n\nOn hatch night, either move the tube into the larval tank with gentle aeration near the eggs, or collect larvae from the main tank using a flashlight, since larvae are drawn to light. Larvae lost to the filter or eaten by tank mates is the most common first mistake."}, {"heading": "Raising the larvae", "text": "Use a 10 to 20 gallon larval tank with dark sides, gentle aeration and no filter. Keep the same temperature and salinity as the parents.\n\n- First week: enriched rotifers at high density, plus green water\n- Second week: start newly hatched brine shrimp along with rotifers\n- Weeks 3 to 6: larvae settle, gain their stripes and start sitting on surfaces\n- Daily: siphon the bottom and replace a small amount of water\n\nRotifer cultures must be running before the first spawn."}, {"heading": "Growing out", "text": "Settled juveniles grow on enriched brine, frozen cyclops and crushed pellets, fed several times a day. They can be kept in a small grow-out tank with live rock rubble. It takes months to reach a size most reefers would buy. Captive-bred neon gobies are valued because they eat prepared foods well and are hardy."}, {"heading": "Common mistakes", "text": "- Using a fixed rock cave that can't be moved on hatch night\n- No rotifer culture ready\n- Strong aeration in the larval tank\n- Overfeeding brine too early, which fouls the water\n- Aggressive tank mates that eat eggs or larvae\n- Disturbing the male so he abandons or eats the clutch"}]$g$::jsonb, $g$[{"q": "Can neon gobies be bred at home?", "a": "Yes. Pairs spawn readily, and with rotifer cultures and a larval tank, home breeders do raise them. Larval care is the hard part."}, {"q": "How do neon gobies lay eggs?", "a": "The female lays eggs inside a tube or cave, and the male guards and fans them until they hatch."}, {"q": "How long do neon goby eggs take to hatch?", "a": "Eggs commonly hatch in roughly 7 to 10 days at reef temperatures, usually after dark."}, {"q": "What do neon goby larvae eat?", "a": "Enriched rotifers first, then newly hatched brine shrimp as the larvae grow."}]$g$::jsonb, $g$Show the pair near their tube with the challenge code card for stage 1, and photograph the eggs inside the tube with a flashlight for stage 2. Date your photos on hatch night so stage 3 timing is clear.$g$),
  ($g$orchid-dottyback$g$, $g$626b7a34-a51d-46b9-9588-2a0fe402619c$g$::uuid, null, null, $g$How to Breed Orchid Dottybacks: Egg Balls and Larvae$g$, $g$Orchid dottybacks lay a ball of eggs in a cave that the male guards. Larvae need rotifers and weeks of care. An expert-level marine project.$g$, $g$Orchid dottybacks are vivid purple marine fish, and pairs in a quiet tank will lay a ball of eggs in a cave for the male to guard. Pairing them without fights and raising the tiny larvae are the challenges. Captive-bred orchid dottybacks are widely sold, but hobbyists who raise them still earn a Society class F entry.$g$, $g${"method": "Cave spawner: eggs laid as a ball inside a cave, guarded by the male", "sexing": "Hard; males are usually larger and longer, females rounder when ripe", "group": "One pair, introduced carefully with a size difference", "breeding_tank": "Saltwater, 20 to 30 gallons, with a cave or tube the pair can use", "conditioning": "Mysis, enriched brine and marine pellets two or three times a day", "trigger": "A settled pair with a good cave and steady feeding", "spawn": "Commonly reported as a few hundred eggs in a ball", "eggs": "Hatch in roughly 4 to 6 days at reef temperatures, usually after dark", "fry": "Tiny larvae live in open water for weeks", "first_foods": "Enriched rotifers, then newly hatched brine shrimp", "grow_out": "Larvae commonly settle in several weeks; months to sell size", "parents": "Male guards eggs; larvae must be collected on hatch night"}$g$::jsonb, $g$[{"heading": "The saltwater setup", "text": "Orchid dottybacks come from the Red Sea. They are on the Society list even though most of the site is freshwater. Keep stable salt water: specific gravity around 1.023 to 1.026, temperature 76 to 80°F and excellent water quality.\n\nA 20 to 30 gallon tank works for a pair. Give them a cave or tube that you can reach or remove, plus enough rock work for the female to escape the male if he gets pushy. Keep other tank mates few and calm."}, {"heading": "Forming a pair", "text": "Sexing orchid dottybacks by eye is hard. Males are usually larger and longer, while ripe females look rounder. Dottybacks are known to be territorial and can fight hard, so pairing needs care.\n\nThe common approach is to add two fish of clearly different sizes, or to use a divider for a week or two so they can see each other before meeting. Captive-bred fish are easy to find and often settle better.\n\nWatch the first days closely. Some chasing is normal, but torn fins, a fish hiding constantly or refusing food mean you should separate them and try again later.\n\nCondition with two or three daily meals of mysis, enriched brine and marine pellets."}, {"heading": "Spawning", "text": "Before spawning, the male courts the female near the cave and the female becomes visibly plump. The female lays a ball of eggs inside the cave, commonly a few hundred, and the male guards it, often wrapping himself around it. Pairs may spawn again every week or two.\n\nThe male becomes very protective of the cave while guarding and may chase anything that comes close, including your hand during maintenance. Keep cleaning around the cave to a minimum until the eggs hatch, and keep feeding the pair normally so the female stays in condition for the next spawn."}, {"heading": "Eggs and hatch night", "text": "Eggs commonly hatch in roughly 4 to 6 days at reef temperatures, usually soon after dark. As hatching nears, the eggs turn silver with visible eyes.\n\nOn hatch night, collect larvae using a flashlight to draw them to one spot, then gently scoop or siphon them into the larval tank. Some breeders move the cave with the egg ball into the larval tank instead."}, {"heading": "Raising the larvae", "text": "Use a 10 to 20 gallon larval tank with dark sides, gentle aeration and no filter. Keep the same temperature and salinity as the parents.\n\n- First week: enriched rotifers at high density, plus green water\n- Second week: start newly hatched brine shrimp\n- Weeks 3 and on: enriched brine and larvae begin settling\n- Daily: siphon the bottom and replace a small amount of water\n\nThe larval stage commonly lasts several weeks. Have rotifer cultures running before the first spawn."}, {"heading": "Growing out", "text": "Settled juveniles develop their purple color as they grow. Feed several times a day with enriched brine, frozen foods and crushed pellets. Dottyback juveniles can become territorial, so give them plenty of rock rubble and space. It takes months to reach a size most reefers would buy."}, {"heading": "Common mistakes", "text": "- Adding two fish of the same size, which often leads to fights\n- No escape routes for the female\n- No rotifer culture ready\n- Strong aeration in the larval tank\n- Leaving larvae in the main tank on hatch night\n- Overcrowding juveniles so they fight\n- Netting the pair apart during the first spawns instead of giving them time\n- Running out of live brine shrimp just as the larvae need more food"}]$g$::jsonb, $g$[{"q": "Can orchid dottybacks be bred at home?", "a": "Yes. Pairs spawn readily, and with rotifer cultures and a larval tank, home breeders do raise them. Larval care is the hard part."}, {"q": "How do you tell male and female orchid dottybacks apart?", "a": "It's hard. Males are usually larger and longer, and ripe females look rounder."}, {"q": "How long do orchid dottyback eggs take to hatch?", "a": "Eggs commonly hatch in roughly 4 to 6 days at reef temperatures, usually after dark."}, {"q": "How do orchid dottybacks lay eggs?", "a": "The female lays a ball of eggs inside a cave, and the male guards it until the larvae hatch."}]$g$::jsonb, $g$Show the pair together with the challenge code card for stage 1, and photograph the egg ball in the cave for stage 2. Date your photos on hatch night so stage 3 timing is clear.$g$),
  ($g$pajama-cardinalfish$g$, $g$3f774993-b10b-439b-8772-727f9c2fc5f7$g$::uuid, null, null, $g$How to Breed Pajama Cardinalfish: Mouthbrooding Males$g$, $g$Pajama cardinal males carry the eggs in their mouths, and the larvae need tiny live foods for weeks. Rarely raised by hobbyists. Expert level.$g$, $g$Pajama cardinalfish are peaceful, easy-going reef fish, and pairs often spawn in home tanks with the male carrying the eggs in his mouth. Raising the larvae that he releases is the hard part, and only a few hobbyists have reported success. It is a Society class F species, so even one raised batch is something to be proud of.$g$, $g${"method": "Paternal mouthbrooder: the male carries the eggs in his mouth", "sexing": "Hard; a holding male shows a swollen throat, females look fuller when ripe", "group": "A small group of 4 to 6 so a pair can form", "breeding_tank": "Saltwater, 30 gallons or more, calm flow and branching cover", "conditioning": "Mysis, enriched brine and marine pellets two or three times a day", "trigger": "A settled pair splitting off from the group", "spawn": "Egg counts vary; breeders report broods in the hundreds", "eggs": "Breeders report the male holds for roughly 1 to 2 weeks", "fry": "Released larvae are tiny and live in open water", "first_foods": "Enriched rotifers and copepod nauplii, then newly hatched brine shrimp", "grow_out": "Weeks in the larval stage; months to sell size", "parents": "No care after release; adults eat larvae, so collect them quickly"}$g$::jsonb, $g$[{"heading": "The saltwater setup", "text": "Pajama cardinalfish come from the western Pacific. They are on the Society list even though most of the site is freshwater. Keep stable salt water: specific gravity around 1.023 to 1.026, temperature 76 to 80°F and excellent water quality.\n\nA 30 gallon or larger tank with calm flow and some branching cover, such as branching rock work or soft corals, suits them. Tank mates should be peaceful. Cardinalfish are slow, careful feeders and do poorly with boisterous fish. Keep the lighting moderate and give the group a sheltered area where they can hover together, as they do in the wild."}, {"heading": "Forming a pair", "text": "Sexing pajama cardinals by eye is hard. The best approach is to keep a small group of four to six and watch for two fish that start staying together and pushing others away. Once a pair forms, consider moving the others to reduce stress.\n\nCondition with two or three daily meals of mysis, enriched brine and marine pellets. A ripe female looks fuller in the belly."}, {"heading": "Spawning and holding", "text": "Courtship involves the pair staying close and displaying. The female releases a mass of eggs, which the male fertilizes and takes into his mouth. A holding male has a swollen throat and usually stops eating.\n\nBreeders report the male holds for roughly 1 to 2 weeks, depending on temperature. Keep the tank quiet during this time; stressed males may swallow or spit out the eggs."}, {"heading": "Release and collection", "text": "The male releases the larvae, usually after dark. Adults and tank mates readily eat them, so plan ahead. Many breeders move the holding male into a separate tank a few days before the expected release, then return him to the main tank after release. Others collect larvae from the main tank at night using a flashlight.\n\nIf you move the male, use a cup rather than a net, and match the water in the holding tank closely to the main tank. A small, bare tank with a heater and gentle aeration is enough. Keep it dimly lit and check it each evening and morning."}, {"heading": "Raising the larvae", "text": "Use a 10 to 20 gallon larval tank with dark sides, gentle aeration and no filter. Keep the same temperature and salinity as the parents.\n\n- First days: enriched rotifers and copepod nauplii, plus green water\n- After about a week: add newly hatched brine shrimp\n- Weeks 2 and on: enriched brine as larvae grow\n- Daily: siphon the bottom and replace a small amount of water\n\nVery few hobbyists have reported raising pajama cardinals, so record your methods."}, {"heading": "Growing out", "text": "Settled juveniles develop their spots and bars over time. Feed several times a day with enriched brine, frozen foods and crushed pellets. They do well in groups if there is enough space. Keep feeding small amounts often rather than one big meal, and keep the water clean, because juveniles are sensitive to poor water quality. It takes months for them to reach a size most reefers would buy."}, {"heading": "Common mistakes", "text": "- Disturbing a holding male\n- Leaving the male in the main tank on release night\n- No rotifer or copepod culture ready\n- Strong aeration in the larval tank\n- Boisterous tank mates that stress the pair\n- Netting the holding male, which often makes him spit the eggs\n- Expecting the larvae to eat brine shrimp from the first day\n- Giving up after one failed brood; most breeders lose several"}]$g$::jsonb, $g$[{"q": "Are pajama cardinalfish mouthbrooders?", "a": "Yes. The male carries the eggs in his mouth until he releases the larvae."}, {"q": "How long does a pajama cardinal hold eggs?", "a": "Breeders report roughly 1 to 2 weeks, depending on temperature."}, {"q": "How do you tell male and female pajama cardinals apart?", "a": "It's hard by eye. A holding male has a swollen throat, and ripe females look fuller."}, {"q": "Can you raise pajama cardinalfish larvae?", "a": "It has been done, but very few hobbyists report success. The larvae need tiny live foods for weeks."}]$g$::jsonb, $g$Show the pair with the challenge code card for stage 1. A clear photo of the male's swollen throat while holding works as stage 2 evidence.$g$),
  ($g$royal-gramma$g$, $g$de8d25ae-1daf-49cb-87fc-826eb08a3862$g$::uuid, null, null, $g$How to Breed Royal Grammas: Algae Nests and Larvae$g$, $g$Male royal grammas build a nest of algae in a cave for the eggs. Larvae need rotifers and weeks of care. An expert-level marine breeding project.$g$, $g$Royal grammas are bright purple and gold reef favorites, and a male will build a nest of algae in a cave for his female's eggs. Spawning can be frequent in a settled pair or group. Raising the larvae takes rotifer cultures and patience, which is why royal grammas sit in Society class F despite being captive bred commercially.$g$, $g${"method": "Nest builder: male builds an algae nest in a cave, eggs laid among the algae", "sexing": "Hard; males are usually larger with longer pelvic fins", "group": "One male with one or more females in a large enough tank", "breeding_tank": "Saltwater, 30 gallons or more, caves and loose macroalgae", "conditioning": "Mysis, enriched brine and marine pellets two or three times a day", "trigger": "A settled male with a cave and nest material", "spawn": "Clutch size varies; breeders report frequent spawns", "eggs": "Hatch in roughly 5 to 7 days at reef temperatures", "fry": "Tiny larvae live in open water for weeks", "first_foods": "Enriched rotifers, then newly hatched brine shrimp", "grow_out": "Larvae settle in several weeks; months to sell size", "parents": "Male guards nest; larvae must be collected on hatch night"}$g$::jsonb, $g$[{"heading": "The saltwater setup", "text": "Royal grammas come from the Caribbean. They are on the Society list even though most of the site is freshwater. Keep stable salt water: specific gravity around 1.023 to 1.026, temperature 76 to 80°F and excellent water quality.\n\nA 30 gallon or larger tank with caves and overhangs suits them. Provide loose bits of macroalgae for the male to use as nest material. Keep tank mates peaceful. Avoid larger, aggressive fish that would take over the caves, since a male without a cave won't build a nest."}, {"heading": "Pairs and groups", "text": "Sexing royal grammas is hard. Males are usually larger with longer pelvic fins, but this is not always clear. Royal grammas are territorial with each other, so a pair or a male with a couple of females works best in a larger tank.\n\nCondition with two or three daily meals of mysis, enriched brine and marine pellets."}, {"heading": "Nest building and spawning", "text": "The male collects bits of algae and packs them into a cave to form a nest. He then courts the female, who lays eggs among the algae. The male guards the nest. Clutch size varies, and breeders report spawns can be frequent once a pair is settled.\n\nThe male defends the cave and nest closely while there are eggs, and may dart out at tank mates or your hand. Leave the cave alone as much as you can, and avoid moving rock work. If you want to move eggs, pick a cave or tube that can be lifted out as one piece before the pair settles into it."}, {"heading": "Eggs and hatch night", "text": "Eggs commonly hatch in roughly 5 to 7 days at reef temperatures, usually after dark. On hatch night, collect larvae using a flashlight to draw them to one spot, then gently scoop or siphon them into the larval tank."}, {"heading": "Raising the larvae", "text": "Use a 10 to 20 gallon larval tank with dark sides, gentle aeration and no filter. Keep the same temperature and salinity as the parents.\n\n- First week: enriched rotifers at high density, plus green water\n- Second week: add newly hatched brine shrimp\n- Weeks 3 and on: enriched brine and larvae begin settling\n- Daily: siphon the bottom and replace a small amount of water\n\nPlan on several weeks of daily feeding before the larvae settle. Have rotifer cultures running before the first spawn, and keep larval density modest so water quality doesn't crash. Larvae drawn to the light are a good sign; larvae lying on the bottom or failing to feed usually mean water quality or food density is off. Survival is low in early attempts, so expect losses and keep notes on what you fed and when."}, {"heading": "Growing out", "text": "Settled juveniles develop their purple and gold color as they grow. Feed several times a day with enriched brine, frozen foods and crushed pellets. They can be territorial, so give them plenty of rock rubble and space. It takes months to reach a size most reefers would buy. Captive-bred royal grammas tend to accept prepared foods readily, which makes them popular with reefers."}, {"heading": "Common mistakes", "text": "- Not providing nest material\n- Keeping two males in a small tank\n- No rotifer culture ready\n- Strong aeration in the larval tank\n- Leaving larvae in the main tank on hatch night\n- Moving rock work during spawning, which can make the male abandon the nest\n- Feeding unenriched brine shrimp through the whole larval stage\n- Overfeeding the larval tank, which fouls the water fast"}]$g$::jsonb, $g$[{"q": "How do royal grammas breed?", "a": "The male builds a nest of algae in a cave, and the female lays eggs among it. The male guards the nest until the eggs hatch."}, {"q": "How do you tell male and female royal grammas apart?", "a": "It's hard. Males are usually larger with longer pelvic fins."}, {"q": "How long do royal gramma eggs take to hatch?", "a": "Eggs commonly hatch in roughly 5 to 7 days at reef temperatures."}, {"q": "Can you keep two royal grammas together?", "a": "A male and female often work, especially in a larger tank. Two males usually fight."}]$g$::jsonb, $g$Show the pair or group with the challenge code card for stage 1, and photograph the nest in the cave for stage 2. Date your photos on hatch night so stage 3 timing is clear.$g$),
  ($g$altum-angelfish$g$, $g$d22045e7-4067-486b-935e-bc3567fc272d$g$::uuid, $g$altum-angelfish$g$, null, $g$How to Breed Altum Angelfish: Very Soft Water and Pairs$g$, $g$Altum angelfish need very soft, acidic water and a tall tank to spawn, and pairs can take years to form. One of the hardest freshwater cichlids.$g$, $g$Altum angelfish are the tallest and most dramatic of the angelfish, and breeding them is a real challenge. They need very soft, acidic water, a tall tank and a pair that forms on its own, and many attempts fail at the egg stage. Captive spawns are still uncommon, which is why altums sit in Society class F.$g$, $g${"method": "Egg depositor: eggs laid on a vertical surface, both parents guard", "sexing": "Unreliable by sight; breeding tube shape at spawning is the best guide", "group": "Raise a group of 5 or more and let a pair form", "breeding_tank": "Tall tank, 75 gallons or more, upright slate or wood", "conditioning": "Frozen bloodworms, brine shrimp and quality foods for weeks", "trigger": "Very soft, acidic water, often pH under 5.5, and stable warm temps", "spawn": "Commonly reported in the low hundreds", "eggs": "Hatch in about 2 to 3 days at 84 to 86°F", "fry": "Wrigglers become free swimming about 4 to 6 days after hatching", "first_foods": "Newly hatched brine shrimp and microworms", "grow_out": "Slow; several months to reach a juvenile size", "parents": "Parents may eat eggs; many breeders remove eggs to hatch separately"}$g$::jsonb, $g$[{"heading": "Tank and water", "text": "Altums are taller than common angelfish and need a tall tank, ideally 24 inches deep or more. The site's care guide lists at least 75 gallons, 82 to 88°F, pH 4.5 to 6.5 and very soft water.\n\nFor breeding, breeders report the best results at the soft, acidic end: pH often below 5.5 and hardness close to zero. Reverse osmosis water is close to essential. Provide upright slate, wood or broad leaves as spawning sites, and keep the tank calm with dim lighting. Use a sponge filter or a gently flowing canister, and change water often with matched temperature and chemistry. Peat or leaf litter helps keep the water soft and slightly stained."}, {"heading": "Forming a pair", "text": "Sexing altums by eye is unreliable. The best approach is to raise a group of five or more and wait for two fish to start claiming a spawning site together. Once a pair forms, move them to their own tank or move the others.\n\nCondition with frozen bloodworms, brine shrimp and quality flake or granules. Wild-caught altums can be shy feeders at first, so be patient.\n\nAltums are sensitive to stress, so keep the group in a quiet room with steady lighting and few tank mates. Peaceful dither fish such as small tetras can help them feel secure. Pairs can take a long time to form, sometimes years, so don't rush the process or split a group too early."}, {"heading": "Spawning", "text": "Before spawning, the pair cleans a vertical surface. The breeding tubes show: the female's is broad and blunt, the male's thinner and pointed. The female lays rows of eggs and the male follows to fertilize them. Clutches are commonly reported in the low hundreds.\n\nSpawning usually takes an hour or two. Both parents then fan and guard the eggs. With a young pair, it is common for the first few clutches to be eaten or to fail, which is why many breeders choose to hatch the eggs separately."}, {"heading": "Eggs and wrigglers", "text": "At 84 to 86°F eggs hatch in about 2 to 3 days. Wrigglers become free swimming about 4 to 6 days after hatching. Eggs that turn white are infertile or fungused; a whole clutch going white usually points to water that is too hard.\n\nMany breeders remove the egg slate to a separate container with water from the breeding tank, gentle aeration and a few drops of methylene blue to prevent fungus."}, {"heading": "Raising the fry", "text": "- Once free swimming: newly hatched brine shrimp and microworms, several times a day\n- Weeks 2 to 4: add crushed flake and frozen foods\n- Small, frequent water changes with matched temperature and chemistry\n- Sponge filtration so fry are not sucked up"}, {"heading": "Growing out", "text": "Altum fry grow slowly and need clean, soft water. Feed several small meals a day and keep water quality high. It takes several months before they look like small altums, and longer before they reach full height. Keep the grow-out tank tall as they get bigger, since cramped altums often develop bent fins. Share young fish with other altum keepers so this rarely bred species becomes more available."}, {"heading": "Common mistakes", "text": "- Water that is too hard for altum eggs\n- A tank that is too short for their tall bodies\n- Disturbing the pair during spawning\n- Skipping water changes in the grow-out tank\n- Expecting quick results; pairs can take years to form\n- Moving a pair to a new tank just as they settle, which often sets them back months"}]$g$::jsonb, $g$[{"q": "Are altum angelfish hard to breed?", "a": "Yes. They need very soft, acidic water and a tall tank, and captive spawns are rare."}, {"q": "How do you tell male and female altum angelfish apart?", "a": "There's no reliable outward sign. The breeding tubes seen at spawning are the best guide."}, {"q": "What pH do altum angelfish need to breed?", "a": "Breeders report the best results with pH often below 5.5 and hardness close to zero."}, {"q": "How long do altum angelfish eggs take to hatch?", "a": "About 2 to 3 days at 84 to 86°F, with fry free swimming about 4 to 6 days later."}]$g$::jsonb, $g$Show the pair beside their spawning site with the challenge code card for stage 1, and note your water parameters in your log. A clear photo of eggs on the slate works for stage 2.$g$),
  ($g$senegal-bichir$g$, $g$626da446-e1bc-4c1f-847d-bc9e3711be26$g$::uuid, $g$senegal-bichir$g$, null, $g$How to Breed Senegal Bichirs: Spawning, Eggs and Larvae$g$, $g$Senegal bichirs scatter eggs among plants after a seasonal trigger, and the larvae have feathery external gills. Rarely bred at home. Expert only.$g$, $g$Senegal bichirs are ancient-looking, hardy oddballs, and most people never think about breeding them. They have been spawned in home aquariums, often after cooler, softer water changes that copy the rainy season, but it is rare. The larvae are fascinating, with feathery external gills. It sits in Society class F because so few hobbyists manage it.$g$, $g${"method": "Egg scatterer: eggs scattered among plants, no parental care", "sexing": "Males have a thicker, broader anal fin; females are often plumper", "group": "A group of mature adults, ideally with more than one of each sex", "breeding_tank": "55 gallons or more, dense plants, tight lid", "conditioning": "Meaty foods such as worms, shrimp and fish, several times a week", "trigger": "Breeders report cooler, softer water changes to copy the rainy season", "spawn": "Commonly reported as a few hundred eggs or fewer", "eggs": "Hatch in roughly 3 to 4 days at 77 to 82°F", "fry": "Larvae have feathery external gills and stay near the bottom", "first_foods": "Newly hatched brine shrimp and microworms", "grow_out": "Several months to reach a juvenile size", "parents": "No parental care; adults eat eggs and fry, so remove them"}$g$::jsonb, $g$[{"heading": "Tank and water", "text": "Senegal bichirs grow to around 12 inches. The site's care guide lists at least 55 gallons, 72 to 82°F and pH 6.5 to 7.5. For breeding, provide dense plants or spawning mops where eggs can land, and a tight lid since bichirs can escape through small gaps.\n\nBichirs are hardy, and they tolerate a wide range of water. For breeding, some keepers lower the hardness and pH slightly, while keeping within the site's range. Give the group plenty of space and hiding places such as wood and caves, since males can squabble when they are in breeding condition."}, {"heading": "Sexing and conditioning", "text": "Males have a thicker, broader anal fin, which they use to cup the eggs during spawning. Females are often plumper. A group of mature adults gives the best chance of a pair.\n\nCondition with meaty foods: worms, shrimp and pieces of fish, several times a week. Well-fed females look noticeably fuller. Mature fish are needed, and bichirs can take a few years to reach breeding size. Young fish under several inches are unlikely to spawn."}, {"heading": "Triggering a spawn", "text": "Breeders report spawns after large, slightly cooler and softer water changes that copy the rainy season. Keep this up for a few weeks and watch for chasing and the male following the female closely.\n\nSome breeders also drop the temperature slightly for a period, then raise it again with fresh, softer water. There is no proven recipe, and many keepers try for months before seeing anything. Keep notes on what you change and when."}, {"heading": "Spawning", "text": "During spawning, the male cups his anal fin to collect the eggs and fertilizes them, then scatters them among plants. Clutches are commonly reported as a few hundred eggs or fewer. Remove the eggs or the adults right away, since adults readily eat them.\n\nSpawning tends to happen at night or early morning, so check the plants and mops each morning. The eggs are small and sticky, and easy to miss among dense plants. A spawning mop that you can lift out makes collecting them much easier."}, {"heading": "Eggs and larvae", "text": "Eggs commonly hatch in roughly 3 to 4 days at 77 to 82°F. The larvae have feathery external gills, which they lose as they grow. They look more like tiny salamanders than fish at first. They stay near the bottom and use their yolk for several days before feeding.\n\nKeep the eggs in a separate container with water from the main tank, gentle aeration and dim light. Remove any eggs that turn white or fuzzy to stop fungus spreading. Larvae should be kept in shallow water, a few inches deep, so they can reach the surface easily, since bichirs gulp air as they grow."}, {"heading": "Raising the fry", "text": "- Once feeding: newly hatched brine shrimp and microworms, several times a day\n- Weeks 2 to 4: add chopped bloodworms and blackworms\n- Small, frequent water changes with matched temperature\n- Sort by size, since larger fry eat smaller ones\n\nGrowth is slow, and it takes several months to reach a juvenile size."}, {"heading": "Common mistakes", "text": "- Leaving eggs with the adults\n- No lid, so bichirs escape\n- Mixing fry of very different sizes\n- Expecting quick results; spawns are rare and unpredictable\n- Overfeeding larvae, which fouls the shallow water quickly\n- Deep water for larvae, which makes it harder for them to reach the surface\n- Forgetting that adult tank mates will hunt any fry that escape into the main tank"}]$g$::jsonb, $g$[{"q": "Can Senegal bichirs breed in an aquarium?", "a": "Yes, but it is rare. Breeders report spawns after cooler, softer water changes."}, {"q": "How do you tell male and female Senegal bichirs apart?", "a": "Males have a thicker, broader anal fin. Females are often plumper."}, {"q": "What do baby bichirs look like?", "a": "The larvae have feathery external gills, which they lose as they grow."}, {"q": "Do bichirs eat their eggs?", "a": "Yes. There is no parental care, and adults readily eat eggs and fry."}]$g$::jsonb, $g$Open your log early with the group and challenge code card in view, since spawns are unpredictable. A clear photo of larvae with their external gills makes an excellent stage 3 record.$g$)
) as v(slug, award_species_id, species_slug, glossary_slug, seo_title, summary, intro, facts, sections, faq, society_tip)
-- Only link a points row that still exists.
left join public.club_award_species a on a.id = v.award_species_id
on conflict (slug) do update set
  award_species_id = excluded.award_species_id,
  species_slug = excluded.species_slug,
  glossary_slug = excluded.glossary_slug,
  seo_title = excluded.seo_title,
  summary = excluded.summary,
  intro = excluded.intro,
  facts = excluded.facts,
  sections = excluded.sections,
  faq = excluded.faq,
  society_tip = excluded.society_tip,
  updated_at = now();

-- Check: guides by Society class.
select coalesce(a.points::text, 'no points row') as points, count(*) as guides
from public.breeding_guides g
left join public.club_award_species a on a.id = g.award_species_id
group by a.points
order by a.points nulls last;
